INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f6fab547-0611-4cd0-99d7-42d0a5686b5f','Loose-particle noise','Loose-particle noise is an audible defect in which small foreign objects, such as metal chips, glue beads, or fibres, are trapped in the magnetic gap or on the diaphragm and rattle when the driver moves. It appears as impulsive noise that is not part of the drive signal and is treated as a manufacturing fault.','Sometimes tiny bits of metal or glue get stuck inside a speaker. When the cone moves, these bits rattle and buzz. This noise is not in the music signal. Factories test for it and reject bad units.','The term names a production defect so technicians and quality staff can detect, describe, and reject speakers that make stray rattles.','In an end-of-line quality test a technician runs a swept tone and watches for impulsive spikes; a loose ferrous chip in the gap shows up as buzzing that fails the Rub and Buzz limit.','Defect / QC',ARRAY['Rub and buzz','Impulsive distortion','Voice coil','Magnetic gap','Cone break-up']::text[],ARRAY['Confusing loose-particle noise with coil rub; both are impulsive but have different causes.','Assuming the noise is an amplifier or cable fault rather than inside the driver.','UNSAFE: blowing compressed air into a gap without eye protection can drive metal chips into the eyes.']::text[],ARRAY['End-of-line quality control on a loudspeaker production line.','Diagnosing a rattle in one driver of a matched pair.','Field service inspection after a driver has been near metalworking dust.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loose-particle noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f6fab547-0611-4cd0-99d7-42d0a5686b5f','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f6fab547-0611-4cd0-99d7-42d0a5686b5f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f6fab547-0611-4cd0-99d7-42d0a5686b5f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1e010111-e967-4c70-bb53-e9e459013ef5','Loss tangent','Loss tangent (tan delta) is the ratio of energy dissipated to energy stored per cycle in a material subjected to oscillating stress or field. For loudspeaker cones and suspensions it quantifies internal mechanical damping of the viscoelastic material.','Every material loses a little energy as heat when it flexes back and forth. Loss tangent measures how much is lost versus stored. A higher value means more damping. It helps control unwanted resonances in cones and surrounds.','It gives designers a single number for a material''s internal damping, guiding cone and surround choices that tame break-up peaks.','A designer compares two cone materials: one with tan delta of 0.02 rings at break-up, while one with tan delta of 0.10 damps the peak, smoothing the high-frequency response.','Material Property',ARRAY['Mechanical hysteresis','Damping','Cone material','Surround','Viscoelasticity']::text[],ARRAY['Thinking a higher loss tangent is always better; too much lowers efficiency and sensitivity.','Confusing mechanical loss tangent with the electrical dielectric loss tangent of a capacitor.','Assuming loss tangent is constant; it varies with frequency and temperature.']::text[],ARRAY['Selecting a doped-paper cone to damp a break-up mode.','Comparing polypropylene and paper diaphragms for smoothness.','Explaining why some cones sound ''ringy'' at high frequencies.']::text[],'Advanced','tan(delta) = E'''' / E''','The loss tangent equals the loss modulus divided by the storage modulus of the material.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loss tangent');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1e010111-e967-4c70-bb53-e9e459013ef5','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1e010111-e967-4c70-bb53-e9e459013ef5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1e010111-e967-4c70-bb53-e9e459013ef5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c3f01acd-9f25-4042-ac10-172028644f6a','Loudspeaker impedance','Loudspeaker impedance is the frequency-dependent complex electrical opposition seen at a driver''s terminals. It combines the voice-coil DC resistance, the coil inductance, and the motional impedance reflected from the moving system, producing a peak at the resonance frequency.','Impedance is how much a speaker resists the amplifier''s current, and it changes with frequency. It is not one fixed number. There is a tall peak at the driver''s resonance. It also rises at high frequencies because of coil inductance.','It tells the amplifier how much current the driver draws at each frequency and is the basis for rating, crossover design, and system matching.','A technician sweeps a driver and reads a DC resistance of 6 ohms, a resonance peak near 40 ohms at 40 Hz, and a rise above a few kilohertz from coil inductance.','Electrical Property',ARRAY['Motional impedance','Nominal versus actual impedance','Voice coil','Resonance frequency']::text[],ARRAY['Treating the nominal rating (for example 8 ohms) as the value at every frequency.','Ignoring the impedance dip that can overload an amplifier.','Forgetting that the resonance peak sits far above the DC resistance.']::text[],ARRAY['Measuring an impedance curve to derive Thiele-Small parameters.','Checking the minimum impedance before choosing an amplifier.','Designing a crossover that depends on the driver''s real impedance.']::text[],'Intermediate','Z_e(s) = R_e + s*L_e + Z_mot(s)','Total electrical impedance equals the voice-coil resistance plus the coil inductance term plus the motional impedance from the moving system.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loudspeaker impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c3f01acd-9f25-4042-ac10-172028644f6a','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c3f01acd-9f25-4042-ac10-172028644f6a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c3f01acd-9f25-4042-ac10-172028644f6a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cc79379d-12a3-470b-a853-9b2bcb75e50e','Lumped nonlinear model','A lumped nonlinear model represents a driver with discrete elements whose values change with state, such as force factor Bl(x), stiffness Kms(x), and inductance Le(x,i). It captures large-signal behavior and the distortion that small-signal models miss.','A simple speaker model uses fixed parts. But real parts change as the cone moves far or the current grows. A lumped nonlinear model lets these values shift with position and current. This predicts distortion at loud levels.','It extends the lumped-parameter approach to loud signals so engineers can predict and reduce nonlinear distortion.','An engineer uses measured Bl(x) and Kms(x) curves in a nonlinear model to predict second-harmonic distortion when the cone swings past its linear range.','Modeling',ARRAY['Lumped-parameter model','Nonlinear parameter identification','Force factor','Parameter trajectory','Nonlinear state-space model']::text[],ARRAY['Assuming small-signal Thiele-Small values still apply at high excursion.','Ignoring the current-dependence of voice-coil inductance.','Treating asymmetry in Bl(x) as a measurement error rather than a real distortion source.']::text[],ARRAY['Predicting distortion of a subwoofer at maximum drive.','Designing DSP linearization from measured nonlinear curves.','Explaining why a driver distorts more on one half of its stroke.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lumped nonlinear model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cc79379d-12a3-470b-a853-9b2bcb75e50e','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cc79379d-12a3-470b-a853-9b2bcb75e50e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cc79379d-12a3-470b-a853-9b2bcb75e50e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'be8f1c3b-906a-4f09-bc37-f3a74cbc4178','Lumped-parameter model','A lumped-parameter model treats a loudspeaker as discrete masses, compliances, and resistances rather than a distributed structure. It is valid where the physical dimensions are small compared with the wavelength and is the foundation of Thiele-Small analysis.','At low frequencies a speaker cone moves as one solid piston. So we can model it with a few simple parts: a mass, a spring, and a damper. This is the lumped-parameter model. It breaks down when the cone flexes at high frequencies.','It reduces a complex electromechanical device to a simple circuit so behavior can be predicted with a handful of parameters.','A technician uses lumped parameters (Mms, Cms, Rms, Bl, Re) to model a woofer in a box and predict its low-frequency roll-off before building it.','Modeling',ARRAY['Thiele-Small parameters','Mechanical equivalent circuit','Lumped nonlinear model','Partial vibration','Moving mass']::text[],ARRAY['Applying the model above the piston band where the cone no longer moves as one unit.','Confusing lumped elements with the real physical parts one-to-one.','Assuming the parameters never drift with temperature or use.']::text[],ARRAY['Deriving box alignment from Thiele-Small parameters.','Teaching the basic mass-spring-damper picture of a driver.','Simulating low-frequency response in a design tool.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lumped-parameter model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'be8f1c3b-906a-4f09-bc37-f3a74cbc4178','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='be8f1c3b-906a-4f09-bc37-f3a74cbc4178') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='be8f1c3b-906a-4f09-bc37-f3a74cbc4178');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '14c4b76f-67c1-404c-b4ce-27468f46d045','Mass corner','The mass corner is the frequency, at and above the driver''s resonance, beyond which the moving mass reactance dominates the suspension compliance reactance, so the cone''s motion becomes mass-controlled. In this region a constant driving force yields constant acceleration, giving the flat piston-band output.','Below resonance a speaker''s springy suspension controls the cone. At the mass corner near resonance, the heavy moving parts take over control. Above it, the cone is ruled by its own weight. This region gives the flat, useful part of the response.','It marks the transition into the mass-controlled operating region where a moving-coil driver produces its flat frequency response.','A designer notes that a woofer with resonance at 40 Hz becomes mass-controlled just above it, so its usable flat band starts near and above that mass corner.','Driver Behavior',ARRAY['Resonance frequency','Moving mass','Compliance','Mechanical quality factor','Piston band']::text[],ARRAY['Confusing the mass corner with the upper break-up frequency.','Assuming the cone is mass-controlled at all frequencies.','Forgetting that below resonance the suspension, not the mass, controls motion.']::text[],ARRAY['Explaining why output is flat above resonance.','Relating resonance frequency to the start of the usable band.','Teaching the three control regions of a driver.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mass corner');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '14c4b76f-67c1-404c-b4ce-27468f46d045','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='14c4b76f-67c1-404c-b4ce-27468f46d045') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='14c4b76f-67c1-404c-b4ce-27468f46d045');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5ebe8078-00f4-48b1-82a9-bac38d1213ab','Mechanical equivalent circuit','A mechanical equivalent circuit models a driver''s moving system as an electrical network, mapping moving mass, suspension compliance, and mechanical resistance to circuit elements. Using the impedance analogy, mass becomes an inductance, compliance a capacitance, and mechanical resistance a resistor.','Engineers like to use circuit tools they already know. So they draw the speaker''s moving parts as an electrical circuit. Mass acts like a coil, the springy suspension like a capacitor, and losses like a resistor. Then they can solve it with circuit math.','It lets engineers analyse mechanical resonance and damping with familiar electrical-circuit methods.','A designer draws Mms as an inductor, Cms as a capacitor, and Rms as a resistor, then reads the resonance frequency straight from the series circuit.','Modeling',ARRAY['Mobility analogy','Motional branch','Lumped-parameter model','Mechanical resistance','Moving mass']::text[],ARRAY['Mixing the impedance and mobility analogies within one diagram.','Forgetting that the analogy only holds in the lumped (piston) band.','Assuming a mechanical resistor dissipates electrical power directly rather than mechanical energy.']::text[],ARRAY['Deriving resonance from a mass-compliance circuit.','Teaching electromechanical analogies.','Combining mechanical and electrical circuits through the force factor.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mechanical equivalent circuit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5ebe8078-00f4-48b1-82a9-bac38d1213ab','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5ebe8078-00f4-48b1-82a9-bac38d1213ab') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5ebe8078-00f4-48b1-82a9-bac38d1213ab');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f15b0e8-69d4-4df1-b1a2-658a2f104c08','Mechanical excursion','Mechanical excursion is the linear displacement of the diaphragm and voice coil from the rest position. Key limits include Xmax, the peak linear travel, and Xmech (or Xdamage), the greater peak beyond which the suspension or coil suffers mechanical damage.','Excursion is how far the cone moves in and out. There is a limit for clean sound, called Xmax. There is a larger hard limit before parts break, called Xmech. Push past that and the coil can slam into the magnet.','It defines how far a driver can move cleanly and safely, setting limits for loud low-frequency reproduction.','A technician reads Xmax of 6 mm and Xmech of 9 mm on a datasheet, then sets a limiter so deep bass never drives the cone past 9 mm.','Displacement',ARRAY['Xmax','Force factor','Compliance','Power handling','Suspension']::text[],ARRAY['Confusing peak excursion with peak-to-peak travel.','Assuming Xmax is a damage limit rather than a linear (distortion) limit.','UNSAFE: driving a subwoofer past Xmech at high power can bottom the coil and destroy the driver, and flying debris or overheating can result.']::text[],ARRAY['Setting excursion-based limiters on a subwoofer.','Diagnosing a driver that bottoms out on bass drops.','Comparing datasheet Xmax figures between drivers.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mechanical excursion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f15b0e8-69d4-4df1-b1a2-658a2f104c08','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f15b0e8-69d4-4df1-b1a2-658a2f104c08') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f15b0e8-69d4-4df1-b1a2-658a2f104c08');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8f1056af-f476-4259-b7f2-cf73e632e1ec','Mechanical hysteresis','Mechanical hysteresis is the energy loss in a driver''s suspension where the force-displacement curve differs during loading and unloading. It arises from viscoelastic behavior of the spider and surround and contributes damping plus slow drift of parameters.','When you push a speaker''s suspension and let go, it does not return the same way it went. Some energy is lost as heat. This lag is called hysteresis. It adds damping and can make parameters drift after hard use.','It explains a real damping and memory effect in suspensions that affects distortion and parameter stability.','A technician notices resonance frequency drops after a long loud session, then recovers over time, a sign of hysteresis and viscoelastic creep in the suspension.','Material Behavior',ARRAY['Loss tangent','Compliance','Spider','Surround','Viscoelasticity']::text[],ARRAY['Assuming compliance is perfectly elastic and lossless.','Blaming resonance drift only on temperature and ignoring viscoelastic creep.','Confusing mechanical hysteresis with magnetic hysteresis in the motor.']::text[],ARRAY['Explaining resonance drift after break-in or hard use.','Modeling suspension damping and creep.','Understanding low-frequency distortion from the suspension.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mechanical hysteresis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8f1056af-f476-4259-b7f2-cf73e632e1ec','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8f1056af-f476-4259-b7f2-cf73e632e1ec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8f1056af-f476-4259-b7f2-cf73e632e1ec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8ce49cfd-3bfe-474c-8fde-14543b582acc','Mechanical quality factor','The mechanical quality factor, Qms, is a dimensionless measure of a driver''s damping from mechanical losses alone at its resonance frequency. A high Qms means low mechanical loss and a sharp, lightly damped resonance.','Qms describes how much the suspension and moving parts damp the resonance. A high Qms means little loss and a tall, narrow resonance peak. A low Qms means the mechanical parts soak up energy. It ignores electrical damping.','It quantifies purely mechanical damping so designers can separate it from electrical damping when predicting resonance behavior.','For fs = 40 Hz, Mms = 0.025 kg, and Rms = 1.5 N s/m: Qms = 2*pi*40*0.025 / 1.5 = 4.19.','Thiele-Small Parameter',ARRAY['Mechanical resistance','Electrical quality factor','Total quality factor','Resonance frequency','Moving mass']::text[],ARRAY['Confusing Qms with the total Q (Qts), which also includes electrical damping.','Thinking a high Qms is always desirable; it can leave resonance underdamped.','Mixing up units, since Rms is in mechanical ohms (N s/m).']::text[],ARRAY['Deriving Qts from Qms and Qes for box design.','Judging suspension damping quality from measurements.','Explaining a peaky low-frequency response.']::text[],'Intermediate','Q_ms = 2*pi*f_s*M_ms / R_ms','Mechanical Q equals two pi times the resonance frequency times the moving mass, divided by the mechanical resistance.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mechanical quality factor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8ce49cfd-3bfe-474c-8fde-14543b582acc','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8ce49cfd-3bfe-474c-8fde-14543b582acc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8ce49cfd-3bfe-474c-8fde-14543b582acc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aebd7909-ac68-4a90-a32e-ccc79ff666ae','Mechanical resistance','Mechanical resistance, Rms, is the loss term of a driver''s moving system that dissipates energy through suspension friction and air damping. It is expressed in mechanical ohms (newton-seconds per metre) and sets the mechanical quality factor at resonance.','As the cone moves, the suspension and air rub away some energy as heat. Mechanical resistance measures that loss. It is given in units of force times time per distance. More resistance means a more damped, less peaky resonance.','It represents mechanical energy loss in the moving system, controlling damping and the height of the resonance peak.','With fs = 40 Hz, Mms = 0.025 kg, and Qms = 4.19: Rms = 2*pi*40*0.025 / 4.19 = 1.5 N s/m.','Thiele-Small Parameter',ARRAY['Mechanical quality factor','Moving mass','Compliance','Damping','Mechanical equivalent circuit']::text[],ARRAY['Treating Rms as an electrical resistance in ohms.','Ignoring that air-load damping adds to suspension damping in Rms.','Assuming Rms is fixed; it varies with temperature and cone motion.']::text[],ARRAY['Computing Qms from measured parameters.','Modeling suspension losses in a mechanical circuit.','Explaining differences in resonance damping between drivers.']::text[],'Intermediate','R_ms = 2*pi*f_s*M_ms / Q_ms','Mechanical resistance equals two pi times the resonance frequency times the moving mass, divided by the mechanical quality factor.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mechanical resistance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aebd7909-ac68-4a90-a32e-ccc79ff666ae','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aebd7909-ac68-4a90-a32e-ccc79ff666ae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aebd7909-ac68-4a90-a32e-ccc79ff666ae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3c44b1d2-b1f8-4200-8303-b16db4dcc51c','Mmd','Mmd is the moving mass of the diaphragm assembly alone, including the cone, voice coil, former, and moving parts of the suspension, but excluding the air load. Adding the air-load mass Mmr gives the total moving mass Mms used in Thiele-Small analysis.','Mmd is the weight of the moving parts by themselves. It includes the cone, coil, and former. It does not count the air that moves with the cone. Add that air mass and you get the total moving mass, Mms.','It separates the driver''s own moving mass from the air it drags along, which matters when the air load changes with mounting.','If total moving mass Mms is 25 g and the air-load mass Mmr is 3 g, then the diaphragm mass Mmd = 25 - 3 = 22 g.','Thiele-Small Parameter',ARRAY['Moving mass','Air-load mass','Voice coil','Cone','Resonance frequency']::text[],ARRAY['Confusing Mmd (no air load) with Mms (with air load).','Forgetting that the air-load mass differs between free air and a baffle.','Assuming Mmd includes the full spider and surround mass rather than their effective moving fraction.']::text[],ARRAY['Separating diaphragm mass from air load in modeling.','Explaining why measured mass changes with baffling.','Computing resonance shifts after adding mass to a cone.']::text[],'Intermediate','M_ms = M_md + M_mr','Total moving mass equals the diaphragm assembly mass plus the air-load mass.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mmd');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3c44b1d2-b1f8-4200-8303-b16db4dcc51c','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3c44b1d2-b1f8-4200-8303-b16db4dcc51c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3c44b1d2-b1f8-4200-8303-b16db4dcc51c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e9b5b72c-ef4b-4b68-bd74-32c9cdcaf83f','Mobility analogy','The mobility analogy is an electromechanical analogy in which mechanical force corresponds to electrical current and velocity corresponds to voltage. It is the dual of the impedance analogy, so mass becomes a capacitance and compliance becomes an inductance while preserving the network topology.','To model a speaker as a circuit, we match mechanical and electrical quantities. In the mobility analogy, force acts like current and velocity like voltage. This makes a mass behave like a capacitor. It keeps the circuit shape the same as the real parts.','It provides a circuit representation whose layout matches the physical mechanical structure, easing intuitive network building.','An engineer uses the mobility analogy so that parts connected in the machine appear connected the same way in the circuit, then converts to the impedance analogy for calculation.','Modeling',ARRAY['Impedance analogy','Mechanical equivalent circuit','Moving mass','Compliance','Motional branch']::text[],ARRAY['Mixing mobility and impedance analogies in one diagram.','Forgetting that mass maps to a capacitor, not an inductor, here.','Assuming series and parallel connections stay the same across both analogies.']::text[],ARRAY['Building a mechanical circuit that mirrors the physical layout.','Teaching duality between the two analogies.','Converting a mechanical network into an electrical one.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mobility analogy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e9b5b72c-ef4b-4b68-bd74-32c9cdcaf83f','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e9b5b72c-ef4b-4b68-bd74-32c9cdcaf83f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e9b5b72c-ef4b-4b68-bd74-32c9cdcaf83f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '429ea5be-5dfd-4655-aa06-50fc63ff1046','Motional branch','The motional branch is the part of a driver''s electrical equivalent circuit that represents the moving system reflected into the electrical domain through the squared force factor. It typically appears as a parallel resistance, inductance, and capacitance that create the impedance peak at resonance.','A speaker''s moving parts show up in its electrical circuit. This part is the motional branch. It appears as a small parallel circuit that peaks at resonance. That is why the impedance rises so much at the resonance frequency.','It captures how the cone''s motion changes the electrical impedance, explaining the resonance peak the amplifier sees.','A technician sees the impedance peak at fs and knows it comes from the motional branch, which disappears if the coil is clamped so the cone cannot move.','Modeling',ARRAY['Motional impedance','Force factor','Blocked impedance','Resonance frequency','Mechanical equivalent circuit']::text[],ARRAY['Thinking the resonance peak comes from the coil inductance rather than motion.','Forgetting the motional branch vanishes when the cone is blocked.','Confusing the parallel motional branch with the series voice-coil elements.']::text[],ARRAY['Explaining the impedance peak at resonance.','Separating blocked and motional impedance in measurements.','Modeling a driver as electrical plus reflected mechanical parts.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Motional branch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '429ea5be-5dfd-4655-aa06-50fc63ff1046','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='429ea5be-5dfd-4655-aa06-50fc63ff1046') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='429ea5be-5dfd-4655-aa06-50fc63ff1046');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '40282397-a4c3-4c2b-a7b2-68e0786c012d','Motional impedance','Motional impedance is the component of a driver''s electrical input impedance that arises from diaphragm motion and the resulting back-EMF. It equals the squared force factor divided by the mechanical impedance, so it peaks near resonance and falls to zero when the coil is blocked.','When the cone moves, it generates a small voltage that opposes the current. This adds extra impedance called motional impedance. It is largest at resonance where the cone moves easily. If you stop the cone, it disappears.','It links the mechanical resonance to the electrical impedance the amplifier sees, and underlies parameter measurement.','With Bl = 7 T m and a minimum mechanical impedance of 1.5 N s/m at resonance, the peak motional impedance is 7^2 / 1.5 = 32.7 ohms added above the coil resistance.','Electrical Property',ARRAY['Motional branch','Blocked impedance','Force factor','Back-EMF','Loudspeaker impedance']::text[],ARRAY['Forgetting that motional impedance is highest at resonance, where mechanical impedance is lowest.','Ignoring back-EMF as the physical source of this impedance.','Assuming a blocked coil still shows a resonance peak.']::text[],ARRAY['Deriving Bl from impedance measurements.','Explaining why the impedance peak appears at resonance.','Separating blocked and motional parts of impedance.']::text[],'Advanced','Z_mot = (Bl)^2 / Z_ms','Motional impedance equals the force factor squared divided by the mechanical impedance of the moving system.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Motional impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '40282397-a4c3-4c2b-a7b2-68e0786c012d','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='40282397-a4c3-4c2b-a7b2-68e0786c012d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='40282397-a4c3-4c2b-a7b2-68e0786c012d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7fa31493-2eba-45d9-98d3-ecd91fc70c33','Moving-coil driver','A moving-coil driver is an electrodynamic transducer in which a coil suspended in a radial magnetic gap carries the audio current and experiences a Lorentz force that drives the diaphragm. It is the most common loudspeaker type, used from subwoofers to tweeters.','A moving-coil driver is the usual kind of speaker. A coil of wire sits in a magnet''s gap. Audio current in the coil makes it push and pull. This moves the cone, which moves the air and makes sound.','It converts electrical audio signals into sound using the force on a current-carrying coil in a magnetic field.','A technician recognises a woofer, midrange, and dome tweeter as moving-coil drivers, all using a voice coil in a magnet gap despite their different sizes.','Transducer Type',ARRAY['Moving-coil loudspeaker operation','Voice coil','Force factor','Magnetic gap','Compression driver']::text[],ARRAY['Confusing moving-coil with moving-iron or electrostatic types.','Assuming the magnet moves; it is fixed while the coil moves.','UNSAFE: leaving the terminals shorted or fingers in the gap of a strong neodymium motor during assembly can pinch skin between attracted parts.']::text[],ARRAY['Identifying driver types in a loudspeaker.','Explaining the basic sound-making mechanism to trainees.','Comparing moving-coil with compression or ribbon drivers.']::text[],'Beginner',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Moving-coil driver');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7fa31493-2eba-45d9-98d3-ecd91fc70c33','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7fa31493-2eba-45d9-98d3-ecd91fc70c33') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7fa31493-2eba-45d9-98d3-ecd91fc70c33');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bfdc8957-f435-4864-adbd-6e6886f405b8','Moving-coil loudspeaker operation','Moving-coil loudspeaker operation is the principle by which audio current in a voice coil, sitting in a radial magnetic field, produces a Lorentz force proportional to Bl times current, moving the cone to radiate sound. The reciprocal effect generates a back-EMF as the coil moves.','Current flows through the voice coil in the magnet''s field. This creates a force that pushes the coil and cone. The cone pumps air to make sound. When the coil moves, it also makes a small opposing voltage.','It describes the electromechanical energy conversion at the heart of nearly every dynamic loudspeaker.','With Bl = 7 T m and a coil current of 2 A, the force on the coil is F = 7 * 2 = 14 N, driving the cone forward.','Operating Principle',ARRAY['Moving-coil driver','Force factor','Back-EMF','Voice coil','Motional impedance']::text[],ARRAY['Forgetting the reciprocal back-EMF that opposes the current.','Assuming force depends only on current and not on the Bl factor.','Thinking the whole magnet field, not just the radial gap field, does the work.']::text[],ARRAY['Teaching how a speaker turns current into motion.','Explaining why Bl matters for sensitivity.','Relating force to current in driver design.']::text[],'Beginner','F = Bl * i','The force on the voice coil equals the force factor times the current through the coil.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Moving-coil loudspeaker operation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bfdc8957-f435-4864-adbd-6e6886f405b8','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bfdc8957-f435-4864-adbd-6e6886f405b8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bfdc8957-f435-4864-adbd-6e6886f405b8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9667a17d-4433-4921-8002-82d7175ce758','Multitone distortion','Multitone distortion is a measurement using an excitation of many simultaneous tones to reveal intermodulation and total distortion under program-like conditions. Distortion products appear at frequencies between the excitation tones and are separated from the tones by analysis.','A single test tone does not act like real music. So we play many tones at once. New unwanted tones appear between them from distortion. Measuring these shows how the speaker misbehaves on complex signals.','It estimates distortion under realistic, dense signals where intermodulation matters more than single-tone harmonics.','A technician plays a multitone signal and reads the distortion energy sitting between the tones to judge a driver''s intermodulation performance.','Distortion / Measurement',ARRAY['Intermodulation distortion','Total harmonic distortion','Nonlinear distortion','Force factor']::text[],ARRAY['Assuming low harmonic distortion guarantees low intermodulation.','Ignoring the crest factor of the multitone signal when setting level.','Reading the excitation tones themselves as distortion products.']::text[],ARRAY['Assessing intermodulation of a driver under dense signals.','Comparing distortion between drivers with realistic excitation.','Evaluating DSP linearization effectiveness.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multitone distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9667a17d-4433-4921-8002-82d7175ce758','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9667a17d-4433-4921-8002-82d7175ce758') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9667a17d-4433-4921-8002-82d7175ce758');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f408a645-8a69-4cc7-ac1d-b5cb18934080','Near-field and far-field transitions','The near-field to far-field transition is the distance beyond which a source behaves as a simple radiator, so on-axis level falls about 6 dB per doubling of distance and interference stabilises. In the near field, path-length differences cause strong peaks and dips, while in the far field the wavefront is effectively spherical.','Close to a speaker, sound waves from different parts fight and reinforce, so level jumps around. Far away, the sound settles down. Then each doubling of distance drops the level by about 6 dB. The change-over distance depends on the source size and the wavelength.','It tells a technician where measurements and predictions of level and directivity become simple and reliable.','For a piston of radius a = 0.1 m at 3 kHz (wavelength 0.114 m), the last on-axis pressure maximum is near r = a^2 / lambda = 0.01 / 0.114 = 0.088 m, so the far field begins beyond about 9 cm.','Radiation / Acoustics',ARRAY['Directivity','Inverse-square law','Pattern collapse','Rayleigh distance','Radiation']::text[],ARRAY['Measuring frequency response too close, inside the near field, and getting comb-like errors.','Assuming the 6 dB per doubling rule holds right next to the source.','Using one fixed transition distance for all frequencies.']::text[],ARRAY['Choosing a valid microphone distance for response measurement.','Explaining odd readings taken close to a large source.','Predicting coverage from an array.']::text[],'Advanced','r_transition ~= a^2 / lambda','The near-to-far transition distance for a circular piston is roughly the piston radius squared divided by the wavelength.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-field and far-field transitions');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f408a645-8a69-4cc7-ac1d-b5cb18934080','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f408a645-8a69-4cc7-ac1d-b5cb18934080') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f408a645-8a69-4cc7-ac1d-b5cb18934080');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2844e372-03e3-4491-babb-c2bacd656097','Nomex former','A Nomex former is a voice-coil bobbin wound with a meta-aramid paper marketed under the Nomex name, a registered trademark of DuPont. The material is heat-resistant, light, and electrically non-conductive, so it withstands coil heat without adding eddy-current losses.','The voice coil is wound on a tube called a former. A Nomex former uses a tough, heat-proof aramid paper made by DuPont. It handles high coil temperatures. Because it does not conduct, it avoids extra magnetic losses.','It provides a lightweight, heat-tolerant, non-conductive coil support that survives high power without adding eddy-current damping.','A designer choosing a high-power woofer specifies a Nomex former so the coil can run hot without the former softening or causing eddy-current losses.','Materials / Construction',ARRAY['Voice coil','Former','Kapton former','Power handling','Thermal compression']::text[],ARRAY['Assuming a Nomex former handles as much heat as a metal one; it trades some heat limit for lower eddy losses.','Confusing the trademark Nomex with the generic aramid paper method.','Believing a non-conductive former eliminates all thermal problems.']::text[],ARRAY['Selecting former material for a high-power driver.','Comparing aramid, polyimide, and aluminium formers.','Explaining eddy-current losses from conductive formers.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nomex former');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2844e372-03e3-4491-babb-c2bacd656097','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2844e372-03e3-4491-babb-c2bacd656097') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2844e372-03e3-4491-babb-c2bacd656097');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ac1355d6-e0ab-4439-9a47-c541a9d18084','Nominal versus actual impedance','Nominal impedance is a single rated value, such as 8 ohms, used to describe a loudspeaker''s load, whereas actual impedance is the full frequency-dependent curve. Under IEC 60268-5 the minimum modulus in the rated band must not fall below 80 percent of the nominal value.','A speaker is sold with one impedance number, like 8 ohms. But the real impedance changes a lot with frequency. It has a tall peak at resonance and dips elsewhere. The rules require the lowest dip to stay near the rated value.','It reconciles a simple rating used for matching with the complex real impedance that determines amplifier loading.','A technician sees a nominal 8 ohm speaker whose curve dips to 6.4 ohms, meeting the 80 percent rule, and checks the amplifier can drive that minimum.','Electrical Property',ARRAY['Loudspeaker impedance','Rated impedance','Minimum impedance','Amplifier loading','DC resistance']::text[],ARRAY['Treating the nominal number as the load at every frequency.','Overlooking the impedance dip that stresses the amplifier.','UNSAFE: paralleling several nominal 8 ohm boxes so the combined minimum impedance drops below the amplifier''s safe load and overheats it.']::text[],ARRAY['Matching an amplifier to a speaker''s real minimum impedance.','Reading an impedance curve versus the rated value.','Wiring multiple cabinets without overloading the amplifier.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nominal versus actual impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ac1355d6-e0ab-4439-9a47-c541a9d18084','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ac1355d6-e0ab-4439-9a47-c541a9d18084') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ac1355d6-e0ab-4439-9a47-c541a9d18084');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1f160b6f-81c4-4dca-b570-3f14d00dab28','Nonlinear parameter identification','Nonlinear parameter identification is the measurement of a driver''s state-dependent parameters, such as force factor Bl(x), stiffness Kms(x), and inductance Le(x,i), from large-signal excitation. It reveals how these values change with displacement and current, characterising distortion sources.','At loud levels, a speaker''s key values change as the cone moves. This method measures those changing values. It plays large signals and tracks how force factor and stiffness shift. The result shows where distortion comes from.','It supplies the state-dependent curves needed for nonlinear modeling, distortion diagnosis, and DSP correction.','An engineer runs a large-signal identification to obtain Bl(x) and Kms(x) curves, then reads the asymmetry that causes even-order distortion.','Measurement / Modeling',ARRAY['Lumped nonlinear model','Parameter trajectory','Force factor','Nonlinear state-space model','Suspension']::text[],ARRAY['Assuming small-signal parameters are enough to predict loud behavior.','Ignoring the current-dependence of voice-coil inductance.','Treating measured asymmetry as noise rather than a real distortion cause.']::text[],ARRAY['Characterising distortion for DSP linearization.','Diagnosing an offset or asymmetric suspension.','Validating a nonlinear driver model.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nonlinear parameter identification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1f160b6f-81c4-4dca-b570-3f14d00dab28','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1f160b6f-81c4-4dca-b570-3f14d00dab28') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1f160b6f-81c4-4dca-b570-3f14d00dab28');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c00c96df-5405-4e01-8e41-9aba75915563','Nonlinear state-space model','A nonlinear state-space model describes a driver with time-domain state equations, using states such as coil current, cone displacement, and velocity, with coefficients that vary nonlinearly. It supports large-signal simulation and real-time control or DSP linearization.','This model tracks the speaker''s inner variables over time: current, position, and speed. Its equations use values that change with the state. That lets it simulate loud, distorting behavior. It also suits real-time correction in a processor.','It provides a time-domain framework for simulating and controlling a driver''s large-signal, nonlinear behavior.','A DSP engineer implements a state-space driver model to predict cone position in real time and pre-distort the signal to cut distortion.','Modeling',ARRAY['Lumped nonlinear model','Nonlinear parameter identification','Parameter trajectory','State variable','DSP linearization']::text[],ARRAY['Confusing a linear state-space model with a nonlinear one.','Ignoring thermal states that also change parameters.','Assuming the model is valid outside the range where parameters were measured.']::text[],ARRAY['Building real-time cone-position estimators.','Simulating a driver at maximum drive.','Designing feedforward distortion correction.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nonlinear state-space model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c00c96df-5405-4e01-8e41-9aba75915563','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c00c96df-5405-4e01-8e41-9aba75915563') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c00c96df-5405-4e01-8e41-9aba75915563');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2cd53681-4ae4-41ea-bcf7-c243e459336e','Parameter trajectory','A parameter trajectory is the plotted variation of a nonlinear driver parameter, such as Bl, Kms, or Le, as a function of displacement or current. Its shape and asymmetry describe the driver''s nonlinearity and predict the dominant distortion products.','As the cone moves, values like force factor change. A parameter trajectory is the graph of that change against position. A lopsided curve means the speaker distorts more on one side. Engineers read these curves to judge a driver.','It visualises how a parameter changes with state so engineers can spot and compare nonlinear behavior.','A technician sees the Bl(x) trajectory drop faster on the outward stroke, warning that the coil may be leaving the gap and causing distortion at high excursion.','Measurement / Modeling',ARRAY['Nonlinear parameter identification','Force factor','Lumped nonlinear model','Suspension','Voice coil offset']::text[],ARRAY['Reading only the rest-position value and ignoring the curve shape.','Assuming a symmetric trajectory when the coil is offset.','Confusing displacement-dependence with current-dependence.']::text[],ARRAY['Judging coil centring from a Bl(x) curve.','Comparing suspension stiffness curves between drivers.','Diagnosing the source of even-order distortion.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Parameter trajectory');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2cd53681-4ae4-41ea-bcf7-c243e459336e','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2cd53681-4ae4-41ea-bcf7-c243e459336e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2cd53681-4ae4-41ea-bcf7-c243e459336e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '65d870d4-ec83-42d8-9113-453777d5d123','Partial vibration','Partial vibration, also called cone break-up, occurs when a diaphragm no longer moves as a rigid piston but flexes in partial modes at higher frequencies. These modes create response peaks and dips and can add distortion.','At low frequencies the cone moves as one solid piece. Higher up, parts of the cone start to flex on their own. This is partial vibration or break-up. It makes bumps and dips in the response.','It explains the high-frequency limit of piston behavior and the resulting irregular response of a diaphragm.','A designer crosses a woofer over below its break-up region so partial vibrations do not colour the sound, and uses cone damping to tame the peak.','Diaphragm Behavior',ARRAY['Cone break-up','Loss tangent','Lumped-parameter model','Diaphragm material','Modal behavior']::text[],ARRAY['Assuming the cone stays a rigid piston at all frequencies.','Blaming break-up peaks on the enclosure rather than the diaphragm.','Thinking stiffer cones remove break-up rather than shifting it upward.']::text[],ARRAY['Setting a crossover below the break-up region.','Explaining a high-frequency response peak in a woofer.','Choosing cone material and damping.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Partial vibration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '65d870d4-ec83-42d8-9113-453777d5d123','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='65d870d4-ec83-42d8-9113-453777d5d123') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='65d870d4-ec83-42d8-9113-453777d5d123');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ddabc66a-5457-41f8-9449-e30d13432184','Passive radiators','A passive radiator, or drone cone, is a diaphragm with a suspension but no motor, mounted in a sealed enclosure. Its moving mass and the enclosure air form a resonant system that reinforces low-frequency output much like a vented-box port.','A passive radiator looks like a speaker but has no magnet or coil. The trapped box air makes it vibrate. It boosts the deep bass like a port does. Its weight sets the tuning frequency.','It extends and tunes low-frequency output without the port noise or length that a vented enclosure would need.','A designer replaces a long port with a passive radiator and adds mass to it, lowering the tuning frequency to reinforce deep bass in a small cabinet.','Enclosure / Loading',ARRAY['Vented enclosure','Port','Enclosure tuning','Moving mass','Compliance']::text[],ARRAY['Thinking the passive radiator is powered like a normal driver.','Undersizing it, so it moves beyond its safe excursion limit and distorts below tuning.','Ignoring that added mass lowers the tuning frequency.']::text[],ARRAY['Tuning a compact subwoofer without a long port.','Replacing a noisy port with a drone cone.','Adjusting bass extension by changing radiator mass.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Passive radiators');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ddabc66a-5457-41f8-9449-e30d13432184','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ddabc66a-5457-41f8-9449-e30d13432184') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ddabc66a-5457-41f8-9449-e30d13432184');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39f0f5da-56a3-4c2a-a07b-64d24a4bf54b','Pattern collapse','Pattern collapse is the undesired narrowing or loss of a loudspeaker''s intended coverage at certain frequencies. It commonly occurs as high-frequency beaming, where the radiating aperture becomes large relative to the wavelength, or from destructive interference between drivers.','A speaker is meant to cover a set angle. At some frequencies the coverage suddenly narrows. This is pattern collapse. It often happens high up, where the source is large compared to the wavelength, so sound beams forward.','It names a directivity fault so technicians can predict where coverage narrows and avoid uneven audience response.','A technician measures a horn narrowing sharply above a few kilohertz and recognises pattern collapse, then adjusts driver spacing or crossover to keep coverage even.','Directivity',ARRAY['Directivity','Beaming','Lobing','Pattern flip','Coverage angle']::text[],ARRAY['Assuming coverage stays constant across all frequencies.','Confusing beaming (single source) with lobing (multiple sources).','Spacing drivers too far apart, causing interference and collapse.']::text[],ARRAY['Explaining narrow high-frequency coverage from a large diaphragm.','Choosing driver spacing to avoid interference.','Predicting uneven audience coverage.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pattern collapse');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39f0f5da-56a3-4c2a-a07b-64d24a4bf54b','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39f0f5da-56a3-4c2a-a07b-64d24a4bf54b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39f0f5da-56a3-4c2a-a07b-64d24a4bf54b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e4533c52-75c5-45d6-b812-9d4bd0e6b344','Pattern flip','Pattern flip is a frequency-dependent behavior of some constant-directivity horns in which the planes of narrow and wide coverage effectively interchange over part of the band. It arises from the differing mouth dimensions and diffraction in the horizontal and vertical planes.','A horn is designed to be wide one way and narrow the other. At some frequencies these can swap, so the narrow and wide directions trade places. This is pattern flip. It comes from the horn''s different mouth sizes in each plane.','It warns designers and technicians that a horn''s coverage in each plane may not stay consistent across frequency.','A technician checking horizontal and vertical polar data notices the narrow axis shift from vertical to horizontal over a frequency band, a sign of pattern flip when aiming a system.','Directivity',ARRAY['Constant-directivity horn','Pattern collapse','Coverage angle','Diffraction','Directivity']::text[],ARRAY['Assuming a horn''s horizontal and vertical coverage stay fixed with frequency.','Aiming a system from a single nominal coverage angle.','Confusing pattern flip with overall pattern collapse.']::text[],ARRAY['Interpreting a horn''s polar plots across frequency.','Aiming horns for even coverage.','Comparing horn designs for pattern consistency.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pattern flip');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e4533c52-75c5-45d6-b812-9d4bd0e6b344','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e4533c52-75c5-45d6-b812-9d4bd0e6b344') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e4533c52-75c5-45d6-b812-9d4bd0e6b344');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5d2acc02-01b0-40bf-a7b0-c566c575805c','Permeability','Permeability is a material''s ability to support a magnetic field, defined as the ratio of magnetic flux density to magnetic field strength. In a loudspeaker motor it governs how effectively pole pieces and plates carry flux into the gap. Relative permeability compares a material to free space.','Permeability shows how easily a material carries magnetic flux. High-permeability steel guides the magnet''s field into the gap. Free space has low permeability. Motor parts use soft iron to channel the field where the coil sits.','It quantifies how well motor materials conduct magnetic flux, which sets the field strength in the voice-coil gap.','For a soft-iron pole with relative permeability about 4000, the permeability is mu = 4000 * (4*pi*10^-7) = 5.0 * 10^-3 H/m, far higher than air.','Magnetics',ARRAY['Magnetic flux','Flux density','Pole piece','Magnetic saturation','Force factor']::text[],ARRAY['Confusing permeability of the pole material with the magnet''s own strength.','Ignoring that permeability falls sharply near magnetic saturation.','Mixing up relative permeability with absolute permeability.']::text[],ARRAY['Choosing pole and plate steel for a motor.','Explaining flux focusing in the gap.','Understanding saturation-related distortion.']::text[],'Intermediate','mu = B / H  (mu = mu_r * mu_0)','Permeability equals magnetic flux density divided by magnetic field strength; it also equals relative permeability times the permeability of free space.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Permeability');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5d2acc02-01b0-40bf-a7b0-c566c575805c','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5d2acc02-01b0-40bf-a7b0-c566c575805c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5d2acc02-01b0-40bf-a7b0-c566c575805c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b9a704d0-9cc5-4997-871d-982cdf99a741','Phase plugs','A phase plug, or phasing plug, is a shaped body placed between a diaphragm and a horn throat, or in front of a cone, that provides nearly equal-length acoustic paths from different parts of the diaphragm. This alignment prevents high-frequency cancellations that would otherwise occur when path lengths differ.','In a compression driver the dome radiates into a small throat. Sound from the centre and edge would travel different distances and cancel. A phase plug adds channels of matched length. This keeps the high frequencies from cancelling.','It equalises acoustic path lengths so a driver keeps smooth high-frequency output into a horn or waveguide.','A technician inspecting a compression driver sees a slotted phase plug ahead of the diaphragm, whose channels keep the top octave from dropping out.','Compression Driver / Construction',ARRAY['Compression driver','Horn','Diaphragm','Throat','Waveguide']::text[],ARRAY['Thinking the phase plug is only a spacer, not an acoustic path-matching device.','Ignoring that a damaged or misaligned plug causes high-frequency dips.','UNSAFE: prying a phase plug against a compression diaphragm can dent or tear the thin foil and ruin the driver.']::text[],ARRAY['Explaining smooth high-frequency output from a compression driver.','Diagnosing top-octave loss from a damaged plug.','Comparing phase-plug designs in horn drivers.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase plugs');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b9a704d0-9cc5-4997-871d-982cdf99a741','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b9a704d0-9cc5-4997-871d-982cdf99a741') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b9a704d0-9cc5-4997-871d-982cdf99a741');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '92487c7d-b175-4b03-9001-429025158b48','Piezoelectric driver','A loudspeaker driver that produces sound by the piezoelectric effect: an applied audio voltage deforms a ceramic element (commonly PZT) that is bonded to or drives a diaphragm. It presents a largely capacitive load and is most often used for high-frequency tweeters, buzzers, and alarms.','This driver uses a special ceramic that bends when voltage is applied. The bending pushes a diaphragm to make sound. It acts like a capacitor, not a normal coil. You often see it in cheap tweeters and beepers.','It converts electrical signals to sound without a magnet or voice coil, giving a rugged, low-cost high-frequency or alarm transducer.','A technician drives it from the amplifier, sometimes with a series resistor, and treats it as a capacitive load rather than a nominal 8-ohm resistive one.','Transducer Type',ARRAY['Ribbon driver','Surface exciter','Compression driver','Diaphragm materials']::text[],ARRAY['Assuming it behaves like an 8-ohm resistive driver; its impedance is mostly capacitive and rises at low frequency.','Expecting deep bass; piezo elements are efficient only at high frequencies.','UNSAFE: Handling or driving large piezo elements at high voltage without discharging them; the ceramic can retain charge and deliver a shock.']::text[],ARRAY['Selecting a rugged tweeter for an outdoor paging horn.','Diagnosing why a piezo tweeter measures open at DC.','Specifying an alarm or buzzer transducer for a fire panel.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Piezoelectric driver');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '92487c7d-b175-4b03-9001-429025158b48','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='92487c7d-b175-4b03-9001-429025158b48') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='92487c7d-b175-4b03-9001-429025158b48');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5ea8c234-bef0-4c9e-bf94-8fa8fc2a2815','Piston-band operation','The frequency range in which a loudspeaker diaphragm moves as a single rigid body, with all points in phase, so that radiation follows simple piston theory. It holds while the acoustic wavelength is large compared with the diaphragm, roughly for ka below about 2, above which cone break-up begins.','In this range the whole cone moves together like a solid piston. Every part pushes the air in step. This happens when the sound wavelength is much larger than the cone. Above it the cone flexes and breaks up.','It defines where a driver behaves predictably and where simple radiation models and Thiele-Small theory apply.','For a 25 cm woofer (a about 0.10 m) the piston band ends near ka=2, giving f = 2c/(2 pi a) = 2*345/(2*pi*0.10) about 1.1 kHz, so it is crossed over below break-up.','Radiation Behavior',ARRAY['Radial mode','Point-source approximation','Resonance frequency','Radiation mass','Small-signal model']::text[],ARRAY['Assuming a driver stays pistonic across its whole range; break-up starts once the wavelength nears the cone size.','Confusing the piston band with the flat part of the frequency response.','Ignoring that a larger cone leaves the piston band at a lower frequency.']::text[],ARRAY['Choosing a crossover point below a woofer''s break-up region.','Explaining why small drivers stay pistonic to higher frequencies.','Interpreting where a measured response begins to show ragged peaks.']::text[],'Intermediate','ka = 2*pi*a/lambda = 2*pi*f*a/c','The dimensionless product ka equals two pi times the diaphragm radius divided by the wavelength; pistonic operation holds roughly while ka is below about 2.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Piston-band operation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5ea8c234-bef0-4c9e-bf94-8fa8fc2a2815','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5ea8c234-bef0-4c9e-bf94-8fa8fc2a2815') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5ea8c234-bef0-4c9e-bf94-8fa8fc2a2815');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c671addc-b8b9-4352-9d8a-b1949509bfe1','Point-source approximation','A modeling simplification that treats a sound source as a single point radiating spherically, valid when the source is small compared with the wavelength and the listener is in the far field. Pressure then falls inversely with distance, giving a 6 dB drop per doubling of distance.','This treats a speaker as a single tiny point that radiates in all directions. It works when the source is small next to the wavelength. The level then drops by six decibels each time you double the distance. It is a handy design shortcut.','It lets engineers predict coverage and level versus distance with simple inverse-square math instead of full radiation models.','If a source gives 100 dB at 1 m, the point-source law predicts 100 - 20*log10(4/1) = 88 dB at 4 m in a free field.','Radiation Behavior',ARRAY['Piston-band operation','Sound-power response','Point source','Splay angles','Steering']::text[],ARRAY['Applying the 6 dB rule to a line array, which behaves more like a line source and rolls off slower.','Using it in the near field or in a reverberant room where the inverse-square law fails.','Forgetting that it only holds when the source is small compared with the wavelength.']::text[],ARRAY['Estimating throw and level loss for a small point-source speaker.','Comparing point-source versus line-array coverage.','Setting expected far-field level for a coverage prediction.']::text[],'Intermediate','L2 = L1 - 20*log10(r2/r1)','The sound level at a far distance equals the level at a reference distance minus twenty times the base-ten logarithm of the ratio of the two distances.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Point-source approximation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c671addc-b8b9-4352-9d8a-b1949509bfe1','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c671addc-b8b9-4352-9d8a-b1949509bfe1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c671addc-b8b9-4352-9d8a-b1949509bfe1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44b1c5c8-1cba-4386-ad46-bc3daaf21b45','Port air velocity','The speed of air moving through a vent (port) of a bass-reflex enclosure, set by the cone''s volume velocity divided by the port cross-sectional area. Excessive velocity causes turbulent chuffing noise and port compression, so designers keep the peak value well below the speed of sound.','This is how fast air rushes through the speaker''s port. It depends on how much air the cone moves and how big the port is. If the air moves too fast, the port makes a chuffing wind noise. Designers make ports big enough to keep the speed low.','It flags when a vent is too small, which would add turbulence noise and limit low-frequency output.','For a cone of area SD=0.033 m^2 at peak velocity 1 m/s and a port area Sp=0.008 m^2, port velocity = (0.033/0.008)*1 about 4 m/s, safely below the roughly 17 m/s chuffing threshold.','Enclosure Design',ARRAY['Ported enclosures','Sensitivity compression','Rub-and-buzz distortion']::text[],ARRAY['Making a port too narrow to fit the cabinet, which raises velocity and causes chuffing.','Assuming velocity is worst at the tuning frequency; peak displacement and chuffing often occur below tuning.','Ignoring that flaring the port ends reduces turbulence at a given velocity.']::text[],ARRAY['Diagnosing a whooshing noise from a subwoofer at high level.','Sizing a vent so peak velocity stays under about 17 m/s.','Choosing a flared port to cut turbulence.']::text[],'Advanced','u_p = (S_D / S_p) * u_D','Port air velocity equals the diaphragm area divided by the port area, multiplied by the diaphragm velocity, because the volume of air per second must be equal through both.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Port air velocity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44b1c5c8-1cba-4386-ad46-bc3daaf21b45','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44b1c5c8-1cba-4386-ad46-bc3daaf21b45') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44b1c5c8-1cba-4386-ad46-bc3daaf21b45');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8987415-e92d-41f2-9d75-d4c3a15a6a57','Ported enclosures','A loudspeaker cabinet with a tuned vent (port) that forms a Helmholtz resonator with the enclosed air, so the port radiates in phase with the cone near the tuning frequency and extends low-frequency output. Also called bass-reflex or vented-box systems, they are analysed with Thiele-Small vented-box theory.','This cabinet has an open tube called a port. The port and the trapped air form a resonator, like blowing across a bottle. Near tuning, the port adds bass output. This lets a speaker go lower than a fully sealed box.','It uses port resonance to boost and extend low-frequency output and reduce cone excursion near the tuning frequency.','A tech tunes the box with fb = (c/2*pi)*sqrt(Sp/(Vb*Leff)); for Sp=0.008 m^2, Vb=0.05 m^3, effective length 0.15 m, fb about 56 Hz.','Enclosure Design',ARRAY['Sealed enclosures','Port air velocity','System resonance','Ql','Tapered quarter-wave tube']::text[],ARRAY['Thinking below tuning the port helps; there the cone unloads and excursion rises sharply.','UNSAFE: Driving a vented box hard below its tuning frequency, where cone unloading can over-excurse and mechanically destroy the driver.','Confusing box tuning frequency with the driver''s free-air resonance.']::text[],ARRAY['Adding a high-pass filter to protect a vented sub below tuning.','Choosing a vented alignment for extra low-end extension.','Measuring impedance to confirm the box tuning frequency.']::text[],'Intermediate','f_b = (c / (2*pi)) * sqrt(S_p / (V_b * L_eff))','The box tuning frequency equals the speed of sound over two pi, times the square root of the port area divided by the product of box volume and effective port length.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ported enclosures');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8987415-e92d-41f2-9d75-d4c3a15a6a57','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8987415-e92d-41f2-9d75-d4c3a15a6a57') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8987415-e92d-41f2-9d75-d4c3a15a6a57');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b33e444c-3d8a-4127-8705-338bc258715c','Qa','In vented-box loudspeaker theory, the quality factor that represents enclosure losses caused by acoustic absorption in the box lining and damping material. A lower Qa means more absorption loss, which reduces and broadens the system''s low-frequency resonance.','This is a number for losses from padding inside the box. Soft lining soaks up some sound energy. A lower value means more energy is lost to the padding. It is one of three loss numbers used to model a vented box.','It lets a designer account for how internal damping material dissipates energy when predicting vented-box response.','A tech adding fiberglass lining lowers Qa, which slightly damps and broadens the tuning; models combine it with Ql and Qp into a total box loss.','Enclosure Parameter',ARRAY['Ql','Qp','Ported enclosures','System resonance','Small-signal model']::text[],ARRAY['Confusing the box-loss quality factors (Qa, Ql, Qp) with the driver''s own Q factors (Qms, Qes, Qts); Qa is an enclosure absorption-loss term, not a driver parameter.','Assuming heavy stuffing only lowers tuning; it also changes Qa and effective volume.','Treating box losses as negligible; real cabinets always have finite Qa, Ql, and Qp.']::text[],ARRAY['Modeling a lined vented cabinet in design software.','Explaining why added damping broadens a resonance peak.','Separating absorption loss from leakage loss in analysis.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Qa');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b33e444c-3d8a-4127-8705-338bc258715c','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b33e444c-3d8a-4127-8705-338bc258715c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b33e444c-3d8a-4127-8705-338bc258715c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4d2c0518-0edd-4e13-b25d-94c3c8bbd0ca','Ql','In vented-box theory, the quality factor representing enclosure leakage losses, mainly air escaping through seams, seals, and gaskets. It is the dominant box-loss term in most designs; a value of about 7 is a common default for a reasonably tight, unlined cabinet.','This number describes air leaking out of the box through gaps. A tight box leaks little and has a high value, around 7. A leaky box has a low value. It is usually the main loss term in vented-box design.','It captures how enclosure air leaks dissipate energy, shaping the height and sharpness of the low-frequency resonance.','Designers typically assume Ql about 7 for a well-sealed vented box, then adjust the alignment if the cabinet is known to be leakier.','Enclosure Parameter',ARRAY['Qa','Qp','Ported enclosures','Resonant impedance peak','System resonance']::text[],ARRAY['Assuming a perfectly lossless box; real enclosures have finite Ql from leaks and seals.','Confusing Ql with the driver''s Qes or Qms.','Using an unrealistically high Ql that predicts a sharper peak than the real cabinet gives.']::text[],ARRAY['Setting a default Ql of 7 in vented-box design software.','Explaining why a poorly gasketed cabinet measures a lower, broader impedance dip.','Comparing predicted and measured box tuning.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ql');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4d2c0518-0edd-4e13-b25d-94c3c8bbd0ca','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4d2c0518-0edd-4e13-b25d-94c3c8bbd0ca') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4d2c0518-0edd-4e13-b25d-94c3c8bbd0ca');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a5c97309-1cd0-470d-b62a-56550022e5f9','Qp','In vented-box theory, the quality factor representing viscous and frictional losses in the port (vent) itself as air moves through it. Narrow or long ports have lower Qp and dissipate more energy, which can reduce output near tuning.','This number describes energy lost by friction inside the port. Air rubbing against the port walls wastes some energy. A narrow port loses more and has a lower value. It is one of the three vented-box loss numbers.','It models frictional dissipation in the vent so predictions of vented-box output near tuning stay accurate.','A tech choosing a very small-diameter port should expect a lower Qp, more port loss, and reduced output at the tuning frequency.','Enclosure Parameter',ARRAY['Qa','Ql','Port air velocity','Ported enclosures','System resonance']::text[],ARRAY['Ignoring port friction in small or long vents, which overstates predicted output.','Confusing Qp with Ql; port loss and leakage loss are distinct mechanisms.','Assuming a larger port always helps; it changes tuning and effective length too.']::text[],ARRAY['Assessing losses in a long, narrow tuning vent.','Explaining reduced output near tuning in a restricted port.','Combining Qa, Ql, and Qp into a total box loss factor.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Qp');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a5c97309-1cd0-470d-b62a-56550022e5f9','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a5c97309-1cd0-470d-b62a-56550022e5f9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a5c97309-1cd0-470d-b62a-56550022e5f9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1752fc83-ca2e-4a32-8caf-23f6c11b01b8','Quasi-static measurement','A characterization method that drives a transducer so slowly, or at such low frequency, that inertial and radiation effects are negligible and the response reflects only static properties such as suspension stiffness, force factor, and inductance versus displacement. It is used to map large-signal, position-dependent parameters like BL(x), Kms(x), and Le(x).','This test moves the cone very slowly or with a slow signal. At that speed, mass and air load barely matter. So the result shows only static traits, like stiffness and motor force. It reveals how these change as the cone moves in and out.','It isolates the position-dependent, nonlinear parameters of a driver by removing dynamic and inertial effects.','An engineer uses a laser displacement sensor and slow current steps to plot BL and stiffness versus cone position, revealing motor and suspension asymmetry.','Measurement Method',ARRAY['Small-signal model','Rest-position offset','Rub-and-buzz distortion','Resonance frequency']::text[],ARRAY['Confusing quasi-static parameters with small-signal ones; quasi-static reveals large-signal, position-dependent behavior.','Running the test too fast, so inertia and air load corrupt the static reading.','Assuming BL and stiffness are constant instead of varying with displacement.']::text[],ARRAY['Mapping BL(x) to find a driver''s linear excursion limit.','Detecting suspension asymmetry that causes a DC offset.','Validating a large-signal model against slow-drive data.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quasi-static measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1752fc83-ca2e-4a32-8caf-23f6c11b01b8','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1752fc83-ca2e-4a32-8caf-23f6c11b01b8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1752fc83-ca2e-4a32-8caf-23f6c11b01b8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b27bc9d0-b307-4599-a6ce-c2eb92e30377','Radial mode','A cone break-up vibration in which bending waves travel radially between the cone''s center and rim, forming concentric nodal rings so the diaphragm no longer moves as one piece. Radial modes appear above the piston band and create peaks and dips in the response.','At high frequencies the cone stops moving as one piece. Waves ripple out from the center to the rim. This forms rings that move in opposite directions. These radial modes add sharp bumps to the response.','It explains why response gets ragged above the piston band and guides cone material and shape choices to tame break-up.','A tech seeing a sharp peak near the top of a woofer''s range identifies a radial break-up mode and crosses over below it or adds cone damping.','Radiation Behavior',ARRAY['Piston-band operation','Tensile strength','Diaphragm materials','Resonance frequency','Rub-and-buzz distortion']::text[],ARRAY['Confusing a radial break-up mode with the fundamental resonance frequency.','Assuming a stiffer cone removes break-up; it usually just moves the modes higher and can make them sharper.','Trying to equalize a sharp break-up peak flat, which often sounds worse than crossing over below it.']::text[],ARRAY['Interpreting a ragged upper-woofer response as cone break-up.','Choosing a coated or damped cone to reduce mode peaks.','Setting a low-pass crossover below the first radial mode.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radial mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b27bc9d0-b307-4599-a6ce-c2eb92e30377','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b27bc9d0-b307-4599-a6ce-c2eb92e30377') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b27bc9d0-b307-4599-a6ce-c2eb92e30377');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '260f2e48-fef2-4988-8f11-41171253a193','Radiation mass','The effective mass of the air load that moves with a vibrating diaphragm, adding to its mechanical moving mass and lowering the system resonance. For a rigid circular piston in an infinite baffle at low frequency, the added mass on one side is (8/3) times air density times radius cubed, equivalent to an end correction of about 0.85 radii.','When a cone moves, it drags nearby air with it. That air acts like extra mass on the cone. This added air mass lowers the resonance a little. It is called the radiation mass or air load.','It accounts for the air-load mass a diaphragm carries, which must be added to the cone mass in resonance and modeling calculations.','For a piston of radius a=0.10 m in a baffle with air density 1.2 kg/m^3, added mass per side = (8/3)*1.2*0.10^3 about 3.2 g, which lowers fs.','Radiation Behavior',ARRAY['Resonance frequency','Piston-band operation','Small-signal model','Point-source approximation']::text[],ARRAY['Forgetting to add the air-load mass, which makes the predicted resonance too high.','Assuming the air mass is constant; it decreases as frequency rises out of the piston band.','Counting only one side when a driver radiates from both faces.']::text[],ARRAY['Correcting a resonance calculation for air loading.','Explaining why an in-baffle fs differs from free-air fs.','Modeling the mechanical load on a small piston.']::text[],'Advanced','M_rad = (8/3) * rho0 * a^3   (one side, baffled piston, low frequency)','The radiation mass on one side of a baffled piston at low frequency equals eight thirds times the air density times the piston radius cubed.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radiation mass');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '260f2e48-fef2-4988-8f11-41171253a193','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='260f2e48-fef2-4988-8f11-41171253a193') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='260f2e48-fef2-4988-8f11-41171253a193');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '137521d4-c90f-457b-a670-49acf5c508e9','Resonance frequency','The free-air fundamental resonance of a loudspeaker driver, denoted fs, where the moving mass and suspension compliance exchange energy and cone motion is greatest for a given force. It equals one over two pi times the square root of the product of moving mass and suspension compliance.','This is the natural bounce frequency of the cone on its springy suspension. At this frequency the cone moves most easily. It is set by the moving mass and the springiness. Engineers call it fs.','It is a core Thiele-Small parameter that sets a driver''s low-frequency limit and guides enclosure design.','For a moving mass Mms=20 g and compliance Cms=1.0 mm/N, fs = 1/(2*pi*sqrt(0.020*0.001)) about 36 Hz.','Driver Parameter',ARRAY['Resonant impedance peak','System resonance','Radiation mass','Small-signal model','Sealed enclosures']::text[],ARRAY['Confusing free-air fs with the in-box system resonance, which is higher.','Assuming fs is fixed; suspension break-in and temperature shift it.','Forgetting that fs already includes the air-load mass in Mms.']::text[],ARRAY['Reading fs from a driver datasheet to plan a box.','Measuring the impedance peak to find fs.','Explaining why a heavier cone lowers fs.']::text[],'Intermediate','f_s = 1 / (2*pi*sqrt(M_ms * C_ms))','The resonance frequency equals one divided by two pi times the square root of the moving mass multiplied by the suspension compliance.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resonance frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '137521d4-c90f-457b-a670-49acf5c508e9','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='137521d4-c90f-457b-a670-49acf5c508e9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='137521d4-c90f-457b-a670-49acf5c508e9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0dfa882a-9e68-4e5f-82ec-88f38917bb8a','Resonant impedance peak','The peak in a driver''s electrical impedance magnitude that occurs at its resonance frequency, caused by the back-EMF from maximum cone velocity. The ratio of this peak to the DC resistance, together with the peak''s bandwidth, yields the mechanical and electrical Q factors.','At resonance the cone moves fastest and pushes back electrically. This makes the driver''s impedance rise to a peak. The height and width of this peak reveal the Q values. Engineers read them from an impedance sweep.','It provides the measurable basis for finding fs, Qms, Qes, and Qts from an impedance curve.','With peak-to-DC ratio r0 = Zmax/Re and mechanical Q found from bandwidth, Qes = Qms/(r0 - 1); e.g. Qms=3, r0=16 gives Qes = 3/15 = 0.2.','Measurement Method',ARRAY['Resonance frequency','Small-signal model','Sensitivity versus efficiency','Ql']::text[],ARRAY['Reading fs at the impedance minimum instead of the peak.','Using nominal impedance instead of the measured DC resistance Re for r0.','Ignoring that a vented box splits the single peak into two.']::text[],ARRAY['Deriving T-S parameters from an impedance sweep.','Confirming box tuning by the twin-peak vented impedance curve.','Checking a driver''s resonance after a reconing.']::text[],'Intermediate','r0 = Z_max / R_e ;  Q_es = Q_ms / (r0 - 1)','The resonance impedance ratio equals the peak impedance divided by the DC resistance; electrical Q equals mechanical Q divided by that ratio minus one.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resonant impedance peak');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0dfa882a-9e68-4e5f-82ec-88f38917bb8a','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0dfa882a-9e68-4e5f-82ec-88f38917bb8a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0dfa882a-9e68-4e5f-82ec-88f38917bb8a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f949c4a6-4c04-4089-9280-09430e974de5','Rest-position offset','A shift of the voice coil''s average (DC) position away from its intended rest point during signal reproduction, produced by asymmetries in the force factor BL(x) or suspension stiffness Kms(x). The coil drifts toward the region of lower stiffness or force, which raises distortion and can cause the coil to hit its limits.','Ideally the cone swings evenly around a center point. If the motor or suspension is lopsided, the cone drifts to one side while playing. This off-center drift is the rest-position offset. It adds distortion and risks bottoming out.','It flags motor and suspension asymmetry that pushes the coil off center and limits safe, clean excursion.','A tech measuring a growing DC displacement at high drive levels traces it to an asymmetric BL(x) curve and considers a driver with better motor symmetry.','Distortion Mechanism',ARRAY['Quasi-static measurement','Rub-and-buzz distortion','Small-signal model','Resonance frequency']::text[],ARRAY['Assuming the coil always stays centered; asymmetry makes it drift under drive.','UNSAFE: Pushing a driver with a large DC offset to full excursion, where the coil bottoms out and can be mechanically damaged.','Confusing this dynamic offset with a permanent miscentered assembly.']::text[],ARRAY['Diagnosing rising distortion as level climbs.','Explaining coil bottoming that only appears at high output.','Comparing motor symmetry between two subwoofers.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rest-position offset');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f949c4a6-4c04-4089-9280-09430e974de5','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f949c4a6-4c04-4089-9280-09430e974de5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f949c4a6-4c04-4089-9280-09430e974de5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '82976057-0b10-4946-8fc6-94e3581d1945','Ribbon driver','A transducer whose diaphragm is a thin, corrugated conductive ribbon (often aluminum) suspended in a strong magnetic field; the audio current flows directly through the ribbon, which serves as both conductor and radiator. Its impedance is very low, so it is usually driven through a step-up transformer.','This driver uses a thin metal strip as both the wire and the diaphragm. Current runs through the strip inside a magnet gap. The strip then vibrates and makes sound. Its resistance is tiny, so it needs a matching transformer.','It provides a very low-mass diaphragm for extended, detailed high-frequency response, common in ribbon tweeters and some microphones.','A tech matches the ribbon''s fraction-of-an-ohm impedance to the amplifier with the built-in transformer and avoids DC or air blasts that can stretch the ribbon.','Transducer Type',ARRAY['Piezoelectric driver','Compression driver','Surface exciter','Tensile strength','Diaphragm materials']::text[],ARRAY['Connecting a bare ribbon directly to an amplifier; its sub-ohm impedance needs the matching transformer.','UNSAFE: Handling or driving a delicate ribbon near strong magnets carelessly; the assembly uses powerful magnets that can pinch and attract tools.','Blowing or sending DC into a ribbon, which permanently stretches or tears it.']::text[],ARRAY['Specifying a ribbon tweeter for a hi-fi system.','Explaining why a ribbon needs a step-up transformer.','Servicing a stretched or sagging ribbon element.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ribbon driver');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '82976057-0b10-4946-8fc6-94e3581d1945','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='82976057-0b10-4946-8fc6-94e3581d1945') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='82976057-0b10-4946-8fc6-94e3581d1945');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '89f844ca-2ea0-44bf-8bb4-0f6660fab2ba','Rub-and-buzz distortion','A high-order, impulsive nonlinear distortion caused by mechanical defects such as a voice coil rubbing the gap, loose particles, glue-joint buzzes, or a touching lead wire. It produces sharp, audible artifacts rich in high harmonics and is a common end-of-line and warranty defect check.','This is a scratchy or buzzy noise from a physical fault in the driver. The coil may rub the gap, or a part may be loose. It adds harsh high-frequency junk to the sound. Factories test for it to catch defects.','It is a key quality-control symptom that reveals mechanical faults a smooth frequency response would miss.','A tech sweeps a driver at moderate level and listens or measures high-order harmonics; a sudden buzz at certain frequencies signals a rubbing coil or loose particle.','Distortion Mechanism',ARRAY['Rest-position offset','Radial mode','Quasi-static measurement','Sensitivity compression']::text[],ARRAY['Confusing rub-and-buzz with normal harmonic distortion; it is defect-driven and impulsive.','Testing only at low level, where a marginal rub may not appear.','Assuming a flat frequency response means the driver is defect-free.']::text[],ARRAY['End-of-line quality testing of new drivers.','Diagnosing a scratchy woofer after abuse.','Confirming a warranty defect before reconing.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rub-and-buzz distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '89f844ca-2ea0-44bf-8bb4-0f6660fab2ba','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='89f844ca-2ea0-44bf-8bb4-0f6660fab2ba') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='89f844ca-2ea0-44bf-8bb4-0f6660fab2ba');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f70aef79-7e86-468f-8d01-26a44d1d2628','Sealed enclosures','A fully closed loudspeaker cabinet in which the trapped air acts as an added spring on the cone, raising the system resonance and total Q above the driver''s free-air values. Also called acoustic-suspension or closed-box systems, they give a gentle 12 dB per octave low-frequency roll-off and good transient behavior.','This is a fully sealed box with no port. The trapped air acts like an extra spring on the cone. That spring raises the resonance and tightens the bass. Sealed boxes roll off gently and handle transients well.','It uses the enclosed air''s stiffness to control cone motion, giving predictable, well-damped low-frequency response.','System resonance rises to fc = fs*sqrt(1 + Vas/Vb); for fs=30 Hz, Vas=0.05 m^3, Vb=0.025 m^3, fc = 30*sqrt(3) about 52 Hz.','Enclosure Design',ARRAY['Ported enclosures','System resonance','Resonance frequency','Small-signal model','Sensitivity versus efficiency']::text[],ARRAY['Assuming a smaller sealed box just plays quieter; it also raises fc and Qtc.','UNSAFE: Applying a large low-frequency boost to compensate for a small sealed box, which can over-excurse and overheat the driver.','Expecting the deep extension of a vented box from an equal-size sealed box.']::text[],ARRAY['Choosing a sealed alignment for tight, accurate bass.','Sizing a box for a target Qtc of about 0.7.','Explaining the 12 dB per octave sealed roll-off.']::text[],'Intermediate','f_c = f_s * sqrt(1 + V_as/V_b) ;  Q_tc = Q_ts * sqrt(1 + V_as/V_b)','The closed-box resonance equals the free-air resonance times the square root of one plus the ratio of equivalent volume to box volume; total Q scales the same way.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sealed enclosures');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f70aef79-7e86-468f-8d01-26a44d1d2628','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f70aef79-7e86-468f-8d01-26a44d1d2628') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f70aef79-7e86-468f-8d01-26a44d1d2628');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8bb52b6a-e6a3-455b-87fc-ad0fb1668fb5','Sensitivity compression','A reduction in a loudspeaker''s output sensitivity at high drive levels, mainly because voice-coil heating raises the coil''s resistance so less current flows for a given voltage. Also called power compression, it is measured as the dB shortfall between actual output and the level a linear device would produce.','When you push a speaker hard, the voice coil heats up. A hot coil has more resistance, so less current flows. The speaker then gets quieter than the input suggests. This loss of loudness is called power compression.','It quantifies how much real output falls short at high power, which matters for headroom and system design.','If a hot coil resistance rises from 6.0 to 10.7 ohms (about 200 C rise, copper coefficient 0.0039/C), output drops about 10*log10(10.7/6.0) about 2.5 dB.','Power Handling',ARRAY['Thermal modulation','Slow thermal time constant','Thermal capacitance','Sensitivity versus efficiency']::text[],ARRAY['Blaming amplifier clipping for output loss that is really thermal power compression.','UNSAFE: Adding more gain to overcome compression, which raises coil temperature further and can burn out the voice coil.','Assuming sensitivity from a low-level spec holds at high, sustained power.']::text[],ARRAY['Explaining why a PA sub sounds quieter after a long loud set.','Budgeting headroom for sustained high-level output.','Comparing power compression figures between drivers.']::text[],'Advanced','Delta_L = 10*log10(R_e_hot / R_e_cold) ;  R_e_hot = R_e_cold*(1 + alpha*Delta_T)','The compression in decibels is about ten times the base-ten logarithm of the ratio of hot to cold coil resistance, where the hot resistance rises with temperature.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sensitivity compression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8bb52b6a-e6a3-455b-87fc-ad0fb1668fb5','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8bb52b6a-e6a3-455b-87fc-ad0fb1668fb5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8bb52b6a-e6a3-455b-87fc-ad0fb1668fb5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '20b2b858-57ca-4841-b6cf-d58ab9244d56','Sensitivity versus efficiency','A distinction between two loudspeaker output ratings: efficiency is the fraction of electrical input power converted to acoustic power (often the reference efficiency eta0), while sensitivity is the sound pressure level at one metre for a standard input of one watt or 2.83 volts. They are related but not identical, since sensitivity depends on the drive convention and impedance.','Efficiency is how much electric power becomes sound power, as a percentage. Sensitivity is how loud a speaker is at one meter for a set input. The two are linked but not the same. Sensitivity depends on whether you use one watt or 2.83 volts.','It clarifies why a percentage efficiency and a dB sensitivity describe related but different aspects of loudspeaker output.','Reference efficiency eta0 = (4*pi^2/c^3)*(fs^3*Vas/Qes); for fs=30, Vas=0.1 m^3, Qes=0.4, eta0 about 0.0065, giving SPL about 112 + 10*log10(0.0065) about 90 dB.','Driver Parameter',ARRAY['Sensitivity compression','Resonance frequency','Sealed enclosures','Resonant impedance peak','Small-signal model']::text[],ARRAY['Treating 1 W and 2.83 V sensitivity as identical; they differ except at 8 ohms nominal.','Assuming higher sensitivity always means higher efficiency regardless of impedance.','Confusing a percentage efficiency figure with a dB sensitivity figure.']::text[],ARRAY['Comparing driver sensitivity specs fairly across impedances.','Estimating output level from Thiele-Small parameters.','Explaining why a 4-ohm driver''s 2.83 V spec flatters it.']::text[],'Intermediate','eta0 = (4*pi^2 / c^3) * (fs^3 * Vas / Qes) ;  SPL_1W1m approx 112 + 10*log10(eta0)','Reference efficiency equals four pi squared over the speed of sound cubed, times the cube of resonance frequency times equivalent volume divided by electrical Q; sensitivity is about 112 dB plus ten times the log of that efficiency.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sensitivity versus efficiency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '20b2b858-57ca-4841-b6cf-d58ab9244d56','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='20b2b858-57ca-4841-b6cf-d58ab9244d56') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='20b2b858-57ca-4841-b6cf-d58ab9244d56');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4be06b3b-b385-410f-8674-3e696c05d195','Slow thermal time constant','The longer thermal time constant of a loudspeaker''s heat model, associated with the large thermal mass of the magnet and frame that heats and cools over minutes rather than the seconds of the voice coil. It governs long-term average power handling and the slow rise of the driver''s overall temperature.','A speaker heats up in two stages. The voice coil warms in seconds, but the magnet and frame warm over minutes. That slow warming is the slow thermal time constant. It sets how much steady power the driver can take over time.','It models the slow heat build-up in the magnet and structure that limits sustained, long-term power handling.','With magnet-structure thermal resistance Rth=2 C/W and capacitance Cth=300 J/C, tau = Rth*Cth = 600 s, so the driver keeps warming for many minutes under load.','Power Handling',ARRAY['Thermal capacitance','Thermal modulation','Sensitivity compression']::text[],ARRAY['Assuming a driver reaches final temperature quickly; the magnet mass keeps heating for minutes.','UNSAFE: Running sustained high power assuming brief-burst ratings apply; slow heat build-up can overheat and ignite coil formers or adhesives.','Confusing the fast coil time constant with the slow structural one.']::text[],ARRAY['Rating long-term versus burst power handling.','Explaining delayed thermal compression during a long show.','Modeling driver cooling between sets.']::text[],'Advanced','tau_slow = R_th * C_th','The slow thermal time constant equals the thermal resistance from the structure to the surroundings multiplied by the thermal capacitance of the magnet and frame.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Slow thermal time constant');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4be06b3b-b385-410f-8674-3e696c05d195','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4be06b3b-b385-410f-8674-3e696c05d195') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4be06b3b-b385-410f-8674-3e696c05d195');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '94a99954-9ac5-4593-80ac-bc942a9e1960','Small-signal model','A linear, lumped-element representation of a loudspeaker valid at low drive levels, where force factor BL, suspension compliance, and inductance are treated as constants. It underlies the Thiele-Small parameters and predicts frequency response, impedance, and resonance in the driver''s linear operating region.','This is a simple model of a speaker at low volume. It treats the motor force and springiness as fixed numbers. That makes the math linear and easy. It gives us the Thiele-Small parameters used for box design.','It provides the linear framework behind Thiele-Small analysis, letting engineers predict low-level behavior and design enclosures.','A tech measures small-signal T-S parameters at low level, then uses them to model a box, knowing they will not hold at high excursion.','Modeling',ARRAY['Quasi-static measurement','Resonance frequency','Resonant impedance peak','Sealed enclosures','Sensitivity versus efficiency']::text[],ARRAY['Applying small-signal parameters at high drive, where nonlinearities dominate.','Assuming BL and compliance stay constant with excursion.','Measuring parameters at too high a level, which biases the results.']::text[],ARRAY['Extracting T-S parameters for enclosure design.','Explaining why box predictions fail at high excursion.','Distinguishing linear from large-signal driver behavior.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Small-signal model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '94a99954-9ac5-4593-80ac-bc942a9e1960','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='94a99954-9ac5-4593-80ac-bc942a9e1960') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='94a99954-9ac5-4593-80ac-bc942a9e1960');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '27220cca-1a6b-4377-bdc1-29bce5ce0044','Sound-power response','The total acoustic power a loudspeaker radiates into the surrounding space as a function of frequency, integrating output over all directions rather than along one axis. It reflects how the reverberant field is energized and often differs from the on-axis response because directivity changes with frequency.','This is the total sound energy a speaker sends out in every direction, versus frequency. It sums output over the whole sphere, not just straight ahead. It shapes the reflected sound you hear in a room. It often differs from the on-axis curve.','It describes the energy a speaker feeds into a room, which governs perceived tonal balance in reverberant listening.','In a free field, W = (p_rms^2/(rho0*c))*4*pi*r^2; for p_rms=1 Pa at r=1 m, W = (1/(1.2*345))*4*pi about 0.030 W.','Radiation Behavior',ARRAY['Point-source approximation','Sensitivity versus efficiency','Splay angles','Steering']::text[],ARRAY['Assuming on-axis response equals the power response; directivity makes them differ.','Ignoring that narrowing directivity at high frequency drops the power response.','Using a single-axis measurement to judge reverberant-field balance.']::text[],ARRAY['Predicting tonal balance in a reverberant room.','Comparing on-axis and power responses of a speaker.','Assessing how directivity shapes radiated energy.']::text[],'Advanced','W = (p_rms^2 / (rho0*c)) * 4*pi*r^2   (free-field point source)','Radiated sound power equals the mean-square pressure divided by the air''s characteristic impedance, times the surface area of a sphere at the measurement radius.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-power response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '27220cca-1a6b-4377-bdc1-29bce5ce0044','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='27220cca-1a6b-4377-bdc1-29bce5ce0044') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='27220cca-1a6b-4377-bdc1-29bce5ce0044');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '138047e3-ed0a-4a8b-8344-179432e2e41c','Splay angles','The mechanical angles set between adjacent enclosures in a line array or cluster, which determine how their coverage patterns overlap and how the array''s vertical or horizontal coverage is shaped. Correct splay matches each element''s angle to the audience geometry for even level and minimal gaps or overlap.','In a line array, boxes are angled relative to each other. These angles between boxes are the splay angles. They decide how the coverage spreads over the audience. Getting them right gives even sound front to back.','It shapes an array''s coverage so every seating area receives even level without gaps or excessive overlap.','A tech uses array-prediction software to set tighter splay at the top of an array for distant seats and wider splay at the bottom for near seats.','System Design',ARRAY['Steering','Point-source approximation','Sound-power response']::text[],ARRAY['Setting all splay angles equal, which over-covers near seats and under-covers far ones.','Confusing mechanical splay with electronic steering by delay.','Ignoring how splay affects inter-element interference and comb filtering.']::text[],ARRAY['Designing line-array coverage for a raked auditorium.','Adjusting splay to cover a balcony evenly.','Using prediction software to optimize array angles.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Splay angles');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '138047e3-ed0a-4a8b-8344-179432e2e41c','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='138047e3-ed0a-4a8b-8344-179432e2e41c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='138047e3-ed0a-4a8b-8344-179432e2e41c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8009759e-fa18-4dc3-bfff-319976c477da','Steering','Electronic aiming of an array''s coverage by applying controlled delay and level to individual drivers or elements, tilting the main lobe without moving the enclosure. In digitally steered column arrays, per-driver delay sets the beam angle, offering coverage control from a fixed physical position.','Steering aims the sound beam using electronics, not by tilting the box. Each driver gets a small delay. Those delays tilt the combined beam up or down. This lets a fixed column aim its sound where needed.','It lets a fixed array redirect its beam electronically, useful where mechanical aiming is impractical, as in reverberant rooms.','For a beam angle theta, per-element delay follows sin(theta) = c*Delta_t/d; a 0.5 ms delay across 0.5 m spacing steers about sin^-1(345*0.0005/0.5) about 20 degrees.','System Design',ARRAY['Splay angles','Point-source approximation','Sound-power response']::text[],ARRAY['Confusing electronic steering with mechanical splay of physical boxes.','Expecting unlimited steering; large angles raise side lobes and reduce output.','Ignoring that steering effectiveness depends on element spacing versus wavelength.']::text[],ARRAY['Aiming a steerable column array in a church.','Directing sound below a balcony without tilting hardware.','Explaining beam tilt from applied per-driver delay.']::text[],'Intermediate','sin(theta) = c * Delta_t / d','The sine of the steering angle equals the speed of sound times the delay between adjacent elements divided by the element spacing.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Steering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8009759e-fa18-4dc3-bfff-319976c477da','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8009759e-fa18-4dc3-bfff-319976c477da') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8009759e-fa18-4dc3-bfff-319976c477da');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7c05750e-9cea-437a-82df-2b293a85df85','Surface exciter','A compact electrodynamic actuator bonded to a panel so that the panel itself vibrates and radiates sound, the basis of distributed-mode and flat-panel loudspeakers. The exciter drives bending waves across the surface rather than moving a conventional cone.','A surface exciter is a small motor stuck to a flat panel. It shakes the panel so the panel makes sound. The whole surface becomes the speaker. This is how flat-panel and distributed-mode speakers work.','It turns an ordinary panel into a loudspeaker, enabling thin, hidden, or decor-integrated sound sources.','A tech bonds an exciter to a chosen panel and picks the mounting spot and panel material to spread modes evenly for smoother response.','Transducer Type',ARRAY['Piezoelectric driver','Ribbon driver','Radial mode','Diaphragm materials']::text[],ARRAY['Expecting deep, even bass from a thin panel with sparse modes.','Mounting the exciter at a panel node, which weakens output.','Assuming any panel works; material and size strongly shape the response.']::text[],ARRAY['Hiding speakers inside wall or ceiling panels.','Building a flat-panel distributed-mode loudspeaker.','Adding sound to a display or partition surface.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface exciter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7c05750e-9cea-437a-82df-2b293a85df85','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7c05750e-9cea-437a-82df-2b293a85df85') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7c05750e-9cea-437a-82df-2b293a85df85');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4b891eb2-9299-41f4-86d1-3269cd4257c1','System resonance','The fundamental resonance of a driver mounted in its enclosure, which for a sealed box (denoted fc) is higher than the driver''s free-air fs because the trapped air adds stiffness. It sets the low-frequency roll-off point of the finished loudspeaker system.','When a driver is put in a box, the box air stiffens the cone. This raises the resonance above the free-air value. That in-box resonance is the system resonance. It marks where the system''s bass begins to roll off.','It defines the finished system''s low-frequency limit, combining driver and enclosure into one resonance figure.','For a sealed box, fc = fs*sqrt(1 + Vas/Vb); a driver with fs=35 Hz, Vas=0.06 m^3 in Vb=0.03 m^3 gives fc = 35*sqrt(3) about 61 Hz.','Enclosure Design',ARRAY['Resonance frequency','Sealed enclosures','Ported enclosures','Small-signal model','Resonant impedance peak']::text[],ARRAY['Confusing system resonance fc with the driver''s free-air fs.','Assuming a bigger box always lowers fc without limit; it approaches fs as a floor.','Ignoring that a vented box has two resonant peaks, not one fc.']::text[],ARRAY['Predicting a sealed system''s roll-off frequency.','Explaining why a small box raises the tuning.','Comparing free-air and in-box resonance.']::text[],'Intermediate','f_c = f_s * sqrt(1 + V_as/V_b)   (sealed box)','The sealed-box system resonance equals the driver free-air resonance times the square root of one plus the ratio of equivalent volume to box volume.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='System resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4b891eb2-9299-41f4-86d1-3269cd4257c1','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4b891eb2-9299-41f4-86d1-3269cd4257c1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4b891eb2-9299-41f4-86d1-3269cd4257c1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '26c25b26-87f2-44c2-8df5-a4b0ff631754','Tapered quarter-wave tube','A loudspeaker enclosure built as an acoustic pipe roughly a quarter-wavelength long at its target frequency, with a changing cross-section (tapered) to control resonances. The tube resonates like an air column open at one end, reinforcing low frequencies; the classic Voigt pipe is an example.','This box is a long pipe about a quarter of a wavelength at the tuning tone. The pipe cross-section narrows or widens along its length. The air column resonates and boosts low notes. The old Voigt pipe is a famous version.','It uses a pipe''s quarter-wave resonance to extend and reinforce bass, an alternative to sealed and vented boxes.','An untapered quarter-wave line of length L tunes near f = c/(4L); for L=2 m, f about 345/8 about 43 Hz, with taper shifting and smoothing the resonances.','Enclosure Design',ARRAY['Ported enclosures','Sealed enclosures','System resonance','Resonance frequency']::text[],ARRAY['Treating a quarter-wave line like a simple vented Helmholtz box; the physics differ.','Ignoring higher-order pipe harmonics that a taper is meant to suppress.','Assuming the tuning uses half-wavelength; an open-closed pipe tunes at a quarter.']::text[],ARRAY['Designing a transmission-line or Voigt-pipe speaker.','Explaining why a pipe tunes at c over 4L.','Using taper to smooth pipe resonance ripples.']::text[],'Advanced','f = c / (4*L)   (quarter-wave, open-closed pipe)','The fundamental tuning frequency of a quarter-wave pipe equals the speed of sound divided by four times the effective pipe length.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tapered quarter-wave tube');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '26c25b26-87f2-44c2-8df5-a4b0ff631754','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='26c25b26-87f2-44c2-8df5-a4b0ff631754') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='26c25b26-87f2-44c2-8df5-a4b0ff631754');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '29ba7702-9bd3-4f90-bc07-7e2ff31cd11d','Tensile strength','The maximum tensile stress a diaphragm, surround, spider, or lead-wire material can withstand before it yields or breaks, equal to the breaking force divided by the cross-sectional area. It bounds how stiff and light a cone can be and how much excursion a suspension can survive.','Tensile strength is how much pulling force a material takes before it tears. It equals the breaking force divided by the area. Cone and suspension materials must be strong enough not to rip. It limits how light and stiff a cone can be.','It sets a material limit that keeps cones, surrounds, and lead wires from tearing under stress and excursion.','Stress equals force over area: a lead wire of 0.2 mm^2 (2e-7 m^2) rated 200 MPa breaks near F = 200e6*2e-7 = 40 N of pull.','Material Property',ARRAY['Radial mode','Diaphragm materials','Ribbon driver','Surface exciter']::text[],ARRAY['Confusing tensile strength with stiffness; a material can be strong yet flexible.','Ignoring fatigue; repeated flexing fails below the single-pull tensile limit.','Assuming a stronger cone is always better, disregarding mass and damping.']::text[],ARRAY['Choosing a durable cone or surround material.','Explaining lead-wire breakage at high excursion.','Comparing diaphragm materials for strength versus mass.']::text[],'Intermediate','sigma = F / A','Tensile stress equals the applied force divided by the cross-sectional area it acts over; failure occurs when this reaches the material''s tensile strength.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tensile strength');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '29ba7702-9bd3-4f90-bc07-7e2ff31cd11d','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='29ba7702-9bd3-4f90-bc07-7e2ff31cd11d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='29ba7702-9bd3-4f90-bc07-7e2ff31cd11d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a63f0719-30d1-4eac-8bed-b8268276e282','Thermal capacitance','The amount of heat a loudspeaker part, such as the voice coil or magnet, must absorb to raise its temperature by one degree, equal to mass times specific heat. Larger thermal capacitance slows temperature rise and, with thermal resistance, sets the thermal time constants that govern power handling.','Thermal capacitance is how much heat a part stores per degree of warming. A heavier part stores more heat and warms slowly. The voice coil has low capacitance and heats fast. The magnet has high capacitance and heats slowly.','It quantifies heat storage in driver parts, setting how fast they warm and how much energy they buffer before overheating.','Cth = mass*specific heat; an aluminum former of 3 g (specific heat about 900 J/kg-C) has Cth = 0.003*900 = 2.7 J/C, so 27 J raises it 10 C.','Power Handling',ARRAY['Slow thermal time constant','Thermal modulation','Sensitivity compression']::text[],ARRAY['Confusing thermal capacitance (heat stored) with thermal resistance (heat flow).','UNSAFE: Assuming a low-mass voice coil can absorb heavy sustained power; its small thermal capacitance lets it overheat and burn quickly.','Ignoring that the coil and magnet have very different capacitances and time constants.']::text[],ARRAY['Modeling a driver''s heat rise under load.','Explaining why voice coils heat faster than magnets.','Estimating burst energy a coil can absorb safely.']::text[],'Advanced','C_th = m * c_p ;  tau = R_th * C_th','Thermal capacitance equals mass times specific heat; combined with thermal resistance it gives the thermal time constant.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermal capacitance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a63f0719-30d1-4eac-8bed-b8268276e282','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a63f0719-30d1-4eac-8bed-b8268276e282') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a63f0719-30d1-4eac-8bed-b8268276e282');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7ae02184-5756-463a-95e6-3c9c8624149e','Thermal modulation','Distortion and parameter shift caused by voice-coil temperature changing during a signal, which modulates the coil''s resistance and thus the current, output, and effective sensitivity. The heating follows the signal envelope, producing time-varying compression and low-order distortion linked to program dynamics.','As a speaker plays, the voice coil heats and cools with the music. Its resistance changes as it heats. That changes the current and the output moment to moment. This signal-driven heating adds compression and distortion.','It explains the dynamic, signal-dependent output changes and distortion that arise from voice-coil heating during program material.','A tech noticing that loud passages briefly lose level and gain distortion attributes it to thermal modulation of the coil resistance and improves driver cooling.','Distortion Mechanism',ARRAY['Sensitivity compression','Slow thermal time constant','Thermal capacitance']::text[],ARRAY['Confusing thermal modulation with amplifier compression; the cause here is coil heating.','UNSAFE: Ignoring persistent thermal modulation, a sign of sustained overheating that can destroy the voice coil.','Assuming coil resistance is constant during dynamic program material.']::text[],ARRAY['Diagnosing dynamic level loss on loud passages.','Explaining program-dependent compression in a driver.','Evaluating how coil cooling reduces thermal distortion.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermal modulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7ae02184-5756-463a-95e6-3c9c8624149e','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7ae02184-5756-463a-95e6-3c9c8624149e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7ae02184-5756-463a-95e6-3c9c8624149e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3214b36f-abc2-448b-8331-6cd9296908d2','Thermal runaway','Thermal runaway is a self-reinforcing rise in loudspeaker voice-coil temperature in which heat degrades the coil''s ability to shed further heat faster than dissipation can remove it, driving the coil toward destructive temperatures. It typically requires a cooling path that worsens with heat, such as ferrofluid drying out, adhesive charring, or a former deforming and losing gap contact.','A voice coil turns some power into heat. Normally the coil sheds that heat to the magnet. Thermal runaway happens when getting hotter makes cooling worse. The coil then keeps heating itself until it fails. It needs a failing cooling path to start.','The concept warns designers and technicians that certain cooling failures can make heating self-feeding, so protection and safe power limits are needed.','A technician who smells hot glue or hears a driver getting quieter and then buzzing pulls back drive level and lets it cool before the coil is destroyed.','Thermal Behaviour',ARRAY['Power compression','Thermal-limited output','Thermal time constant','Ferrofluid','Voice coil']::text[],ARRAY['UNSAFE: Pushing a driver harder when it goes quiet from power compression, which can drive the hot coil into runaway and fire risk.','Assuming every loudspeaker suffers runaway; copper''s rising resistance often self-limits power under constant voltage.','Confusing normal power compression with true thermal runaway.']::text[],ARRAY['A touring subwoofer coil failing after ferrofluid dried out over years of hard use.','A design review adding thermal protection to prevent coil charring.','Diagnosing a driver that grew quiet, then intermittent, then open-circuit.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermal runaway');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3214b36f-abc2-448b-8331-6cd9296908d2','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3214b36f-abc2-448b-8331-6cd9296908d2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3214b36f-abc2-448b-8331-6cd9296908d2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '31ed4aa3-851e-44e7-b54b-30e83e3b21ac','Thermal state variable','A thermal state variable is a temperature (or temperature rise) used in a lumped thermal model of a loudspeaker to describe the instantaneous heat stored in a part of the motor, most importantly the voice-coil temperature rise dTv = Tv - Ta above ambient. Additional state variables track the pole/gap and magnet temperatures, each with its own time constant.','Engineers model a driver''s heat with a few tracked temperatures. Each one is a thermal state variable. The main one is how far the voice coil sits above room temperature. Others track the magnet and pole piece. They let a model predict heating over time.','It lets a thermal model and protection system estimate hidden internal temperatures in real time from the power going into the driver.','A DSP limiter estimates coil temperature rise from a model; if dTv nears the safe limit near 200 to 250 degrees Celsius it reduces gain.','Thermal Behaviour',ARRAY['Thermal time constant','Thermal-limited output','Thermal runaway','Voice coil','Power handling']::text[],ARRAY['UNSAFE: Trusting a modeled coil temperature during a burn-in test without margin, risking coil damage or fire if the model is wrong.','Treating the single coil temperature as the whole picture and ignoring magnet and gap states.','Assuming instantaneous heating; each state variable follows its own time constant.']::text[],ARRAY['A powered speaker''s DSP tracking coil temperature to protect the driver.','Klippel measurements extracting thermal parameters for a state model.','Explaining why a driver keeps heating after the burst has ended.']::text[],'Advanced','dT_v(t) = T_v(t) - T_a ;  dT_vss = (R_tv + R_tg + R_tm) * P_t','The voice-coil thermal state variable is the coil temperature minus the ambient temperature. At steady state the coil temperature rise equals the total thermal resistance from coil to air multiplied by the dissipated power.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermal state variable');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '31ed4aa3-851e-44e7-b54b-30e83e3b21ac','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='31ed4aa3-851e-44e7-b54b-30e83e3b21ac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='31ed4aa3-851e-44e7-b54b-30e83e3b21ac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd74c1a51-aebd-4fe1-8dbc-2467c191d52e','Thermal time constant','The thermal time constant of a loudspeaker part is the time for its temperature to reach about 63 percent of its final rise under steady power, equal to the product of that part''s thermal resistance and thermal capacitance (tau = R_th * C_th). The voice-coil constant is short (seconds to tens of seconds), while the magnet structure''s is long (minutes).','Parts of a driver heat up and cool down at their own speed. The thermal time constant measures that speed. It is the thermal resistance times the heat storage of the part. A voice coil reacts in seconds. The heavy magnet takes minutes.','It sets how fast a part heats or cools, which decides how a driver responds to short bursts versus sustained power.','For a coil with R_tv = 5.9 K/W and C_tv = 3.6 Ws/K, tau = 5.9 * 3.6 = about 21 seconds to reach 63 percent of its final temperature rise.','Thermal Behaviour',ARRAY['Thermal state variable','Thermal-limited output','Power compression','Voice coil','Power handling']::text[],ARRAY['Assuming a driver has one time constant; the coil, gap, and magnet each have different ones.','Confusing the short coil constant with the long magnet constant when predicting long-term heating.','UNSAFE: Using a short pink-noise burst to rate power, which hides the slow magnet heating that later causes overheating.']::text[],ARRAY['Predicting coil heating during a fast musical transient versus a sustained tone.','Choosing a power-test signal duration long enough to heat the magnet.','Explaining why a speaker keeps warming minutes after a loud passage.']::text[],'Intermediate','tau = R_th * C_th','The thermal time constant equals the thermal resistance of the heat path multiplied by the thermal capacitance (heat storage) of the part.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermal time constant');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd74c1a51-aebd-4fe1-8dbc-2467c191d52e','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d74c1a51-aebd-4fe1-8dbc-2467c191d52e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d74c1a51-aebd-4fe1-8dbc-2467c191d52e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '15477efb-80ff-4030-a96f-0fbcd2c936b6','Thermal-limited output','Thermal-limited output is the maximum acoustic output a loudspeaker can sustain before voice-coil heating, not mechanical excursion, becomes the limiting factor. As the coil heats its resistance rises, drawing less power under constant voltage and compressing output; the safe long-term limit is set by the temperature the coil and adhesives can survive.','A speaker can be limited two ways. One is how far the cone can move. The other is how hot the coil gets. Thermal-limited output is when heat sets the ceiling. As the coil warms, its resistance rises. It then draws less power and plays quieter.','It defines the sustained loudness ceiling caused by heat, guiding safe continuous power ratings and system design.','If coil resistance rises from 1.88 to 2.62 ohms with a 100 kelvin rise, constant-voltage power drops by 10*log10(1.88/2.62) = about 1.5 dB of thermal power compression.','Thermal Behaviour',ARRAY['Power compression','Thermal time constant','Thermal runaway','Sensitivity','Power handling']::text[],ARRAY['Confusing thermal limiting (heat) with mechanical limiting (excursion or Xmax).','UNSAFE: Adding more amplifier voltage to restore lost loudness, which raises coil temperature toward failure.','Assuming rated power gives rated loudness; power compression reduces real output as the coil heats.']::text[],ARRAY['A subwoofer that sounds fine on transients but compresses on long bass notes.','Setting a continuous power rating from coil temperature limits.','Comparing peak versus long-term SPL specs on a datasheet.']::text[],'Intermediate','dSPL ~= 10 * log10(R_cold / R_hot) ;  R_hot = R_cold * (1 + delta * dT)','The thermal power compression in decibels is about ten times the log of cold resistance divided by hot resistance. The hot resistance equals the cold resistance times one plus the copper temperature coefficient times the temperature rise.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermal-limited output');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '15477efb-80ff-4030-a96f-0fbcd2c936b6','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='15477efb-80ff-4030-a96f-0fbcd2c936b6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='15477efb-80ff-4030-a96f-0fbcd2c936b6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dc890a99-e1c9-479c-825d-1e259acccc67','Top plate','The top plate (front plate) is the ferromagnetic pole piece on the front face of a loudspeaker motor that, together with the center pole, forms the magnetic gap in which the voice coil sits. Its thickness and inner bore set the gap height and help concentrate magnetic flux across the gap.','A speaker motor guides magnetism into a narrow gap. The top plate is the steel ring on the front of the magnet. With the center pole it forms that gap. The voice coil rides inside it. Its thickness sets how tall the gap is.','It routes and concentrates the magnet''s flux across the gap so the voice coil sits in a strong, well-defined magnetic field.','A technician centering a reconed driver checks that the voice coil moves freely in the top plate bore without rubbing before the glue sets.','Motor Structure',ARRAY['Magnetic gap','Pole piece','Back plate','Voice coil','Flux density']::text[],ARRAY['Confusing the top plate with the back plate or the pole piece; each is a different motor part.','Assuming a thicker top plate always helps; it changes gap height and flux distribution.','UNSAFE: Handling large assembled magnet motors carelessly; strong fields can snap steel parts together and crush fingers.']::text[],ARRAY['Identifying motor parts while reconing a blown driver.','Reading a driver cutaway to see where the gap is formed.','Comparing ferrite and neodymium motor layouts.']::text[],'Beginner',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Top plate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dc890a99-e1c9-479c-825d-1e259acccc67','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dc890a99-e1c9-479c-825d-1e259acccc67') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dc890a99-e1c9-479c-825d-1e259acccc67');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39ae8192-edc4-4b1c-ad26-0ac0dc95c405','Total quality factor','The total quality factor Qts is the Thiele-Small parameter describing the combined damping of a driver at its free-air resonance, formed from the mechanical (Qms) and electrical (Qes) quality factors in parallel. It governs the shape of the low-frequency resonance peak and strongly influences enclosure choice.','Every driver has a main resonance. How sharp that peak is depends on damping. The total quality factor, Qts, combines two kinds of damping. One is mechanical, one is electrical. A low Qts means tight, well-damped bass.','It summarizes a driver''s overall resonance damping in one number, guiding whether it suits a sealed, vented, or other enclosure.','For Qms = 3.0 and Qes = 0.40, Qts = (3.0 * 0.40) / (3.0 + 0.40) = 1.2 / 3.4 = about 0.35, a value well suited to a vented box.','Thiele-Small Parameters',ARRAY['Mechanical Q (Qms)','Electrical Q (Qes)','Resonance frequency (Fs)','Thiele-Small parameters','Equivalent volume (Vas)']::text[],ARRAY['Adding Qms and Qes directly instead of combining them in parallel.','Thinking Qts alone determines box size; it works together with Fs and Vas.','Assuming a high Qts is always better; it usually gives a boomy, underdamped low end.']::text[],ARRAY['Choosing between a sealed or vented box from a driver''s datasheet.','Measuring Thiele-Small parameters before a subwoofer design.','Explaining why a driver sounds boomy in the wrong enclosure.']::text[],'Intermediate','Qts = (Qms * Qes) / (Qms + Qes)','The total quality factor equals the mechanical quality factor times the electrical quality factor, divided by their sum.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Total quality factor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39ae8192-edc4-4b1c-ad26-0ac0dc95c405','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39ae8192-edc4-4b1c-ad26-0ac0dc95c405') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39ae8192-edc4-4b1c-ad26-0ac0dc95c405');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '877c3d6c-7e75-4c5c-b25e-65ac2c4a937e','Transmission lines','A transmission-line loudspeaker uses a long, often folded and damped internal duct behind the driver, ideally about a quarter-wavelength at the tuning frequency, to load the cone and radiate low-frequency output from the line''s terminus. Absorptive stuffing damps higher-order pipe resonances while the fundamental reinforces the low end.','A transmission line is a long tunnel inside a speaker box. The driver sits at one end. Sound travels down the tunnel and exits the far end. The tunnel length is tuned near a quarter of a bass wavelength. Stuffing tames unwanted echoes inside.','It loads the driver and extends low-frequency output by using a tuned, damped pipe rather than a small sealed or ported volume.','For a 40 Hz tuning, a quarter-wave line length is L = c / (4f) = 343 / (4 * 40) = about 2.14 metres, usually folded to fit a cabinet.','Enclosure Loading',ARRAY['Transmission-line terminus','Quarter-wave resonator','Damping (stuffing)','Bass reflex','Enclosure loading']::text[],ARRAY['Thinking a transmission line has no resonance; it is a tuned quarter-wave pipe, not lossless.','Ignoring that stuffing lowers the effective speed of sound and shifts tuning.','Confusing a transmission line with a simple ported (bass-reflex) box.']::text[],ARRAY['Designing a floor-standing speaker with extended, well-damped bass.','Folding a long line to fit a practical cabinet.','Explaining why a line cabinet is larger than a sealed box.']::text[],'Advanced','L = c / (4 * f)','The quarter-wave line length equals the speed of sound divided by four times the tuning frequency.','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transmission lines');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '877c3d6c-7e75-4c5c-b25e-65ac2c4a937e','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='877c3d6c-7e75-4c5c-b25e-65ac2c4a937e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='877c3d6c-7e75-4c5c-b25e-65ac2c4a937e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '02a8c295-0829-43fd-a406-51f42364de36','Transmission-line terminus','The transmission-line terminus is the open end (mouth or vent) of a transmission-line enclosure where the internal duct radiates its low-frequency output into the room. Its area and position set the acoustic loading and how the line''s output combines with the driver''s front radiation.','A transmission-line speaker has a long tunnel inside. The terminus is the open mouth where that tunnel exits. Bass energy leaves the box there. Its size and placement affect how the bass adds to the direct sound.','It is the radiating outlet of the line, where the tuned low-frequency energy exits and joins the driver''s direct output.','A technician places the terminus near the floor or driver so its low output stays in phase with the cone and adds to, rather than cancels, the bass.','Enclosure Loading',ARRAY['Transmission lines','Port (vent)','Quarter-wave resonator','Enclosure loading','Group delay']::text[],ARRAY['Treating the terminus like a simple bass-reflex port; the line behind it behaves differently.','Placing the terminus where its output cancels the driver at the crossover region.','Ignoring terminus area, which affects loading and any higher-frequency leakage.']::text[],ARRAY['Positioning the mouth of a folded line for best in-room bass.','Measuring near-field output at the terminus during voicing.','Explaining phase interaction between the terminus and the cone.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transmission-line terminus');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '02a8c295-0829-43fd-a406-51f42364de36','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='02a8c295-0829-43fd-a406-51f42364de36') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='02a8c295-0829-43fd-a406-51f42364de36');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '096607ca-ce4f-45d3-b7e2-0b8100ed0c75','Vertical off-axis response','Vertical off-axis response is a loudspeaker''s frequency response measured at angles above and below the on-axis reference in the vertical plane. In multi-way systems it often shows deep interference notches near the crossover, caused by path-length differences between vertically separated drivers.','A speaker does not sound the same at every angle. Vertical off-axis response measures the sound above and below the main axis. Near the crossover, two stacked drivers can cancel each other. This creates dips at certain up-and-down angles.','It reveals how tonal balance changes with listening height and exposes crossover lobing between vertically spaced drivers.','A technician measures 15 degrees up and down; a deep notch near the crossover tells them where floor and ceiling reflections may color the sound.','Directivity',ARRAY['Off-axis response','Crossover','Lobing','Directivity','Polar response']::text[],ARRAY['Judging a speaker only by its on-axis curve and ignoring vertical behavior.','Confusing vertical lobing notches with a driver fault.','Forgetting that tilting or stacking drivers steers the vertical lobe.']::text[],ARRAY['Aligning a crossover to keep the main lobe on the audience.','Explaining why a speaker sounds thin when heard while standing.','Aiming studio monitors so the listener sits in the smoothest vertical window.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vertical off-axis response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '096607ca-ce4f-45d3-b7e2-0b8100ed0c75','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='096607ca-ce4f-45d3-b7e2-0b8100ed0c75') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='096607ca-ce4f-45d3-b7e2-0b8100ed0c75');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '30cb1a7c-c78e-4c2a-bc9a-17d4ec03c279','Wavefront curvature','Wavefront curvature describes the geometric shape of a propagating acoustic wavefront, from strongly curved (spherical) near a compact source to nearly flat (planar) far away or from a large line source. Horns and waveguides deliberately shape wavefront curvature to control a loudspeaker''s directivity.','Sound spreads as a moving surface called a wavefront. Close to a small source, that surface is round, like a growing bubble. Far away, or from a tall line source, it looks nearly flat. This shape is the wavefront curvature.','It explains how a source''s size and any horn or waveguide set the shape of the radiated wave and thus its coverage.','A technician chooses a line array to get a nearly flat wavefront that spreads less over distance, keeping level more even across a deep audience.','Radiation',ARRAY['Waveguides','Line array','Directivity','Point source','Horn']::text[],ARRAY['Assuming all sources radiate flat, plane waves; small sources are nearly spherical.','Confusing wavefront curvature with the cabinet or cone shape.','Thinking a curved array line automatically gives a smooth combined wavefront without proper design.']::text[],ARRAY['Deciding between a point-source and line-array system for a venue.','Shaping a waveguide to match a target coverage pattern.','Explaining why line-array level falls off more slowly with distance.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wavefront curvature');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '30cb1a7c-c78e-4c2a-bc9a-17d4ec03c279','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='30cb1a7c-c78e-4c2a-bc9a-17d4ec03c279') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='30cb1a7c-c78e-4c2a-bc9a-17d4ec03c279');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0cbee20e-2f20-4423-97f1-f0ff43ee4579','Waveguides','An acoustic waveguide is a shaped duct or shallow horn placed in front of a compression driver or dome that guides the radiated wavefront to control directivity, typically giving a defined, more uniform coverage angle. Unlike a classic gain horn, a waveguide''s main goal is directivity control rather than acoustic loading and efficiency.','A waveguide is a molded flare in front of a tweeter or driver. It guides the sound outward in a chosen pattern. Its main job is to set the coverage angle. A plain horn instead aims to boost efficiency. Many modern speakers use waveguides.','It controls the horizontal and vertical coverage of a high-frequency driver so the sound spreads in a predictable, even pattern.','A technician picks a 90 by 60 degree waveguide so one cabinet evenly covers the seating width without over-spilling onto side walls.','Directivity',ARRAY['Horn','Compression driver','Directivity','Wavefront curvature','Constant directivity']::text[],ARRAY['Assuming a waveguide is only for high-frequency loudness; its main role is directivity.','Treating a waveguide and a full gain horn as identical.','Ignoring that the driver and waveguide must be matched for smooth response.']::text[],ARRAY['Selecting coverage angle for a fixed-install loudspeaker.','Matching a compression driver to a waveguide throat.','Explaining smoother off-axis response in a waveguide-loaded monitor.']::text[],'Intermediate',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Waveguides');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0cbee20e-2f20-4423-97f1-f0ff43ee4579','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0cbee20e-2f20-4423-97f1-f0ff43ee4579') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0cbee20e-2f20-4423-97f1-f0ff43ee4579');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24f996bb-eca4-4c81-9a6e-de3039674db5','Working-point shift','A working-point shift is a systematic offset of the voice coil''s rest position away from the magnetic gap center, caused by asymmetries in suspension stiffness Kms(x) or force factor Bl(x) that rectify the drive signal into a net DC displacement. The displaced coil experiences reduced Bl and generates added, often even-order, distortion, and may rub at high excursion.','A voice coil should sit centered in the gap. When the suspension or motor is lopsided, hard drive pushes it off center. This offset is the working-point shift. The coil then makes weaker force and more distortion. In bad cases it rubs and buzzes.','The concept explains a large-signal fault where nonlinear asymmetry drags the coil off center, degrading output and raising distortion.','A technician seeing rising even-order distortion and a coil creeping toward the softer suspension side at high level suspects Kms(x) asymmetry causing a working-point shift.','Nonlinear Distortion',ARRAY['DC displacement','Bl(x)','Suspension asymmetry','Xmax','Intermodulation distortion']::text[],ARRAY['Confusing a working-point shift with normal symmetric excursion limiting.','Blaming the amplifier for a coil that drifts off center from suspension asymmetry.','UNSAFE: Ignoring a coil creeping and rubbing at high level, which can jam and burn out the driver.']::text[],ARRAY['Diagnosing a subwoofer that distorts and buzzes only at high excursion.','Klippel large-signal testing revealing suspension or Bl asymmetry.','Explaining even-order distortion that grows with drive level.']::text[],'Advanced',NULL,NULL,'f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Working-point shift');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24f996bb-eca4-4c81-9a6e-de3039674db5','f4e5d4af-4eb4-4124-91d5-6e4c1bb64a37',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24f996bb-eca4-4c81-9a6e-de3039674db5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24f996bb-eca4-4c81-9a6e-de3039674db5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8594078e-b0de-4b71-9a72-a7f39e690e56','Acoustic compliance of enclosure','The acoustic compliance of a sealed enclosure is the acoustical analogue of a spring, describing how much the trapped air volume yields to a change in pressure. It equals the net box volume divided by the product of air density and the square of the speed of sound, so a larger box is more compliant and acts as a weaker air spring.','Trapped air in a sealed box acts like a spring. Acoustic compliance measures how easily that air gives way. A bigger box is a softer spring. A smaller box is a stiffer one.','It quantifies the air-spring stiffness a sealed box adds to the driver, which sets the system''s resonance and damping.','For a 0.03 m3 (30 L) sealed box with air density 1.21 kg/m3 and sound speed 343 m/s, the acoustic compliance is 0.03 / (1.21 x 343^2) which is about 2.1 x 10^-7 m^5/N.','Enclosure Parameter',ARRAY['Box compliance','Equivalent volume Vas','Closed-box resonance','Air spring','Sealed enclosure']::text[],ARRAY['Confusing acoustic compliance (C_ab) with the driver''s mechanical compliance (C_ms); they use different units and references.','Assuming a bigger box only adds bass, when it also lowers system resonance and Q.','Using gross box volume instead of the net volume after subtracting driver and bracing.']::text[],ARRAY['Sizing a sealed subwoofer box for a target resonance.','Computing closed-box Q from driver and box parameters.','Comparing a driver''s Vas to a chosen box volume.']::text[],'Advanced','C_ab = V_b / (rho_0 * c^2)','Acoustic compliance equals the net box volume divided by air density times the speed of sound squared.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic compliance of enclosure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8594078e-b0de-4b71-9a72-a7f39e690e56','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8594078e-b0de-4b71-9a72-a7f39e690e56') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8594078e-b0de-4b71-9a72-a7f39e690e56');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '57fe5a7f-32d3-4bac-8e40-d794c4c23b15','Acoustic lens','An acoustic lens is a passive structure of angled slats, perforated plates, or channels placed in front of a driver to bend and spread wavefronts, widening high-frequency dispersion by making different portions of the wave travel different path lengths. JBL popularized slant-plate acoustic lenses on horn tweeters in the 1950s and 1960s.','An acoustic lens sits in front of a tweeter or horn. It is built from angled plates or slots. Sound passes through and fans out wider. This spreads the high frequencies more evenly.','It broadens and controls high-frequency directivity where a bare driver or horn would beam too narrowly.','A technician recognizes the slant-plate lens on a vintage JBL horn as a dispersion device to keep, not a cosmetic grille to remove.','Radiation Control',ARRAY['Horn (waveguide)','Baffle diffraction','Directivity','Beamwidth','Constant directivity']::text[],ARRAY['Thinking an acoustic lens focuses sound like an optical lens, when it actually spreads it.','Mistaking the angled slats for a decorative grille.','Removing the lens and losing high-frequency coverage width.']::text[],ARRAY['Restoring vintage studio monitors with slant-plate lenses.','Explaining wide high-frequency dispersion from an old horn.','Comparing an acoustic lens to a modern constant-directivity waveguide.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic lens');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '57fe5a7f-32d3-4bac-8e40-d794c4c23b15','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='57fe5a7f-32d3-4bac-8e40-d794c4c23b15') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='57fe5a7f-32d3-4bac-8e40-d794c4c23b15');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8fa32098-65d5-4660-ae93-2c70a20d1a3d','Acoustic resistance enclosure','An acoustic resistance enclosure uses a vent or panel filled with a controlled acoustic resistance, such as a porous plug or damped opening, so the box behaves between sealed and ported. The resistance damps the driver''s fundamental resonance and lowers the impedance peak without creating a sharply tuned Helmholtz response.','This box has a vent packed with resistive material. Air moves through it but is heavily damped. The result sits between a sealed and a ported box. It tames the driver''s main resonance.','It flattens the impedance peak and controls cone motion using acoustic damping rather than a sharp port tuning.','A technician fits a resistive vent, such as a Scan-Speak Variovent (a trademarked resistive-vent product), to damp a driver''s resonance in a compact box.','Enclosure Type',ARRAY['Aperiodic enclosure','Box loss','Sealed enclosure','Ported enclosure','Damping material']::text[],ARRAY['Confusing it with a tuned port; there is no strong Helmholtz resonance.','Expecting large bass extension, when the effect is mainly damping.','Treating the resistive plug as a simple leak rather than a designed resistance.']::text[],ARRAY['Taming an underdamped driver in a small cabinet.','Reducing the impedance peak for an easier amplifier load.','Building a hybrid between sealed and transmission-line loading.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic resistance enclosure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8fa32098-65d5-4660-ae93-2c70a20d1a3d','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8fa32098-65d5-4660-ae93-2c70a20d1a3d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8fa32098-65d5-4660-ae93-2c70a20d1a3d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e7196f3a-7333-47e3-9469-23f4ebcdc2cf','Annular phase plug','An annular phase plug is a plug with concentric ring-shaped (annular) channels placed between a compression driver''s diaphragm and the horn throat. It divides the diaphragm''s output into equal-length paths so the wavefronts recombine in phase and avoid high-frequency cancellation.','A phase plug fills the space in front of a compression driver''s dome. The annular type uses ring-shaped slots. Each slot path has the same length. Sound from the whole dome arrives together, so highs stay smooth.','It keeps high-frequency output smooth by equalizing the path lengths from the diaphragm to the throat.','When replacing a compression driver''s diaphragm, a technician seats it at the correct gap so the annular slots line up and highs are not lost.','Compression Driver Part',ARRAY['Circumferential phase plug','Compression chamber','Compression driver','Throat','Diaphragm']::text[],ARRAY['Confusing an annular (concentric-ring) phase plug with a circumferential (radial-slot) one.','Setting the wrong diaphragm gap, which alters the chamber and can cause rubbing.','Assuming the phase plug is only a spacer rather than a path-length equalizer.']::text[],ARRAY['Rebuilding a compression driver after diaphragm failure.','Choosing a driver for smooth high-frequency response.','Diagnosing high-frequency dips from a misaligned plug.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Annular phase plug');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e7196f3a-7333-47e3-9469-23f4ebcdc2cf','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e7196f3a-7333-47e3-9469-23f4ebcdc2cf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e7196f3a-7333-47e3-9469-23f4ebcdc2cf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0ca9f0df-2410-4d26-b229-77b48e05c783','Aperiodic enclosure','An aperiodic enclosure has a heavily damped, resistive vent that provides a leak controlled by acoustic resistance rather than a tuned mass of air. This gives broad, non-resonant loading that damps the driver''s fundamental resonance and reduces the impedance peak.','An aperiodic box has a vent stuffed with resistive material. It does not ring at one tuned note. Instead it gently bleeds air and damps the cone. This lowers the impedance peak and smooths the bass.','It damps the driver''s resonance and lowers system Q in a small box without a sharply tuned port.','A technician installs a damped vent so the impedance peak at resonance is flattened, easing the amplifier load and controlling cone motion.','Enclosure Type',ARRAY['Acoustic resistance enclosure','Sealed enclosure','Box loss','Ported enclosure','Damping material']::text[],ARRAY['Expecting ported-level bass extension from an aperiodic vent.','Treating it as just a leaky sealed box rather than a designed resistance.','Ignoring how much the stuffing density changes the result.']::text[],ARRAY['Building a compact subwoofer with controlled resonance.','Taming an underdamped driver''s impedance peak.','Making a hybrid between sealed and transmission-line loading.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aperiodic enclosure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0ca9f0df-2410-4d26-b229-77b48e05c783','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0ca9f0df-2410-4d26-b229-77b48e05c783') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0ca9f0df-2410-4d26-b229-77b48e05c783');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd3bc696a-0481-4bd1-8ae3-75ac19d35eb7','Apparent acoustic center','The apparent acoustic center is the point in space from which a loudspeaker''s radiated sound appears to diverge as a spherical wave at a given frequency, used as the timing reference for arrival-time and phase measurements. It can shift with frequency and usually differs from the driver''s physical location.','The acoustic center is where a speaker''s sound seems to start. Measurements treat it as the source point. It is not always the visible driver position. It can also move with frequency.','It gives a consistent reference for measuring delay, phase, and alignment between drivers or loudspeakers.','When aligning a woofer and tweeter, a technician sets delay to match their acoustic centers rather than their front baffle faces.','Radiation Concept',ARRAY['Acoustic center','Phase alignment','Group delay','Crossover lobing','Time alignment']::text[],ARRAY['Assuming it sits at the dust cap or voice coil.','Ignoring that it changes with frequency.','Confusing the acoustic center with the geometric center of the driver.']::text[],ARRAY['Time-aligning a multi-way loudspeaker.','Setting delays in an array prediction model.','Setting up a reference for phase measurements.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Apparent acoustic center');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd3bc696a-0481-4bd1-8ae3-75ac19d35eb7','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d3bc696a-0481-4bd1-8ae3-75ac19d35eb7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d3bc696a-0481-4bd1-8ae3-75ac19d35eb7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '79484256-935f-4e64-abd4-c351c2b23688','Backplate vent','A backplate vent (pole vent) is a hole or channel through the back plate and pole piece of a driver''s magnet assembly that lets air move behind the dust cap and voice coil. It reduces air-cavity compression, helps cool the voice coil, and lowers audible noise and nonlinear stiffness.','The magnet has a hole through its back, called a pole vent. It lets trapped air escape from behind the cone. This helps cool the voice coil. It also cuts air noise and unwanted stiffness.','It relieves pressure under the dust cap and improves voice-coil cooling and linearity.','When mounting a driver, a technician keeps the pole vent clear so cooling and airflow are preserved and chuffing behind the cone is avoided.','Driver Part',ARRAY['Voice-coil cooling','Dust cap','Pole piece','Air compression','Power compression']::text[],ARRAY['Blocking the vent with sealant, foam, or mounting hardware.','Confusing the pole vent with an enclosure bass port.','UNSAFE: Blocking the pole vent raises voice-coil temperature and risks thermal burnout and driver failure at high power.']::text[],ARRAY['Mounting a driver without obstructing its pole vent.','Diagnosing a chuffing noise from behind the cone.','Managing thermal reliability in high-power use.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Backplate vent');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '79484256-935f-4e64-abd4-c351c2b23688','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='79484256-935f-4e64-abd4-c351c2b23688') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='79484256-935f-4e64-abd4-c351c2b23688');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '909c86d8-aa74-480d-8293-98e3cd7b000f','Baffle diffraction','Baffle diffraction is the bending and re-radiation of sound at the edges and boundaries of a loudspeaker baffle, creating secondary wavefronts that interfere with the direct output. It causes frequency-response ripple and the baffle step, and is strongest when the wavelength is comparable to the baffle dimensions.','Sound spreading across a speaker''s front panel reaches the edges. The edges re-radiate small new waves. These mix with the main sound. The result is bumps and dips in the response.','It names an unwanted radiation effect that designers must control to get a smooth frequency response.','A technician rounds or chamfers baffle edges and offsets the drivers to reduce diffraction ripple and smooth the response.','Radiation Effect',ARRAY['Baffle step','Edge diffraction','Directivity index','Enclosure geometry','Free-field response']::text[],ARRAY['Confusing the broad baffle-step transition with narrow diffraction ripples.','Placing a driver centered on a symmetric baffle, which worsens diffraction.','Assuming grille frames and sharp edges have no effect.']::text[],ARRAY['Designing the baffle shape and driver layout of a monitor.','Explaining measured response ripples above a few hundred hertz.','Choosing edge treatments to smooth the response.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Baffle diffraction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '909c86d8-aa74-480d-8293-98e3cd7b000f','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='909c86d8-aa74-480d-8293-98e3cd7b000f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='909c86d8-aa74-480d-8293-98e3cd7b000f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c9a1f2f4-72aa-4e37-a4e3-ed7de4a1dcb5','Balloon plot','A balloon plot is a three-dimensional polar representation of a loudspeaker''s directional output, showing radiated level in every direction at a given frequency as a lobed surface resembling a balloon. Standardized directivity balloon data feed acoustic prediction software.','A balloon plot shows how a speaker radiates in three dimensions. Louder directions bulge out. Quieter ones pull in. The shape looks like a lumpy balloon that software uses to model coverage.','It conveys full-sphere directivity so designers can predict a loudspeaker''s coverage in a room.','A technician imports a manufacturer''s balloon data (in CLF or GLL format) into prediction software to aim loudspeakers and arrays.','Directivity Data',ARRAY['Coverage balloon','Directivity index','Polar pattern','Beamwidth','Directivity factor']::text[],ARRAY['Reading a single-frequency balloon as if it described the whole spectrum.','Treating the radius as distance rather than relative level.','Ignoring the angular resolution at which the data were measured.']::text[],ARRAY['Modeling loudspeaker coverage in prediction software.','Comparing the directivity of competing loudspeakers.','Aiming an array to cover an audience evenly.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Balloon plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c9a1f2f4-72aa-4e37-a4e3-ed7de4a1dcb5','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c9a1f2f4-72aa-4e37-a4e3-ed7de4a1dcb5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c9a1f2f4-72aa-4e37-a4e3-ed7de4a1dcb5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '61bb457d-4c1e-42c2-a8fe-8b0771e1fa99','Bessel alignment','A Bessel alignment tunes a box so its transfer function approximates a Bessel (Bessel-Thomson) polynomial, chosen for maximally flat group delay and the best transient settling at the cost of a gentler amplitude roll-off. It generally suits drivers of moderate total Q, around 0.3.','A Bessel alignment tunes a box for clean timing. Its group delay stays flat. This gives quick, tidy transient response. The trade-off is a softer bass roll-off.','It prioritizes time-domain accuracy over the steepest possible bass extension.','A technician picks a Bessel target when transient accuracy matters more than deep low-frequency reach, using a driver of moderate Qts.','Box Alignment',ARRAY['Butterworth alignment','Chebyshev alignment','Group delay','Quasi-Butterworth alignment','Box tuning frequency']::text[],ARRAY['Expecting the flattest amplitude, when Bessel trades amplitude flatness for flat delay.','Confusing a Bessel alignment with a Butterworth alignment.','Assuming any driver Qts will meet the alignment.']::text[],ARRAY['Designing a monitor that favors transient accuracy.','Comparing alignment families for a given driver.','Choosing a target for clean low-frequency timing.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bessel alignment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '61bb457d-4c1e-42c2-a8fe-8b0771e1fa99','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='61bb457d-4c1e-42c2-a8fe-8b0771e1fa99') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='61bb457d-4c1e-42c2-a8fe-8b0771e1fa99');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b227a82c-e2f1-4c60-aafa-315c48d61a91','Bi-radial horn','A bi-radial horn is a constant-directivity horn whose walls flare along two different profiles so horizontal and vertical coverage angles are independently controlled and held roughly constant across the usable band. "Bi-Radial" is a registered trademark of Harman International (JBL); the underlying method is generic constant-directivity horn design credited to D. B. Keele and others.','A bi-radial horn shapes its two axes separately. One curve sets side-to-side coverage. Another sets up-and-down coverage. This keeps the coverage angle steady with frequency. JBL owns the Bi-Radial name.','It delivers even, largely frequency-independent coverage from a single horn.','A technician specifies a 90 by 40 degree bi-radial horn to match a room''s width and depth.','Horn Type',ARRAY['Constant directivity','Conical horn','CD waveguide','Coverage angle','Diffraction slot']::text[],ARRAY['Treating "Bi-Radial" as a generic term instead of a JBL trademark.','Assuming perfect constant directivity at every frequency.','Ignoring high-frequency beaming above the constant-directivity band.']::text[],ARRAY['Selecting a horn to match audience coverage.','Restoring or servicing JBL professional systems.','Comparing constant-directivity horn designs.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bi-radial horn');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b227a82c-e2f1-4c60-aafa-315c48d61a91','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b227a82c-e2f1-4c60-aafa-315c48d61a91') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b227a82c-e2f1-4c60-aafa-315c48d61a91');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24b8aa1e-301c-4dfa-8c42-bdba89060add','Bipole enclosure','A bipole enclosure carries matching drivers on opposite faces wired in phase, so both cones move outward together and produce a nearly omnidirectional, diffuse radiation pattern. It contrasts with a dipole, whose opposite drivers move out of phase.','A bipole speaker has drivers on two opposite sides. Both push out at the same time, in phase. Sound spreads widely in all directions. This creates a spacious, diffuse effect.','It creates an enveloping, diffuse sound field, often used for surround channels.','A technician places bipole surrounds to the sides of a room for a wrap-around field rather than a pinpoint image.','Enclosure Type',ARRAY['Dipole enclosure','Omnidirectional radiation','Surround loudspeaker','Radiation pattern','Cardioid radiation']::text[],ARRAY['Wiring the opposing drivers out of phase, which makes a dipole instead.','Confusing a bipole with a dipole.','Expecting sharp stereo imaging from a diffuse radiator.']::text[],ARRAY['Installing surround loudspeakers in a home theater.','Designing for a diffuse, enveloping sound field.','Choosing between bipole and dipole surrounds.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bipole enclosure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24b8aa1e-301c-4dfa-8c42-bdba89060add','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24b8aa1e-301c-4dfa-8c42-bdba89060add') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24b8aa1e-301c-4dfa-8c42-bdba89060add');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2258f15b-5020-4816-98eb-7f21225888d4','Box compliance','Box compliance describes how the sealed enclosure''s air spring loads the driver, and designers work with it as the compliance ratio alpha: the dimensionless ratio of the driver''s equivalent air-compliance volume (Vas) to the net box volume (Vb). Because alpha is a pure ratio, it is distinct from the enclosure''s acoustic compliance C_ab, which carries units of m^5/N. A smaller box raises alpha and stiffens the air spring.','Box compliance is the springiness of the air in a sealed box. A small box is a stiff spring. We compare it to the driver with a ratio. That ratio is the driver''s Vas divided by the box volume.','It quantifies how the enclosed air stiffens the driver, which sets the system''s resonance and Q.','With Vas of 60 L in a 20 L net box, the compliance ratio alpha is 60/20 = 3, a value used to find closed-box Q and resonance.','Enclosure Parameter',ARRAY['Acoustic compliance of enclosure','Equivalent volume Vas','Closed-box Q','Closed-box resonance','Compliance ratio']::text[],ARRAY['Confusing box compliance with the driver''s mechanical compliance.','Using gross box volume instead of net volume after stuffing and bracing.','Mixing units, such as liters with cubic meters, in the ratio.']::text[],ARRAY['Sizing a sealed enclosure for a driver.','Computing closed-box Q and resonance.','Matching a driver to a target box volume.']::text[],'Intermediate','alpha = V_as / V_b','The compliance ratio equals the driver''s equivalent air-compliance volume divided by the net box volume.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Box compliance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2258f15b-5020-4816-98eb-7f21225888d4','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2258f15b-5020-4816-98eb-7f21225888d4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2258f15b-5020-4816-98eb-7f21225888d4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1bc8a8a6-5c44-412a-aa46-9160a56b83e3','Box loss','Box loss is the combined energy loss in a vented enclosure from leakage (Ql), absorption and damping (Qa), and port viscous and friction losses (Qp), grouped into a total loss quality factor Qb. These losses lower output near tuning and round off the response and impedance peaks; Small''s analysis commonly assumes a leakage Ql of about 7.','Real boxes leak and absorb some energy. These losses are grouped into a quality factor. Lower numbers mean higher loss. Losses reduce port output and round off the response.','It accounts for real-world enclosure imperfections that an ideal lossless model ignores.','A designer assumes a leakage Ql of about 7 when modeling a vented box, then adjusts tuning to account for real losses.','Enclosure Parameter',ARRAY['Box tuning frequency','Butterworth alignment','Leakage loss','Port loss','Absorption loss']::text[],ARRAY['Ignoring losses and predicting an unrealistically peaky response.','Confusing leakage Ql with the driver''s total Qts.','Assuming a lossless port with no viscous drag.']::text[],ARRAY['Modeling a vented box more realistically.','Diagnosing weaker-than-predicted port output.','Sealing enclosure leaks to control losses.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Box loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1bc8a8a6-5c44-412a-aa46-9160a56b83e3','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1bc8a8a6-5c44-412a-aa46-9160a56b83e3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1bc8a8a6-5c44-412a-aa46-9160a56b83e3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b4aa0697-14df-40af-b127-de9048943d15','Box tuning frequency','The box tuning frequency (fb) is the Helmholtz resonance of a vented enclosure, set by the port''s air mass and the box''s air compliance. At fb the port radiation is greatest and the driver''s cone motion reaches a minimum.','A ported box resonates like a bottle you blow across. That resonance is the tuning frequency. At it, the port does most of the work. The cone barely moves there.','It sets where the port reinforces bass output and where cone excursion is minimized.','With a port area of 0.005 m2, a 0.05 m3 box, and 0.15 m effective port length, fb = (343/6.283) x sqrt(0.005 / (0.05 x 0.15)) is about 45 Hz.','Enclosure Parameter',ARRAY['Helmholtz resonance','Box loss','Butterworth alignment','Port length','Vent']::text[],ARRAY['Using the physical port length instead of the effective length with end correction.','UNSAFE: Choosing too small a port raises air speed and causes port chuffing and turbulence noise at high output.','Forgetting that stuffing changes the effective internal volume and shifts tuning.']::text[],ARRAY['Tuning a ported subwoofer to a target frequency.','Trimming port length to correct measured tuning.','Diagnosing chuffing from an undersized port.']::text[],'Intermediate','f_b = (c / (2*pi)) * sqrt( S_v / (V_b * L_eff) )','Box tuning frequency equals the speed of sound over two pi, times the square root of the port area divided by the box volume times the port''s effective length.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Box tuning frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b4aa0697-14df-40af-b127-de9048943d15','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b4aa0697-14df-40af-b127-de9048943d15') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b4aa0697-14df-40af-b127-de9048943d15');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '485ccd9b-368c-4aca-b081-40d35437210a','Broadside subwoofer array','A broadside subwoofer array is a row of subwoofers set side-by-side along a line and driven in phase, producing a broadside radiation pattern that narrows horizontal coverage and increases forward level as boxes are added. It has no inherent front-to-back cancellation.','Broadside means subs in a straight line, all firing forward together. The line narrows the side-to-side spread. It adds level straight ahead. It does not cancel behind by itself.','It controls horizontal low-frequency coverage and boosts on-axis output through coupling.','A technician lays a broadside sub line across the front of the stage to tighten horizontal pattern and raise forward level.','Array Configuration',ARRAY['End-fire array','Cardioid subwoofer array','Gradient array','Coupling','Directivity']::text[],ARRAY['Expecting rear cancellation, which requires cardioid or end-fire methods, not a plain broadside line.','UNSAFE: Very high combined SPL close to a broadside sub line can exceed safe hearing-exposure limits; keep workers back and use hearing protection.','Ignoring element spacing, which causes comb filtering across the line.']::text[],ARRAY['Designing festival subwoofer coverage.','Tightening horizontal low-frequency spread.','Coupling multiple subs for greater forward level.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Broadside subwoofer array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '485ccd9b-368c-4aca-b081-40d35437210a','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='485ccd9b-368c-4aca-b081-40d35437210a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='485ccd9b-368c-4aca-b081-40d35437210a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '34f5120f-aa99-4b9d-945d-3ce411defc6d','Butterworth alignment','A Butterworth alignment tunes a box so the system transfer function matches a Butterworth polynomial, giving a maximally flat amplitude response in the passband. The fourth-order Butterworth (B4) vented-box alignment requires a driver with a specific total Q near 0.383, with box volume near Vas and tuning near the driver''s free-air resonance.','A Butterworth alignment aims for the flattest bass response. No bumps sit in the passband. For a ported box, this needs a driver with a specific Q. The box volume roughly matches the driver''s Vas.','It achieves the flattest possible amplitude response for a given filter order.','For a B4 alignment, a technician selects a driver with Qts near 0.38, sets box volume near Vas, and tunes near the driver''s free-air resonance.','Box Alignment',ARRAY['Quasi-Butterworth alignment','Chebyshev alignment','Bessel alignment','Box tuning frequency','Maximally flat response']::text[],ARRAY['Forcing a driver with the wrong Qts into a B4 alignment.','Confusing maximally flat amplitude (Butterworth) with flat delay (Bessel).','Ignoring box losses that shift the real response away from the ideal.']::text[],ARRAY['Designing a flat-response vented box.','Selecting a driver for a target alignment.','Comparing alignment families for one project.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Butterworth alignment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '34f5120f-aa99-4b9d-945d-3ce411defc6d','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='34f5120f-aa99-4b9d-945d-3ce411defc6d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='34f5120f-aa99-4b9d-945d-3ce411defc6d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '13d46a49-987f-4f29-9fab-2ce35b74b346','C4 alignment','The C4 alignment is a fourth-order Chebyshev vented-box tuning that accepts a small amount of controlled passband ripple in exchange for extended low-frequency bandwidth compared with the Butterworth (B4) alignment. It suits drivers with higher total Q than the Butterworth case.','A C4 is a ported-box tuning that allows a little ripple. That small ripple buys extra low-end reach. It fits drivers with higher Q. It is one of the classic Thiele-Small alignments.','It extends usable bandwidth by trading a small, deliberate passband ripple for reach.','A technician accepts about a decibel of passband ripple in a C4 to gain deeper extension from a higher-Qts driver.','Box Alignment',ARRAY['Butterworth alignment','Chebyshev alignment','Quasi-Butterworth alignment','Box tuning frequency','Passband ripple']::text[],ARRAY['Assuming a ripple-free response, when C4 has deliberate passband ripple.','Confusing C4 (Chebyshev) with B4 (Butterworth).','Using a low-Qts driver where C4 is not suitable.']::text[],ARRAY['Extending bass reach from a given driver.','Comparing a C4 target against a B4 target.','Accepting mild ripple for bandwidth in a subwoofer.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='C4 alignment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '13d46a49-987f-4f29-9fab-2ce35b74b346','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='13d46a49-987f-4f29-9fab-2ce35b74b346') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='13d46a49-987f-4f29-9fab-2ce35b74b346');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '77733ee8-a2e5-4020-82ba-b2ba427b99a7','Cardioid radiation','Cardioid radiation is a heart-shaped directional pattern with strong output to the front and a deep null to the rear. Loudspeakers achieve it by combining monopole and gradient (dipole) sources, using spaced drivers, delay, or ports so rearward radiation cancels.','A cardioid pattern is heart-shaped. It sends sound forward strongly. Behind the speaker there is a deep null. Speakers create it by combining sources so the rear waves cancel.','It reduces sound radiated behind the loudspeaker, for example off a stage.','A technician builds a cardioid subwoofer array so bass is loud in the audience but much quieter on stage.','Radiation Pattern',ARRAY['Cardioid subwoofer array','End-fire array','Gradient source','Dipole enclosure','Directivity index']::text[],ARRAY['Expecting equal rear cancellation at all frequencies, when the effect is band-limited.','UNSAFE: A rear null does not remove the high SPL right next to the boxes; protect hearing near the array.','Setting the wrong delay or polarity, which can steer the null forward instead of rearward.']::text[],ARRAY['Reducing low-frequency bleed onto a stage.','Setting up a cardioid subwoofer configuration.','Designing directional low-frequency coverage.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cardioid radiation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '77733ee8-a2e5-4020-82ba-b2ba427b99a7','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='77733ee8-a2e5-4020-82ba-b2ba427b99a7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='77733ee8-a2e5-4020-82ba-b2ba427b99a7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4e354d8b-4bad-48a4-8cb3-1230f6ce68c2','Chebyshev alignment','A Chebyshev alignment tunes a box so its transfer function follows a Chebyshev polynomial, deliberately allowing equal-ripple variation in the passband in exchange for a steeper cutoff or extended bandwidth compared with the maximally flat Butterworth alignment.','A Chebyshev alignment allows small, even ripples in the response. In return, it reaches lower or rolls off more steeply. It is less flat than Butterworth. Designers choose it to gain bandwidth.','It trades passband flatness for extended reach or a steeper roll-off.','A technician selecting a C4 target accepts equal-ripple passband variation to extend a driver''s low-frequency reach.','Box Alignment',ARRAY['Butterworth alignment','C4 alignment','Bessel alignment','Passband ripple','Box tuning frequency']::text[],ARRAY['Assuming a Chebyshev response is flat, when it has intentional ripple.','Confusing amplitude ripple with audible distortion.','Applying it with a driver Qts that does not suit the alignment.']::text[],ARRAY['Extending bandwidth from a chosen driver.','Comparing Chebyshev and Butterworth targets.','Designing a subwoofer that accepts ripple for reach.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Chebyshev alignment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4e354d8b-4bad-48a4-8cb3-1230f6ce68c2','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4e354d8b-4bad-48a4-8cb3-1230f6ce68c2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4e354d8b-4bad-48a4-8cb3-1230f6ce68c2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a5ed19c7-35cd-4254-b90f-c48dca1c2e6a','Circumferential phase plug','A circumferential phase plug uses channels arranged as radial slots around the circumference between a compression driver''s diaphragm and throat. It equalizes path lengths so wavefronts from different diaphragm radii combine in phase and extend smooth high-frequency output.','This phase plug uses slots set around the driver like spokes. Each channel keeps the path length equal. Sound from the dome recombines in phase. This smooths the high frequencies.','It equalizes the path lengths from the diaphragm to the throat to avoid high-frequency cancellation.','A technician identifies the phase-plug type when servicing a compression driver, since it affects reassembly and high-frequency response.','Compression Driver Part',ARRAY['Annular phase plug','Compression chamber','Compression driver','Throat','Diaphragm']::text[],ARRAY['Confusing a circumferential (radial-slot) plug with an annular (concentric-ring) one.','Misaligning the plug on reassembly and shifting the high-frequency response.','Leaving debris that blocks the narrow channels.']::text[],ARRAY['Rebuilding a compression driver.','Comparing phase-plug designs for high-frequency smoothness.','Cleaning and reassembling a driver correctly.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Circumferential phase plug');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a5ed19c7-35cd-4254-b90f-c48dca1c2e6a','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a5ed19c7-35cd-4254-b90f-c48dca1c2e6a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a5ed19c7-35cd-4254-b90f-c48dca1c2e6a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7532c2d9-35d3-4baa-8329-19e4dd78e086','Closed-box Q','Closed-box Q (Qtc) is the total quality factor of a driver in a sealed enclosure at the system resonance, equal to the driver''s total Q times the square root of one plus the compliance ratio. A smaller box raises Qtc, and a Qtc of about 0.707 gives a maximally flat (Butterworth) sealed alignment.','Closed-box Q describes how peaky a sealed system is at resonance. A tight box raises it. Around 0.7 gives the flattest response. Higher sounds boomy, lower sounds lean.','It predicts the sealed system''s response shape and damping at resonance.','With Qts of 0.35, Vas of 60 L, and a 20 L box, Qtc = 0.35 x sqrt(60/20 + 1) = 0.35 x 2 = 0.70, a flat Butterworth sealed alignment.','Enclosure Parameter',ARRAY['Closed-box resonance','Box compliance','Butterworth alignment','Qts','Sealed enclosure']::text[],ARRAY['Confusing system Qtc with the driver''s own Qts.','Targeting Qtc too high (boomy) or too low (thin).','Using gross box volume instead of net volume.']::text[],ARRAY['Sizing a sealed box for a target response.','Aiming for a flat 0.707 sealed alignment.','Comparing damping between candidate box volumes.']::text[],'Intermediate','Q_tc = Q_ts * sqrt(V_as/V_b + 1)','Closed-box Q equals the driver''s total Q times the square root of one plus the ratio of equivalent volume to net box volume.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Closed-box Q');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7532c2d9-35d3-4baa-8329-19e4dd78e086','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7532c2d9-35d3-4baa-8329-19e4dd78e086') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7532c2d9-35d3-4baa-8329-19e4dd78e086');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4d8fb0d9-1e12-4bf8-b349-5e1db167a1c9','Closed-box resonance','Closed-box resonance (fc) is the resonance frequency of a driver in a sealed enclosure, raised above the driver''s free-air resonance by the added air-spring stiffness. It equals the free-air resonance times the square root of one plus the compliance ratio, and marks where cone excursion and impedance peak in the sealed system.','Putting a driver in a sealed box adds an air spring. That stiffer spring raises the resonance. A smaller box raises it more. This new resonance is the closed-box resonance.','It locates the sealed system''s resonance and low-frequency roll-off point.','With free-air resonance fs of 25 Hz, Vas of 60 L, and a 20 L box, fc = 25 x sqrt(60/20 + 1) = 25 x 2 = 50 Hz.','Enclosure Parameter',ARRAY['Closed-box Q','Box compliance','Free-air resonance','Sealed enclosure','Acoustic compliance of enclosure']::text[],ARRAY['Assuming a sealed box lowers resonance, when it actually raises it.','Confusing system fc with the driver''s free-air fs.','Ignoring how stuffing changes the effective box volume.']::text[],ARRAY['Predicting a sealed system''s roll-off.','Sizing a sealed subwoofer box.','Relating box volume to resonance shift.']::text[],'Intermediate','f_c = f_s * sqrt(V_as/V_b + 1)','Closed-box resonance equals the driver''s free-air resonance times the square root of one plus the ratio of equivalent volume to net box volume.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Closed-box resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4d8fb0d9-1e12-4bf8-b349-5e1db167a1c9','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4d8fb0d9-1e12-4bf8-b349-5e1db167a1c9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4d8fb0d9-1e12-4bf8-b349-5e1db167a1c9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f24d7f24-3e0f-4ded-b016-2767ade837d5','Compression chamber','The compression chamber (front chamber) is the small sealed air cavity between a compression driver''s diaphragm and the phase plug or throat. Its volume, together with the phase-plug slots, loads the diaphragm and helps set the high-frequency response and the driver''s compression of air into the throat.','A compression driver squeezes sound through a small cavity. That cavity sits between the dome and the horn throat. It is called the compression chamber. Its size shapes the high-end response.','It loads the diaphragm and concentrates its output into the narrow horn throat.','A technician keeps the diaphragm gap correct during replacement so the chamber volume, and the high-frequency response, are preserved.','Compression Driver Part',ARRAY['Compression ratio','Phase plug','Throat','Diaphragm','Compression driver']::text[],ARRAY['Setting the wrong diaphragm gap, which changes the chamber volume and response.','Confusing the front (compression) chamber with the rear chamber.','Trapping debris inside the chamber during service.']::text[],ARRAY['Rebuilding a compression driver.','Understanding a driver''s high-frequency loading.','Troubleshooting altered response after service.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compression chamber');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f24d7f24-3e0f-4ded-b016-2767ade837d5','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f24d7f24-3e0f-4ded-b016-2767ade837d5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f24d7f24-3e0f-4ded-b016-2767ade837d5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4a7b3da6-4a87-43b0-b55c-f633f034c958','Compression ratio','In a compression driver, the compression ratio is the ratio of the diaphragm''s effective radiating area to the horn throat area. Typical values of roughly 5:1 to 10:1 raise the acoustic pressure and improve coupling efficiency at the throat.','A compression driver pushes a large dome into a small throat. The compression ratio compares those two areas. Bigger ratios raise pressure at the throat. Typical values are about five to ten to one.','It increases pressure and efficiency by concentrating the diaphragm''s output into a small throat.','A diaphragm area of 13 cm2 feeding a 2 cm2 throat gives a compression ratio of 13/2, about 6.5 to 1.','Compression Driver Parameter',ARRAY['Compression chamber','Throat','Diaphragm','Horn (waveguide)','Loading']::text[],ARRAY['Confusing this area ratio with power or dynamic-range compression.','Assuming a higher ratio is always better, when very high ratios raise distortion.','Mixing area units when computing the ratio.']::text[],ARRAY['Comparing compression drivers on paper.','Matching a driver to a horn throat size.','Estimating throat pressure and efficiency.']::text[],'Intermediate','CR = S_d / S_t','Compression ratio equals the effective diaphragm area divided by the throat area.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compression ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4a7b3da6-4a87-43b0-b55c-f633f034c958','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4a7b3da6-4a87-43b0-b55c-f633f034c958') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4a7b3da6-4a87-43b0-b55c-f633f034c958');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e168c578-e1f7-491d-9dab-dc89aadef529','Conical horn','A conical horn has straight walls whose cross-sectional area expands with the square of the axial distance from the apex. Its coverage angle is set mainly by the wall angle and stays fairly constant with frequency, but it loads the driver less at low frequencies and has a higher effective cutoff than an exponential horn.','A conical horn has straight, sloping walls. Its opening angle sets the coverage. That angle stays fairly steady with frequency. But it loads the driver less in the bass than a flared horn.','It provides predictable, roughly constant-angle coverage, making it a basis for constant-directivity designs.','A technician chooses a conical constant-directivity horn when steady coverage angle matters more than deep low-frequency loading.','Horn Type',ARRAY['Exponential horn','Constant directivity','Bi-radial horn','Flare rate','Horn cutoff']::text[],ARRAY['Assuming a conical horn loads the driver like an exponential horn in the bass.','Treating the coverage angle as exactly the wall angle at every frequency.','Ignoring throat-mismatch reflections that cause response ripple.']::text[],ARRAY['Designing constant-directivity horns.','Planning coverage angle for a room.','Comparing conical and exponential flare behavior.']::text[],'Advanced','S(x) = S_t * (x / x_0)^2','The cross-sectional area grows with the square of the distance from the apex.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Conical horn');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e168c578-e1f7-491d-9dab-dc89aadef529','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e168c578-e1f7-491d-9dab-dc89aadef529') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e168c578-e1f7-491d-9dab-dc89aadef529');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '73c7fe8b-847a-4a2a-9f1f-10e84275be0a','Constant directivity','Constant directivity is a design goal, especially for horns, in which the radiated coverage angle stays roughly independent of frequency across the operating band, keeping tonal balance uniform throughout the coverage area. It is realized by constant-directivity horns and waveguides developed by Keele, Henricksen and Ureda, and others.','Constant directivity means the coverage angle stays the same across frequencies. High and low notes cover the same area. So the tone is even everywhere in the pattern. Special horn shapes achieve this.','It keeps frequency balance consistent for every listener inside the coverage area.','A technician chooses a 60 by 40 degree constant-directivity horn so on-axis and off-axis listeners hear a similar tonal balance.','Directivity Concept',ARRAY['Constant-beamwidth transducer','Bi-radial horn','CD waveguide','Directivity index','Beamwidth']::text[],ARRAY['Assuming constant directivity holds at the very highest frequencies, when beaming returns above the CD band.','Forgetting that constant-directivity horns need high-frequency EQ boost for their falling on-axis response.','Confusing directivity control with sensitivity or efficiency.']::text[],ARRAY['Planning even room coverage.','Applying high-frequency EQ to a constant-directivity horn.','Comparing horn designs for uniform tonal balance.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Constant directivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '73c7fe8b-847a-4a2a-9f1f-10e84275be0a','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='73c7fe8b-847a-4a2a-9f1f-10e84275be0a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='73c7fe8b-847a-4a2a-9f1f-10e84275be0a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5fa2c75c-d012-4d78-a17b-9fb92ebe878e','Constant-beamwidth transducer','A constant-beamwidth transducer (CBT) is a source whose beamwidth stays nearly constant with frequency, realized by amplitude-shading a curved (circular-arc) array so its radiation approximates a spherical-cap source. D. B. Keele adapted the concept to audio line arrays from underwater-acoustics work by Rogers and Van Buren.','A CBT keeps its coverage angle steady across frequency. It uses drivers on a curved arc. Their levels are shaded, loudest in the middle. This gives smooth, even coverage without harsh lobes.','It provides frequency-independent, smooth coverage from a line array with minimal off-axis lobing.','A technician deploys a CBT circular-arc array for even coverage down a long room with little corrective EQ.','Directivity Concept',ARRAY['Constant directivity','Line array','Beamwidth','Amplitude shading','Ground-plane array']::text[],ARRAY['Expecting a straight, unshaded line array to behave like a CBT.','Ignoring the amplitude taper that a CBT requires.','Confusing a CBT arc with a conventional curved J-array.']::text[],ARRAY['Achieving even coverage in a long or reverberant room.','Applying amplitude shading to an arc array.','Comparing a CBT to a conventional line array.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Constant-beamwidth transducer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5fa2c75c-d012-4d78-a17b-9fb92ebe878e','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5fa2c75c-d012-4d78-a17b-9fb92ebe878e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5fa2c75c-d012-4d78-a17b-9fb92ebe878e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c82b7a8b-03c9-4c86-8531-af046db53dc2','Coverage balloon','A coverage balloon is a directivity balloon plot used specifically to visualize a loudspeaker''s coverage, showing its three-dimensional radiated level surface at one or more frequencies so designers can see where output is strong or weak. It is essentially the directivity balloon used in acoustic prediction software.','A coverage balloon is a three-dimensional picture of a speaker''s reach. Bulges show loud directions. Dents show weak ones. Designers use it to aim speakers at the audience.','It visualizes a loudspeaker''s coverage so designers can aim and choose loudspeakers.','A technician rotates a coverage balloon in prediction software to confirm the audience sits inside the strong-output region.','Directivity Data',ARRAY['Balloon plot','Directivity index','Beamwidth','Polar pattern','Coverage angle']::text[],ARRAY['Reading a single frequency''s balloon as the whole coverage picture.','Treating the balloon radius as distance rather than relative level.','Ignoring how multiple loudspeakers interact when overlaid.']::text[],ARRAY['Aiming loudspeakers to cover an audience.','Modeling coverage during system design.','Presenting a coverage prediction to a client.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coverage balloon');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c82b7a8b-03c9-4c86-8531-af046db53dc2','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c82b7a8b-03c9-4c86-8531-af046db53dc2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c82b7a8b-03c9-4c86-8531-af046db53dc2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '414ed549-b0a5-4f34-9355-0bc65d3bd989','Crossover lobing','Crossover lobing is the tilting and rippling of the combined radiation pattern near a multi-way loudspeaker''s crossover region. It is caused by path-length differences between spaced drivers that both radiate there, producing constructive and destructive interference that shifts the main lobe off the intended axis.','Near the crossover, two drivers both make sound at once. They sit apart, so their waves interfere. The combined pattern tilts and ripples. The loudest direction can move off the intended axis.','It names an interference effect designers must manage when spaced drivers overlap in a crossover region.','A technician measures vertically off-axis to spot lobing, then adjusts crossover slope, polarity, or driver spacing to recenter the lobe.','Radiation Effect',ARRAY['Lobing error','Crossover','Apparent acoustic center','Directivity index','Comb filtering']::text[],ARRAY['Measuring only on-axis and missing the lobing entirely.','Confusing driver-spacing lobing with comb filtering from room reflections.','Ignoring driver spacing and crossover slope as causes.']::text[],ARRAY['Voicing a multi-way loudspeaker.','Measuring vertical off-axis response.','Choosing crossover slope and driver layout.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Crossover lobing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '414ed549-b0a5-4f34-9355-0bc65d3bd989','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='414ed549-b0a5-4f34-9355-0bc65d3bd989') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='414ed549-b0a5-4f34-9355-0bc65d3bd989');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'af8ebc10-b063-4f55-8a5d-4e6fe0a1d505','Diffraction horn','A horn that widens horizontal coverage by passing sound through a narrow slot or aperture, so the wavefront diffracts (spreads) at the slot edges. The narrow dimension is kept small relative to the wavelength, forcing wide dispersion rather than a beam.','A diffraction horn spreads sound sideways on purpose. It squeezes the wave through a thin slot. Small openings make sound bend and fan out wide. This gives broad, even coverage instead of a tight beam.','It exploits diffraction at a narrow slot to hold wide, fairly steady horizontal coverage across a broad frequency range.','A technician picks a diffraction (slot) horn when a fill zone needs wide, even side-to-side coverage rather than a narrow throw.','Horn type',ARRAY['Constant-directivity horn','Mouth diffraction','Directivity narrowing','Multicellular horn','Horn mouth']::text[],ARRAY['Assuming the wide pattern stays perfectly flat with frequency; it narrows as wavelength shrinks.','Confusing a diffraction slot horn with a simple exponential horn.','UNSAFE: Standing close to a high-SPL horn without hearing protection during setup and tuning.']::text[],ARRAY['Choosing a wide-dispersion horn for front-fill coverage.','Explaining why a slot horn fans sound out sideways.','Comparing diffraction horns with modern constant-directivity waveguides.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffraction horn');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'af8ebc10-b063-4f55-8a5d-4e6fe0a1d505','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='af8ebc10-b063-4f55-8a5d-4e6fe0a1d505') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='af8ebc10-b063-4f55-8a5d-4e6fe0a1d505');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8e2e0743-0501-4837-9655-0fb9a2e88d67','Dipole enclosure','A baffle or open enclosure that lets a driver radiate from both its front and rear with opposite polarity, creating a figure-of-eight (cosine) directivity pattern with deep nulls to the sides. With no sealed air load, its low-frequency output falls at about 6 dB per octave as front and rear waves increasingly cancel.','A dipole speaker is open at the back. Sound comes off the front and the rear. The two sides are out of phase, so they cancel to the sides. This makes a figure-eight pattern with quiet spots at 90 degrees.','It gives a controlled figure-eight radiation pattern and reduced side output, which can lower room excitation from side reflections.','A technician equalizes a dipole to offset its natural 6 dB per octave bass rolloff and aims the side nulls toward nearby reflective surfaces (such as side walls) to reduce the energy those surfaces reflect back.','Enclosure type',ARRAY['Gradient loudspeaker','Open baffle','Baffle step','Directivity','Cardioid loudspeaker']::text[],ARRAY['Forgetting the front and rear waves cancel, so bass needs boost or a large baffle.','Placing a dipole tight against a wall, which fills its rear null.','Confusing a dipole (figure-eight) with a cardioid (one-sided) pattern.']::text[],ARRAY['Setting up open-baffle monitors and correcting their bass rolloff.','Aiming dipole nulls to reduce side-wall reflections.','Explaining why an open-back speaker loses low bass.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dipole enclosure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8e2e0743-0501-4837-9655-0fb9a2e88d67','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8e2e0743-0501-4837-9655-0fb9a2e88d67') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8e2e0743-0501-4837-9655-0fb9a2e88d67');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ad771cf6-24ea-4642-8ac6-e5cb38244563','Directivity discontinuity','An abrupt change in a loudspeaker system''s coverage angle over a small frequency span, typically where two drivers or devices of different beamwidth hand over at a crossover. It shows up as a sudden widening or narrowing of the polar pattern rather than a smooth transition.','Directivity discontinuity is a sudden jump in how wide a speaker covers. It usually happens at a crossover. One driver is wide, the next is narrow. The coverage snaps from one width to another instead of blending.','Naming this fault helps designers spot places where coverage changes too fast, which harms off-axis tonal balance.','A technician checks polar plots near the crossover and adjusts the crossover point so the two drivers'' beamwidths line up.','Directivity behavior',ARRAY['Directivity mismatch','Constant-directivity horn','Power response','Crossover frequency','Beamwidth']::text[],ARRAY['Judging a system only on-axis and missing the off-axis coverage jump.','Assuming a flat on-axis response guarantees smooth directivity.','Blaming room acoustics for a problem built into the crossover.']::text[],ARRAY['Reading a directivity sonogram and finding a jump at the crossover.','Choosing a crossover point where cone and horn beamwidths match.','Diagnosing uneven tonal balance for off-axis listeners.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directivity discontinuity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ad771cf6-24ea-4642-8ac6-e5cb38244563','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ad771cf6-24ea-4642-8ac6-e5cb38244563') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ad771cf6-24ea-4642-8ac6-e5cb38244563');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a86fafb9-8245-4be9-bd8b-b8f623530ac5','Directivity mismatch','A condition where two drivers meeting at a crossover have different beamwidths at that frequency, so their combined off-axis response is uneven even when the on-axis response is smooth. The result is a bump or dip in radiated power and a lobing pattern that changes with angle.','Directivity mismatch means two drivers cover different widths where they cross over. On-axis may sound fine. Off to the side, the balance goes wrong. The wide driver spreads more energy than the narrow one at the same pitch.','The idea guides driver and horn selection so that neighbouring bands cover the same angle where they blend.','A technician matches a horn''s beamwidth to the cone''s beamwidth at crossover, or moves the crossover to where they agree.','Directivity behavior',ARRAY['Directivity discontinuity','Constant-directivity horn','Power response','Crossover frequency','Beamwidth']::text[],ARRAY['Setting a crossover only by on-axis response and ignoring coverage angle.','Pairing a wide cone with a narrow horn at the same crossover frequency.','Assuming power response follows the on-axis curve.']::text[],ARRAY['Matching a compression-driver horn to a woofer at crossover.','Explaining an off-axis tonal dip that on-axis measurements miss.','Selecting a waveguide whose pattern matches the woofer.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directivity mismatch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a86fafb9-8245-4be9-bd8b-b8f623530ac5','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a86fafb9-8245-4be9-bd8b-b8f623530ac5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a86fafb9-8245-4be9-bd8b-b8f623530ac5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8c9378a8-c5e9-41b2-a3a4-3c2a49cfb297','Directivity narrowing','The tendency of a radiator''s coverage angle to shrink as frequency rises, because the effective radiating aperture grows large relative to the wavelength. It is the main reason plain cones and dome drivers ''beam'' at high frequencies.','Directivity narrowing means a speaker aims tighter as pitch goes up. High notes have short waves. A driver looks large compared to those short waves. So the sound focuses into a narrower beam.','Understanding it explains why coverage changes with frequency and why horns and waveguides are used to control the pattern.','A technician expects a bare cone to beam above the frequency where its diameter nears one wavelength, so a smaller driver or waveguide is used for treble.','Directivity behavior',ARRAY['Beamwidth','Constant-directivity horn','Directivity index','Radiating aperture','Diffraction horn']::text[],ARRAY['Expecting a large cone to keep wide coverage up to high frequencies.','Confusing narrowing caused by size with a crossover setting.','Judging coverage from on-axis response alone.']::text[],ARRAY['Explaining why a 12-inch cone beams in the high midrange.','Choosing a tweeter size for wider treble coverage.','Deciding where a waveguide is needed to hold pattern.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directivity narrowing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8c9378a8-c5e9-41b2-a3a4-3c2a49cfb297','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8c9378a8-c5e9-41b2-a3a4-3c2a49cfb297') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8c9378a8-c5e9-41b2-a3a4-3c2a49cfb297');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '40062a7d-c858-465e-b9ef-a54c725caf2c','Directivity sonogram','A two-dimensional map of a loudspeaker''s directivity showing frequency on one axis and off-axis angle on the other, with sound level drawn as contour lines or colour. It compresses a full set of polar measurements into one picture of how coverage changes with frequency.','A directivity sonogram is a coverage map. One axis is frequency. The other is the angle off-center. Color or lines show how loud each spot is. It reveals how wide the speaker covers at every pitch.','It lets a designer see pattern control, beaming, and directivity jumps across the whole band at a glance.','A technician reads a sonogram to confirm a horn holds its rated coverage and to spot narrowing or a crossover discontinuity.','Measurement display',ARRAY['Directivity spectrogram','Beamwidth','Constant-directivity horn','Polar response','Directivity narrowing']::text[],ARRAY['Reading absolute level from a normalized sonogram, where on-axis is set to zero.','Ignoring that angle resolution depends on how many polars were measured.','Confusing a directivity map with a simple frequency-response curve.']::text[],ARRAY['Verifying a horn keeps 60 by 40 degree coverage across its band.','Comparing two waveguides for pattern control.','Documenting a loudspeaker''s directivity for a spec sheet.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directivity sonogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '40062a7d-c858-465e-b9ef-a54c725caf2c','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='40062a7d-c858-465e-b9ef-a54c725caf2c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='40062a7d-c858-465e-b9ef-a54c725caf2c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '004bd851-0177-4b04-89da-9b0fcf4c536b','Directivity spectrogram','A frequency-versus-angle colour map of a loudspeaker''s normalized directivity, essentially the same display as a directivity sonogram and often used as a synonym for it. Contours mark angles where output has fallen by set amounts (for example -6 dB) relative to the on-axis level.','A directivity spectrogram is a colored coverage map. It plots frequency against off-axis angle. The colors show how the level drops as you move off-center. Many people use this name for the same thing as a sonogram.','It presents full polar data in one image so coverage and pattern control can be judged across frequency.','A technician uses the -6 dB contour on the map to read the horn''s beamwidth at each frequency.','Measurement display',ARRAY['Directivity sonogram','Beamwidth','Polar response','Constant-directivity horn','Isobar plot']::text[],ARRAY['Assuming ''spectrogram'' here means a time-based audio display; this one is angle versus frequency.','Treating the normalized map as absolute SPL.','Comparing maps with different color or contour scales as if identical.']::text[],ARRAY['Reading a manufacturer''s directivity map to pick a horn.','Checking that coverage stays constant with frequency.','Comparing pattern control between two devices.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directivity spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '004bd851-0177-4b04-89da-9b0fcf4c536b','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='004bd851-0177-4b04-89da-9b0fcf4c536b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='004bd851-0177-4b04-89da-9b0fcf4c536b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2754c52e-1321-4e5b-9c69-c2834f00072e','Enclosure compliance','The acoustic compliance (springiness) of the air trapped inside a sealed loudspeaker box, which acts as an added stiffness on the driver and raises the system resonance. It is set by the box volume divided by the product of air density and the square of the speed of sound.','The air in a sealed box acts like a spring. Enclosure compliance measures how soft that spring is. A bigger box is a softer spring. A smaller box is stiffer and pushes the resonance higher.','It quantifies how much a box stiffens the driver, letting a designer predict the sealed-system resonance and bass alignment.','For a 28-litre (0.028 m^3) sealed box, C_ab = 0.028 / (1.2 * 343^2) is about 2.0e-7 m^3/Pa (m^5/N).','Enclosure parameter',ARRAY['Sealed enclosure','Equivalent volume (Vas)','System resonance','Total Q (Qtc)','Driver compliance']::text[],ARRAY['Using the box''s outside volume instead of the net internal air volume.','Forgetting that bracing and driver displacement reduce usable volume.','Assuming a smaller box always sounds tighter without checking the raised Q.']::text[],ARRAY['Sizing a sealed subwoofer box for a target resonance.','Explaining why a small box lifts the system resonance.','Comparing a driver''s Vas with the chosen box volume.']::text[],'Advanced','C_ab = V_b / (rho * c^2)','Box acoustic compliance equals the enclosed air volume divided by air density times the speed of sound squared.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Enclosure compliance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2754c52e-1321-4e5b-9c69-c2834f00072e','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2754c52e-1321-4e5b-9c69-c2834f00072e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2754c52e-1321-4e5b-9c69-c2834f00072e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '074c117f-e085-419c-9ed2-133f66bd80bb','End-fire subwoofer array','A directional low-frequency array in which several subwoofers are spaced in a line along the direction of throw, each delayed so their outputs add in front and cancel behind. The delay per box equals the physical spacing divided by the speed of sound.','An end-fire array lines up subs front to back. Each rear sub gets a small time delay. The delays make the sound add up going forward. Behind the array, the waves cancel, so the stage stays quieter.','It steers bass energy toward the audience and away from the stage, cutting low-frequency spill and feedback behind the array.','For subs spaced 1 m apart, set each delay to t = d/c = 1 / 343 = about 2.9 ms so the rear box fires first.','Array technique',ARRAY['Cardioid subwoofer array','Gradient loudspeaker','Directional bass','Delay tapering','Broadside array']::text[],ARRAY['Setting the delay from the wrong reference so the pattern points backward.','Spacing boxes too far apart, which breaks the cancellation at higher bass frequencies.','UNSAFE: Rigging or stacking heavy subwoofers without proper restraint, straps, or ballast.']::text[],ARRAY['Reducing bass on stage at an outdoor concert.','Setting delays on a row of subs for forward-directed bass.','Comparing end-fire and cardioid sub setups for a venue.']::text[],'Advanced','t = d / c','The delay for each element equals the spacing between elements divided by the speed of sound.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='End-fire subwoofer array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '074c117f-e085-419c-9ed2-133f66bd80bb','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='074c117f-e085-419c-9ed2-133f66bd80bb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='074c117f-e085-419c-9ed2-133f66bd80bb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9236506d-7980-44c9-ab60-8d9340d9335c','Exponential horn','A horn whose cross-sectional area grows exponentially with distance from the throat, giving a constant flare rate and a well-defined low-frequency cutoff. Its area follows S(x) = S_t * e^(m*x), where m is the flare constant.','An exponential horn gets wider at a steady rate. Its area doubles over equal steps of length. This shape loads the driver well down to a set low limit. Below that cutoff, the horn stops working efficiently.','It efficiently matches a small driver to the air over a wide band and was long the standard horn profile.','With throat area S_t = 0.001 m^2 and flare m = 4 per metre, at x = 0.5 m the area is 0.001 * e^2 = about 0.0074 m^2.','Horn type',ARRAY['Flare constant','Flare rate','Horn cutoff frequency','Hyperbolic-exponential horn','Horn throat']::text[],ARRAY['Expecting full output below the horn''s cutoff frequency.','Confusing the acoustic flare cutoff with an electrical high-pass setting.','Ignoring that a small mouth still limits real low-frequency loading.']::text[],ARRAY['Designing a midrange horn with a target cutoff.','Explaining the steady rate at which a horn opens up.','Comparing exponential and conical horn loading.']::text[],'Advanced','S(x) = S_t * e^(m*x)','Cross-sectional area at distance x equals the throat area times e raised to the flare constant times x.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Exponential horn');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9236506d-7980-44c9-ab60-8d9340d9335c','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9236506d-7980-44c9-ab60-8d9340d9335c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9236506d-7980-44c9-ab60-8d9340d9335c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8408409c-acae-46cb-b783-88d544f8cef1','Flare constant','The constant m in an exponential horn''s area law S(x) = S_t * e^(m*x), expressed in reciprocal metres, that sets how fast the horn opens and thus its cutoff frequency. A larger flare constant means a faster expansion and a higher cutoff.','The flare constant is the number that sets how fast a horn widens. A big value means the horn opens quickly. A small value means it opens slowly. It directly fixes the horn''s low-frequency limit.','It is the single design number that ties an exponential horn''s shape to its cutoff frequency.','With m = 4 per metre and c = 343 m/s, the cutoff is f_c = m*c/(4*pi) = 4*343/12.57 = about 109 Hz.','Horn parameter',ARRAY['Flare rate','Exponential horn','Horn cutoff frequency','Horn throat','Hyperbolic-exponential horn']::text[],ARRAY['Mixing up units, since m is per metre, not a percentage.','Assuming a faster flare gives deeper bass; it actually raises cutoff.','Treating the flare constant as the only limit while ignoring mouth size.']::text[],ARRAY['Calculating a horn''s cutoff from its flare.','Choosing a flare to place cutoff below the crossover.','Comparing two horns of different expansion speed.']::text[],'Advanced','f_c = m*c / (4*pi)','Cutoff frequency equals the flare constant times the speed of sound, divided by four times pi.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flare constant');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8408409c-acae-46cb-b783-88d544f8cef1','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8408409c-acae-46cb-b783-88d544f8cef1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8408409c-acae-46cb-b783-88d544f8cef1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c467968d-0588-4a38-bff3-659c0febf522','Flare rate','The rate at which a horn''s cross-section expands along its length; for an exponential horn it equals the flare constant m and directly determines the cutoff frequency. A higher flare rate opens the horn faster and raises the frequency below which loading collapses.','Flare rate is how quickly a horn widens along its length. Open it fast and the cutoff moves up. Open it slowly and the cutoff drops. For an exponential horn, flare rate is the same as the flare constant.','It links a horn''s physical expansion to its usable low-frequency limit and its loading behaviour.','To reach a 50 Hz cutoff, solve m = 4*pi*f_c/c = 4*pi*50/343 = about 1.83 per metre for an exponential flare.','Horn parameter',ARRAY['Flare constant','Exponential horn','Horn cutoff frequency','Hyperbolic-exponential horn','Horn mouth']::text[],ARRAY['Believing a faster flare gives more low bass; it raises cutoff instead.','Confusing flare rate with the physical length of the horn.','Ignoring that mouth size sets the real low-frequency limit too.']::text[],ARRAY['Setting a flare to reach a target cutoff.','Explaining the trade between horn size and low-frequency reach.','Comparing slow and fast flaring horns.']::text[],'Advanced','f_c = m*c / (4*pi)','Cutoff frequency equals the flare rate times the speed of sound, divided by four times pi.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flare rate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c467968d-0588-4a38-bff3-659c0febf522','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c467968d-0588-4a38-bff3-659c0febf522') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c467968d-0588-4a38-bff3-659c0febf522');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8226a9bc-8602-4347-b754-e005842ffce2','Front-loaded horn','A horn placed on the front (radiating) face of a driver''s diaphragm, so the throat sees the front side of the cone or compression diaphragm directly. It contrasts with rear- or back-loaded horns, which are fed by the diaphragm''s back side.','A front-loaded horn sits in front of the speaker cone. The cone''s front pushes straight into the horn throat. This is the common horn layout. It loads and directs the sound coming off the front.','It couples the driver''s front output to the air through the horn for higher efficiency and controlled directivity.','A technician uses a front-loaded bass horn for high output but checks that its cutoff and mouth size suit the target low frequency.','Horn type',ARRAY['Rear-loaded horn','Horn throat','Compression driver','Front-loaded bass horn','Horn cutoff frequency']::text[],ARRAY['Confusing front-loaded with rear-loaded (back-loaded) horn layouts.','Expecting deep bass from a short front horn with a small mouth.','UNSAFE: Working near a high-output horn at full level without hearing protection.']::text[],ARRAY['Selecting a front-loaded horn subwoofer for a large venue.','Explaining how a compression driver mounts to a horn throat.','Comparing front-loaded and back-loaded cabinet designs.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Front-loaded horn');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8226a9bc-8602-4347-b754-e005842ffce2','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8226a9bc-8602-4347-b754-e005842ffce2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8226a9bc-8602-4347-b754-e005842ffce2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '087e1b13-12bc-4f3a-b394-31a74f7ba8c5','Gradient loudspeaker','A loudspeaker whose radiation is governed by the pressure gradient between two closely spaced sources or sides of a diaphragm, producing an inherently directional pattern. A first-order gradient source radiates as a dipole (figure-eight), and combining orders can yield cardioid-type patterns.','A gradient loudspeaker works from the difference in pressure between two points. That difference makes it directional by nature. A basic gradient source is a dipole with a figure-eight pattern. Mixing effects can make a one-sided, cardioid pattern.','It provides directional low-frequency or broadband radiation without relying on a large sealed box, useful for controlling spill.','A technician deploys gradient (cardioid) subwoofer setups so bass is directed at the audience and reduced behind the array.','Radiation type',ARRAY['Dipole enclosure','Cardioid subwoofer array','End-fire subwoofer array','Directivity','Open baffle']::text[],ARRAY['Assuming any open-back speaker is a true controlled gradient source.','Forgetting gradient sources lose low-frequency output to front-back cancellation.','Confusing a first-order dipole with a cardioid pattern.']::text[],ARRAY['Building a cardioid sub array from gradient principles.','Explaining the link between gradient microphones and gradient speakers.','Reducing stage bass with directional sources.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gradient loudspeaker');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '087e1b13-12bc-4f3a-b394-31a74f7ba8c5','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='087e1b13-12bc-4f3a-b394-31a74f7ba8c5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='087e1b13-12bc-4f3a-b394-31a74f7ba8c5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1d002416-034c-4914-834a-bc5dc71b4b43','Higher-order horn mode','An acoustic mode inside a horn or waveguide in which the wavefront is no longer a simple single-parameter wave, arising above a frequency set by the passage''s transverse dimensions. These higher-order modes (HOMs) add cross-channel resonances that colour the response and disturb the directivity.','Inside a wide horn, sound can bounce across the mouth as well as along it. These extra patterns are higher-order modes. They appear once the horn is wide compared to the wavelength. They cause ripples and coloration in the sound.','The concept explains high-frequency coloration and pattern irregularities that simple one-dimensional horn theory misses.','A technician favours smooth-walled waveguides and gentle flares to delay higher-order modes and keep the response clean.','Horn theory',ARRAY['Horn honk','Waveguide','Directivity discontinuity','Mouth diffraction','Compression driver']::text[],ARRAY['Assuming plane-wave horn theory fully predicts a wide horn''s high-frequency response.','Blaming only the driver for coloration that comes from horn modes.','Ignoring that sharp geometry changes excite higher-order modes.']::text[],ARRAY['Explaining high-frequency roughness in a wide horn.','Choosing a waveguide profile to suppress internal modes.','Interpreting ripples in a horn''s measured response.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Higher-order horn mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1d002416-034c-4914-834a-bc5dc71b4b43','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1d002416-034c-4914-834a-bc5dc71b4b43') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1d002416-034c-4914-834a-bc5dc71b4b43');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ec903e6c-1c20-4273-b276-a72e9dd74138','Horn cutoff frequency','The lowest frequency at which a horn still couples the diaphragm efficiently to the air; below it the acoustic loading collapses and radiated output falls off sharply. For an exponential horn it is fixed by the flare constant and the speed of sound.','Every horn has a low-frequency limit. That limit is the cutoff frequency. Above it, the horn loads the driver well. Below it, the horn stops working and output drops fast.','It defines the usable low-frequency edge of a horn so the driver is not asked to work where loading fails.','For an exponential horn with flare m = 2 per metre, f_c = m*c/(4*pi) = 2*343/12.57 = about 55 Hz.','Horn theory',ARRAY['Flare constant','Flare rate','Exponential horn','Horn mouth','Mouth circumference']::text[],ARRAY['Trying to use a horn well below cutoff and expecting full output.','Confusing the acoustic cutoff with an electrical high-pass filter.','Ignoring that mouth size, not just flare, limits real low-frequency loading.']::text[],ARRAY['Choosing a horn whose cutoff sits below the crossover.','Explaining why a small horn cannot reproduce low midrange.','Protecting a driver by not driving it below horn cutoff.']::text[],'Advanced','f_c = m*c / (4*pi)','The horn cutoff frequency equals the flare constant times the speed of sound, divided by four times pi.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Horn cutoff frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ec903e6c-1c20-4273-b276-a72e9dd74138','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ec903e6c-1c20-4273-b276-a72e9dd74138') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ec903e6c-1c20-4273-b276-a72e9dd74138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7eceb4a9-f7ac-45d7-b7c4-34a5d4d87702','Horn honk','A midrange coloration, often described as ''honky'' or nasal, caused by resonances inside a horn from mouth reflections, standing waves, and abrupt geometry. It concentrates energy in a narrow band and departs from a smooth response.','Horn honk is a nasal, honky midrange sound. It comes from echoes and resonances inside the horn. Reflections at the mouth bounce back and pile up. That extra energy colors the tone.','Naming this coloration helps technicians link a subjective flaw to real causes like mouth reflection and standing waves.','A technician reduces honk by choosing a horn with a smooth flare and well-rounded mouth, and by equalizing the offending band.','Horn artifact',ARRAY['Mouth reflection','Higher-order horn mode','Standing wave','Mouth termination','Horn mouth']::text[],ARRAY['Blaming the driver alone when the horn geometry causes the coloration.','Trying to fully fix honk with EQ while ignoring reflections and modes.','Assuming all horns honk, when good termination greatly reduces it.']::text[],ARRAY['Diagnosing a nasal midrange in a horn-loaded speaker.','Comparing an abrupt old horn with a smooth modern waveguide.','Explaining why mouth rounding cleans up horn tone.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Horn honk');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7eceb4a9-f7ac-45d7-b7c4-34a5d4d87702','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7eceb4a9-f7ac-45d7-b7c4-34a5d4d87702') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7eceb4a9-f7ac-45d7-b7c4-34a5d4d87702');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '237a4fd1-35f0-492c-b2cf-8d7f4be0644a','Horn mouth','The large open end of a horn where sound exits into the surrounding air; its area and circumference set how well the horn loads at low frequencies and where directivity control ends. A mouth too small for the wavelength reflects energy back into the horn and causes response ripple.','The horn mouth is the big open end. Sound leaves the horn there and spreads into the room. A large mouth loads low notes well. A small mouth reflects low notes back and adds ripple.','It terminates the horn into the air; its size governs low-frequency loading and the lowest frequency where the pattern is controlled.','A technician sizes the mouth so its circumference is at least one wavelength at cutoff, giving smooth loading down to that frequency.','Horn part',ARRAY['Horn throat','Mouth circumference','Mouth reflection','Mouth diffraction','Mouth termination']::text[],ARRAY['Making the mouth too small, which raises the real cutoff and adds ripple.','Assuming flare alone sets low-frequency reach while ignoring mouth size.','Forgetting the mouth also sets where pattern control gives out.']::text[],ARRAY['Sizing a horn mouth for a target low frequency.','Explaining ripple caused by an undersized mouth.','Comparing large and small mouths for directivity control.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Horn mouth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '237a4fd1-35f0-492c-b2cf-8d7f4be0644a','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='237a4fd1-35f0-492c-b2cf-8d7f4be0644a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='237a4fd1-35f0-492c-b2cf-8d7f4be0644a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a20253c5-85cb-40ea-a2bc-6fe3bb1cf816','Horn throat','The small end of a horn at the driver, where the diaphragm couples into the horn and the acoustic impedance seen by the diaphragm is highest. Throat area, together with the diaphragm area, sets the compression ratio and the initial loading on the driver.','The horn throat is the narrow end at the driver. The diaphragm pushes into this small opening. A small throat raises the load on the driver. This boosts efficiency but can add strain and distortion.','It presents a high acoustic load to the diaphragm, transforming its motion into efficient radiation through the horn.','A technician checks that the compression driver''s exit matches the horn throat diameter to avoid a step and reflection at the joint.','Horn part',ARRAY['Horn mouth','Compression driver','Compression ratio','Acoustic impedance','Exponential horn']::text[],ARRAY['Mismatching the driver exit and throat, creating a discontinuity and reflection.','Using too high a compression ratio, which raises distortion.','UNSAFE: Overdriving a throat-loaded compression driver to extreme SPL near unprotected ears.']::text[],ARRAY['Matching a compression driver to a horn throat.','Explaining why throat size affects efficiency and distortion.','Inspecting the driver-to-horn joint for a smooth transition.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Horn throat');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a20253c5-85cb-40ea-a2bc-6fe3bb1cf816','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a20253c5-85cb-40ea-a2bc-6fe3bb1cf816') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a20253c5-85cb-40ea-a2bc-6fe3bb1cf816');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '846aa733-74e4-4238-8cc3-068972e9c5b5','Hyperbolic horn','A horn from the Salmon (hypex) family whose cross-section expands by a hyperbolic-cosine function, giving loading behaviour between the exponential and conical horns near the throat. It is a special case of the hyperbolic-exponential family with the shape parameter T less than one.','A hyperbolic horn opens along a hyperbolic curve. Its throat loads a bit differently from an exponential horn. It belongs to a family set by a shape number called T. Choosing T changes how the throat behaves near cutoff.','It offers a way to tailor throat loading and the response near cutoff by selecting the shape parameter.','A technician picks a hyperbolic (low-T) profile when smoother throat loading near cutoff is wanted, accepting a response peak just above cutoff.','Horn type',ARRAY['Hyperbolic-exponential horn','Exponential horn','Catenoidal horn','Flare rate','Horn cutoff frequency']::text[],ARRAY['Treating ''hyperbolic'' and ''exponential'' horns as identical shapes.','Ignoring the response peak near cutoff that low-T profiles can show.','Forgetting it is one member of the wider hypex family.']::text[],ARRAY['Selecting a horn profile for throat loading near cutoff.','Comparing hyperbolic, exponential, and conical flares.','Explaining the Salmon horn family to a student.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hyperbolic horn');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '846aa733-74e4-4238-8cc3-068972e9c5b5','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='846aa733-74e4-4238-8cc3-068972e9c5b5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='846aa733-74e4-4238-8cc3-068972e9c5b5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '46587efd-8913-4cd9-a7eb-42047c2a5295','Hyperbolic-exponential horn','The Salmon family of horns, often called ''hypex,'' whose area follows S(x) = S_t*[cosh(x/x0) + T*sinh(x/x0)]^2, with a shape parameter T that spans from catenoidal (T=0) to exponential (T=1). The reference length x0 sets the cutoff through f_c = c/(2*pi*x0).','The hypex horn is a family of shapes set by a number called T. At T equal to one it is exponential. At T equal to zero it is catenoidal. Changing T tunes how the throat loads near cutoff.','It gives designers one adjustable formula to trade throat loading against response smoothness near cutoff.','For f_c = 100 Hz, x0 = c/(2*pi*f_c) = 343/628 = about 0.55 m; with T = 0.6 at x = 0.3 m the area is about 2.25 * S_t.','Horn type',ARRAY['Hyperbolic horn','Exponential horn','Catenoidal horn','Flare rate','Horn cutoff frequency']::text[],ARRAY['Forgetting that T=1 reduces the formula to the exponential horn.','Choosing very low T without expecting a response bump near cutoff.','Confusing the reference length x0 with the physical horn length.']::text[],ARRAY['Tuning a horn''s throat loading with the T parameter.','Deriving the exponential horn as a special case.','Comparing hypex profiles for a given cutoff.']::text[],'Advanced','S(x) = S_t*[cosh(x/x0) + T*sinh(x/x0)]^2 ,  x0 = c/(2*pi*f_c)','Area equals throat area times the square of hyperbolic cosine of x over x0 plus T times hyperbolic sine of x over x0.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hyperbolic-exponential horn');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '46587efd-8913-4cd9-a7eb-42047c2a5295','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='46587efd-8913-4cd9-a7eb-42047c2a5295') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='46587efd-8913-4cd9-a7eb-42047c2a5295');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f8102344-465e-4dd3-a9b9-55212a01632f','Isobaric enclosure','A compound loudspeaker loading in which two drivers are coupled in tandem with a small sealed air pocket between them, driven so they move together and keep that trapped air at nearly constant pressure. This makes the pair behave like one driver but halves the box volume needed for a given alignment.','An isobaric setup uses two drivers face to face or in a tube. A small sealed pocket of air sits between them. They move together, so that air stays at steady pressure. The trick is that the box can be half the usual size.','It lets a designer reach a low tuning in a much smaller box than a single driver would need.','A technician builds an isobaric pair to fit a subwoofer into half the cabinet volume, accepting the cost and weight of a second driver.','Enclosure type',ARRAY['Sealed enclosure','Compound loading','Equivalent volume (Vas)','Enclosure compliance','System resonance']::text[],ARRAY['Wiring the two drivers out of step so they fight instead of moving together.','Expecting more output; isobaric saves space, not sensitivity.','Ignoring the extra weight, cost, and power draw of the second driver.']::text[],ARRAY['Fitting a subwoofer into a very small cabinet.','Explaining why isobaric halves the required box volume.','Wiring a tandem driver pair correctly.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Isobaric enclosure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f8102344-465e-4dd3-a9b9-55212a01632f','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f8102344-465e-4dd3-a9b9-55212a01632f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f8102344-465e-4dd3-a9b9-55212a01632f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '965c6d51-bfdc-4467-807f-7c12c92fbdd7','Linkwitz transform','An active second-order filter that cancels a sealed-box loudspeaker''s own resonance and Q with matching zeros, then imposes a new lower target resonance and Q chosen by the designer. Devised by Siegfried Linkwitz, it extends bass from a small sealed box at the cost of added power and excursion.','The Linkwitz transform is an EQ trick for a sealed speaker. It cancels the box''s natural resonance. Then it sets a new, lower resonance you choose. This gives deeper bass from a small box, but needs more power.','It reshapes a sealed system''s low-frequency response electronically, trading amplifier power and cone travel for extended, well-damped bass.','A technician might transform a sealed sub from f0 = 80 Hz, Q0 = 1.2 to a target fp = 30 Hz, Qp = 0.707 (Butterworth) using the biquad.','Active alignment',ARRAY['Sealed enclosure','Total Q (Qtc)','System resonance','Enclosure compliance','Active equalization']::text[],ARRAY['Forgetting the big low-frequency boost needs extra amplifier power and cone travel.','Applying the transform without a high-pass to protect against over-excursion.','Entering the wrong measured f0 and Q, so the cancellation is off.']::text[],ARRAY['Extending bass from a compact sealed subwoofer.','Flattening a sealed system to a Butterworth target.','Setting up DSP for a small sealed monitor.']::text[],'Advanced','H(s) = [s^2 + (w0/Q0)*s + w0^2] / [s^2 + (wp/Qp)*s + wp^2]','The filter divides the box''s own second-order response by the desired target second-order response.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Linkwitz transform');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '965c6d51-bfdc-4467-807f-7c12c92fbdd7','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='965c6d51-bfdc-4467-807f-7c12c92fbdd7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='965c6d51-bfdc-4467-807f-7c12c92fbdd7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2afda220-458c-4075-acec-8d8d0ecc31d4','Mantaray horn','Mantaray is Altec Lansing''s trademark name for an early commercial constant-directivity horn, introduced in the mid-1970s, whose geometry holds nearly uniform coverage across its band and reduces high-frequency beaming. The underlying method is the generic constant-directivity horn, detailed in the makers'' AES paper.','Mantaray is a brand name from Altec Lansing. It was one of the first constant-directivity horns sold. Its shape keeps coverage about the same at every pitch. This stops the horn from beaming at high frequencies.','It aimed to give even coverage so off-axis listeners hear the same tonal balance as those on-axis.','A technician treats a Mantaray as a constant-directivity horn and reads its rated coverage (for example about 40 by 20 degrees) from the datasheet.','Horn type',ARRAY['Constant-directivity horn','Diffraction horn','Directivity narrowing','Horn mouth','Waveguide']::text[],ARRAY['Treating ''Mantaray'' as a generic word rather than an Altec Lansing trademark.','Assuming its coverage is perfectly flat with frequency across the whole range.','Forgetting constant-directivity horns need HF boost to offset falling on-axis level.']::text[],ARRAY['Identifying a vintage Altec constant-directivity horn.','Explaining the origins of constant-directivity horn design.','Reading a Mantaray horn''s rated coverage angles.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mantaray horn');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2afda220-458c-4075-acec-8d8d0ecc31d4','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2afda220-458c-4075-acec-8d8d0ecc31d4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2afda220-458c-4075-acec-8d8d0ecc31d4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '203bb240-5ded-443f-a852-f03cd613ea4a','Mass-loaded transmission line','A transmission-line enclosure whose open terminus is restricted by a port, adding acoustic mass that lowers the line''s tuning and shortens the line needed for a given frequency. It behaves as a hybrid between a quarter-wave transmission line and a ported (bass-reflex) box.','A mass-loaded transmission line is a long internal duct with a small port at the end. The port adds mass that lowers the tuning. This lets a shorter line reach the same low note. It acts like a mix of a transmission line and a ported box.','It gives extended, well-damped low bass from a more compact line than a plain quarter-wave design.','A technician tunes a mass-loaded line by adjusting the terminus port size and stuffing to place the low-frequency tuning where wanted.','Enclosure type',ARRAY['Transmission line','Ported enclosure','Quarter-wave resonator','Port tuning','Enclosure compliance']::text[],ARRAY['Confusing a mass-loaded line with a plain quarter-wave transmission line.','Over-stuffing the line, which kills the intended port output.','UNSAFE: Running high level through a small terminus port, causing loud chuffing and airflow noise.']::text[],ARRAY['Designing a compact subwoofer with extended low bass.','Tuning a mass-loaded line''s terminus port.','Comparing MLTL, ported, and sealed low-frequency loading.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mass-loaded transmission line');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '203bb240-5ded-443f-a852-f03cd613ea4a','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='203bb240-5ded-443f-a852-f03cd613ea4a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='203bb240-5ded-443f-a852-f03cd613ea4a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c384b648-528f-4b47-9229-c03eb11fe8af','Mouth circumference','The perimeter of a horn''s mouth, used in the common design rule that the mouth circumference should be at least one wavelength at the horn''s cutoff frequency for smooth loading and minimal reflection. This sets a minimum mouth size, since a smaller mouth raises the effective cutoff and adds ripple.','Mouth circumference is the distance around the horn''s opening. A design rule says it should equal at least one wavelength at cutoff. A smaller mouth reflects low notes back. That reflection raises the real cutoff and adds ripple.','It provides a simple size target that ties the mouth''s dimensions to the horn''s lowest usable frequency.','For a 100 Hz cutoff, wavelength is c/f = 343/100 = 3.43 m, so the mouth circumference should be at least about 3.43 m.','Horn parameter',ARRAY['Horn mouth','Mouth reflection','Mouth diffraction','Horn cutoff frequency','Mouth termination']::text[],ARRAY['Using a mouth smaller than one wavelength at cutoff and expecting smooth loading.','Confusing mouth circumference with mouth area or diameter.','Assuming a large mouth alone guarantees pattern control at all frequencies.']::text[],ARRAY['Sizing a horn mouth to reach a target low frequency.','Explaining ripple from an undersized mouth.','Estimating the minimum mouth for a bass horn.']::text[],'Advanced','C_mouth >= c / f_c','The mouth circumference should be at least the speed of sound divided by the cutoff frequency.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mouth circumference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c384b648-528f-4b47-9229-c03eb11fe8af','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c384b648-528f-4b47-9229-c03eb11fe8af') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c384b648-528f-4b47-9229-c03eb11fe8af');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6d1f2e46-2a6c-447d-99e8-ec99cc4e1701','Mouth diffraction','The bending and spreading of sound at the edges of a horn''s mouth, which broadens directivity and adds response ripple, most strongly at frequencies where the mouth is small relative to the wavelength. It is a key reason a horn loses pattern control toward its low end.','Mouth diffraction is sound bending at the edges of the horn opening. It spreads the beam wider than the horn walls intend. It is strongest for long, low-frequency waves. It also adds small ripples to the response.','The concept explains why horns lose directivity control at low frequencies and why mouth shape and rounding matter.','A technician expects a horn to widen and lose pattern control below the frequency where its mouth spans about one wavelength.','Radiation effect',ARRAY['Mouth reflection','Horn mouth','Mouth termination','Directivity narrowing','Diffraction horn']::text[],ARRAY['Assuming a horn holds its rated pattern all the way down to cutoff.','Ignoring that sharp mouth edges worsen diffraction ripple.','Confusing mouth diffraction with an internal horn resonance.']::text[],ARRAY['Explaining why a horn''s pattern widens at low frequencies.','Choosing a rounded mouth to reduce diffraction ripple.','Interpreting loss of directivity at the horn''s low end.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mouth diffraction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6d1f2e46-2a6c-447d-99e8-ec99cc4e1701','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6d1f2e46-2a6c-447d-99e8-ec99cc4e1701') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6d1f2e46-2a6c-447d-99e8-ec99cc4e1701');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '84fcc7bd-4db1-41d8-a8b7-5fa209ff432d','Mouth reflection','The portion of sound reflected back into a horn at the mouth because of the impedance mismatch between the horn and free air, strongest near and below cutoff. These reflections set up standing waves along the horn and cause ripples in the frequency and impedance response.','At the horn mouth, the air suddenly opens up. That change reflects some sound back inside. Reflections are worst near the horn''s low limit. They bounce along the horn and add ripples to the response.','It explains a major source of horn response ripple and guides the use of large mouths and gradual terminations.','A technician reduces mouth reflection by enlarging the mouth and adding a smooth roundover so the horn blends gradually into the air.','Radiation effect',ARRAY['Mouth termination','Mouth circumference','Horn honk','Standing wave','Horn mouth']::text[],ARRAY['Expecting a small-mouth horn to have a smooth low-frequency response.','Confusing mouth reflection with a mismatch at the throat.','Assuming EQ alone can remove reflection-caused ripple.']::text[],ARRAY['Explaining ripple in a horn''s impedance and response.','Improving a horn by enlarging and rounding the mouth.','Diagnosing standing waves in a short horn.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mouth reflection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '84fcc7bd-4db1-41d8-a8b7-5fa209ff432d','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='84fcc7bd-4db1-41d8-a8b7-5fa209ff432d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='84fcc7bd-4db1-41d8-a8b7-5fa209ff432d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '49b3b17c-918d-4b16-b463-60b5e2a0678d','Mouth termination','How a horn''s mouth transitions into the surrounding air, including any roundover or flared lip, chosen to minimize the impedance mismatch and the resulting reflections. A gradual, well-rounded termination smooths the response and improves directivity near the mouth''s frequency limit.','Mouth termination is how the horn ends and meets the open air. A sharp edge causes strong reflections. A smooth, rounded lip eases the change. That rounding cuts ripple and cleans up the sound.','It reduces the abrupt impedance step at the mouth so less energy reflects back into the horn.','A technician adds a large radius roundover at the mouth to lower diffraction and reflection ripple in the response.','Horn design',ARRAY['Mouth reflection','Mouth diffraction','Horn mouth','Mouth circumference','Horn honk']::text[],ARRAY['Leaving a sharp mouth edge that increases reflection and diffraction.','Assuming termination shape does not affect frequency response.','Focusing only on mouth area while ignoring the edge profile.']::text[],ARRAY['Adding a roundover to a horn mouth to smooth response.','Explaining why modern horns have flared lips.','Comparing sharp-edged and rounded horn mouths.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mouth termination');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '49b3b17c-918d-4b16-b463-60b5e2a0678d','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='49b3b17c-918d-4b16-b463-60b5e2a0678d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='49b3b17c-918d-4b16-b463-60b5e2a0678d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1e4db201-5eee-4a6d-9559-00ec24509976','Multicellular horn','A horn assembled from an array of small individual cells sharing a common throat through a manifold, each cell steering part of the coverage so the whole controls directivity over a wide band. It was a classic mid-century approach to broad, controlled high-frequency coverage before smooth constant-directivity horns.','A multicellular horn is many small horn cells joined at one throat. Each cell aims a slice of the sound. Together they cover a wide area. It was an early way to control coverage across a broad band.','It splits the wavefront into many small radiators to hold coverage wider and steadier than a single large horn.','A technician may service a vintage multicell horn and expects some response ripple where the cells'' outputs overlap and interfere.','Horn type',ARRAY['Constant-directivity horn','Diffraction horn','Directivity narrowing','Horn throat','Mantaray horn']::text[],ARRAY['Expecting perfectly smooth response; cell overlap causes interference ripple.','Confusing a multicellular horn with a modern single-piece waveguide.','Assuming more cells always means better sound quality.']::text[],ARRAY['Servicing a vintage multicellular theatre horn.','Explaining early attempts at wide, controlled coverage.','Comparing multicell horns with constant-directivity designs.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multicellular horn');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1e4db201-5eee-4a6d-9559-00ec24509976','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1e4db201-5eee-4a6d-9559-00ec24509976') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1e4db201-5eee-4a6d-9559-00ec24509976');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '37278925-221b-4257-9354-8f0242ac0bc1','Oblate spheroidal waveguide','A high-frequency horn whose interior walls follow the oblate spheroidal coordinate system, so the wavefront expands from the driver throat with a continuous, gently curving profile. This smooth expansion suppresses the abrupt throat discontinuity, higher-order modes, and mouth diffraction of conventional horns, giving controlled directivity. The approach was introduced by Earl Geddes.','This is a horn shaped by a special curved geometry. Sound leaves the driver and widens out very smoothly. The smooth path avoids sharp bends that add distortion. The result is steady, even coverage across frequencies.','It couples a compression driver to the air while holding a chosen coverage angle, avoiding the diffraction and response ripple of sharp-throat horns.','A technician meets it as a constant-directivity waveguide on a studio monitor or PA cabinet; it is picked to keep a set angle, such as 90 degrees, smooth off-axis.','Waveguide design',ARRAY['Throat aperture','Constant-directivity horn','Phase plug','Compression driver','Directivity index']::text[],ARRAY['Assuming any curved horn is an oblate spheroidal waveguide; the profile follows a specific coordinate system.','Thinking a waveguide removes the need to control the throat-to-diaphragm transition.','Expecting deep low-frequency loading from a shallow HF waveguide.']::text[],ARRAY['Selecting an HF waveguide for even off-axis response on a monitor.','Explaining why a waveguide has less mouth diffraction than a radial horn.','Matching a compression driver to a controlled-directivity device.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Oblate spheroidal waveguide');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '37278925-221b-4257-9354-8f0242ac0bc1','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='37278925-221b-4257-9354-8f0242ac0bc1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='37278925-221b-4257-9354-8f0242ac0bc1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4095bbd1-dce4-4bf2-9e8d-2ca38ea2293e','Open baffle','A loudspeaker mounting in which the driver sits on a flat panel with no sealed rear enclosure, so the front and rear radiation remain exposed and out of phase. It behaves as a dipole, with a figure-eight polar pattern and a low-frequency roll-off set by the path length around the baffle.','An open baffle is a driver on a board with no box behind it. Sound comes off the front and the back. The back wave is out of phase with the front. This creates a figure-eight pattern and weak deep bass.','It provides dipole radiation with reduced side output and no enclosure resonances, favoured for its cancellation of room boundary effects to the sides.','A technician sizes the baffle so the front-to-back cancellation stays below the wanted range; a wider panel or added equalisation compensates the natural 6 dB/octave bass roll-off.','Enclosure type',ARRAY['Dipole radiation','Baffle step','Rear-loaded horn','Radiation pattern','Diffraction']::text[],ARRAY['Expecting deep bass from a small open baffle; the rear wave cancels the front at low frequencies.','Forgetting the figure-eight pattern has deep nulls to the sides.','Confusing an open baffle with an infinite baffle, which is sealed on one side.']::text[],ARRAY['Building a dipole speaker to reduce side-wall reflections.','Explaining why an open-baffle woofer needs equalisation for low bass.','Positioning an open baffle away from the front wall to control the rear wave.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Open baffle');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4095bbd1-dce4-4bf2-9e8d-2ca38ea2293e','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4095bbd1-dce4-4bf2-9e8d-2ca38ea2293e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4095bbd1-dce4-4bf2-9e8d-2ca38ea2293e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5a4250ba-95f0-4294-b7ef-8a77a46f7cda','Organ-pipe resonance','A standing-wave resonance inside an air column such as a port, duct, or transmission line, named for its likeness to a musical organ pipe. A tube closed at one end and open at the other resonates at odd quarter-wave multiples, while a tube open at both ends resonates at half-wave multiples of its length.','Air inside a tube can ring at certain notes, like an organ pipe. The tube length sets which notes appear. A tube closed at one end rings at a quarter-wave. These extra resonances can colour a speaker''s sound.','Understanding it lets a designer predict and damp unwanted duct or line resonances that add peaks and dips above the intended tuning.','For a 0.86 m closed-open duct, the first resonance is f = c/(4L) = 343/(4*0.86) = about 100 Hz; stuffing or bracing tames such modes.','Acoustic resonance',ARRAY['Pipe resonance','Quarter-wave enclosure','Standing wave','Port turbulence','Transmission-line enclosure']::text[],ARRAY['Assuming the port only resonates at the box tuning frequency; long ports also ring at pipe modes.','Using the half-wave formula for a duct that is closed at one end.','Ignoring pipe resonances when a long vent adds a midrange peak.']::text[],ARRAY['Diagnosing a midrange peak caused by a long bass-reflex port.','Damping standing waves inside a transmission-line cabinet.','Choosing port length to keep pipe modes out of the passband.']::text[],'Intermediate','f_n = (2n - 1) * c / (4L)   [one end closed];  f_n = n * c / (2L)   [both ends open]','For a pipe closed at one end, the resonance frequencies are odd multiples of the speed of sound divided by four times the length. For a pipe open at both ends, they are whole multiples of the speed of sound divided by twice the length.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Organ-pipe resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5a4250ba-95f0-4294-b7ef-8a77a46f7cda','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5a4250ba-95f0-4294-b7ef-8a77a46f7cda') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5a4250ba-95f0-4294-b7ef-8a77a46f7cda');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3ac12650-b53d-49f8-a8ec-8a98a66f77d0','Passive-radiator alignment','The set of enclosure and passive-radiator parameters chosen to give a target low-frequency response in a passive-radiator (drone-cone) system. It parallels vented-box alignment theory, but the box air resonates against the moving mass and compliance of the passive radiator rather than against a port''s air mass.','This is how you tune a speaker that uses a drone cone instead of a port. The drone cone has no motor of its own. Its weight and springiness set the tuning. You pick these to shape the bass response.','It lets a designer achieve a vented-style bass response where a port would be too long or too noisy, using a tuned diaphragm instead.','A technician tunes the system by adding or removing weight on the passive radiator, then measures the impedance twin peaks to confirm the target box tuning frequency.','Enclosure alignment',ARRAY['Passive-radiator mass','Passive-radiator compliance','Quasi-Butterworth alignment','Bass-reflex tuning','Impedance curve']::text[],ARRAY['Treating a passive-radiator system exactly like a ported box; the radiator''s own compliance shifts the tuning.','Ignoring that the passive radiator adds a sharp notch just below tuning.','Choosing a passive radiator with too little peak displacement for the woofer''s output.']::text[],ARRAY['Designing a compact subwoofer where a port would be impractically long.','Tuning a portable speaker''s drone cone to the desired bass frequency.','Verifying alignment by reading the twin impedance peaks.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Passive-radiator alignment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3ac12650-b53d-49f8-a8ec-8a98a66f77d0','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3ac12650-b53d-49f8-a8ec-8a98a66f77d0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3ac12650-b53d-49f8-a8ec-8a98a66f77d0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '191958bb-0b73-400e-961a-b175ddc98973','Passive-radiator compliance','The mechanical springiness of a passive radiator''s suspension, describing how far the diaphragm moves for a given force. Together with the radiator''s moving mass and the box air compliance, it fixes the system''s tuning frequency and the depth of the notch below it.','This is how springy the drone cone''s suspension is. A softer suspension moves more easily. Its springiness works with the cone weight and the box air. Together they set where the bass tuning lands.','It is a design parameter that, with radiator mass and box volume, determines the passive-radiator tuning and how cleanly the diaphragm can swing.','A technician favours a high-compliance (loose) surround so the box air, not the suspension, dominates tuning, keeping the drone cone''s added notch predictable.','Enclosure parameter',ARRAY['Passive-radiator mass','Passive-radiator excursion','Passive-radiator alignment','Suspension compliance','Box tuning frequency']::text[],ARRAY['Assuming the radiator suspension has no effect on tuning; a stiff surround raises the tuning frequency.','Confusing compliance with mass; compliance is springiness, mass is weight.','Ignoring that a very stiff suspension limits usable excursion.']::text[],ARRAY['Selecting a passive radiator whose suspension will not dominate tuning.','Explaining a tuning shift after a stiff drone cone was substituted.','Balancing compliance against needed diaphragm travel.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Passive-radiator compliance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '191958bb-0b73-400e-961a-b175ddc98973','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='191958bb-0b73-400e-961a-b175ddc98973') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='191958bb-0b73-400e-961a-b175ddc98973');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1e2a6c3-710b-4e20-b5de-f3188c92b70c','Passive-radiator excursion','The peak linear travel of a passive radiator''s diaphragm, which must exceed the driving woofer''s excursion because the passive radiator carries the full vented output at and near tuning. Insufficient travel causes the radiator to bottom out and distort or become audible.','This is how far the drone cone can move in and out. Near tuning it moves more than the powered woofer. If it cannot move far enough, it slaps or distorts. So it needs plenty of travel.','It sets the maximum clean output of a passive-radiator system, because the radiator, not a port, handles the low-frequency air movement.','A technician chooses a passive radiator with peak travel roughly 1.5 to 2 times the woofer''s, so the radiator does not bottom out at rated power.','Enclosure parameter',ARRAY['Passive-radiator mass','Passive-radiator compliance','Port compression','Excursion limit','Bottoming']::text[],ARRAY['UNSAFE: Driving a passive-radiator system so hard the radiator bottoms out, which can damage the diaphragm and produce loud mechanical noise.','Using a passive radiator with less displacement than the woofer.','Assuming the radiator moves less than the woofer; near tuning it moves more.']::text[],ARRAY['Sizing a passive radiator so it does not bottom at full power.','Diagnosing a slapping noise from an overdriven drone cone.','Matching radiator travel to a high-excursion subwoofer driver.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Passive-radiator excursion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1e2a6c3-710b-4e20-b5de-f3188c92b70c','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1e2a6c3-710b-4e20-b5de-f3188c92b70c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1e2a6c3-710b-4e20-b5de-f3188c92b70c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f14b8f0d-21d0-46d8-8a5a-01804e680a19','Passive-radiator mass','The total moving mass of a passive radiator, the main parameter used to set a passive-radiator system''s tuning frequency. Adding mass lowers the tuning; removing mass raises it, because the mass resonates against the box air compliance much as a port''s air mass does.','This is the weight of the moving drone cone. Heavier means a lower tuning note. Lighter means a higher one. Builders add or remove small weights to hit the target.','It is the primary tuning control for a passive-radiator enclosure, replacing the length adjustment used to tune a port.','To tune a box of Vb = 20 L with a radiator of piston area Sp = 0.02 m^2 to fb = 30 Hz, the required moving mass follows fb = (1/2*pi)*sqrt(rho*c^2*Sp^2/(Vb*Mmp)); solving gives Mmp of roughly 0.08 kg.','Enclosure parameter',ARRAY['Passive-radiator compliance','Passive-radiator alignment','Box tuning frequency','Port air mass','Helmholtz resonance']::text[],ARRAY['Adding mass expecting a higher tuning; more mass lowers the tuning frequency.','Forgetting to include the added tuning weights in the moving mass.','Ignoring that the radiator''s own suspension compliance also shifts tuning slightly.']::text[],ARRAY['Adding weights to a drone cone to reach a target bass frequency.','Explaining why a heavier passive radiator tunes a box lower.','Substituting a passive radiator and recalculating tuning.']::text[],'Intermediate','fb = (1 / (2*pi)) * sqrt( rho * c^2 * Sp^2 / (Vb * Mmp) )','The passive-radiator tuning frequency equals one over two pi, times the square root of air density times the speed of sound squared times the radiator area squared, divided by the box volume times the radiator moving mass.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Passive-radiator mass');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f14b8f0d-21d0-46d8-8a5a-01804e680a19','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f14b8f0d-21d0-46d8-8a5a-01804e680a19') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f14b8f0d-21d0-46d8-8a5a-01804e680a19');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bafc014c-f818-436e-bda2-22c28ed7a95c','Phase center','The apparent point in space from which the wavefront of a source appears to radiate, found from the curvature of its phase response. For a horn or waveguide it usually lies behind the mouth and can move with frequency, which matters when aligning it with other drivers.','This is the spot a speaker seems to send sound from. It is not always the front of the box. For a horn it often sits back inside. Its position can change with frequency.','It defines the effective acoustic origin used to time-align drivers so their outputs sum correctly through the crossover region.','A technician measures phase and adjusts driver offset or delay so the horn''s phase center lines up with the woofer''s, giving a flat summed response at the crossover.','Radiation & directivity',ARRAY['Acoustic center','Phase response','Time alignment','Crossover region','Group delay']::text[],ARRAY['Assuming the phase center sits at the visible front of the horn or dust cap.','Treating the phase center as fixed; it can move with frequency.','Aligning drivers by cone position instead of measured phase.']::text[],ARRAY['Time-aligning a horn tweeter with a woofer at the crossover.','Setting driver delay in a multiway active loudspeaker.','Explaining why a horn''s origin is behind its mouth.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase center');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bafc014c-f818-436e-bda2-22c28ed7a95c','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bafc014c-f818-436e-bda2-22c28ed7a95c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bafc014c-f818-436e-bda2-22c28ed7a95c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4ee457a9-bd7b-41f0-963b-693285a0eae2','Pipe resonance','The standing-wave resonance of the air column in any tube or duct, including bass-reflex ports, transmission lines, and horns. The lowest resonance depends on the duct length and its end conditions, and higher resonances occur at integer-related multiples that can add response peaks.','Air in any tube can ring at set frequencies. The tube length decides which ones. Longer tubes ring at lower notes. In a speaker these can add unwanted peaks.','Recognising it lets a designer keep duct and line resonances out of the audible passband or damp them where they fall.','For a 1.2 m open-open duct the first resonance is f = c/(2L) = 343/(2*1.2) = about 143 Hz; damping material lowers its Q.','Acoustic resonance',ARRAY['Organ-pipe resonance','Quarter-wave enclosure','Standing wave','Transmission-line enclosure','Port end correction']::text[],ARRAY['Confusing the box Helmholtz tuning with the port''s own pipe resonance; they are different mechanisms.','Using the wrong end condition, which doubles the predicted frequency.','Neglecting to add damping when a line resonance falls in the passband.']::text[],ARRAY['Predicting the resonance of a long transmission-line cabinet.','Damping a port''s pipe mode that colours the midrange.','Choosing duct length to move resonances above the crossover.']::text[],'Intermediate','f_n = n * c / (2L)   [open-open];  f_n = (2n - 1) * c / (4L)   [closed-open]','For a duct open at both ends, resonances are whole multiples of the speed of sound over twice the length. For a duct closed at one end, they are odd multiples of the speed of sound over four times the length.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pipe resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4ee457a9-bd7b-41f0-963b-693285a0eae2','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4ee457a9-bd7b-41f0-963b-693285a0eae2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4ee457a9-bd7b-41f0-963b-693285a0eae2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '152a7d09-1fcc-49d8-956b-4fb0a1bfeed2','Polar map','A colour-coded contour plot that shows a loudspeaker''s off-axis response over both frequency and angle at once, with level indicated by colour. It condenses many individual polar responses into a single chart so coverage narrowing and lobing are easy to see.','A polar map is a colour chart of a speaker''s coverage. One axis is frequency, the other is angle. Colours show how loud it is off to the side. It reveals where coverage gets narrow.','It gives a compact view of directivity versus frequency so a designer or system tech can judge coverage smoothness at a glance.','A technician reads a polar map to confirm a horn holds its rated angle, checking that the coverage colour band stays constant with frequency instead of pinching in.','Radiation & directivity',ARRAY['Directivity index','Polar response','Beamwidth','Constant-directivity horn','Off-axis response']::text[],ARRAY['Reading a polar map as a room map; it shows angle and frequency, not physical distance.','Ignoring the level scale, so a small dip looks like a large one.','Assuming a single on-axis curve tells the same story as a polar map.']::text[],ARRAY['Comparing the directivity of two horns before a purchase.','Checking that a waveguide keeps constant coverage with frequency.','Documenting a loudspeaker''s off-axis behaviour in a datasheet.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Polar map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '152a7d09-1fcc-49d8-956b-4fb0a1bfeed2','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='152a7d09-1fcc-49d8-956b-4fb0a1bfeed2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='152a7d09-1fcc-49d8-956b-4fb0a1bfeed2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ef0304ac-0eed-4754-b4c1-3542a156ac83','Pole vent','A hole bored through the centre pole piece of a moving-coil driver''s magnet system, opening the space beneath the dust cap to the outside. It relieves air pressure trapped under the cap and channels airflow past the voice coil to aid cooling.','This is a hole through the center of a driver''s magnet. It lets air move in and out under the dust cap. Without it, trapped air adds noise and stress. It also helps cool the voice coil.','It prevents a trapped air pocket under the dust cap from acting as a stiff spring or whistling, and it improves voice-coil cooling under power.','A technician relies on the pole vent to move heat away from the coil during long high-power use, and to stop a pressurised dust cap from adding noise or nonlinearity.','Driver construction',ARRAY['Voice-coil cooling','Dust cap','Power compression','Pole piece','Air noise']::text[],ARRAY['Blocking or sealing the pole vent, which traps air and can whistle or stiffen the suspension.','Confusing the pole vent with the enclosure port; one is in the driver, the other in the box.','UNSAFE: Ignoring a blocked pole vent during sustained high-power use, allowing extra voice-coil heating and possible thermal failure.']::text[],ARRAY['Explaining a whistling noise from a sealed pole piece.','Improving cooling on a high-power subwoofer driver.','Diagnosing added distortion from a pressurised dust cap.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pole vent');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ef0304ac-0eed-4754-b4c1-3542a156ac83','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ef0304ac-0eed-4754-b4c1-3542a156ac83') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ef0304ac-0eed-4754-b4c1-3542a156ac83');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '53ee1632-3ab9-4933-817b-46625224bc2a','Port Mach number','The peak air velocity in a loudspeaker port expressed as a fraction of the speed of sound. It is a convenient figure of merit for port sizing, because turbulence, chuffing noise, and port compression grow rapidly as the Mach number rises.','This compares the port''s air speed to the speed of sound. A higher value means faster air in the port. Fast air becomes turbulent and noisy. Designers keep this number small.','It gives a single number for judging whether a port is large enough to avoid audible turbulence and output loss at the target level.','For peak port velocity U = 17 m/s and c = 343 m/s, M = U/c = 0.05, near the usual point where chuffing begins; a technician enlarges or flares the port to lower it.','Port/vent behavior',ARRAY['Port chuffing','Port turbulence','Port compression','Port air mass','Flared port']::text[],ARRAY['UNSAFE: Undersizing a port so air velocity is high, which drives turbulence and can strain the driver at high power.','Comparing average velocity to peak; the peak value drives chuffing.','Assuming a small port is fine because it works quietly at low level.']::text[],ARRAY['Sizing a subwoofer port to keep velocity below the chuffing threshold.','Choosing a flared port to reduce peak Mach number.','Explaining port noise that appears only at high output.']::text[],'Advanced','M = U / c','The port Mach number equals the peak air velocity in the port divided by the speed of sound.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Port Mach number');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '53ee1632-3ab9-4933-817b-46625224bc2a','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='53ee1632-3ab9-4933-817b-46625224bc2a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='53ee1632-3ab9-4933-817b-46625224bc2a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dcd5dac3-1b35-4e92-a4ac-8f4ee9b570eb','Port acoustic resistance','The real, loss part of a port''s acoustic impedance, representing energy lost to viscous friction and turbulence rather than stored in the moving air mass. It damps the box resonance at low level but grows nonlinearly with air velocity, contributing to port compression at high output.','A port both moves air and wastes some energy as heat and noise. The wasted part is its acoustic resistance. At low level it is small and steady. At high level it rises and eats output.','It sets the losses that damp the vented-box resonance and, when velocity is high, limits how much low-frequency output the port can deliver.','If a port drops 2 Pa of pressure while passing a volume velocity of 0.01 m^3/s, its acoustic resistance is R = p/U = 200 acoustic ohms (Pa*s/m^3).','Port/vent behavior',ARRAY['Port air mass','Port compression','Port turbulence','Acoustic impedance','Quality factor']::text[],ARRAY['Treating port resistance as constant; it rises steeply with air velocity.','Confusing acoustic resistance (losses) with acoustic mass (energy storage).','Ignoring port losses when predicting the depth of the impedance saddle.']::text[],ARRAY['Explaining why a small port loses output at high drive.','Modelling the damping of a vented-box resonance.','Choosing a larger port to reduce velocity-dependent losses.']::text[],'Advanced','R_A = p / U','Port acoustic resistance equals the acoustic pressure difference across the port divided by the volume velocity through it.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Port acoustic resistance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dcd5dac3-1b35-4e92-a4ac-8f4ee9b570eb','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dcd5dac3-1b35-4e92-a4ac-8f4ee9b570eb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dcd5dac3-1b35-4e92-a4ac-8f4ee9b570eb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ed7643e5-a6ae-490f-bc6b-219e69db8a93','Port air mass','The mass of air moving as a plug inside a bass-reflex port, which resonates against the springiness of the enclosed box air to form a Helmholtz resonator. This air mass, set by the port''s cross-section and effective length, largely determines the box tuning frequency.','The air inside a port moves as one slug. That moving air has weight. It bounces against the springy box air. Together they set the box tuning note.','It is the resonating mass of the vented-box Helmholtz system, so choosing port area and length sets the tuning frequency.','For a port of area S = 0.005 m^2 and effective length Leff = 0.15 m into a box Vb = 0.03 m^3, tuning is fb = (c/2*pi)*sqrt(S/(Vb*Leff)) = (343/6.283)*sqrt(0.005/(0.03*0.15)) = about 58 Hz.','Port/vent behavior',ARRAY['Port end correction','Helmholtz resonance','Box tuning frequency','Port acoustic resistance','Passive-radiator mass']::text[],ARRAY['Using the physical port length instead of the effective length, giving a wrong tuning.','Forgetting that a larger port area needs a longer port for the same tuning.','Ignoring the air mass when a fat, short port tunes higher than expected.']::text[],ARRAY['Calculating a bass-reflex tuning frequency during design.','Explaining why widening a port raises the tuning.','Relating port dimensions to the box Helmholtz resonance.']::text[],'Advanced','fb = (c / (2*pi)) * sqrt( S / (Vb * Leff) )','The box tuning frequency equals the speed of sound over two pi, times the square root of the port area divided by the box volume times the effective port length.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Port air mass');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ed7643e5-a6ae-490f-bc6b-219e69db8a93','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ed7643e5-a6ae-490f-bc6b-219e69db8a93') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ed7643e5-a6ae-490f-bc6b-219e69db8a93');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '92bba641-f95f-410b-af93-c71bd4edfff9','Port chuffing','The audible, broadband huffing or whistling noise produced when air in a loudspeaker port becomes turbulent at high velocity. It signals that the port is too small for the output demanded and is often accompanied by port compression and added distortion.','Chuffing is a huffing or whooshing noise from a port. It happens when the air moves too fast. Fast air becomes turbulent and noisy. It means the port is too small for the volume.','Recognising chuffing tells a technician the port air velocity is too high, so the port must be enlarged, flared, or the level reduced.','A technician keeps peak port velocity below roughly 5 percent of the speed of sound (about 17 m/s); above this, chuffing and compression appear, so a larger or flared port is fitted.','Port/vent behavior',ARRAY['Port turbulence','Port Mach number','Port compression','Flared port','Port air mass']::text[],ARRAY['UNSAFE: Cranking a small-ported system into audible chuffing, masking driver overexcursion that can damage the driver.','Blaming the driver for a noise that is actually port turbulence.','Assuming a longer port fixes chuffing; cross-sectional area and flaring matter more.']::text[],ARRAY['Diagnosing a whooshing noise from a subwoofer at high level.','Deciding to flare a port to cure chuffing.','Explaining why a small port limits clean output.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Port chuffing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '92bba641-f95f-410b-af93-c71bd4edfff9','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='92bba641-f95f-410b-af93-c71bd4edfff9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='92bba641-f95f-410b-af93-c71bd4edfff9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6c65d6ee-7dc9-404c-91f1-d21119c8c367','Port compression','The loss of port output at high drive levels, where rising velocity-dependent losses and turbulence keep the port from delivering the low-frequency reinforcement it provides at low levels. It flattens the tuning peak and reduces maximum bass output.','At high volume a port stops helping as much. Air losses and turbulence rise with level. The bass boost from the port shrinks. This is port compression.','It describes a real limit on a vented system''s maximum clean bass, guiding technicians to size ports for the required output.','A technician measures output at low and high drive; if the tuning peak falls with level, the port is compressing and needs a larger area or flared ends.','Port/vent behavior',ARRAY['Port chuffing','Port turbulence','Port Mach number','Port acoustic resistance','Power compression']::text[],ARRAY['UNSAFE: Adding more power to overcome port compression, which can push the driver past safe excursion.','Confusing port compression with driver power compression from voice-coil heating.','Expecting the ported bass boost to scale linearly with level.']::text[],ARRAY['Measuring maximum output of a ported subwoofer.','Explaining lost bass punch at high level despite more power.','Choosing a larger port to reduce compression.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Port compression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6c65d6ee-7dc9-404c-91f1-d21119c8c367','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6c65d6ee-7dc9-404c-91f1-d21119c8c367') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6c65d6ee-7dc9-404c-91f1-d21119c8c367');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fbd08633-f958-47a2-bff7-cf60da924a4c','Port end correction','An added effective length applied to a port because the moving air plug extends slightly beyond each physical opening. The effective length, longer than the physical length, is what sets the true Helmholtz tuning; each flanged end adds about 0.85 times the port radius.','Air keeps moving a little past each end of a port. So the port acts longer than it measures. This extra length lowers the tuning. Designers add it before calculating.','It corrects the tuning calculation so the built port produces the intended box resonance rather than a higher one.','A 0.10 m physical port of radius a = 0.03 m with one flanged and one free end has Leff = 0.10 + (0.85 + 0.61)*0.03 = about 0.144 m, which is used in the tuning formula.','Port/vent behavior',ARRAY['Port air mass','Helmholtz resonance','Box tuning frequency','Pipe resonance','Flared port']::text[],ARRAY['Using the physical length in the tuning formula and getting a tuning that is too high.','Applying the same correction to both ends when one is flanged and one is free.','Ignoring that a flared mouth changes the effective end correction.']::text[],ARRAY['Calculating the real length to cut a bass-reflex port.','Explaining why a built port tunes lower than its measured length suggests.','Correcting a tuning prediction for a flanged versus free port end.']::text[],'Advanced','Leff = Lphys + k * a   (flanged end k = 0.85; free/unflanged end k = 0.61)','The effective port length equals the physical length plus a correction factor times the port radius, summed for each end, using about 0.85 for a flanged end and 0.61 for a free end.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Port end correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fbd08633-f958-47a2-bff7-cf60da924a4c','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fbd08633-f958-47a2-bff7-cf60da924a4c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fbd08633-f958-47a2-bff7-cf60da924a4c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1ee0ac96-9fb6-4515-8ca1-a98e3fecd090','Port turbulence','The breakdown of smooth (laminar) airflow into chaotic eddies inside a port when air velocity is high, especially at the port ends. It creates broadband noise (chuffing), adds nonlinear losses, and contributes to port compression.','When port air moves fast it stops flowing smoothly. It breaks into swirling eddies. These eddies make noise and waste energy. This is port turbulence.','Understanding it guides port sizing and shaping, since smooth flow keeps the port quiet and efficient at high output.','A technician reduces turbulence by enlarging the port area and rounding or flaring the ends, which keeps flow attached and lowers peak velocity.','Port/vent behavior',ARRAY['Port chuffing','Port Mach number','Port compression','Flared port','Port acoustic resistance']::text[],ARRAY['UNSAFE: Ignoring port turbulence noise that hides an overdriven, at-risk driver.','Thinking a sharp-edged port opening is as quiet as a rounded one.','Assuming turbulence only matters for subwoofers, not compact ported boxes.']::text[],ARRAY['Rounding port ends to cut turbulent noise.','Explaining why flared ports stay quieter at high level.','Diagnosing broadband port noise at high drive.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Port turbulence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1ee0ac96-9fb6-4515-8ca1-a98e3fecd090','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1ee0ac96-9fb6-4515-8ca1-a98e3fecd090') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1ee0ac96-9fb6-4515-8ca1-a98e3fecd090');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '52f6ec42-cf0e-4f3c-afc8-bf0613b5cb5d','QB3 alignment','A quasi-Butterworth third-order vented-box alignment used with drivers whose total Q is below the value required for a maximally flat Butterworth (B4) response. It gives a smooth, gently rolled-off low-frequency response, typically in a somewhat larger box than a B4 would need. The family derives from Thiele''s vented-box theory.','QB3 is a way to tune a ported box for lower-Q drivers. These drivers cannot make a perfectly flat B4 response. QB3 gives a smooth, gentle roll-off instead. It usually needs a slightly bigger box.','It extends flat-response vented tuning to the many real drivers whose total Q is too low for a true Butterworth alignment.','A technician with a driver of Qts around 0.3 chooses a QB3 alignment from the tables, sizing the box and port for a smooth roll-off rather than forcing a B4.','Enclosure alignment',ARRAY['Quasi-Butterworth alignment','SBB4 alignment','Butterworth alignment','Box tuning frequency','Qtc']::text[],ARRAY['Forcing a low-Q driver into a B4 box and getting a droopy response instead of a QB3.','Assuming QB3 always means a smaller box; it is often larger than B4.','Confusing the third-order QB3 roll-off with a true fourth-order alignment.']::text[],ARRAY['Selecting an alignment for a driver with Qts below 0.383.','Reading vented-box alignment tables during design.','Explaining why a low-Q woofer suits a quasi-Butterworth box.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='QB3 alignment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '52f6ec42-cf0e-4f3c-afc8-bf0613b5cb5d','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='52f6ec42-cf0e-4f3c-afc8-bf0613b5cb5d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='52f6ec42-cf0e-4f3c-afc8-bf0613b5cb5d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d335022-3626-4df1-8117-a191f5c28fe7','Qtc','The total quality factor of a sealed (closed-box) loudspeaker system at its resonance, describing the damping and shape of the low-frequency roll-off. A Qtc of 0.707 gives a maximally flat Butterworth response; higher values give a peaked, boomier roll-off and lower values a gentler, overdamped one.','Qtc describes the bass shape of a sealed speaker box. It measures how damped the box resonance is. About 0.707 gives the flattest response. Higher values sound boomier; lower values sound tighter.','It is the main design target for a sealed box, letting a technician trade box size against bass extension and transient behaviour.','For a driver with Qts = 0.4 in a box giving Vas/Vb = 2.1, Qtc = Qts*sqrt(1 + Vas/Vb) = 0.4*sqrt(3.1) = about 0.70, a Butterworth alignment.','Enclosure parameter',ARRAY['Qts','Closed-box alignment','Vas','Box tuning frequency','Butterworth alignment','Total enclosure Q']::text[],ARRAY['Applying Qtc to a ported box; it is a sealed-box parameter.','Making the box very small, which raises Qtc and produces a boomy peak.','Forgetting that Fc rises by the same factor as Qtc as the box shrinks.']::text[],ARRAY['Choosing a sealed-box volume for a target bass response.','Explaining why a tiny sealed box sounds boomy.','Setting Qtc to 0.707 for a maximally flat sealed alignment.']::text[],'Intermediate','Qtc = Qts * sqrt(1 + Vas/Vb);   Fc = Fs * sqrt(1 + Vas/Vb)','The closed-box total Q equals the driver total Q times the square root of one plus the ratio of equivalent volume to box volume. The box resonance frequency rises by the same square-root factor above the driver free-air resonance.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Qtc');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d335022-3626-4df1-8117-a191f5c28fe7','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d335022-3626-4df1-8117-a191f5c28fe7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d335022-3626-4df1-8117-a191f5c28fe7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dfdb26a6-b665-461e-8405-4e83361cb754','Quarter-wave enclosure','An enclosure whose acoustic behaviour relies on a duct or line about one quarter of a wavelength long at the tuning frequency, closed at the driver end and open at the terminus. The quarter-wave resonance reinforces low-frequency output, as in transmission-line and tapered-pipe designs.','This box uses a long internal pipe to boost bass. The pipe is about a quarter of a wavelength long. One end is closed, the other open. Its resonance adds low-frequency output.','It uses a quarter-wave air-column resonance, rather than a Helmholtz port, to extend and reinforce low-frequency response.','To tune a quarter-wave line to 40 Hz, length L = c/(4*f) = 343/(4*40) = about 2.1 m; the line is then folded to fit the cabinet.','Enclosure type',ARRAY['Transmission-line enclosure','Pipe resonance','Organ-pipe resonance','Tapered line','Box tuning frequency']::text[],ARRAY['Confusing a quarter-wave line with a Helmholtz-tuned port; the resonance mechanism differs.','Ignoring higher pipe modes that add peaks above the fundamental.','Forgetting that stuffing shifts the effective line length and tuning.']::text[],ARRAY['Designing a transmission-line subwoofer.','Folding a quarter-wave line to fit a cabinet.','Explaining bass reinforcement in a tapered-pipe speaker.']::text[],'Intermediate','f = c / (4L)','The quarter-wave tuning frequency equals the speed of sound divided by four times the line length.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quarter-wave enclosure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dfdb26a6-b665-461e-8405-4e83361cb754','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dfdb26a6-b665-461e-8405-4e83361cb754') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dfdb26a6-b665-461e-8405-4e83361cb754');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '084ea066-f523-4ca7-b891-5e2c8e6be29b','Quasi-Butterworth alignment','A family of vented-box alignments that approximate the maximally flat Butterworth response for drivers whose parameters do not exactly fit a true Butterworth (B4) tuning. The common third-order member, QB3, suits lower-Q drivers and trades a slightly larger box for a smooth roll-off.','This is a group of ported-box tunings close to the flat Butterworth ideal. Real drivers rarely fit the exact flat tuning. These alignments get close anyway. The third-order one suits lower-Q drivers.','It broadens the range of drivers that can achieve a near-flat vented response without an exact Butterworth match.','A technician picks a quasi-Butterworth alignment from tables when a driver''s Qts sits just below the B4 value, keeping a smooth response in a practical box.','Enclosure alignment',ARRAY['QB3 alignment','SBB4 alignment','Butterworth alignment','Box tuning frequency','Qts']::text[],ARRAY['Treating quasi-Butterworth as a single tuning rather than a family of alignments.','Assuming it matches B4 extension exactly; the roll-off is a little different.','Ignoring the driver Q that decides which member applies.']::text[],ARRAY['Choosing a near-flat vented tuning for a real driver.','Explaining why B4 rarely fits a given woofer exactly.','Reading alignment tables to pick a QB3 tuning.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quasi-Butterworth alignment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '084ea066-f523-4ca7-b891-5e2c8e6be29b','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='084ea066-f523-4ca7-b891-5e2c8e6be29b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='084ea066-f523-4ca7-b891-5e2c8e6be29b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '78986333-a2e0-4327-90f7-fb098918032f','Radial phase plug','A phase plug for a compression driver whose openings are radial slots running from the centre outward, equalising the acoustic path lengths from the annular diaphragm to the throat. Matching the path lengths prevents high-frequency cancellations that would otherwise notch the response.','A phase plug sits between the driver''s dome and the horn throat. A radial one uses slots that run outward like spokes. It makes every sound path the same length. This stops high notes from cancelling.','It keeps the many paths from a large diaphragm arriving in phase at the throat, extending smooth high-frequency output.','A technician meets it inside a compression driver; a well-matched radial phase plug is why the driver stays smooth to the top of its range without deep response notches.','Driver construction',ARRAY['Phase plug','Compression driver','Throat aperture','Diaphragm','High-frequency response']::text[],ARRAY['Assuming any phase plug shape works equally; slot geometry sets where cancellations fall.','Confusing a radial (spoke) phase plug with a circumferential (ring) one.','Thinking the phase plug is only a spacer, not a path-length equaliser.']::text[],ARRAY['Explaining smooth top-end response of a compression driver.','Comparing radial and circumferential phase-plug designs.','Diagnosing a high-frequency notch from a mismatched phase plug.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radial phase plug');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '78986333-a2e0-4327-90f7-fb098918032f','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='78986333-a2e0-4327-90f7-fb098918032f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='78986333-a2e0-4327-90f7-fb098918032f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '82455813-f220-4b53-b514-d18e2d4c3379','Rear-loaded horn','An enclosure in which the back of the driver feeds a folded horn while the front radiates directly, so the horn reinforces low frequencies. The direct front output covers the midrange and the horn mouth adds efficient bass over a limited band.','In this box the front of the driver plays normally. The back feeds into a folded horn. The horn boosts the low notes. It adds efficient bass over a narrow range.','It uses horn loading on the rear wave to raise low-frequency efficiency and output from a single full-range driver.','A technician uses a rear-loaded horn with an efficient full-range driver where high sensitivity and extended bass are wanted from low amplifier power.','Enclosure type',ARRAY['Front-loaded horn','Folded horn','Horn cutoff','Open baffle','Acoustic loading']::text[],ARRAY['Expecting flat, wideband bass; horn loading works only over a limited band.','Confusing a rear-loaded horn with a front-loaded (throat-on-driver) horn.','Ignoring the phase interaction between the direct front output and the horn mouth.']::text[],ARRAY['Building a high-efficiency single-driver speaker.','Explaining the bass boost from a folded rear horn.','Matching a full-range driver to a rear-loaded cabinet.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rear-loaded horn');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '82455813-f220-4b53-b514-d18e2d4c3379','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='82455813-f220-4b53-b514-d18e2d4c3379') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='82455813-f220-4b53-b514-d18e2d4c3379');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b6e07320-3c59-45bd-af2d-3dc8d46a12b4','Resistive vent','A deliberately lossy vent that adds acoustic resistance between the box interior and outside air, damping the driver resonance without fully sealing the enclosure. Also called an aperiodic vent, it uses a resistive element such as a fibrous plug or damped membrane to control the impedance peak.','A resistive vent is a leaky, damped opening in a box. It is not a tuned port and not fully sealed. A stuffing plug or damped pad adds resistance. This tames the driver''s resonance peak.','It flattens the impedance and resonance peak of a driver, giving a smooth, well-damped roll-off in a compact box.','A technician fits a resistive (aperiodic) vent, adjusting the amount of damping material until the impedance peak flattens to the target while keeping the box small.','Enclosure type',ARRAY['Aperiodic enclosure','Port acoustic resistance','Sealed enclosure','Impedance curve','Qtc']::text[],ARRAY['Treating a resistive vent as a tuned port; it damps rather than resonates.','Adding too little resistance, leaving a large impedance peak.','Assuming it extends bass like a bass-reflex port; it mainly controls damping.']::text[],ARRAY['Damping a driver resonance in a small aperiodic cabinet.','Flattening an impedance peak for an easier amplifier load.','Choosing an aperiodic vent where a port would be too long.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resistive vent');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b6e07320-3c59-45bd-af2d-3dc8d46a12b4','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b6e07320-3c59-45bd-af2d-3dc8d46a12b4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b6e07320-3c59-45bd-af2d-3dc8d46a12b4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f5418386-ad98-4547-bdd8-ada0e5843522','SBB4 alignment','A fourth-order vented-box alignment in the boom-box (BB4) family, extended by Bullock to suit drivers of moderate total Q. It gives a smooth, well-behaved low-frequency roll-off and is one of the tabulated alignments derived from Thiele and Small vented-box theory.','SBB4 is a ported-box tuning in the boom-box family. It suits drivers with a middling Q value. It gives a smooth bass roll-off. Builders read it from alignment tables.','It provides a defined, smooth vented alignment for drivers whose Q does not fit a flat Butterworth tuning, without the ripple of a Chebyshev alignment.','A technician with a driver near the SBB4 Q range reads the tables to set box volume and port tuning, obtaining a smooth response without a passband peak.','Enclosure alignment',ARRAY['QB3 alignment','Quasi-Butterworth alignment','Butterworth alignment','Box tuning frequency','Qts']::text[],ARRAY['Assuming SBB4 is identical to a Butterworth B4; its response and box differ.','Applying it to a driver whose Q is far outside the alignment''s range.','Confusing the SBB4 (boom-box family) with a Chebyshev alignment that has ripple.']::text[],ARRAY['Selecting a smooth vented alignment for a moderate-Q woofer.','Reading alignment tables during subwoofer design.','Explaining alternatives when a driver will not fit a B4 tuning.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='SBB4 alignment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f5418386-ad98-4547-bdd8-ada0e5843522','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f5418386-ad98-4547-bdd8-ada0e5843522') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f5418386-ad98-4547-bdd8-ada0e5843522');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e33cf3de-e984-4043-b8e8-2e41113e76ce','SBIR','Speaker Boundary Interference Response, the comb-filter pattern of peaks and dips created when a loudspeaker''s direct sound combines with its reflection from a nearby boundary such as a wall or floor. The first and deepest cancellation occurs where the extra path length equals half a wavelength.','SBIR stands for speaker boundary interference response. Sound from the speaker also bounces off a nearby wall or floor. The direct and reflected sound mix and cancel at some frequencies. This makes dips in the bass and low mids.','It explains position-dependent bass dips so a technician can place a loudspeaker to push the worst cancellation out of the critical range.','For a speaker 1.0 m from a wall, the first dip falls near f = c/(4d) = 343/(4*1.0) = about 86 Hz; moving the speaker changes this frequency.','Radiation & directivity',ARRAY['Boundary reinforcement','Comb filtering','Baffle step','Room modes','Half-space loading']::text[],ARRAY['Blaming the loudspeaker for a dip that is really a boundary cancellation.','Assuming equalisation fixes SBIR; a true null cannot be filled by boosting.','Ignoring the floor bounce, which causes SBIR just like a wall does.']::text[],ARRAY['Placing a monitor to move an SBIR dip out of the vocal range.','Explaining a bass dip that changes with speaker distance to the wall.','Diagnosing a floor-bounce cancellation in a room measurement.']::text[],'Intermediate','f_dip = c / (4d)','The first boundary-interference dip frequency equals the speed of sound divided by four times the speaker-to-boundary distance.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='SBIR');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e33cf3de-e984-4043-b8e8-2e41113e76ce','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e33cf3de-e984-4043-b8e8-2e41113e76ce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e33cf3de-e984-4043-b8e8-2e41113e76ce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cfc6277e-e8d4-429d-8945-78acf36caced','Shaded array','A loudspeaker or transducer array in which the drive level (and sometimes filtering) is tapered element by element across the array, rather than driven uniformly. This amplitude shading, or windowing, lowers side lobes and smooths the main beam at the cost of some beamwidth.','A shaded array feeds its speakers at different levels. The outer ones are turned down. This tapering is called shading. It reduces stray side lobes and smooths coverage.','It controls the array''s directivity by weighting elements, trading a slightly wider main beam for reduced side-lobe energy and smoother coverage.','A technician applies amplitude shading in a DSP-driven column so outer elements play quieter, suppressing side lobes that would splash sound onto ceilings or walls.','Array behavior',ARRAY['Steered array','Line array','Side lobes','Beamwidth','Amplitude taper']::text[],ARRAY['Confusing shading (amplitude taper) with steering (delay taper).','Expecting shading to narrow the beam; it usually widens the main lobe slightly.','Ignoring that shading trades side-lobe control against main-beam width.']::text[],ARRAY['Reducing side lobes on a steerable column loudspeaker.','Smoothing coverage across a seating area.','Explaining why outer array elements are driven at lower level.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shaded array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cfc6277e-e8d4-429d-8945-78acf36caced','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cfc6277e-e8d4-429d-8945-78acf36caced') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cfc6277e-e8d4-429d-8945-78acf36caced');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24e5778d-2f3e-4f36-ae50-c08fe5567a77','Steered array','A loudspeaker array whose main lobe is aimed electronically by applying progressive time delays (and often level) across its elements, without physically tilting the array. Digital signal processing sets the delays so the combined wavefront points toward the chosen coverage angle.','A steered array aims its sound using delays, not by tilting. Each speaker gets a slightly different delay. This tips the combined beam up or down. Software sets the angle.','It lets a fixed, slim column aim coverage at the audience electronically, useful where a physical tilt is impossible or unsightly.','A technician sets the steering angle in the loudspeaker''s DSP so the beam points down at the seating, then verifies coverage with a measurement or prediction.','Array behavior',ARRAY['Shaded array','Beam steering','Line array','Digital signal processing','Beamwidth']::text[],ARRAY['UNSAFE: Aiming a high-output steered column at nearby listeners'' ear height, risking excessive exposure in the beam.','Confusing electronic steering with physical aiming of the cabinet.','Steering far off-axis and losing beam control or gaining side lobes.']::text[],ARRAY['Aiming a column loudspeaker in a reverberant church.','Setting DSP delays to point coverage at a balcony.','Explaining how a flat column can cover a raked audience.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Steered array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24e5778d-2f3e-4f36-ae50-c08fe5567a77','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24e5778d-2f3e-4f36-ae50-c08fe5567a77') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24e5778d-2f3e-4f36-ae50-c08fe5567a77');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a06ee8f5-44e0-488c-aa3e-04d8ff88649b','Throat aperture','The small cross-sectional opening at the narrow end of a horn where it couples to the driver''s diaphragm or a compression driver''s exit. Its area sets the acoustic loading and, with the flare, the impedance transformation from the high-pressure throat to the low-pressure mouth.','The throat is the narrow opening at the small end of a horn. The driver connects here. Its size sets how hard the horn loads the driver. It begins the horn''s pressure transformation.','It sets the starting cross-section for the horn flare, controlling acoustic loading, efficiency, and the throat-to-mouth impedance transformation.','A technician matches the throat aperture to the compression driver''s exit diameter, avoiding an abrupt step that would cause reflections and response irregularity.','Horn theory',ARRAY['Horn mouth','Compression driver','Flare rate','Phase plug','Acoustic impedance transformation']::text[],ARRAY['Mismatching the throat area to the driver exit, causing a discontinuity and response ripple.','Confusing the throat (small end) with the mouth (large end) of the horn.','Assuming a smaller throat always means more output; it also raises distortion and limits power.']::text[],ARRAY['Matching a horn throat to a 1-inch or 2-inch compression driver exit.','Explaining why a throat step causes a response dip.','Selecting throat size for a target loading and power handling.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Throat aperture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a06ee8f5-44e0-488c-aa3e-04d8ff88649b','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a06ee8f5-44e0-488c-aa3e-04d8ff88649b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a06ee8f5-44e0-488c-aa3e-04d8ff88649b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '95a5ae10-8cca-471c-9840-ce58bacaabbe','Throat distortion','Throat distortion is nonlinear harmonic distortion generated in the small, high-pressure air region at a horn''s throat, where sound-pressure amplitude is greatest. Because the local speed of sound rises slightly with pressure, wave peaks travel faster than troughs and progressively steepen the waveform, creating harmonics. For an infinite exponential horn the percent second-harmonic distortion rises with the frequency ratio f/fc and with the square root of throat intensity.','A horn squeezes sound into a tiny opening called the throat. The air there gets very loud and packed tight. Loud, packed air does not stretch and squash evenly. This bends the sound wave and adds harsh extra tones. Louder throats make more of this distortion.','The concept explains why horns add audible harmonic distortion at high drive levels, guiding designers to limit throat pressure and choose an adequate throat area.','For fc=500 Hz, f=2000 Hz and throat intensity I_t=100 W/m2: D2 = 1.73x10^-2 x (2000/500) x sqrt(100) = 1.73x10^-2 x 4 x 10 = 0.69%; a technician lowers drive level or picks a larger-format driver to cut it.','Horn Distortion',ARRAY['Throat impedance','Compression driver','Horn cutoff frequency','Exponential horn','Throat intensity']::text[],ARRAY['UNSAFE: Driving a compression driver to maximum throat pressure to reach target level, exposing operators and audience to hazardous horn SPL while distortion climbs.','Blaming throat distortion on the diaphragm when it arises from nonlinear air behaviour in the throat.','Assuming distortion stays constant with frequency; it grows with the f/fc ratio.']::text[],ARRAY['A horn-loaded PA rig sounding harsh only at high SPL.','Choosing a larger-format compression driver to lower throat intensity.','Measuring rising second-harmonic distortion as level increases on a horn.']::text[],'Advanced','D2[%] = 1.73x10^-2 * (f/fc) * sqrt(I_t)','Percent second-harmonic distortion equals a constant times the ratio of frequency to horn cutoff frequency, times the square root of the acoustic intensity at the throat.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Throat distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '95a5ae10-8cca-471c-9840-ce58bacaabbe','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='95a5ae10-8cca-471c-9840-ce58bacaabbe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='95a5ae10-8cca-471c-9840-ce58bacaabbe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c79a3052-6174-47cd-a670-46301c66427b','Throat impedance','Throat impedance is the acoustic impedance a horn presents to its driver at the throat (small end), combining an acoustic resistance (the power-transferring term) and an acoustic reactance (a mass-like energy-storage term). For an infinite exponential horn above cutoff it equals (rho0*c/S_T)[sqrt(1-(fc/f)^2) + j(fc/f)], so the resistive part rises toward rho0*c/S_T as frequency climbs well above cutoff.','The throat is where the driver meets the horn. Impedance is how hard the air pushes back there. A good horn makes the air push back more evenly. This helps the driver move air well. Below the horn''s cutoff, the loading falls away.','It quantifies how well a horn couples a driver to the air, which sets sensitivity, loading, and how low in frequency the horn works.','For an exponential horn with throat area S_T=10 cm2 (0.001 m2) at f=2fc, the resistive part is (413/0.001)*sqrt(1-0.25) = 3.6x10^5 acoustic ohms; a technician confirms the driver''s rated throat area matches the horn.','Horn Loading',ARRAY['Throat resistance','Throat reactance','Horn cutoff frequency','Compression driver','Radiation impedance']::text[],ARRAY['Treating throat impedance as purely resistive; near and below cutoff it is largely reactive.','UNSAFE: Forcing extra power into a driver poorly matched to the throat, risking driver failure and hazardous SPL.','Confusing throat area with mouth area.']::text[],ARRAY['Matching a 1-inch versus 2-inch compression driver to a horn throat.','Explaining weak output below a horn''s cutoff.','Comparing loading of exponential and conical horns.']::text[],'Advanced','Z_AT = (rho0*c/S_T) * [ sqrt(1 - (fc/f)^2) + j*(fc/f) ],  for f > fc','Throat acoustic impedance equals air''s characteristic impedance divided by throat area, times a real part (square root of one minus the squared cutoff-to-frequency ratio) plus an imaginary part (the cutoff-to-frequency ratio).','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Throat impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c79a3052-6174-47cd-a670-46301c66427b','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c79a3052-6174-47cd-a670-46301c66427b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c79a3052-6174-47cd-a670-46301c66427b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3648e248-79c9-4b2d-ac61-7a0bcd4301d2','Throat reactance','Throat reactance is the imaginary (reactive) part of a horn''s throat impedance: the mass-like component that stores and returns energy rather than radiating acoustic power. For an infinite exponential horn it equals (rho0*c/S_T)(fc/f), so it dominates near and below cutoff and falls as frequency rises above cutoff.','Some of the air''s push-back stores energy instead of sending sound out. That stored part is the reactance. It is strongest near the horn''s low limit. Higher up it fades, and the horn works better.','It describes the non-radiating, energy-storing part of throat loading, which limits useful output near a horn''s cutoff frequency.','At f=fc the reactance equals rho0*c/S_T; at f=4fc it falls to a quarter of that; a designer keeps the working band above cutoff so reactance stays small.','Horn Loading',ARRAY['Throat impedance','Throat resistance','Horn cutoff frequency','Reactance','Exponential horn']::text[],ARRAY['Thinking reactance radiates sound power; it only stores and returns energy.','Ignoring reactance near cutoff, where it dominates the throat impedance.','Confusing acoustic throat reactance with the voice coil''s electrical reactance.']::text[],ARRAY['Explaining why a horn stops loading just below cutoff.','Analyzing the imaginary part of a measured throat impedance.','Comparing reactance of exponential and hyperbolic horns.']::text[],'Advanced','X_AT = (rho0*c/S_T) * (fc/f)','Throat reactance equals air''s characteristic impedance divided by throat area, times the ratio of cutoff frequency to operating frequency.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Throat reactance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3648e248-79c9-4b2d-ac61-7a0bcd4301d2','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3648e248-79c9-4b2d-ac61-7a0bcd4301d2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3648e248-79c9-4b2d-ac61-7a0bcd4301d2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c9e1ebc6-fb41-49db-9c65-d521ccb919d4','Throat reflection','Throat reflection is sound energy reflected back toward the throat from impedance discontinuities in the horn, chiefly the mouth: a too-small mouth reflects long wavelengths back down the horn and causes response ripple. Reflection is minimized when the mouth is acoustically large, commonly stated as k*r_m >= 1 (mouth roughly one wavelength in circumference or larger).','Sound travels down the horn and out the mouth. If the mouth is too small, some sound bounces back. The reflected sound fights the new sound. This makes bumps and dips in the response. A big enough mouth stops most of the bounce.','It explains the ripple and uneven loading seen when a horn mouth is too small, guiding minimum mouth-size choices.','For a low limit of 300 Hz, minimum mouth radius r_m = c/(2*pi*f) = 343/(2*pi*300) = 0.18 m (about 0.36 m diameter); a technician sizes the mouth so k*r_m >= 1 at the lowest wanted frequency.','Horn Behaviour',ARRAY['Throat impedance','Horn mouth','Horn cutoff frequency','Standing wave','Directivity']::text[],ARRAY['Using an undersized mouth to save space, which causes strong response ripple.','Believing reflections occur only at the throat, not at the mouth.','Ignoring that reflection worsens toward low frequencies (long wavelengths).']::text[],ARRAY['Diagnosing ripple in a bass horn''s low-end response.','Sizing the mouth of a midrange horn for smooth loading.','Comparing folded-horn designs with different mouth areas.']::text[],'Advanced','minimal reflection when k*r_m >= 1,  with k = 2*pi*f/c','Mouth reflection is low when the wave number times the mouth radius is at least one.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Throat reflection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c9e1ebc6-fb41-49db-9c65-d521ccb919d4','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c9e1ebc6-fb41-49db-9c65-d521ccb919d4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c9e1ebc6-fb41-49db-9c65-d521ccb919d4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '965dc988-09c8-4a05-b9d7-a564ebbf44ea','Throat resistance','Throat resistance is the real (resistive) part of a horn''s throat impedance, the component that actually transfers acoustic power from the driver into radiated sound. For an infinite exponential horn it equals (rho0*c/S_T)*sqrt(1-(fc/f)^2): zero at cutoff and rising toward the maximum rho0*c/S_T well above cutoff, which is why loading and sensitivity fall off near the cutoff frequency.','One part of the air''s push-back actually sends sound out. That part is the resistance. It does the real work. At the horn''s low limit it drops to zero. Well above that limit it reaches full strength.','It represents the power-transferring part of horn loading, which governs sensitivity and how effectively the driver radiates.','At f=2fc the factor sqrt(0.75)=0.866; with S_T=0.001 m2, throat resistance = (413/0.001)*0.866 = 3.6x10^5 acoustic ohms; a designer keeps the passband above cutoff so resistance stays high.','Horn Loading',ARRAY['Throat impedance','Throat reactance','Horn cutoff frequency','Radiation resistance','Efficiency']::text[],ARRAY['Assuming throat resistance is flat above cutoff; it climbs from zero toward its maximum.','Expecting real output below cutoff, where resistance is essentially zero.','Confusing acoustic throat resistance with the voice coil''s DC resistance.']::text[],ARRAY['Explaining a horn''s sensitivity roll-off near cutoff.','Comparing power transfer of different horn flares.','Reading the real part of a measured throat impedance curve.']::text[],'Advanced','R_AT = (rho0*c/S_T) * sqrt(1 - (fc/f)^2),  for f > fc','Throat resistance equals air''s characteristic impedance divided by throat area, times the square root of one minus the squared cutoff-to-frequency ratio.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Throat resistance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '965dc988-09c8-4a05-b9d7-a564ebbf44ea','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='965dc988-09c8-4a05-b9d7-a564ebbf44ea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='965dc988-09c8-4a05-b9d7-a564ebbf44ea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '01d9bff8-d37e-4b3f-a1c2-3244467aaa6a','Total enclosure Q','Total enclosure Q (Qtc) is the total quality factor of a driver mounted in a sealed (closed) box, at the resulting system resonance, combining the driver''s electrical and mechanical damping as loaded by the box air compliance. It equals Qts*sqrt(Vas/Vb + 1); Qtc=0.707 gives a maximally flat (Butterworth) response, while higher values give a peaked, boomier low end.','A sealed box adds a spring of trapped air behind the cone. This stiffens the driver and raises its resonance. Total box Q tells how peaky that resonance is. About 0.7 is smooth and tight. Higher is louder near resonance but boomy.','It predicts the shape of a sealed box''s low-frequency response, so a designer can choose a box volume for a target sound.','Qts=0.35, Vas=50 L, Vb=25 L: Qtc = 0.35*sqrt(50/25 + 1) = 0.35*sqrt(3) = 0.61 (near Butterworth); a technician trims Vb to hit a target Qtc.','Enclosure Alignment',ARRAY['Sealed enclosure','Qts','Vas','System resonance','Butterworth alignment','Qtc']::text[],ARRAY['Forgetting Vb is net internal volume, after subtracting the driver, bracing, and fill displacement.','Using Qes instead of Qts in the formula.','Thinking a higher Qtc means deeper bass; it means a resonance peak, not more extension.']::text[],ARRAY['Choosing a sealed box volume for a subwoofer driver.','Deciding between a tight 0.7 Qtc and a warmer 1.0 Qtc.','Predicting the low-frequency bump of an undersized sealed box.']::text[],'Intermediate','Qtc = Qts * sqrt(Vas/Vb + 1) ;  fc = fs * sqrt(Vas/Vb + 1)','Total box Q equals the driver''s total Q times the square root of one plus the ratio of the driver''s equivalent compliance volume to the net box volume; the closed-box resonance scales by the same factor.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Total enclosure Q');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '01d9bff8-d37e-4b3f-a1c2-3244467aaa6a','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='01d9bff8-d37e-4b3f-a1c2-3244467aaa6a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='01d9bff8-d37e-4b3f-a1c2-3244467aaa6a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8b4a3929-3a80-44c6-97af-12cd3930dfa6','Tractrix horn','A tractrix horn is a horn whose wall contour follows the tractrix curve, derived on the assumption of a constant-radius spherical wavefront that stays tangent to the walls; the profile was applied to horns by P.G.A.H. Voigt (patented 1926). It expands faster than an exponential horn near the mouth, giving a wide mouth in a comparatively short length.','A tractrix horn uses a special flared shape. The math tries to keep the sound wave rounded as it grows. This shape flares out fast near the opening. So the horn can be short but still have a wide mouth. It was first used by inventor P.G.A.H. Voigt.','It offers a horn profile intended to control the wavefront and directivity while keeping the horn short, an alternative to the exponential flare.','A designer fixes the mouth radius r_m, then plots horn radius r against axial distance x from the tractrix equation to cut or 3D-print the profile.','Horn Geometry',ARRAY['Exponential horn','Horn cutoff frequency','Wavefront','Compression driver','Horn mouth']::text[],ARRAY['Assuming the wavefront is truly spherical; measurements show it is not, and beaming rises with frequency.','Treating a tractrix horn as identical to an exponential horn.','Forgetting that a finite tractrix mouth still needs adequate size to avoid reflections.']::text[],ARRAY['Designing a short midrange horn with wide coverage.','Comparing tractrix and exponential loading for a compression driver.','3D-printing a horn from a computed tractrix contour.']::text[],'Advanced','x = r_m*ln[(r_m + sqrt(r_m^2 - r^2))/r] - sqrt(r_m^2 - r^2)','The axial distance from the mouth equals the mouth radius times the natural log of a radius ratio, minus a square-root term, tracing the tractrix curve.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tractrix horn');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8b4a3929-3a80-44c6-97af-12cd3930dfa6','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8b4a3929-3a80-44c6-97af-12cd3930dfa6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8b4a3929-3a80-44c6-97af-12cd3930dfa6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ba2eeeea-e461-4616-8356-788edeb2a250','Under-spider vent','An under-spider vent is a set of openings in a loudspeaker''s motor or frame located just beneath the spider (inner suspension), positioned around the voice coil so cone motion pumps air across the coil for cooling and relieves pressure trapped under the suspension. It targets the hottest region of the motor to raise power handling and reduce thermal (power) compression.','The spider is a springy ring that centers the cone. Under it sits the hot voice coil. Under-spider vents are holes right below the spider. As the cone moves, they pump air over the coil. This cools it and lets trapped air escape.','To cool the voice coil and vent internal air pressure, so the driver handles more power with less thermal compression and distortion.','A technician keeps these vents clear of dust, gaskets, and grille foam so the pumping cooling action across the coil is not blocked.','Motor Cooling',ARRAY['Spider','Voice coil','Pole vent','Power compression','Thermal time constant']::text[],ARRAY['UNSAFE: Sealing or blocking motor vents to quiet air noise, which lets the voice coil overheat and fail.','Assuming the vents are only for cooling; they also relieve air pressure under the suspension.','Confusing an under-spider vent with a pole-piece (center) vent.']::text[],ARRAY['Cooling a high-power subwoofer motor during long shows.','Diagnosing power compression in a hard-driven driver.','Comparing vented and non-vented motor structures.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Under-spider vent');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ba2eeeea-e461-4616-8356-788edeb2a250','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ba2eeeea-e461-4616-8356-788edeb2a250') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ba2eeeea-e461-4616-8356-788edeb2a250');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1e29475c-11f1-42a1-966c-de71f3fe6029','Variovent','Variovent is a trademarked acoustic-resistance (aperiodic) vent made by Scan-Speak: a panel of damping material sandwiched between two grilles and fitted to an otherwise sealed enclosure. It adds controlled acoustic resistance so the box behaves partway between sealed and vented, lowering system Q and making the box act effectively larger without a tuned port. The Variovent name is a Scan-Speak (Scan-Speak A/S, Denmark) trademark; the underlying method is the generic aperiodic acoustic-resistance vent.','Variovent is a brand of resistive vent from Scan-Speak. It is damping material held between two grilles. You fit it to a sealed box wall. It lets a little air leak through in a controlled way. This calms the box resonance and acts like a bigger box.','To damp a sealed box''s resonance and lower its system Q, allowing a smaller or better-controlled enclosure without a resonant port.','A builder fits one Variovent for a box up to roughly 40 litres, adds more for larger volumes, then measures the flattened impedance peak to confirm the damping.','Enclosure Damping',ARRAY['Aperiodic enclosure','Acoustic resistance','Sealed enclosure','Total enclosure Q','Damping material']::text[],ARRAY['Treating a Variovent as a tuned bass port; it is resistive, not a resonant Helmholtz vent.','Expecting large low-frequency extension; it mainly damps and modestly enlarges the effective volume.','Over-compressing or overpacking the material, which changes its acoustic resistance.']::text[],ARRAY['Building an aperiodic sealed box for a high-Q driver.','Taming a boomy sealed enclosure without adding a port.','Retrofitting damping to lower a system''s Q.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Variovent');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1e29475c-11f1-42a1-966c-de71f3fe6029','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1e29475c-11f1-42a1-966c-de71f3fe6029') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1e29475c-11f1-42a1-966c-de71f3fe6029');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '35293066-bf85-47fa-b04e-60731b5bb90b','Vent resonance','Vent resonance is the Helmholtz resonance formed by the mass of air in a bass-reflex vent (port) working against the springiness (compliance) of the enclosed box air, producing the box tuning frequency fb at which the port radiates in phase and reinforces low-frequency output. It is set by the vent''s cross-sectional area, effective length, and the net box volume.','A reflex box has an open tube called a port. The air in the port acts like a weight. The air in the box acts like a spring. Together they bounce at one frequency. At that frequency the port adds bass. Port size and length set this frequency.','It defines the tuning frequency of a ported box, where the vent reinforces bass and the cone''s motion is minimized.','For A_v=0.005 m2, L_eff=0.15 m, V_b=0.05 m3: fb = (343/(2*pi))*sqrt(0.005/(0.05*0.15)) = 54.6*sqrt(0.667) = 45 Hz; a technician shortens the port to raise fb.','Enclosure Tuning',ARRAY['Bass reflex','Helmholtz resonance','Vented-box alignment','Port','Box tuning frequency']::text[],ARRAY['Forgetting vent end corrections, so real tuning is lower than a simple length predicts.','UNSAFE: Making a port too small to fit, causing high air velocity, chuffing, and driver over-excursion below tuning.','Confusing vent resonance (box tuning) with the driver''s free-air resonance.']::text[],ARRAY['Tuning a reflex subwoofer to a target frequency.','Reading the impedance-curve minimum that marks fb.','Fixing port chuffing noise at high output.']::text[],'Intermediate','fb = (c/(2*pi)) * sqrt( A_v / (V_b * L_eff) )','The box tuning frequency equals the speed of sound over two pi, times the square root of vent area divided by the product of box volume and effective vent length.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vent resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '35293066-bf85-47fa-b04e-60731b5bb90b','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='35293066-bf85-47fa-b04e-60731b5bb90b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='35293066-bf85-47fa-b04e-60731b5bb90b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1f856d3a-056a-4aa2-a6f2-31a44d19ebe9','Vented-box alignment','A vented-box alignment is a specific matched set of driver and box parameters, defined by the compliance ratio (alpha = Vas/Vb), the tuning ratio (h = fb/fs), and the driver''s total Q, that yields a defined low-frequency response shape such as the maximally flat fourth-order Butterworth (B4) or quasi-Butterworth (QB3) alignments in Thiele/Small theory. It fixes box volume and port tuning to suit the driver so the combined response meets a target roll-off.','A ported box has three linked choices. These are the box size, the port tuning, and the driver. An alignment is a matched set of these three. Each set gives a known bass shape. One popular set gives the flattest response.','It provides a systematic way to fit a ported box to a driver so the low-frequency response follows a chosen, predictable curve.','A technician reads the compliance ratio and tuning ratio from a Thiele/Small alignment table for the driver''s Qts, then sets Vb and fb; for example a Qts near 0.38 suggests roughly alpha=1.4 with tuning near the driver resonance.','Enclosure Alignment',ARRAY['Bass reflex','Thiele-Small parameters','Vent resonance','Qts','Box tuning frequency']::text[],ARRAY['Forcing a driver into an alignment its Qts does not suit, needing EQ or a leaky-box compromise.','Ignoring real box losses (Ql), which shift the achieved alignment.','Assuming any ported box is correctly ''tuned'' just because it has a port.']::text[],ARRAY['Designing a reflex cabinet from a driver''s Thiele/Small parameters.','Choosing between a B4 and a QB3 alignment.','Checking measured response against the target alignment curve.']::text[],'Advanced','alpha = Vas/Vb ;  h = fb/fs  (alignment tables relate alpha, h, and Qts)','An alignment is defined by the compliance ratio (driver compliance volume over box volume) and the tuning ratio (box tuning frequency over driver resonance), chosen to fit the driver''s total Q.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vented-box alignment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1f856d3a-056a-4aa2-a6f2-31a44d19ebe9','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1f856d3a-056a-4aa2-a6f2-31a44d19ebe9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1f856d3a-056a-4aa2-a6f2-31a44d19ebe9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f1acdc8f-2ee1-455f-bc38-e17a276737cd','Vertical lobing','Vertical lobing is the frequency-dependent interference pattern of peaks and nulls in the vertical polar response of a multi-way loudspeaker, caused by path-length differences between vertically spaced drivers (typically woofer and tweeter) reproducing the same crossover-region frequencies. The main lobe can tilt off the design axis, and deep nulls appear at angles where the two arrivals are out of phase.','A two-way speaker has drivers set apart on the front. Near the crossover both play the same notes. Move up or down and one driver is farther away. The two sounds can cancel at some angles. This makes dips and tilts in the vertical response.','It describes how driver spacing and crossover choices shape the vertical coverage, which affects tonal balance for listeners above and below the axis.','A technician measures vertical off-axis response through the crossover, then adjusts crossover order, driver spacing, or tweeter polarity to steer the main lobe onto the listening axis.','Radiation Pattern',ARRAY['Crossover','Comb filtering','Polar response','Lobing error','Driver spacing']::text[],ARRAY['Judging a speaker only on-axis and missing deep vertical nulls off-axis.','Assuming reversing tweeter polarity removes lobing; it mainly tilts the lobe.','Confusing vertical lobing with room reflections.']::text[],ARRAY['Designing a two-way crossover to keep the main lobe on-axis.','Aligning acoustic centers of woofer and tweeter.','Tilting a center-channel speaker''s lobe away from listeners.']::text[],'Intermediate','nulls where path difference d = (2n - 1)*(lambda/2),  n = 1, 2, 3...','Cancellation nulls occur at vertical angles where the extra distance to one driver differs from the other by an odd number of half wavelengths.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vertical lobing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f1acdc8f-2ee1-455f-bc38-e17a276737cd','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f1acdc8f-2ee1-455f-bc38-e17a276737cd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f1acdc8f-2ee1-455f-bc38-e17a276737cd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a0593c55-ffe5-49b8-bc77-67ea2737bfc9','Virtual source','A virtual source is an apparent point of sound origin that does not coincide with a physical driver, such as the acoustic apex behind a horn''s throat or the phantom point from which an array''s wavefront appears to diverge. It gives a single geometric origin for modeling coverage and acoustic centers, even though no transducer sits at that point.','Sound can seem to come from a spot with no speaker there. That spot is a virtual source. A horn can look like the sound starts behind it. Arrays can place an apparent source point in space. Designers use this apparent point to aim coverage.','It provides a single point to represent where a horn or array seems to radiate from, simplifying coverage-angle and array-splay geometry.','A system designer treats each horn''s virtual apex as the ray origin when laying out coverage angles across an audience.','Radiation Model',ARRAY['Acoustic center','Line array','Directivity','Wavefront','Point source']::text[],ARRAY['Equating the virtual source with the physical driver location.','Assuming it stays fixed with frequency; the acoustic center can move.','Limiting the idea to stereo phantom images only.']::text[],ARRAY['Aiming horn coverage from its virtual apex.','Modeling line-array splay angles.','Defining an acoustic center for measurement alignment.']::text[],'Intermediate',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Virtual source');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a0593c55-ffe5-49b8-bc77-67ea2737bfc9','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a0593c55-ffe5-49b8-bc77-67ea2737bfc9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a0593c55-ffe5-49b8-bc77-67ea2737bfc9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0dad7603-d268-4ddc-80d4-406e3eaea58b','Voigt pipe','A Voigt pipe is a tapered quarter-wave pipe enclosure (a tapered transmission line) named after inventor P.G.A.H. Voigt, in which the driver sits near the narrow, near-closed end and the pipe expands to a larger open mouth. Its quarter-wavelength resonance reinforces low frequencies, while the taper spreads and helps damp the higher pipe modes.','A Voigt pipe is a long tapered tube with a speaker near the narrow end. The tube is open at the wide end. Its length is tuned to a quarter of a bass wavelength. That resonance boosts low notes. The taper smooths out unwanted higher tones. It is named after inventor P.G.A.H. Voigt.','It uses a tuned tapered pipe to extend and reinforce low-frequency output from a single driver in a slim cabinet.','For a 1.5 m effective pipe length, the fundamental is about f1 = 343/(4*1.5) = 57 Hz; a builder sets pipe length to place this resonance where low-frequency support is wanted.','Enclosure Type',ARRAY['Transmission line','Quarter-wave resonance','Tapered quarter-wave tube','Standing wave','Full-range driver']::text[],ARRAY['Treating a Voigt pipe as a full horn; it is a quarter-wave resonator, not a horn.','Ignoring higher pipe modes, which add response ripple.','Placing the driver at the wrong point along the pipe, exciting unwanted modes.']::text[],ARRAY['Building a slim single-driver full-range cabinet.','Getting deep bass from a small footprint.','Comparing a tapered quarter-wave pipe with a reflex box.']::text[],'Advanced','f1 ~= c / (4*L)   (fundamental quarter-wave resonance)','The lowest pipe resonance is roughly the speed of sound divided by four times the effective pipe length.','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voigt pipe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0dad7603-d268-4ddc-80d4-406e3eaea58b','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0dad7603-d268-4ddc-80d4-406e3eaea58b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0dad7603-d268-4ddc-80d4-406e3eaea58b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '444dff06-0148-45d0-b7ce-3fa42e518fce','Waveguide loading','Waveguide loading is the use of a shallow, carefully shaped flare (a constant-directivity waveguide) in front of a direct-radiating driver, usually a dome tweeter or compression driver, to control directivity and provide modest acoustic loading without the strong impedance transformation of a true horn. Unlike a compression horn, a waveguide is designed primarily to set a uniform coverage pattern rather than to maximize efficiency.','A waveguide is a smooth flared shape in front of a tweeter. It guides where the high sound goes. This keeps the coverage even across frequency. It gives only a little loudness boost. A full horn instead squeezes the sound for more output.','To shape and stabilize a driver''s directivity versus frequency, improving power response and matching a woofer''s directivity through the crossover.','A designer picks a waveguide with, say, a nominal 90 by 60 degree pattern so the tweeter''s coverage matches the woofer''s near the crossover frequency.','Directivity Control',ARRAY['Constant-directivity horn','Directivity index','Compression driver','Crossover','Coverage angle']::text[],ARRAY['UNSAFE: Assuming a waveguide adds large horn-like gain and driving the tweeter to hazardous SPL that damages it and hearing.','Confusing a directivity waveguide with a high-efficiency compression horn.','Expecting a waveguide to extend low-frequency loading like a bass horn.']::text[],ARRAY['Matching a tweeter''s directivity to a woofer at the crossover.','Designing a constant-directivity studio monitor.','Controlling early room reflections with tighter coverage.']::text[],'Advanced',NULL,NULL,'a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Waveguide loading');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '444dff06-0148-45d0-b7ce-3fa42e518fce','a63ccad5-33c7-4e5c-b9a2-ba6e8c896b29',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='444dff06-0148-45d0-b7ce-3fa42e518fce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='444dff06-0148-45d0-b7ce-3fa42e518fce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '81621d4e-567e-458b-a5ee-3cf258e1a592','Acoustic suspension','A sealed loudspeaker enclosure design in which the trapped air acts as the dominant spring restoring the cone, paired with a low-stiffness (high-compliance) woofer suspension. The air spring controls the resonance, letting a small sealed box give extended, well-damped low bass. The approach was pioneered by Edgar Villchur and Acoustic Research in the 1950s and is now a generic technique.','An acoustic suspension speaker uses a fully sealed box. The trapped air behaves like a spring. That air spring pushes the cone back to center. This lets a small sealed box make deep, tight bass.','To get extended low bass from a compact sealed box by using the enclosed air, rather than the cone''s own suspension, as the main restoring force.','For a woofer with Vas=100 L in a Vb=25 L sealed box, the compliance ratio is 4, so system resonance fc = fs*sqrt(1+4); at fs=25 Hz that is about 56 Hz.','Enclosure type',ARRAY['Compliance ratio','Sealed box','Vas (equivalent volume)','Suspension compliance','Air spring']::text[],ARRAY['Thinking acoustic suspension means the cone floats freely; the sealed air is the main spring.','Assuming the sealed design is just less efficient by flaw rather than a deliberate compliance trade-off.','Confusing acoustic suspension (sealed) with bass-reflex (ported) alignments.']::text[],ARRAY['Choosing a small sealed monitor for tight, controlled bass.','Explaining why a sealed box needs a high-compliance woofer.','Estimating how a smaller box raises system resonance.']::text[],'Intermediate','fc = fs * sqrt(1 + Vas/Vb)','System resonance equals the driver''s free-air resonance times the square root of one plus the ratio of equivalent suspension volume to box volume.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic suspension');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '81621d4e-567e-458b-a5ee-3cf258e1a592','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='81621d4e-567e-458b-a5ee-3cf258e1a592') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='81621d4e-567e-458b-a5ee-3cf258e1a592');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b5ed0972-6aa2-47b2-87c4-089bf76a63c4','Air-gap flux density','The magnetic flux density, in tesla, present in the narrow air gap of a driver''s magnetic circuit where the voice coil sits. Together with the length of coil conductor lying in that gap, it sets the motor''s force factor BL.','This is the strength of the magnetic field in the motor gap. The voice coil moves inside this gap. A stronger gap field makes a stronger push on the coil. It is measured in tesla.','To quantify how strong the motor''s magnetic field is where the coil works, which directly scales the force produced per amp.','With gap flux B=1.2 T and coil length in the gap l=8 m, the force factor BL = B*l = 9.6 T*m (equal to 9.6 N/A).','Motor parameter',ARRAY['BL product','Force factor','Voice coil','Magnetic circuit','Pole piece']::text[],ARRAY['Confusing total magnet energy with the flux density actually in the gap.','Assuming a larger magnet always yields higher gap flux; gap length and pole geometry set it.','Forgetting that magnetic saturation limits how high the gap flux can go.']::text[],ARRAY['Comparing two woofers'' motor strength from their BL and gap flux.','Understanding why a tighter gap raises flux density.','Explaining sensitivity differences between drivers.']::text[],'Intermediate','BL = B * l','The force factor equals the air-gap flux density multiplied by the length of voice-coil conductor lying in the gap.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Air-gap flux density');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b5ed0972-6aa2-47b2-87c4-089bf76a63c4','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b5ed0972-6aa2-47b2-87c4-089bf76a63c4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b5ed0972-6aa2-47b2-87c4-089bf76a63c4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1a50104c-8fab-475a-8b49-6935737ac8db','Aluminum cone','A cone or dome diaphragm made from thin aluminum, often anodized, chosen for high stiffness-to-mass so it stays pistonic to higher frequencies than paper. Its low internal damping gives a sharp, high-Q breakup resonance that must be crossed out or notched.','This diaphragm is made from thin aluminum. Aluminum is stiff and light. That keeps the cone moving as one piece up higher. But metal rings at its breakup point. Designers filter out that sharp resonance.','To extend a driver''s clean, pistonic range using a stiff metal diaphragm, at the cost of a sharp breakup peak.','A technician crosses an aluminum-cone woofer below its breakup peak, or adds a notch filter, to keep the ringing out of the passband.','Diaphragm material',ARRAY['Breakup frequency','Ceramic-metal composite','Beryllium diaphragm','Bending stiffness','Cone treatment']::text[],ARRAY['Assuming a metal cone has no breakup; it just moves the sharp peak higher.','Running an aluminum driver too close to its breakup peak without a notch.','Thinking anodizing is only cosmetic; it adds a stiff, hard oxide layer.']::text[],ARRAY['Selecting a crossover point below a metal woofer''s breakup.','Diagnosing a harsh peak from an unfiltered aluminum tweeter.','Comparing metal and paper cones for a monitor design.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aluminum cone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1a50104c-8fab-475a-8b49-6935737ac8db','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1a50104c-8fab-475a-8b49-6935737ac8db') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1a50104c-8fab-475a-8b49-6935737ac8db');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '80bab53e-bece-46f2-984b-1afa1bc8a998','Annular diaphragm','A ring-shaped radiating diaphragm with a controlled or plugged center, used in ring-radiator tweeters and many compression drivers. The annulus radiates while a central phase plug or pole shapes the wavefront and suppresses the central dome mode.','This diaphragm is shaped like a ring. The middle is not the main radiating part. A plug or post sits in the center. The ring shape avoids some center vibration problems. Ring-radiator tweeters use this.','To radiate high frequencies from a ring while a center plug tames the central resonance and shapes dispersion.','A technician recognizes a ring-radiator tweeter''s central plug as part of the acoustic design, not a defect, and avoids poking it.','Diaphragm geometry',ARRAY['Compression diaphragm','Phase plug','Dome diaphragm','Breakup frequency','Ring radiator']::text[],ARRAY['Mistaking the central phase plug for a damaged or missing dome.','Assuming an annular diaphragm behaves exactly like a full dome.','Denting the delicate ring during handling.']::text[],ARRAY['Identifying a ring-radiator tweeter in a monitor.','Explaining why the tweeter center looks filled in.','Comparing dome and ring-radiator dispersion.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Annular diaphragm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '80bab53e-bece-46f2-984b-1afa1bc8a998','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='80bab53e-bece-46f2-984b-1afa1bc8a998') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='80bab53e-bece-46f2-984b-1afa1bc8a998');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44109d41-1b0a-4ca9-b960-151a19c7f87e','Areal mass','A diaphragm''s moving mass divided by its radiating area, usually expressed in kg/m2 (or g/cm2). It largely sets a driver''s sensitivity, since a lighter, larger radiator accelerates more easily for a given force.','This is diaphragm mass spread over its area. Divide the moving mass by the radiating area. A light, wide diaphragm has low areal mass. Low areal mass helps a driver play loud efficiently.','To compare how heavy diaphragms are relative to their size, which predicts sensitivity and high-frequency reach.','A 0.5 g dome 25 mm across has radiating area about 4.9e-4 m2, so its areal mass is roughly 1.0 kg/m2.','Diaphragm parameter',ARRAY['Moving mass (Mms)','Sensitivity','Diaphragm material','Beryllium diaphragm','Bending stiffness']::text[],ARRAY['Comparing raw diaphragm mass without accounting for area.','Assuming lower areal mass always means better sound, ignoring stiffness.','Confusing areal mass with total moving mass Mms.']::text[],ARRAY['Comparing tweeter diaphragm materials for sensitivity.','Explaining why beryllium domes are prized for low areal mass.','Estimating efficiency from diaphragm mass and size.']::text[],'Intermediate','sigma = m / A','Areal mass equals the diaphragm''s moving mass divided by its radiating area.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Areal mass');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44109d41-1b0a-4ca9-b960-151a19c7f87e','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44109d41-1b0a-4ca9-b960-151a19c7f87e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44109d41-1b0a-4ca9-b960-151a19c7f87e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7ba580c-dab6-4c9b-91e4-a54f45522328','Asymmetric magnetic circuit','A motor design whose magnetic structure is deliberately shaped so the force factor BL(x) or inductance Le(x) stays more constant as the coil moves in and out. Extended pole pieces, copper caps, or offset gaps counter the natural front-back asymmetry of a simple motor.','A normal motor pushes unevenly as the coil moves in and out. An asymmetric motor is shaped to fix this. It uses extended poles or copper parts. The goal is steadier force across the coil''s travel. This lowers distortion.','To linearize the motor so force and inductance vary less with cone position, reducing large-signal distortion.','A technician expects such a driver to hold BL(x) flatter over its excursion, giving lower distortion at high output.','Motor design',ARRAY['BL(x)','Current-dependent inductance','Demodulation ring','Force factor','Pole piece']::text[],ARRAY['Assuming any large motor is automatically linear.','Confusing deliberate magnetic asymmetry with a manufacturing defect.','Ignoring that inductance asymmetry also creates distortion, not just BL.']::text[],ARRAY['Comparing subwoofer motors for low distortion.','Explaining why some drivers use copper pole caps and rings.','Reading a Klippel report showing BL(x) symmetry.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Asymmetric magnetic circuit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7ba580c-dab6-4c9b-91e4-a54f45522328','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7ba580c-dab6-4c9b-91e4-a54f45522328') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7ba580c-dab6-4c9b-91e4-a54f45522328');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '03a77ac2-af70-4c54-a7a9-3c953a8d6456','BL product','The product of the air-gap flux density B and the length l of voice-coil conductor lying in that gap, giving the driver''s force factor in tesla-metres (equivalently newtons per amp). It converts coil current into mechanical force on the diaphragm.','BL is the motor''s strength number. It multiplies the gap field by the coil wire length. This tells how much push you get per amp. A higher BL means a stronger motor.','To express, in one number, how effectively a driver turns current into cone force.','With B=1.2 T and l=8 m, BL = 9.6 T*m; a 2 A coil current then produces F = BL*i = 19.2 N.','Motor parameter',ARRAY['Air-gap flux density','Force factor','BL(x)','BL(i)','Voice coil']::text[],ARRAY['Reading BL as a fixed constant; it drops as the coil leaves the gap.','Assuming higher BL is always better, ignoring damping and moving mass.','Confusing BL (T*m) with the raw gap flux density B (T).']::text[],ARRAY['Comparing two woofers'' motor strength.','Predicting force output at a given drive current.','Interpreting a Thiele-Small parameter sheet.']::text[],'Intermediate','BL = B * l ; F = BL * i','The force factor equals gap flux density times conductor length in the gap; force equals the force factor times coil current.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='BL product');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '03a77ac2-af70-4c54-a7a9-3c953a8d6456','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='03a77ac2-af70-4c54-a7a9-3c953a8d6456') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='03a77ac2-af70-4c54-a7a9-3c953a8d6456');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6911bc2c-7786-4cbe-95de-270c98fca9aa','BL(i)','The force factor expressed as a function of voice-coil current, capturing how coil current modulates the gap flux (flux/reluctance modulation) and slightly changes BL. It is a current-driven large-signal nonlinearity, distinct from the position dependence BL(x).','BL can change with the current itself. Big coil currents nudge the magnet''s field. This makes the motor push a little unevenly. It adds distortion at high drive levels. Copper rings reduce this effect.','To describe the current-driven part of motor nonlinearity, separate from cone position, for accurate distortion modelling.','A technician expects a motor with a shorting/demodulation ring to show a flatter BL(i) and lower current-related distortion.','Motor nonlinearity',ARRAY['BL(x)','Current-dependent force factor','Demodulation ring','Current-dependent inductance','Force factor']::text[],ARRAY['Assuming BL depends only on position, not current.','Ignoring current modulation of flux in high-power drivers.','Confusing BL(i) with the inductance nonlinearity Le(i).']::text[],ARRAY['Analyzing intermodulation distortion at high power.','Explaining why demodulation rings help at high current.','Reading a large-signal motor model.']::text[],'Advanced','F = BL(i) * i','The force equals the current-dependent force factor times the coil current.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='BL(i)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6911bc2c-7786-4cbe-95de-270c98fca9aa','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6911bc2c-7786-4cbe-95de-270c98fca9aa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6911bc2c-7786-4cbe-95de-270c98fca9aa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'da63d5c0-054a-43b5-a189-66ffd23f26dc','BL(x)','The force factor expressed as a function of voice-coil displacement x, describing how motor strength falls as the coil moves out of the uniform-flux gap. A wide, symmetric BL(x) curve about the rest position is a key marker of low large-signal distortion.','BL changes as the cone moves in and out. In the center the motor is strongest. Near the ends of travel it weakens. An uneven BL(x) curve adds distortion. Good motors keep it flat and symmetric.','To characterize position-dependent motor strength, the dominant source of large-signal (high-excursion) distortion.','A technician reads a Klippel BL(x) plot; a curve staying above about 70% of peak across Xmax indicates a well-behaved motor.','Motor nonlinearity',ARRAY['BL product','BL(i)','Xmax','Asymmetric magnetic circuit','Force factor']::text[],ARRAY['Treating BL as constant over the whole stroke.','Assuming a long coil always fixes BL(x); overhang design still matters.','Ignoring BL(x) asymmetry, which shifts the coil rest position under drive.']::text[],ARRAY['Judging a subwoofer''s clean excursion limit.','Explaining even-order distortion from an offset BL(x).','Comparing overhung and underhung motor designs.']::text[],'Advanced','F(x) = BL(x) * i','The force at a given position equals the position-dependent force factor times the coil current.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='BL(x)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'da63d5c0-054a-43b5-a189-66ffd23f26dc','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='da63d5c0-054a-43b5-a189-66ffd23f26dc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='da63d5c0-054a-43b5-a189-66ffd23f26dc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f50829ef-efbd-48c6-9c91-51b59045a9e6','Bell mode','A diaphragm breakup mode in which the rim and body flex in a bell-like pattern of radial and circumferential nodal lines, rather than moving as a rigid piston. Such modes appear above the breakup frequency and color the response with peaks and dips.','Above a certain frequency a diaphragm stops moving as one piece. Parts of it flex like a struck bell. This makes rings, peaks, and dips. Designers push this out of the audible band. Stiff materials and damping help.','To name the bell-like flexing modes that limit a diaphragm''s clean pistonic range.','A technician expects a metal-dome tweeter''s bell mode as a sharp high peak, controlled by the crossover choice or a notch filter.','Breakup behavior',ARRAY['Breakup frequency','Bending stiffness','Cone treatment','Aluminum cone','Diamond diaphragm']::text[],ARRAY['Thinking breakup means the diaphragm simply stops working.','Assuming stiffer material removes bell modes rather than moving them up.','Ignoring bell-mode ringing just outside the crossover point.']::text[],ARRAY['Explaining a metal dome''s ultrasonic peak.','Choosing damping to tame cone bell modes.','Interpreting a laser scan of cone vibration.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bell mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f50829ef-efbd-48c6-9c91-51b59045a9e6','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f50829ef-efbd-48c6-9c91-51b59045a9e6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f50829ef-efbd-48c6-9c91-51b59045a9e6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1f322a78-3a0d-4779-819e-ce3064cf02a4','Bending stiffness','A diaphragm''s resistance to bending (flexural rigidity), set by the material''s Young''s modulus, its thickness cubed, and Poisson''s ratio. Higher bending stiffness raises the breakup frequency, keeping the diaphragm pistonic over a wider band.','This is how hard a diaphragm is to bend. It grows fast with thickness. Stiffer, thicker material bends less. That pushes breakup higher. So the cone stays a clean piston longer.','To quantify how well a diaphragm resists flexing, which controls where breakup starts.','For thin aluminum (E=69 GPa, nu=0.33) at t=0.1 mm, flexural rigidity D = E*t^3/[12*(1-nu^2)] is about 6.5e-3 N*m.','Mechanical property',ARRAY['Breakup frequency','Bell mode','Aluminum cone','Composite cone','Areal mass']::text[],ARRAY['Thinking a small thickness change barely matters; stiffness scales with thickness cubed.','Ignoring damping, which also shapes breakup, not just stiffness.','Confusing bending stiffness with suspension compliance.']::text[],ARRAY['Choosing a cone material to raise breakup.','Explaining why thin metal domes are made stiff.','Comparing sandwich cones for rigidity.']::text[],'Advanced','D = E * t^3 / [12 * (1 - nu^2)]','Flexural rigidity equals Young''s modulus times thickness cubed, divided by twelve times one minus Poisson''s ratio squared.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bending stiffness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1f322a78-3a0d-4779-819e-ce3064cf02a4','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1f322a78-3a0d-4779-819e-ce3064cf02a4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1f322a78-3a0d-4779-819e-ce3064cf02a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a2f7c894-b1a1-4b7e-aa01-9babdfa8cea4','Beryllium diaphragm','A diaphragm made from beryllium metal or foil, prized for its very high stiffness-to-mass and high internal sound velocity, which pushes breakup far above the audio band. It is used in premium tweeters and compression drivers; beryllium dust is toxic if the diaphragm is machined or broken.','Beryllium is a light, very stiff metal. It keeps a tweeter pistonic to very high frequencies. So it sounds clean and extended. But beryllium dust is poisonous to breathe. Intact drivers are safe; broken ones are a hazard.','To achieve extremely high breakup frequencies and low areal mass in high-end tweeters and compression drivers.','A technician never sands, files, or bare-hands a shattered beryllium dome; a broken unit is bagged and disposed of following hazardous-material guidance.','Diaphragm material',ARRAY['Diamond diaphragm','Aluminum cone','Areal mass','Breakup frequency','Compression diaphragm']::text[],ARRAY['UNSAFE: Sanding, filing, or cleaning up a shattered beryllium diaphragm without respiratory protection; inhaled dust can cause chronic beryllium disease.','UNSAFE: Discarding broken beryllium drivers in normal trash instead of following hazardous-waste handling.','Assuming an intact beryllium dome is dangerous in normal use; the risk is inhaled dust from breakage.','Thinking the benefit is loudness; it is really extended stiffness and low mass.']::text[],ARRAY['Servicing a high-end tweeter with a beryllium dome.','Explaining why a broken beryllium unit needs special disposal.','Comparing beryllium and diamond tweeters.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beryllium diaphragm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a2f7c894-b1a1-4b7e-aa01-9babdfa8cea4','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a2f7c894-b1a1-4b7e-aa01-9babdfa8cea4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a2f7c894-b1a1-4b7e-aa01-9babdfa8cea4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4fda8555-d27a-402f-abbd-a5d2948f38fd','Bottoming','The condition where a driven cone reaches its rearward mechanical limit and the voice-coil former or cone strikes the backplate or magnet assembly. It produces a hard knocking sound and can permanently damage the coil or suspension.','Bottoming is when the cone slams into its back limit. The coil part hits the magnet structure. You hear a hard knock. This can wreck the voice coil. It comes from too much power or too little box loading.','To name the destructive over-excursion event that marks a driver''s inward mechanical limit.','A technician who hears knocking at high level immediately reduces drive and adds a high-pass filter to stop over-excursion.','Failure mode',ARRAY['Buckling','Xmax','Over-excursion','Voice coil','Compliance nonlinearity']::text[],ARRAY['UNSAFE: Continuing to drive a woofer that is knocking, which quickly destroys the voice coil.','Blaming the amplifier for the knock instead of over-excursion.','Ignoring a subsonic high-pass filter on ported or vinyl playback.']::text[],ARRAY['Diagnosing knocking from a subwoofer at high level.','Setting a high-pass filter to protect a driver.','Explaining damage from playing a ported box below tuning.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bottoming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4fda8555-d27a-402f-abbd-a5d2948f38fd','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4fda8555-d27a-402f-abbd-a5d2948f38fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4fda8555-d27a-402f-abbd-a5d2948f38fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'df7411df-3a71-466d-84eb-e79864a621de','Breakup frequency','The frequency above which a diaphragm ceases to move as a rigid piston and begins to flex into modal (breakup) vibration. It is set by the diaphragm''s bending stiffness, mass distribution, and geometry, and marks the top of the clean pistonic band.','Below this frequency the cone moves as one piece. Above it the cone flexes and rings. That point is the breakup frequency. Stiffer, lighter diaphragms break up higher. Designers keep breakup out of the passband.','To mark where a diaphragm stops behaving pistonically, setting the usable top end of a driver.','A technician crosses a metal woofer well below its breakup frequency, or notches the peak, to keep ringing out of the response.','Breakup behavior',ARRAY['Bell mode','Bending stiffness','Cone treatment','Aluminum cone','Diamond diaphragm']::text[],ARRAY['Assuming breakup is a single clean point rather than a region of modes.','Thinking metal cones have no breakup.','Crossing a driver too close to its breakup peak.']::text[],ARRAY['Choosing a crossover point for a metal woofer.','Explaining a sharp response peak at high frequency.','Comparing paper and metal cone breakup.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Breakup frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'df7411df-3a71-466d-84eb-e79864a621de','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='df7411df-3a71-466d-84eb-e79864a621de') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='df7411df-3a71-466d-84eb-e79864a621de');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5e6014bb-5884-4c26-926c-5a464e8b16b9','Buckling','A mechanical instability in which a cone, surround, or voice-coil former suddenly deforms or collapses out of shape under compressive or drive stress, rather than flexing smoothly. In drivers it often refers to former or cone collapse at high excursion or from overheating.','Buckling is a sudden collapse of shape. A cone or coil tube bends out of form. It happens under heavy stress or heat. Unlike normal flexing, it does not spring back. It usually means damage.','To name the collapse-type failure of a diaphragm or former under mechanical or thermal stress.','A technician inspecting a failed driver looks for a buckled former or creased cone as evidence of over-excursion or thermal damage.','Failure mode',ARRAY['Bottoming','Over-excursion','Cone treatment','Bending stiffness','Voice coil']::text[],ARRAY['Confusing cosmetic cone creasing with harmless flexing.','Assuming buckling is purely mechanical; heat softens the former too.','Ignoring buckling risk when running near mechanical limits.']::text[],ARRAY['Inspecting a blown driver for a collapsed former.','Explaining a creased cone after abuse.','Understanding limits of a lightweight former.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Buckling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5e6014bb-5884-4c26-926c-5a464e8b16b9','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5e6014bb-5884-4c26-926c-5a464e8b16b9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5e6014bb-5884-4c26-926c-5a464e8b16b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9e064470-8680-437f-a668-43ed1521c2c5','Carbon fiber cone','A cone made from woven or chopped carbon-fibre reinforced composite, offering high stiffness-to-mass with more internal damping than bare metal. It raises the breakup frequency while softening the breakup peak compared with aluminum.','This cone uses carbon fiber in resin. It is stiff yet light. It also has some built-in damping. So it plays clean high and rings less than metal. Many hi-fi and pro woofers use it.','To combine high stiffness with useful damping, extending pistonic range without a harsh metal-like peak.','A technician can often cross a carbon-fibre woofer a little higher than a metal one because its breakup peak is better damped.','Diaphragm material',ARRAY['Composite cone','Aluminum cone','Bending stiffness','Breakup frequency','Cone treatment']::text[],ARRAY['Assuming carbon fibre has no breakup; it is just better damped.','Treating all ''carbon'' cones as identical regardless of weave and resin.','Ignoring that added resin can raise moving mass.']::text[],ARRAY['Choosing a woofer cone material for a monitor.','Comparing carbon and aluminum breakup behavior.','Explaining a woven cone''s appearance to a client.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Carbon fiber cone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9e064470-8680-437f-a668-43ed1521c2c5','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9e064470-8680-437f-a668-43ed1521c2c5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9e064470-8680-437f-a668-43ed1521c2c5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '95dff869-2d65-448a-af01-676d466353a1','Ceramic-metal composite','A diaphragm formed by bonding or growing a hard ceramic layer, often aluminum oxide, onto a metal substrate such as aluminum, producing a very stiff, hard sandwich. The ceramic raises stiffness and breakup frequency while the metal core adds toughness and constrains the layer. Examples include Accuton drivers (Thiel & Partner GmbH) and JBL''s Cerametallic cones.','This diaphragm mixes metal and ceramic. A hard ceramic skin sits on a metal core. Ceramic is very stiff. The pair moves as a clean piston up high. Hard-anodized aluminum is a common example.','To gain ceramic-level stiffness and high breakup while keeping some metal toughness.','A technician treats a hard-anodized or ceramic dome as brittle; a sharp knock can chip or crack the ceramic layer.','Diaphragm material',ARRAY['Aluminum cone','Diamond diaphragm','Beryllium diaphragm','Bending stiffness','Breakup frequency']::text[],ARRAY['Assuming a ceramic dome is unbreakable; the hard layer is brittle.','Confusing simple anodizing with a full ceramic composite.','Expecting no breakup rather than a very high, sharp one.']::text[],ARRAY['Handling an Accuton-style ceramic driver carefully.','Comparing ceramic and metal tweeter breakup.','Explaining why hard domes chip if knocked.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ceramic-metal composite');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '95dff869-2d65-448a-af01-676d466353a1','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='95dff869-2d65-448a-af01-676d466353a1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='95dff869-2d65-448a-af01-676d466353a1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '75fa8c53-6c3f-44f4-bc9c-6a75617d4b2d','Compliance modulation','The time-varying change in suspension compliance as the coil moves, so that the effective stiffness, and thus resonance, shifts within each cycle. This position-dependent modulation of Cms is a recognized source of distortion, especially near resonance.','The suspension''s springiness changes as the cone moves. It is softer at center and stiffer at the edges. So its stiffness wobbles during each cycle. That shifts the driver''s resonance. The result is added distortion.','To describe how movement-dependent stiffness changes distort the signal and modulate resonance.','A technician links audible low-frequency distortion near resonance to compliance modulation shown on a Kms(x) curve.','Suspension nonlinearity',ARRAY['Compliance nonlinearity','Compliance corner','BL(x)','Current-dependent inductance','Suspension']::text[],ARRAY['Assuming resonance is fixed regardless of drive level.','Confusing compliance modulation with thermal power compression.','Blaming the amplifier for a suspension-driven effect.']::text[],ARRAY['Explaining level-dependent resonance shifts.','Reading a Klippel Kms(x) plot.','Diagnosing low-frequency distortion.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compliance modulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '75fa8c53-6c3f-44f4-bc9c-6a75617d4b2d','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='75fa8c53-6c3f-44f4-bc9c-6a75617d4b2d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='75fa8c53-6c3f-44f4-bc9c-6a75617d4b2d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '125f0435-b982-4d3f-96cd-a14803a613ac','Compliance nonlinearity','The property that a driver''s suspension compliance Cms, or its inverse stiffness Kms, varies with displacement rather than staying constant, typically stiffening at large excursions. It is a primary mechanical source of harmonic and intermodulation distortion.','An ideal spring pushes back in proportion to travel. A real suspension does not. It gets stiffer as the cone moves far. This uneven springiness adds distortion. It is worst near the travel limits.','To capture the position-dependent stiffness that makes real suspensions distort at high excursion.','A technician expects a driver with an asymmetric Cms(x) curve to produce even-order distortion and a shifting rest position under drive.','Suspension nonlinearity',ARRAY['Compliance modulation','Compliance corner','Compliance ratio','BL(x)','Xmax']::text[],ARRAY['Treating suspension compliance as a single fixed number.','Ignoring Cms asymmetry, which offsets the coil rest position.','Confusing compliance nonlinearity with motor (BL) nonlinearity.']::text[],ARRAY['Interpreting a Cms(x) plot.','Explaining distortion that rises with level.','Comparing suspensions for linearity.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compliance nonlinearity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '125f0435-b982-4d3f-96cd-a14803a613ac','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='125f0435-b982-4d3f-96cd-a14803a613ac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='125f0435-b982-4d3f-96cd-a14803a613ac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '45914cd9-e06c-48b7-8702-7ec045e6bd0c','Compliance ratio','In sealed-box theory, the ratio (usually written alpha) of the driver''s suspension compliance to the enclosure air compliance, equal to Vas/Vb. It sets how much a given box raises the system resonance and Q above the driver''s free-air values.','This compares two springs. One is the driver''s suspension. The other is the trapped box air. Alpha is their ratio, Vas over Vb. A smaller box gives a bigger alpha. That raises the system''s resonance.','To predict how a sealed box changes a driver''s resonance and damping from its free-air values.','For Vas=50 L in a Vb=25 L sealed box, alpha = Vas/Vb = 2, and system resonance fc = fs*sqrt(1+alpha) = fs*sqrt(3).','Enclosure parameter',ARRAY['Acoustic suspension','Vas (equivalent volume)','Sealed box','Suspension compliance','Qtc']::text[],ARRAY['Swapping Vas and Vb in the ratio.','Assuming a bigger box always sounds better; alpha sets the trade-off.','Confusing compliance ratio with compliance nonlinearity.']::text[],ARRAY['Sizing a sealed box for a target resonance.','Explaining why a small box raises fc.','Reading Thiele-Small alignment tables.']::text[],'Intermediate','alpha = Vas / Vb ; fc = fs * sqrt(1 + alpha)','The compliance ratio is equivalent suspension volume divided by box volume; system resonance is free-air resonance times the square root of one plus that ratio.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compliance ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '45914cd9-e06c-48b7-8702-7ec045e6bd0c','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='45914cd9-e06c-48b7-8702-7ec045e6bd0c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='45914cd9-e06c-48b7-8702-7ec045e6bd0c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1c7674db-abf6-4e88-ae60-81382dd0e262','Composite cone','A cone built from two or more bonded materials or a sandwich structure, for example a foam or honeycomb core between stiff skins, engineered to combine high stiffness, low mass, and internal damping. The mix pushes breakup up while softening its peak versus a single-material cone.','A composite cone blends materials on purpose. It may sandwich a light core between stiff skins. This is stiff, light, and well damped. It plays clean high with less ringing. Many modern drivers use this.','To tailor stiffness, mass, and damping together, beyond what one material allows.','A technician recognizes a sandwich or layered cone as a damping strategy, allowing a somewhat higher, smoother crossover.','Diaphragm material',ARRAY['Carbon fiber cone','Aluminum cone','Cone treatment','Bending stiffness','Breakup frequency']::text[],ARRAY['Assuming a composite cone has no breakup.','Treating all layered cones as equivalent.','Ignoring bond quality, which affects long-term reliability.']::text[],ARRAY['Selecting a sandwich-cone woofer.','Explaining a honeycomb cone''s benefits.','Comparing single-material and composite cones.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Composite cone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1c7674db-abf6-4e88-ae60-81382dd0e262','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1c7674db-abf6-4e88-ae60-81382dd0e262') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1c7674db-abf6-4e88-ae60-81382dd0e262');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5e1a31bd-09cd-4901-bc0a-38be1fba33b5','Compression diaphragm','The diaphragm inside a compression driver, usually a dome or annular ring, that radiates into a small throat through a phase plug so its area greatly exceeds the throat area. This compression ratio couples the diaphragm efficiently to a horn for high sensitivity.','This is the diaphragm in a compression driver. It is much larger than the small throat opening. A phase plug guides the sound into that throat. Squeezing the air this way raises efficiency. A horn then loads it.','To couple a diaphragm to a horn through a compressed throat, giving high efficiency at high frequencies.','A technician protects a compression driver with a proper high-pass filter, since its thin diaphragm cannot survive low-frequency excursion.','Driver component',ARRAY['Phase plug','Annular diaphragm','Beryllium diaphragm','Diaphragm material','Breakup frequency']::text[],ARRAY['Sending low frequencies or a switch-on thump to a compression driver, which can tear its thin diaphragm.','Assuming the diaphragm and throat are the same size.','Forgetting the phase plug''s role in the sound path.']::text[],ARRAY['Setting a high-pass for a horn-loaded tweeter.','Replacing a blown compression-driver diaphragm.','Explaining a compression driver''s high efficiency.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compression diaphragm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5e1a31bd-09cd-4901-bc0a-38be1fba33b5','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5e1a31bd-09cd-4901-bc0a-38be1fba33b5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5e1a31bd-09cd-4901-bc0a-38be1fba33b5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '223e34a6-7746-4813-aec8-d43932ae71be','Cone treatment','A coating, doping, or impregnation applied to a paper or fibre cone to add internal damping, control breakup, and seal it against moisture. Common treatments include damping lacquers, PVA, or resin doping applied selectively to shape the cone''s response.','Cone treatment is a coating on a paper cone. It adds damping and stiffness. It can also block moisture. This tames ringing and smooths the response. Makers often paint it on by hand.','To fine-tune a cone''s damping, stiffness, and durability after it is formed.','A technician recognizes a doped or coated cone as a deliberate damping choice, not dirt, and avoids solvents that could dissolve it.','Diaphragm material',ARRAY['Composite cone','Aluminum cone','Breakup frequency','Bell mode','Bending stiffness']::text[],ARRAY['Mistaking a damping coating for dirt or a defect.','Cleaning a treated cone with solvents that dissolve it.','Assuming treatment only stiffens; it mainly adds damping.']::text[],ARRAY['Identifying a doped guitar-speaker cone.','Explaining why a cone looks painted.','Choosing a treated cone for smoother response.']::text[],'Beginner',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cone treatment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '223e34a6-7746-4813-aec8-d43932ae71be','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='223e34a6-7746-4813-aec8-d43932ae71be') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='223e34a6-7746-4813-aec8-d43932ae71be');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7bffd730-dfe8-4d6f-92be-7c05e81bc010','Current-dependent force factor','The dependence of the force factor BL on voice-coil current, written BL(i), arising because coil current modulates the flux in the gap (flux/reluctance modulation). It is one of the current-driven large-signal nonlinearities in a driver''s motor.','The motor''s strength can shift with the current itself. A large current tweaks the magnet''s field. So BL is not perfectly fixed. This adds distortion at high drive. Shorting rings reduce it.','To describe how coil current, not just position, changes motor strength, for accurate large-signal modelling.','A technician expects a motor with a copper shorting ring to show a flatter BL(i) and less current-related distortion.','Motor nonlinearity',ARRAY['BL(i)','BL(x)','Demodulation ring','Current-dependent inductance','Force factor']::text[],ARRAY['Assuming BL depends on position only.','Confusing current-dependent BL with current-dependent inductance.','Ignoring flux modulation at high power.']::text[],ARRAY['Modelling intermodulation at high power.','Explaining why shorting rings help.','Reading a large-signal motor report.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Current-dependent force factor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7bffd730-dfe8-4d6f-92be-7c05e81bc010','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7bffd730-dfe8-4d6f-92be-7c05e81bc010') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7bffd730-dfe8-4d6f-92be-7c05e81bc010');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c5341f6f-0d20-46ef-9f5e-7a5e4294cf3a','Current-dependent inductance','The variation of voice-coil inductance Le with coil current, written Le(i), caused by partial magnetic saturation of the pole structure as current rises. It is a nonlinear, lossy effect that generates distortion and interacts with the position dependence Le(x).','The voice coil''s inductance is not constant. Big currents partly saturate the iron. That lowers the inductance. The change happens within each cycle. This adds distortion, mostly at higher frequencies.','To capture how coil current changes inductance through core saturation, a source of nonlinear distortion.','A technician expects demodulation rings or copper pole sleeves to flatten Le(i) and reduce this distortion.','Motor nonlinearity',ARRAY['Current-dependent force factor','Demodulation ring','BL(i)','Asymmetric magnetic circuit','Voice coil']::text[],ARRAY['Treating voice-coil inductance as a fixed value.','Confusing Le(i) with Le(x) position dependence.','Ignoring core saturation at high power.']::text[],ARRAY['Explaining rising distortion at high frequency and power.','Justifying copper caps and rings in a motor.','Reading a nonlinear inductance measurement.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Current-dependent inductance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c5341f6f-0d20-46ef-9f5e-7a5e4294cf3a','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c5341f6f-0d20-46ef-9f5e-7a5e4294cf3a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c5341f6f-0d20-46ef-9f5e-7a5e4294cf3a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2c707ecf-bd4d-4a3d-ac2e-9714129df8be','Demagnetization','A permanent loss of a magnet''s flux, and thus of motor BL, caused by heat above the material''s limit, a strong opposing field from high coil current, or mechanical shock. AlNiCo magnets are especially prone to demagnetization from the coil''s own field.','A magnet can lose strength for good. Too much heat can do it. A strong opposing coil field can too. So can hard shocks. When it happens, the motor gets weaker and quieter.','To name the permanent weakening of a driver''s magnet and the causes to avoid.','A technician suspects partial demagnetization when an old AlNiCo driver measures low sensitivity with otherwise normal parameters.','Magnet behavior',ARRAY['Air-gap flux density','BL product','Magnetic circuit','Force factor','Pole piece']::text[],ARRAY['UNSAFE: Handling large neodymium magnet assemblies without care; they snap together with great force and can crush fingers.','Assuming ferrite and neodymium demagnetize as easily as AlNiCo.','Blaming a weak magnet for a fault that is really a rubbing coil.','Overheating a driver, which can both burn the coil and demagnetize an AlNiCo magnet.']::text[],ARRAY['Diagnosing low output in a vintage AlNiCo speaker.','Explaining heat limits for magnet materials.','Handling powerful neodymium assemblies safely.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Demagnetization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2c707ecf-bd4d-4a3d-ac2e-9714129df8be','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2c707ecf-bd4d-4a3d-ac2e-9714129df8be') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2c707ecf-bd4d-4a3d-ac2e-9714129df8be');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1f6263d-d775-4eef-9c04-7cf9f6458634','Demodulation ring','A conductive shorting ring of copper or aluminum, also called a Faraday ring, placed in the motor''s magnetic circuit to reduce modulation of the gap flux by coil current and position. It acts as a short-circuited secondary that linearizes voice-coil inductance Le(i)/Le(x) and lowers eddy-current and inductance-related distortion.','This is a metal ring inside the motor. It sits near the pole and gap. It fights changes in the magnetic field. That steadies the coil''s inductance. The result is less distortion and better high-power behavior.','To stabilize gap flux and voice-coil inductance so the motor stays more linear under current and movement.','A technician expects a driver with a copper shorting/demodulation ring to measure lower inductance-related distortion and a flatter Le(x).','Motor component',ARRAY['Current-dependent inductance','Current-dependent force factor','Asymmetric magnetic circuit','Voice coil','BL(i)']::text[],ARRAY['Confusing a demodulation ring with a dust cap or spacer.','Assuming it changes tuning; it mainly reduces distortion.','Thinking only exotic drivers use it; many quality woofers do.']::text[],ARRAY['Explaining copper rings in a motor cutaway.','Justifying a driver''s low high-frequency distortion.','Comparing motors with and without shorting rings.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Demodulation ring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1f6263d-d775-4eef-9c04-7cf9f6458634','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1f6263d-d775-4eef-9c04-7cf9f6458634') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1f6263d-d775-4eef-9c04-7cf9f6458634');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '34d9fc31-47f0-4ff7-b8c8-2b8af02a853e','Diamond diaphragm','A tweeter dome made of synthetic diamond, usually grown by chemical vapour deposition (CVD), exploiting diamond''s extreme stiffness and very high sound velocity to push breakup well above 60 to 70 kHz. It gives near-ideal pistonic behaviour across the audio band at high cost. Notable examples include the Bowers & Wilkins Diamond tweeter and Accuton diamond drivers.','This tweeter dome is made of lab-grown diamond. Diamond is the stiffest common material. So the dome stays a clean piston very high up. Its ringing sits above hearing. It is very expensive to make.','To place diaphragm breakup far above the audio band for extended, low-distortion high frequencies.','A technician handles a diamond dome as fragile; despite its hardness, a knock can shatter the thin shell.','Diaphragm material',ARRAY['Beryllium diaphragm','Ceramic-metal composite','Aluminum cone','Breakup frequency','Bending stiffness']::text[],ARRAY['Assuming ''diamond hard'' means unbreakable; the thin dome is brittle.','Thinking the benefit is loudness rather than very high breakup.','Confusing a diamond-coated dome with a solid CVD diamond dome.']::text[],ARRAY['Servicing a high-end diamond-tweeter loudspeaker.','Explaining ultrasonic breakup of a diamond dome.','Comparing diamond, beryllium, and ceramic tweeters.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diamond diaphragm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '34d9fc31-47f0-4ff7-b8c8-2b8af02a853e','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='34d9fc31-47f0-4ff7-b8c8-2b8af02a853e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='34d9fc31-47f0-4ff7-b8c8-2b8af02a853e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1a54db31-af02-4fe0-8f05-ae041b92fd28','Diamond-like carbon coating','A thin, hard amorphous-carbon film applied to a driver diaphragm or dome, containing a high fraction of diamond-like (sp3) carbon bonds. It raises the surface stiffness-to-mass ratio, pushing the diaphragm''s first break-up resonance higher in frequency without adding much mass.','This is a very hard, thin carbon layer sprayed onto a speaker dome or cone. It makes the surface much stiffer but stays light. A stiffer, light diaphragm stays smooth to a higher pitch. That keeps the sound clean at high frequencies.','It stiffens a diaphragm so it moves as one piece over a wider band, delaying the ragged break-up that colours high-frequency response.','A technician selecting a tweeter may choose a diamond-coated dome to push break-up above the audio band, giving a smoother top octave than an untreated aluminium dome.','Diaphragm materials',ARRAY['Dome','Fabric dome','Flexural rigidity','Diaphragm piston region','Diaphragm anisotropy']::text[],ARRAY['Assuming the coating alone makes a tweeter better, ignoring the whole motor and suspension.','Confusing a diamond-like carbon film with a solid diamond diaphragm.','Thinking the coating lowers moving mass; it mainly raises stiffness.']::text[],ARRAY['Comparing tweeter dome materials for a smooth high-frequency response.','Explaining why a coated dome resists break-up better than plain metal.','Reading a driver datasheet that lists a hard carbon diaphragm coating.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diamond-like carbon coating');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1a54db31-af02-4fe0-8f05-ae041b92fd28','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1a54db31-af02-4fe0-8f05-ae041b92fd28') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1a54db31-af02-4fe0-8f05-ae041b92fd28');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a4a288ca-96bf-4ac3-ada8-c59badc57a2d','Diaphragm anisotropy','The condition where a diaphragm''s mechanical properties, chiefly stiffness, differ with direction because of its material or construction, such as a woven or fibre-reinforced cone. This directional variation shapes how and where break-up modes form across the surface.','Some cones are stiffer in one direction than another. This uneven stiffness is called anisotropy. It changes where the cone starts to flex and ring. Woven and fibre cones often behave this way on purpose.','It lets designers steer or spread break-up resonances by choosing materials whose stiffness varies by direction, smoothing the response.','A technician comparing a woven-glass cone to an isotropic paper cone notes the woven cone spreads its break-up over a wider, gentler band rather than one sharp peak.','Diaphragm materials',ARRAY['Diaphragm piston region','Flexural rigidity','Diamond-like carbon coating','Fabric dome','Diaphragm mass']::text[],ARRAY['Assuming every cone material behaves the same in all directions.','Treating a directional-stiffness cone as if it had one single break-up frequency.','Confusing material anisotropy with a manufacturing defect.']::text[],ARRAY['Choosing a woven cone to soften a harsh break-up peak.','Explaining why fibre cones show broad rather than sharp resonances.','Modelling cone break-up in finite-element software.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diaphragm anisotropy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a4a288ca-96bf-4ac3-ada8-c59badc57a2d','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a4a288ca-96bf-4ac3-ada8-c59badc57a2d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a4a288ca-96bf-4ac3-ada8-c59badc57a2d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7b7d1759-7db2-409a-b0c3-33a894f99f97','Diaphragm mass','The total moving mass of a driver''s diaphragm assembly, comprising the mechanical parts (cone or dome, voice coil, former and part of the surround) plus the air-load mass the diaphragm drags on both faces. In Thiele-Small notation the total is Mms and the purely mechanical part is Mmd.','This is how much the moving parts of a speaker weigh. It includes the cone, the voice coil, and some air pushed along. More moving mass lowers the driver''s resonance. It also lowers sensitivity.','It sets, with suspension compliance, the driver''s resonance frequency and strongly affects sensitivity and how easily the cone starts and stops.','For a mechanical mass Mmd of 12 g and an air-load mass of about 1.5 g, the total moving mass Mms is roughly 13.5 g; this feeds directly into the resonance formula fs = 1/(2*pi*sqrt(Mms*Cms)).','Driver parameters',ARRAY['Effective radiating area','Equivalent compliance volume','Diaphragm piston region','Diaphragm anisotropy','Displacement limit']::text[],ARRAY['Forgetting the air-load mass and using only the mechanical mass Mmd.','Assuming heavier cones are always worse, ignoring the design goal.','Confusing moving mass with the driver''s total weight including the magnet.']::text[],ARRAY['Estimating a driver''s resonance from its parameters.','Explaining why a low-sensitivity woofer often has high moving mass.','Comparing two woofers with similar size but different mass.']::text[],'Intermediate','Mms = Mmd + Mmr','Total moving mass equals the diaphragm assembly''s own mass plus the air-load mass on both faces.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diaphragm mass');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7b7d1759-7db2-409a-b0c3-33a894f99f97','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7b7d1759-7db2-409a-b0c3-33a894f99f97') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7b7d1759-7db2-409a-b0c3-33a894f99f97');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ca75503-b69b-4f08-bead-8da2160f7b40','Diaphragm piston region','The frequency band in which the diaphragm moves back and forth as a single rigid body, so every point on it moves in phase and with equal amplitude. It extends from the driver''s low end up to the first break-up (modal) frequency, above which parts of the diaphragm start to flex independently.','At low and middle pitches the cone moves as one solid piece. Every part moves together, in and out. This band is the piston region. Above it the cone starts to bend and ring instead.','It marks the range where a driver behaves predictably and radiates cleanly, which designers try to keep wide enough to cover the driver''s job.','A technician sets a woofer''s crossover below its first break-up so it works only in its pistonic band, avoiding the peaks and dips of cone flexing.','Diaphragm behavior',ARRAY['Diaphragm anisotropy','Flexural rigidity','Diaphragm mass','Effective radiating area','Diamond-like carbon coating']::text[],ARRAY['Assuming a cone stays pistonic across its whole usable range.','Ignoring that break-up ends the piston region and adds colouration.','Confusing the piston region with the flat part of the response curve.']::text[],ARRAY['Choosing a crossover point below cone break-up.','Explaining why small drivers stay pistonic higher than large ones.','Reading a response curve to spot where pistonic behaviour ends.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diaphragm piston region');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ca75503-b69b-4f08-bead-8da2160f7b40','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ca75503-b69b-4f08-bead-8da2160f7b40') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ca75503-b69b-4f08-bead-8da2160f7b40');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bc51f51e-28a1-4db3-b7de-ad69349fe3ff','Diaphragm rocking','A parasitic motion in which the voice coil and diaphragm tilt or wobble instead of moving straight along the driver axis, also called a rocking or ''rock-and-roll'' mode. Suspension asymmetry, uneven glue joints or an off-centre coil can trigger it, leading to coil rub against the pole piece and added distortion.','Ideally the coil and cone move straight in and out. Sometimes they tilt and wobble side to side instead. This wobble is called rocking. It can make the coil scrape the magnet gap and buzz.','Naming this fault helps technicians spot and cure a common cause of voice-coil rub, buzzing and premature wear in drivers.','When a woofer buzzes only at high excursion, a technician suspects a rocking mode and checks for an off-centre coil or an uneven spider before condemning the driver.','Failure modes',ARRAY['Dynamic voice-coil position','Displacement limit','Diaphragm mass','Equal-hung voice coil','Fatigue life']::text[],ARRAY['Blaming the amplifier for a buzz that is actually coil rub from rocking.','Assuming all diaphragm motion is perfectly axial.','Overlooking uneven spider or surround as the cause of tilt.']::text[],ARRAY['Diagnosing a buzz that appears only at high volume.','Inspecting a driver for an off-centre or rubbing voice coil.','Explaining rocking modes when teaching driver assembly quality.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diaphragm rocking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bc51f51e-28a1-4db3-b7de-ad69349fe3ff','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bc51f51e-28a1-4db3-b7de-ad69349fe3ff') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bc51f51e-28a1-4db3-b7de-ad69349fe3ff');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '14ae8299-611b-49e4-aa22-6376d40f8b33','Differential-drive motor','A dual-coil, dual-gap loudspeaker motor in which two in-line voice coils sit in two separate, oppositely polarised magnetic gaps, marketed by JBL Professional as Differential Drive. ''Differential Drive'' is a JBL Professional (Harman International) trademark and patented design; the underlying method is a generic dual-gap, dual-coil electrodynamic motor.','This motor uses two voice coils in two magnet gaps instead of one. JBL Professional calls its version Differential Drive. The design cuts weight and spreads out heat. It also lowers distortion from the coil.','It aims to cut moving and magnet weight, spread heat over more surface, and reduce coil inductance and flux modulation compared with a single-gap motor.','A technician servicing a JBL professional woofer recognises the two in-line coils and dual gaps as Differential Drive, and orders the matching factory recone rather than a generic single-coil kit.','Motor topology',ARRAY['Dual-gap motor','Electrodynamic motor','Flux modulation','Faraday ring','Ferrite magnet']::text[],ARRAY['Treating ''Differential Drive'' as a generic term instead of a JBL trademark.','Assuming any dual-coil driver uses this specific dual-gap layout.','Fitting a single-coil recone kit to a dual-gap motor.']::text[],ARRAY['Servicing or reconing a JBL professional low-frequency driver.','Explaining why a neodymium motor weighs far less than a ferrite one.','Comparing motor topologies when specifying a subwoofer driver.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Differential-drive motor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '14ae8299-611b-49e4-aa22-6376d40f8b33','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='14ae8299-611b-49e4-aa22-6376d40f8b33') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='14ae8299-611b-49e4-aa22-6376d40f8b33');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '840b3e57-994c-44aa-a437-e10c805193fa','Dipole cancellation','The progressive loss of low-frequency output in an unbaffled or open-baffle (dipole) source, caused by the out-of-phase rear radiation wrapping around to meet and partly cancel the front radiation. Below the first response peak the output falls at about 6 dB per octave as wavelength grows relative to the front-to-back path.','An open speaker radiates from front and back in opposite phase. At low pitches the back sound wraps around and cancels the front. This is dipole cancellation. It makes bass drop off steadily as the pitch falls.','It explains why open-baffle and dipole loudspeakers naturally lose bass, so designers plan equalisation or a large baffle to compensate.','A technician setting up an open-baffle woofer applies low-shelf boost to offset the 6 dB-per-octave dipole roll-off and restore usable bass.','Radiation behavior',ARRAY['Dipole null','Dipole peak','Effective radiating area','Displacement-limited output','Diaphragm mass']::text[],ARRAY['Expecting an open baffle to give the same bass as a sealed box.','Confusing the smooth dipole roll-off with a sharp cancellation null.','Forgetting that a bigger baffle shifts cancellation lower in frequency.']::text[],ARRAY['Equalising an open-baffle or dipole loudspeaker.','Explaining weak bass from a driver used without an enclosure.','Choosing baffle size to control low-frequency cancellation.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dipole cancellation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '840b3e57-994c-44aa-a437-e10c805193fa','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='840b3e57-994c-44aa-a437-e10c805193fa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='840b3e57-994c-44aa-a437-e10c805193fa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd3fcd740-38de-4841-bf07-d07474048603','Dipole null','A deep cancellation in a dipole source''s on-axis response occurring where the front-to-back acoustic path difference equals one full wavelength, so the front and out-of-phase rear waves cancel. For an effective source separation D the first on-axis null falls at the frequency where the wavelength equals D.','A dipole has opposite-phase front and back sound. At one certain pitch they cancel almost completely on axis. This deep dip is the dipole null. It sits where the front-to-back distance equals one wavelength.','It marks the frequency where a dipole nearly stops radiating on axis, which designers must keep above the driver''s working band.','For an effective front-to-back separation D of 0.3 m and sound speed c of 343 m/s, the first on-axis null lands near f = c/D = 343/0.3 = about 1143 Hz.','Radiation behavior',ARRAY['Dipole peak','Dipole cancellation','Effective radiating area','Displacement-limited output','Dome']::text[],ARRAY['Confusing the dipole null with the gentler broadband dipole roll-off.','Using cabinet width instead of the effective acoustic path for D.','Placing the driver''s passband across the null frequency.']::text[],ARRAY['Designing an open baffle so its null sits above the crossover.','Explaining a deep on-axis dip in a dipole''s measured response.','Choosing baffle dimensions to move the null out of band.']::text[],'Advanced','f_null = c / D','The first on-axis dipole null frequency equals the speed of sound divided by the effective front-to-back path separation.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dipole null');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd3fcd740-38de-4841-bf07-d07474048603','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d3fcd740-38de-4841-bf07-d07474048603') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d3fcd740-38de-4841-bf07-d07474048603');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5facf021-fa71-4d10-9340-23c2b2e3dab9','Dipole peak','The first response maximum of a dipole source on axis, occurring where the front-to-back acoustic path difference equals half a wavelength so the front and rear radiation add. For an effective source separation D the peak falls at the frequency where half a wavelength equals D.','A dipole radiates front and back in opposite phase. At one pitch the back wave lines up and adds to the front. This gives a response bump called the dipole peak. Below it the bass rolls off.','It marks the top of a dipole''s natural rising response, above which the output flattens and then breaks into peaks and nulls.','For an effective separation D of 0.3 m and sound speed c of 343 m/s, the first dipole peak sits near f = c/(2*D) = 343/0.6 = about 572 Hz, one octave below the first null.','Radiation behavior',ARRAY['Dipole null','Dipole cancellation','Effective radiating area','Diaphragm mass','Dome']::text[],ARRAY['Mistaking the dipole peak for a driver resonance or box tuning.','Assuming the peak and null fall at the same frequency.','Ignoring that baffle size sets where the peak occurs.']::text[],ARRAY['Interpreting the rising low end of a measured dipole response.','Placing crossover and peak so the response stays smooth.','Explaining open-baffle behaviour to a trainee.']::text[],'Advanced','f_peak = c / (2*D)','The first on-axis dipole peak frequency equals the speed of sound divided by twice the effective front-to-back path separation.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dipole peak');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5facf021-fa71-4d10-9340-23c2b2e3dab9','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5facf021-fa71-4d10-9340-23c2b2e3dab9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5facf021-fa71-4d10-9340-23c2b2e3dab9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c07d5998-195d-4642-86da-b7ac779894a3','Displacement limit','The maximum linear peak excursion of a driver''s diaphragm, usually denoted Xmax, over which force factor and suspension stay reasonably constant before distortion rises sharply. A common geometric estimate is half the difference between the voice-coil winding height and the magnetic gap height.','A cone can only move so far in and out cleanly. That limit is called Xmax. Push past it and the sound distorts fast. It is set mainly by the coil and magnet gap sizes.','It defines how far a driver can move linearly, setting a ceiling on clean low-frequency output and guiding safe drive levels.','For a voice-coil winding height of 14 mm in a 6 mm magnetic gap, the geometric Xmax is (14 - 6)/2 = 4 mm of peak one-way excursion.','Driver parameters',ARRAY['Displacement-limited output','Equal-hung voice coil','Effective radiating area','Diaphragm rocking','Flux density distribution']::text[],ARRAY['Treating the geometric estimate as the exact distortion-limited excursion.','Confusing Xmax (linear) with Xmech, the mechanical damage limit.','Assuming a bigger cone always has more excursion capability.']::text[],ARRAY['Comparing woofers for how loud they can play clean bass.','Setting amplifier limits to keep a driver within Xmax.','Reading a datasheet''s excursion and gap specifications.']::text[],'Intermediate','Xmax = (Hvc - Hgap) / 2','Linear peak excursion equals the voice-coil winding height minus the gap height, divided by two.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Displacement limit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c07d5998-195d-4642-86da-b7ac779894a3','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c07d5998-195d-4642-86da-b7ac779894a3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c07d5998-195d-4642-86da-b7ac779894a3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fd270131-0c2a-4ff0-8976-4926425b1f26','Displacement-limited output','The maximum acoustic output a driver can produce at low frequencies before its diaphragm reaches its linear excursion limit, rather than before it runs out of thermal or amplifier power. The peak volume displacement, cone area times peak excursion, sets this ceiling, and required excursion rises 12 dB per octave as frequency falls.','At low pitches a speaker''s loudness is capped by how far the cone can move. Once it hits its travel limit, it cannot get louder cleanly. This is displacement-limited output. It falls fast as the pitch drops.','It explains why deep-bass output is limited by cone travel and area, guiding driver and enclosure choices for a target loudness.','A driver with cone area Sd of 0.02 m^2 and Xmax of 4 mm has a peak volume displacement Vd = Sd*Xmax = 0.02 * 0.004 = 8e-5 m^3, about 80 cm^3, which fixes its clean deep-bass ceiling.','Driver performance',ARRAY['Displacement limit','Effective radiating area','Diaphragm mass','Dipole cancellation','Equivalent compliance volume']::text[],ARRAY['Assuming more amplifier power alone can raise deep-bass output past the excursion limit.','Confusing displacement-limited output with thermal power limits.','UNSAFE: Standing close to a high-output driver at sustained high SPL without hearing protection can cause permanent hearing loss.']::text[],ARRAY['Predicting a subwoofer''s clean maximum level at 30 Hz.','Choosing between more cone area or more excursion for bass.','Explaining why small woofers cannot play loud deep bass.']::text[],'Advanced','Vd = Sd * Xmax','Peak volume displacement equals effective cone area times linear peak excursion.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Displacement-limited output');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fd270131-0c2a-4ff0-8976-4926425b1f26','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fd270131-0c2a-4ff0-8976-4926425b1f26') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fd270131-0c2a-4ff0-8976-4926425b1f26');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d248a96-1a0c-4af4-9eca-8f28759d5134','Dome','A convex (or occasionally concave) diaphragm shape used mainly in tweeters and some midranges, driven at its rim by a voice coil bonded to the dome''s edge. The curved form is inherently rigid for its mass, helping it stay pistonic to high frequencies before break-up.','A dome is a small curved diaphragm, common in tweeters. The voice coil drives it around its outer edge. The curved shape stays stiff for its weight. That helps it work cleanly up to high pitches.','It provides a light, rigid radiator for high frequencies with wide dispersion, driven efficiently at its edge by the voice coil.','A technician replacing a blown tweeter matches the dome diameter and material, since a 25 mm fabric dome and a 25 mm metal dome disperse and break up differently.','Diaphragm types',ARRAY['Fabric dome','Diamond-like carbon coating','Diaphragm piston region','Flexural rigidity','Effective radiating diameter']::text[],ARRAY['Assuming all domes are interchangeable regardless of material or size.','Confusing a dome tweeter with a cone tweeter.','Ignoring that dome material sets the top-octave character.']::text[],ARRAY['Selecting a replacement tweeter dome.','Comparing metal, fabric and coated dome behaviour.','Explaining edge-driven versus centre-driven diaphragms.']::text[],'Beginner',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dome');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d248a96-1a0c-4af4-9eca-8f28759d5134','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d248a96-1a0c-4af4-9eca-8f28759d5134') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d248a96-1a0c-4af4-9eca-8f28759d5134');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '79fd3866-c85d-412c-aa64-01e5aec40d46','Dual-gap motor','A loudspeaker motor built with two magnetic gaps stacked along the axis, typically carrying two voice coils, so the drive force is shared between two gap-and-coil pairs. The layout can shorten each coil, spread heat, and reduce inductance and flux modulation compared with a single deep gap.','This motor has two magnet gaps instead of one. It usually holds two voice coils, one in each gap. Splitting the job spreads heat and lowers distortion. JBL''s Differential Drive is one example.','It splits the motor into two gaps to improve heat handling, cut inductance-related distortion, and allow lighter neodymium magnet structures.','A technician identifies a dual-gap motor by its two coil leads per side and stacked gaps, then follows the maker''s service data for the correct recone and coil wiring.','Motor topology',ARRAY['Differential-drive motor','Electrodynamic motor','Flux modulation','Faraday ring','Ferrite magnet']::text[],ARRAY['Confusing a dual-gap motor with a simple dual-voice-coil single-gap woofer.','Miswiring the two coils in series or parallel.','Assuming every neodymium driver uses a dual-gap layout.']::text[],ARRAY['Servicing a professional driver with two magnetic gaps.','Explaining how dual gaps improve heat dissipation.','Comparing motor designs for a lightweight touring cabinet.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dual-gap motor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '79fd3866-c85d-412c-aa64-01e5aec40d46','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='79fd3866-c85d-412c-aa64-01e5aec40d46') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='79fd3866-c85d-412c-aa64-01e5aec40d46');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4847f344-0ada-44fc-80ee-aa5135952b7e','Dynamic DC displacement','A large-signal effect in which a driver''s mean diaphragm rest position shifts away from centre while a symmetrical signal is applied, driven by asymmetries in force factor Bl(x), stiffness Kms(x) or inductance Le(x). The coil settles at a new average position, usually moving progressively toward one side as level rises.','Under a loud signal, a cone''s average resting spot can drift off centre. Uneven motor and suspension forces cause this drift. It is called dynamic DC displacement. It can push the coil toward its limit.','Recognising this drift helps explain why some drivers creep toward their excursion limits and distort or jam under heavy low-frequency drive.','A technician using large-signal measurement watches the DC displacement curve; a strong outward drift warns that the motor''s Bl asymmetry may cause the coil to bottom or jump out at high level.','Nonlinear behavior',ARRAY['Dynamic voice-coil position','Displacement limit','Flux density distribution','Diaphragm rocking','Equal-hung voice coil']::text[],ARRAY['Assuming a symmetrical drive signal always keeps the cone centred.','Confusing this signal-induced drift with a simple manufacturing offset.','Ignoring DC displacement when judging a driver''s safe excursion.']::text[],ARRAY['Interpreting large-signal driver measurements.','Explaining why a woofer creeps outward under heavy bass.','Diagnosing coil bottoming that only appears at high level.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic DC displacement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4847f344-0ada-44fc-80ee-aa5135952b7e','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4847f344-0ada-44fc-80ee-aa5135952b7e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4847f344-0ada-44fc-80ee-aa5135952b7e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '31abc1f1-9569-43c1-9c6c-c38df0075c4a','Dynamic voice-coil position','The instantaneous position of the voice coil within the magnetic gap as the driver operates, tracked over time in large-signal analysis. Monitoring it reveals how far the coil moves each way and whether its average position drifts, exposing nonlinear symmetry problems.','This is where the voice coil sits in the gap moment to moment as it plays. Engineers track it during loud tests. It shows how far the coil swings each way. It also shows any drift off centre.','Tracking coil position over time lets engineers see excursion, asymmetry and drift that a simple resonance measurement cannot reveal.','In a large-signal test a technician reads the coil''s position trace to confirm peak excursion stays within Xmax and that the coil is not drifting toward the gap edge.','Nonlinear behavior',ARRAY['Dynamic DC displacement','Displacement limit','Flux density distribution','Equal-hung voice coil','Diaphragm rocking']::text[],ARRAY['Confusing instantaneous coil position with the fixed rest position.','Assuming peak excursion alone tells the whole story without symmetry.','Ignoring coil drift toward the gap edge under heavy drive.']::text[],ARRAY['Running a large-signal excursion test on a woofer.','Verifying a driver stays within its linear range.','Diagnosing asymmetric motion in a distorting driver.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic voice-coil position');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '31abc1f1-9569-43c1-9c6c-c38df0075c4a','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='31abc1f1-9569-43c1-9c6c-c38df0075c4a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='31abc1f1-9569-43c1-9c6c-c38df0075c4a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1a0cad7-ed43-4dac-8cbb-c591313e31ee','Eddy current','Circulating electrical currents induced in a conductor, such as the steel pole piece and top plate of a driver motor, by the changing magnetic field of the moving voice coil. These currents dissipate energy as heat and, in a motor, contribute to a frequency-dependent voice-coil impedance and losses.','A changing magnetic field stirs up loops of current in nearby metal. These loops are eddy currents. In a speaker motor they form in the steel parts. They waste some energy as heat and change the coil''s impedance.','Understanding eddy currents explains part of a driver''s rising impedance with frequency and the losses that shorting rings are added to control.','A technician noting a driver''s voice-coil inductance falling with frequency recognises eddy-current losses in the steel, which a copper or aluminium shorting ring is fitted to reduce.','Motor electromagnetics',ARRAY['Eddy-current brake','Faraday ring','Flux modulation','Electrodynamic motor','Flux density distribution']::text[],ARRAY['Confusing eddy currents with the useful current in the voice coil.','Ignoring eddy-current losses when modelling voice-coil impedance.','Assuming a laminated or ring-shielded pole behaves like solid steel.']::text[],ARRAY['Explaining why voice-coil inductance is frequency dependent.','Understanding why shorting rings are added to a motor.','Modelling losses in a driver''s magnetic circuit.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Eddy current');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1a0cad7-ed43-4dac-8cbb-c591313e31ee','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1a0cad7-ed43-4dac-8cbb-c591313e31ee') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1a0cad7-ed43-4dac-8cbb-c591313e31ee');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '88bc8c2f-ba0d-4435-8a9e-43992a8d335e','Eddy-current brake','A damping effect (or deliberate mechanism) in which eddy currents induced in a conductor moving through a magnetic field create a force opposing that motion. In a loudspeaker context, conductive rings and structures interact with the field so that eddy currents add motional damping and shape the motor''s behaviour.','When metal moves through a magnetic field, induced currents push back against the motion. This drag is an eddy-current brake. It always opposes movement, never helps it. In motors it adds a little damping.','It describes how induced currents resist relative motion, a principle used for damping and braking and present as a loss mechanism in driver motors.','A technician explaining why a conductive sleeve adds damping notes that motion through the gap induces eddy currents whose force opposes the movement, like a contactless brake.','Motor electromagnetics',ARRAY['Eddy current','Faraday ring','Flux modulation','Electrodynamic motor','Flux density distribution']::text[],ARRAY['Thinking an eddy-current brake can ever assist rather than oppose motion.','Confusing eddy-current damping with mechanical friction.','Assuming the braking force is constant regardless of speed.']::text[],ARRAY['Explaining contactless damping from a conductive structure.','Understanding losses that oppose voice-coil motion.','Teaching the principle behind eddy-current damping.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Eddy-current brake');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '88bc8c2f-ba0d-4435-8a9e-43992a8d335e','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='88bc8c2f-ba0d-4435-8a9e-43992a8d335e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='88bc8c2f-ba0d-4435-8a9e-43992a8d335e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '47714f8d-b46e-4d47-8f5a-2aab34616f58','Effective radiating area','The equivalent piston area of a driver diaphragm that actually couples to the air, denoted Sd in Thiele-Small parameters. It is taken from the effective radiating diameter, measured to roughly the middle of the surround, not the full outer edge of the cone.','A cone does not push air right out to its rim. The area that really moves air is the effective radiating area, Sd. It is found from a diameter measured to about the middle of the surround. It is a bit smaller than the full cone.','It quantifies how much air a driver moves, feeding output, efficiency and enclosure-tuning calculations.','For an effective radiating diameter of 0.13 m, Sd = pi*(0.13/2)^2 = pi*(0.065)^2 = about 0.0133 m^2, roughly 133 cm^2.','Driver parameters',ARRAY['Effective radiating diameter','Diaphragm mass','Displacement-limited output','Equivalent compliance volume','Diaphragm piston region']::text[],ARRAY['Using the full cone outer diameter instead of the mid-surround diameter.','Confusing Sd with the nominal driver size like ''12 inch''.','Forgetting Sd is an equivalent piston area, not the exact cone area.']::text[],ARRAY['Calculating a driver''s volume displacement.','Comparing air-moving ability of similar-sized drivers.','Feeding Sd into enclosure design software.']::text[],'Intermediate','Sd = pi * (d_eff / 2)^2','Effective radiating area equals pi times the square of half the effective radiating diameter.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Effective radiating area');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '47714f8d-b46e-4d47-8f5a-2aab34616f58','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='47714f8d-b46e-4d47-8f5a-2aab34616f58') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='47714f8d-b46e-4d47-8f5a-2aab34616f58');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '856b4b0f-5a10-4428-a1b6-dd8b74e493cd','Effective radiating diameter','The equivalent piston diameter used to compute a driver''s effective radiating area, taken across the diaphragm to approximately the middle of the surround. It is derived from, or defines, Sd and is smaller than the nominal frame size.','This is the working diameter of a driver''s moving area. It is measured to about the middle of the surround. It is smaller than the outside of the frame. It sets the effective radiating area, Sd.','It gives a single diameter figure that fixes the effective radiating area used in loudspeaker calculations.','From an effective radiating area Sd of 0.0133 m^2, the effective diameter is d_eff = 2*sqrt(Sd/pi) = 2*sqrt(0.0133/3.1416) = about 0.130 m.','Driver parameters',ARRAY['Effective radiating area','Diaphragm mass','Dome','Diaphragm piston region','Displacement-limited output']::text[],ARRAY['Reading the effective diameter as the nominal frame or basket size.','Measuring to the cone edge rather than mid-surround.','Confusing diameter with the advertised driver size in inches.']::text[],ARRAY['Deriving Sd for a driver from a physical measurement.','Comparing true radiating size across drivers.','Checking a datasheet''s stated effective diameter.']::text[],'Intermediate','d_eff = 2 * sqrt(Sd / pi)','Effective radiating diameter equals two times the square root of effective radiating area divided by pi.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Effective radiating diameter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '856b4b0f-5a10-4428-a1b6-dd8b74e493cd','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='856b4b0f-5a10-4428-a1b6-dd8b74e493cd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='856b4b0f-5a10-4428-a1b6-dd8b74e493cd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4a99facc-db8f-4c82-bc26-75e02db96f69','Electrodynamic motor','The moving-coil drive system of a conventional loudspeaker, in which current through a voice coil sitting in a fixed radial magnetic field produces an axial force on the diaphragm. The force equals the product of the gap flux density, coil conductor length in the field and the current, summarised as the force factor Bl times current.','This is the usual speaker motor. Current flows through a coil sitting in a magnet''s field. That produces a push on the cone. The push equals the motor strength Bl times the current.','It converts electrical current into diaphragm motion, the basic mechanism of nearly all cone and dome loudspeakers.','For a force factor Bl of 9 T*m and a coil current of 3 A, the motor force is F = Bl*i = 9 * 3 = 27 N driving the cone.','Motor topology',ARRAY['Differential-drive motor','Dual-gap motor','Ferrite magnet','Flux density distribution','Faraday ring']::text[],ARRAY['Confusing the electrodynamic (moving-coil) motor with electrostatic drive.','Forgetting force depends on flux density, coil length and current together.','UNSAFE: A driver''s assembled magnet is strong; keep fingers, tools and magnetic media clear to avoid pinch injuries and data loss.']::text[],ARRAY['Explaining how a cone loudspeaker makes sound.','Estimating drive force from motor parameters.','Comparing moving-coil motors with other transducer types.']::text[],'Beginner','F = Bl * i','The motor force equals the force factor (gap flux density times coil length in the field) times the coil current.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electrodynamic motor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4a99facc-db8f-4c82-bc26-75e02db96f69','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4a99facc-db8f-4c82-bc26-75e02db96f69') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4a99facc-db8f-4c82-bc26-75e02db96f69');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '482e96f4-d67d-4ae2-b2bb-65d79f1da6a5','Enclosed-air stiffness','The restoring stiffness that the trapped air in a sealed enclosure adds to a driver''s moving system as the cone compresses and rarefies it. Referred to the cone, this air stiffness equals air density times sound-speed squared times cone area squared divided by the box volume, and it raises system resonance above the driver''s free-air value.','Air sealed in a box acts like a spring behind the cone. Pushing in squeezes it and it pushes back. This is enclosed-air stiffness. A smaller box gives a stiffer spring and higher resonance.','It explains how box volume adds a spring to the driver, raising system resonance and controlling low-frequency alignment in sealed enclosures.','For a box volume of 0.02 m^3, cone area Sd of 0.0133 m^2 and air constant rho0*c^2 of about 1.4e5 Pa, the air stiffness is K = 1.4e5 * (0.0133)^2 / 0.02 = about 1240 N/m.','Enclosure design',ARRAY['Equivalent compliance volume','Effective radiating area','Diaphragm mass','Displacement-limited output','Diaphragm piston region']::text[],ARRAY['Forgetting that a smaller box stiffens the air and raises resonance.','Ignoring cone area, which enters as a square in the stiffness.','Confusing air stiffness with the driver''s own suspension stiffness.']::text[],ARRAY['Predicting how box size shifts a sealed system''s resonance.','Comparing sealed-box alignments for a given driver.','Explaining why tiny boxes give high, well-damped resonance.']::text[],'Advanced','K_box = rho0 * c^2 * Sd^2 / Vb','The enclosed-air stiffness at the cone equals air density times sound speed squared times cone area squared, divided by box volume.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Enclosed-air stiffness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '482e96f4-d67d-4ae2-b2bb-65d79f1da6a5','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='482e96f4-d67d-4ae2-b2bb-65d79f1da6a5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='482e96f4-d67d-4ae2-b2bb-65d79f1da6a5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '59ab8e4a-e52d-490e-bb11-53ae7dc9ed63','Equal-hung voice coil','A voice-coil-and-gap geometry in which the winding height equals the magnetic gap height, so the coil fully fills the gap at rest. It is the boundary case between an overhung coil (winding taller than the gap) and an underhung coil (winding shorter than the gap).','Here the voice coil is exactly as tall as the magnet gap. It just fills the gap when the cone is at rest. This is the equal-hung case. It sits between overhung and underhung designs.','Naming this geometry helps technicians classify a motor''s linearity trade-offs, since coil-versus-gap height sets excursion and force-factor behaviour.','A technician reading a motor spec where coil height equals gap height recognises an equal-hung design, expecting force factor to fall off as soon as the coil moves either way.','Motor topology',ARRAY['Displacement limit','Flux density distribution','Dynamic voice-coil position','Electrodynamic motor','Flux modulation']::text[],ARRAY['Confusing equal-hung with overhung or underhung geometries.','Assuming equal-hung gives the most linear excursion of the three.','Ignoring that force factor drops as soon as an equal-hung coil moves.']::text[],ARRAY['Classifying a driver''s motor geometry from its specs.','Comparing overhung, underhung and equal-hung linearity.','Explaining force-factor roll-off with coil position.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equal-hung voice coil');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '59ab8e4a-e52d-490e-bb11-53ae7dc9ed63','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='59ab8e4a-e52d-490e-bb11-53ae7dc9ed63') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='59ab8e4a-e52d-490e-bb11-53ae7dc9ed63');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1a6931c2-75bd-4451-a090-b69ca5df21e9','Equivalent compliance volume','A Thiele-Small parameter, Vas, equal to the volume of air whose acoustic stiffness matches the driver''s own suspension compliance. It equals air density times sound-speed squared times cone area squared times mechanical compliance, and expresses suspension springiness as an equivalent air volume.','Vas is the box of air that would spring back just like the driver''s suspension. A loose, springy suspension gives a large Vas. A stiff one gives a small Vas. It helps set the right box size.','It restates a driver''s suspension compliance as an air volume, letting designers choose enclosure size for a target alignment.','For rho0*c^2 of about 1.4e5 Pa, Sd of 0.0133 m^2 and mechanical compliance Cms of 1.0e-3 m/N, Vas = 1.4e5 * (0.0133)^2 * 1.0e-3 = about 0.0248 m^3, roughly 25 litres.','Driver parameters',ARRAY['Enclosed-air stiffness','Effective radiating area','Diaphragm mass','Displacement-limited output','Diaphragm piston region']::text[],ARRAY['Treating Vas as the recommended box volume rather than a compliance measure.','Forgetting cone area enters squared, so it dominates Vas.','Confusing a large Vas (soft suspension) with a large required box always.']::text[],ARRAY['Choosing an enclosure volume for a given driver.','Comparing suspension springiness across drivers.','Feeding Vas into sealed or vented alignment tables.']::text[],'Intermediate','Vas = rho0 * c^2 * Sd^2 * Cms','Equivalent compliance volume equals air density times sound speed squared times cone area squared times suspension compliance.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equivalent compliance volume');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1a6931c2-75bd-4451-a090-b69ca5df21e9','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1a6931c2-75bd-4451-a090-b69ca5df21e9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1a6931c2-75bd-4451-a090-b69ca5df21e9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '60fa829b-37c3-42ba-8e48-652bf2a6853a','Fabric dome','A soft-dome diaphragm woven from textile such as silk, polyester or coated fabric, then treated with a damping coating and formed into a dome, used mainly in tweeters. Its internal damping tends to smooth break-up so resonances appear as gentle, well-controlled features rather than sharp metallic peaks.','This is a tweeter dome made of treated woven cloth. The cloth is soft and self-damping. It breaks up gently instead of ringing sharply. Many people call the result smooth or warm.','It provides a well-damped, forgiving high-frequency radiator whose break-up is smooth, at the cost of the extreme rigidity of metal domes.','A technician choosing a tweeter for a smooth, non-fatiguing top end may pick a fabric dome over a metal dome to avoid a sharp break-up peak in the audio band.','Diaphragm types',ARRAY['Dome','Diamond-like carbon coating','Diaphragm anisotropy','Flexural rigidity','Diaphragm piston region']::text[],ARRAY['Assuming fabric domes cannot reach high frequencies well.','Confusing a self-damping fabric dome with an undamped plastic dome.','Thinking all soft domes sound the same regardless of coating.']::text[],ARRAY['Selecting a smooth-sounding tweeter for a monitor.','Comparing fabric and metal dome break-up behaviour.','Replacing a damaged soft-dome tweeter.']::text[],'Beginner',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fabric dome');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '60fa829b-37c3-42ba-8e48-652bf2a6853a','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='60fa829b-37c3-42ba-8e48-652bf2a6853a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='60fa829b-37c3-42ba-8e48-652bf2a6853a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e21b07c3-20a1-46b7-9fb6-d94bd9ca2977','Faraday ring','A conductive ring, usually copper or aluminium, placed on or around the pole piece of a driver motor to act as a shorted turn. It carries induced currents that oppose changes in the gap flux, reducing flux modulation, voice-coil inductance and its variation with position, and thereby lowering distortion.','A Faraday ring is a metal ring fitted in the motor''s magnet gap area. It acts like a single shorted coil. It fights sudden changes in the magnet''s field. This lowers distortion from the voice coil.','It stabilises the gap flux and reduces inductance-related and flux-modulation distortion, improving a driver''s clarity, especially in the midrange.','A technician comparing two woofers notes the one with a copper shorting ring shows lower, more constant inductance and less flux-modulation distortion at high current.','Motor electromagnetics',ARRAY['Flux modulation','Eddy current','Electrodynamic motor','Flux density distribution','Ferrite magnet']::text[],ARRAY['Confusing a Faraday (shorting) ring with a structural spacer.','Assuming any metal ring in the motor is a shorting ring.','Ignoring that the ring lowers and steadies voice-coil inductance.']::text[],ARRAY['Explaining how a shorting ring reduces distortion.','Comparing motors with and without a copper cap or ring.','Reading a driver datasheet that lists a shorting ring.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Faraday ring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e21b07c3-20a1-46b7-9fb6-d94bd9ca2977','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e21b07c3-20a1-46b7-9fb6-d94bd9ca2977') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e21b07c3-20a1-46b7-9fb6-d94bd9ca2977');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '81a7698b-9a62-49c4-8701-9a8e319e587f','Fatigue life','The number of flex cycles a driver''s repeatedly stressed parts, such as the surround, spider and voice-coil lead wires, can endure before cracking or breaking. It depends on the material, the stress amplitude per cycle and environmental factors, and sets a limit on the driver''s mechanical service life.','Speaker parts bend back and forth millions of times. Each bend adds a little wear. Fatigue life is how many bends they survive before failing. Bigger swings shorten this life.','It quantifies how long flexing driver parts last, guiding material choice and reliability expectations for suspensions and lead wires.','A technician seeing broken tinsel lead wires on a hard-driven woofer recognises a fatigue failure and looks for excessive excursion or slack lead-wire routing as the cause.','Reliability',ARRAY['Diaphragm rocking','Displacement limit','Flexural rigidity','Diaphragm mass','Displacement-limited output']::text[],ARRAY['Assuming a part that survives one big stress will last indefinitely.','Ignoring that larger excursion swings shorten fatigue life sharply.','Confusing gradual fatigue failure with a single overload event.']::text[],ARRAY['Diagnosing broken voice-coil lead wires.','Explaining why hard-driven suspensions eventually crack.','Judging expected service life of a driver''s moving parts.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fatigue life');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '81a7698b-9a62-49c4-8701-9a8e319e587f','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='81a7698b-9a62-49c4-8701-9a8e319e587f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='81a7698b-9a62-49c4-8701-9a8e319e587f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '058e2c01-2df1-4f0d-8b98-8f3e49e9f37d','Ferrite magnet','A ceramic permanent magnet made from sintered strontium or barium ferrite, the most common motor magnet in conventional loudspeakers. It offers a modest energy product at low cost and good corrosion resistance, but is heavier and bulkier than neodymium for the same magnetic energy.','A ferrite magnet is a hard ceramic magnet. It is cheap and resists rust. It is heavier and weaker than a neodymium magnet of the same size. Most ordinary speakers use one.','It supplies the fixed magnetic field in a driver motor cheaply and reliably, at the cost of extra weight and size versus rare-earth magnets.','A technician choosing between two woofers notes the ferrite version is heavier and larger than the neodymium version but usually cheaper for the same output.','Motor materials',ARRAY['Electrodynamic motor','Differential-drive motor','Dual-gap motor','Flux density distribution','Faraday ring']::text[],ARRAY['Assuming ferrite and neodymium magnets are interchangeable by size.','Confusing a ferrite (ceramic) magnet with an Alnico or neodymium type.','UNSAFE: Large ferrite motor magnets can pinch fingers and skin against steel tools and erase magnetic media; handle with care and keep clear of pacemakers.']::text[],ARRAY['Comparing magnet types when specifying a driver.','Explaining why a ferrite motor is heavy.','Servicing a driver with a large ceramic magnet.']::text[],'Beginner',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ferrite magnet');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '058e2c01-2df1-4f0d-8b98-8f3e49e9f37d','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='058e2c01-2df1-4f0d-8b98-8f3e49e9f37d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='058e2c01-2df1-4f0d-8b98-8f3e49e9f37d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b4cea1c6-0daa-469a-9d6d-f346bc1d386c','Flexural rigidity','A measure of a plate or diaphragm''s resistance to bending, set by its material stiffness (Young''s modulus), thickness cubed and Poisson''s ratio. For a thin plate it equals Young''s modulus times thickness cubed divided by twelve times one minus Poisson''s ratio squared, and higher values push break-up higher.','Flexural rigidity is how hard a panel is to bend. Thicker, stiffer material bends less. Because thickness enters cubed, a little more thickness helps a lot. Higher rigidity keeps a diaphragm pistonic to higher pitch.','It links diaphragm material and thickness to break-up frequency, guiding material choices for stiff, well-behaved cones and domes.','For aluminium with E of 70e9 Pa, thickness t of 0.2 mm (0.0002 m) and Poisson''s ratio nu of 0.33, D = E*t^3 / (12*(1 - nu^2)) = 70e9*(0.0002)^3 / (12*0.891) = about 0.052 N*m.','Diaphragm materials',ARRAY['Diaphragm piston region','Diaphragm anisotropy','Diamond-like carbon coating','Dome','Fabric dome']::text[],ARRAY['Forgetting that thickness enters as a cube, dominating rigidity.','Assuming a stiffer material always gives a lighter, better diaphragm.','Ignoring damping, which also shapes break-up beyond raw rigidity.']::text[],ARRAY['Comparing diaphragm materials for break-up performance.','Explaining why thin metal domes ring while thicker cones do not.','Modelling a cone''s first break-up frequency.']::text[],'Advanced','D = E * t^3 / (12 * (1 - nu^2))','Flexural rigidity equals Young''s modulus times thickness cubed, divided by twelve times one minus Poisson''s ratio squared.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flexural rigidity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b4cea1c6-0daa-469a-9d6d-f346bc1d386c','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b4cea1c6-0daa-469a-9d6d-f346bc1d386c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b4cea1c6-0daa-469a-9d6d-f346bc1d386c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f4c9bcdf-d793-4539-a157-3450d3b9626e','Flux density distribution','The variation of magnetic flux density along the voice-coil travel path in the motor gap, rather than a single average value. Because flux density falls off toward the edges of the gap, the force factor Bl changes with coil position, and this distribution largely sets the driver''s large-signal linearity.','The magnet''s field in the gap is not the same everywhere. It is strongest in the middle and weaker at the edges. This pattern is the flux density distribution. It decides how the motor''s push changes as the coil moves.','It explains how force factor varies with excursion, which underlies a driver''s distortion and effective linear travel.','A technician reviewing a Bl-versus-position curve reads it as the flux distribution seen by the coil, and judges linear excursion from how far Bl stays near its peak.','Motor electromagnetics',ARRAY['Electrodynamic motor','Flux modulation','Displacement limit','Equal-hung voice coil','Dynamic voice-coil position']::text[],ARRAY['Treating gap flux density as one fixed number for the whole travel.','Assuming Bl stays constant across the full excursion.','Confusing the static flux distribution with signal-driven flux modulation.']::text[],ARRAY['Interpreting a Bl-versus-excursion curve.','Explaining why force factor drops at large excursion.','Comparing motor designs for large-signal linearity.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flux density distribution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f4c9bcdf-d793-4539-a157-3450d3b9626e','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f4c9bcdf-d793-4539-a157-3450d3b9626e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f4c9bcdf-d793-4539-a157-3450d3b9626e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '547de1e0-3f34-4035-ad39-7dbecdb855db','Flux modulation','The signal-driven variation of the gap flux caused by the voice coil''s own alternating magnetic field adding to and subtracting from the fixed magnet flux. Because force factor depends on gap flux, this modulation makes Bl vary with current, producing distortion; conductive shorting rings are used to suppress it.','The voice coil makes its own magnetic field as current flows. That field pushes on the magnet''s steady field in the gap. So the field wobbles with the signal. This wobble, called flux modulation, adds distortion.','It identifies a current-dependent distortion mechanism in motors, motivating shorting rings and low-loss pole materials to keep gap flux steady.','A technician measuring rising distortion at high drive current in a ring-less motor attributes part of it to flux modulation and expects a copper shorting ring to reduce it.','Motor electromagnetics',ARRAY['Faraday ring','Eddy current','Flux density distribution','Electrodynamic motor','Differential-drive motor']::text[],ARRAY['Confusing flux modulation with the static flux-density distribution.','Ignoring that flux modulation grows with drive current.','Assuming only the fixed magnet sets the gap flux while signal is present.']::text[],ARRAY['Explaining current-dependent distortion in a driver.','Justifying a shorting ring or copper pole cap.','Comparing motors for high-level midrange clarity.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flux modulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '547de1e0-3f34-4035-ad39-7dbecdb855db','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='547de1e0-3f34-4035-ad39-7dbecdb855db') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='547de1e0-3f34-4035-ad39-7dbecdb855db');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '08b8471b-a3e6-4d83-b59c-c0be1fcded3c','Flux stabilization','Design techniques that keep the magnetic flux in a driver''s gap steady as voice-coil current and coil position change, chiefly by adding conductive parts such as shorting (Faraday) rings, copper caps, or copper-plated pole pieces to the magnetic circuit. This lowers flux modulation, eddy-current losses, inductance variation, and the resulting distortion.','Current in the coil can shift the magnet''s field. That shifting field adds distortion. Flux stabilization adds copper rings or caps near the pole. These steady the field and cut distortion.','It keeps the gap flux nearly constant so the motor stays linear and low in distortion, even at high drive levels.','A technician spots shorting rings or copper pole caps in a driver cutaway and expects flatter impedance and lower midrange distortion.','Magnetic circuit',ARRAY['Inductance modulation','Magnetic circuit','Magnetic flux','Magnetic saturation','Force factor']::text[],ARRAY['Thinking a shorting ring adds output; it mainly reduces distortion and inductance.','Confusing flux stabilization with raw magnet strength.','Assuming a copper cap is decorative rather than functional.']::text[],ARRAY['Comparing woofers with and without shorting rings for distortion.','Reading a datasheet that lists a copper cap or Faraday ring.','Diagnosing rising midrange distortion in an older driver.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flux stabilization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '08b8471b-a3e6-4d83-b59c-c0be1fcded3c','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='08b8471b-a3e6-4d83-b59c-c0be1fcded3c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='08b8471b-a3e6-4d83-b59c-c0be1fcded3c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a3524309-57f1-4640-8d6f-569b149b1304','Force factor','The electrodynamic coupling coefficient of a moving-coil driver, equal to the gap flux density B times the length l of coil wire in the gap (Bl). It links current to force (F = Bl*i) and coil velocity to back-EMF, with units of tesla-metre (T*m), equal to newtons per ampere (N/A).','The force factor tells how strongly current turns into cone force. It is the gap field times the wire length in that field. A bigger value means more push per amp. Engineers write it as Bl.','It quantifies motor strength and sets a driver''s efficiency, damping, and force produced per ampere of current.','With B = 1.2 T and l = 8 m, Bl = 9.6 T*m; a 2 A current then makes F = Bl*i = 19.2 N of force.','Motor parameter',ARRAY['Motor strength','Magnetic flux','Magnet gap','Long-coil motor','Magnetic circuit']::text[],ARRAY['Confusing Bl (T*m) with magnet weight or flux alone.','Forgetting Bl falls at large excursion, written Bl(x).','Mixing units; Bl in T*m equals N/A.']::text[],ARRAY['Comparing two woofers'' motor strength on a spec sheet.','Estimating force output from drive current.','Explaining why high Bl raises sensitivity.']::text[],'Intermediate','Bl = B * l ;  F = Bl * i','The force factor equals the gap flux density multiplied by the length of voice-coil wire in the gap; the force produced equals the force factor times the current.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Force factor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a3524309-57f1-4640-8d6f-569b149b1304','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a3524309-57f1-4640-8d6f-569b149b1304') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a3524309-57f1-4640-8d6f-569b149b1304');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a437df2b-8879-4029-b24b-3784702928dc','Graphene diaphragm','A driver diaphragm made from graphene or, more often, a graphene-oxide composite membrane, using graphene''s very high stiffness-to-mass ratio to push cone breakup higher and reduce distortion. It appears mainly in headphone and micro-speaker drivers; GrapheneQ is a trademarked example owned by Ora Graphene Audio.','Graphene is a very thin, very stiff carbon sheet. A graphene diaphragm is light yet rigid. That mix pushes distortion and breakup higher in frequency. It is common in headphones and tiny speakers.','It aims to give a stiff, low-mass diaphragm that stays pistonic over a wider band, lowering distortion in small drivers.','A technician meets it in premium earphones and headphones; off-the-shelf GrapheneQ drivers ship in 40 mm and 50 mm sizes with extended, low-distortion treble.','Diaphragm material',ARRAY['Modal diaphragm','Honeycomb core','Kevlar cone','Magnesium cone','Inverted dome']::text[],ARRAY['Assuming ''graphene'' always means pure single-layer graphene; most are graphene-oxide composites.','Thinking the material alone guarantees better sound regardless of motor and tuning.','Treating a marketing ''graphene'' label as proof of a single-atom layer.']::text[],ARRAY['Evaluating a graphene-driver headphone spec.','Explaining why a tiny driver has low distortion.','Comparing diaphragm materials for earphones.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Graphene diaphragm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a437df2b-8879-4029-b24b-3784702928dc','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a437df2b-8879-4029-b24b-3784702928dc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a437df2b-8879-4029-b24b-3784702928dc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '75b0a5cd-7df8-49fb-a49b-7ffc8ffee7ad','Honeycomb core','A sandwich-diaphragm construction in which a lightweight honeycomb layer (aramid such as DuPont Nomex, aluminium, or paper) is bonded between two thin facing skins. The core resists shear, so the panel gains high bending stiffness at low mass and a raised breakup frequency.','A honeycomb core is a light cell layer between two skins. It works like a stiff, hollow sandwich. This makes the diaphragm rigid but not heavy. Rigid, light panels break up at higher frequencies.','It maximises stiffness-to-weight so the diaphragm behaves as a piston over a wider band before breakup.','A technician sees honeycomb-sandwich cones or flat diaphragms in some monitors; expect a very rigid panel with a high, sharp breakup mode to keep out of band.','Diaphragm construction',ARRAY['Modal diaphragm','Graphene diaphragm','Kevlar cone','Magnesium cone','Mechanical fatigue']::text[],ARRAY['Thinking the core radiates sound; it mainly stiffens the sandwich.','Assuming heavier means stronger; the goal is stiffness per unit mass.','Ignoring that the sharp breakup peak still needs crossover control.']::text[],ARRAY['Inspecting a flat sandwich diaphragm in a studio monitor.','Explaining why a light cone stays pistonic to high frequencies.','Choosing a crossover point below a honeycomb cone''s breakup.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Honeycomb core');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '75b0a5cd-7df8-49fb-a49b-7ffc8ffee7ad','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='75b0a5cd-7df8-49fb-a49b-7ffc8ffee7ad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='75b0a5cd-7df8-49fb-a49b-7ffc8ffee7ad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '488f5cb9-af04-4c4b-a2a0-269b25b09dbb','Inductance asymmetry','An unequal change of voice-coil inductance Le as the coil moves inward versus outward from rest, because the coil overlaps more or less iron on each side of the gap. The resulting Le(x) curve is asymmetric, producing even-order distortion and a position-dependent reluctance force.','The coil''s inductance changes as it moves. If it changes more one way than the other, that is asymmetry. This lopsided change adds distortion. It also creates a small pull toward the iron.','It names a motor nonlinearity that engineers reduce for lower distortion and that testers use as a diagnostic.','A technician reads Le(x) in Klippel results; a shorting ring or symmetric pole design flattens the curve and cuts the even-order distortion.','Motor nonlinearity',ARRAY['Inductance modulation','Motor asymmetry','Magnetic saturation','Flux stabilization','Force factor']::text[],ARRAY['Confusing inductance asymmetry (Le versus position) with inductance modulation (Le versus current).','Assuming it only matters at high frequencies.','Overlooking that it also biases the cone''s rest position.']::text[],ARRAY['Interpreting an asymmetric Le(x) plot.','Choosing a driver with a symmetric magnetic gap.','Explaining even-order distortion from motor geometry.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inductance asymmetry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '488f5cb9-af04-4c4b-a2a0-269b25b09dbb','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='488f5cb9-af04-4c4b-a2a0-269b25b09dbb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='488f5cb9-af04-4c4b-a2a0-269b25b09dbb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8645ab39-7e8e-4d66-a8f4-004de74bf6b3','Inductance modulation','The variation of voice-coil inductance during operation as coil current and position change the iron overlap and the permeability of the magnetic circuit. It causes flux modulation, back-EMF distortion (harmonics and intermodulation) and impedance variation, and is reduced by shorting rings and copper pole caps.','The coil acts partly like a changing inductor. Its inductance shifts with current and position. That shifting distorts the signal. Copper rings near the pole reduce the effect.','It names the mechanism behind a key driver distortion and explains why flux-stabilising parts are added.','A technician expects lower midrange distortion from drivers fitted with copper shorting rings, which linearise the inductance.','Motor nonlinearity',ARRAY['Inductance asymmetry','Flux stabilization','Magnetic saturation','Force factor','Magnetic circuit']::text[],ARRAY['Thinking it only affects high frequencies; it causes broadband intermodulation.','Confusing inductance modulation with cone breakup.','Assuming voice-coil inductance is a single fixed number.']::text[],ARRAY['Explaining intermodulation distortion in a midrange driver.','Justifying a copper-capped pole in a design.','Reading Le(i) curves in large-signal test data.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inductance modulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8645ab39-7e8e-4d66-a8f4-004de74bf6b3','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8645ab39-7e8e-4d66-a8f4-004de74bf6b3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8645ab39-7e8e-4d66-a8f4-004de74bf6b3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a02600d0-5eb6-4604-b19d-94a9d3111453','Instantaneous displacement','The voice-coil or cone position x(t) at a given instant relative to rest, a time-varying signal whose peak value determines whether the driver stays within its linear excursion limits. A positive or negative sign marks outward or inward motion, distinguishing it from RMS or peak excursion.','This is where the cone sits at one instant. It swings out and back as it plays. The biggest swing must stay inside safe limits. The sign shows outward or inward motion.','It describes the moment-by-moment motion used to judge excursion limits and distortion.','For a 40 Hz tone at 4 mm peak, x(t) = 4*sin(2*pi*40*t) mm. A quarter-period in, at t = 1/160 s, the coil is at its 4 mm outward peak.','Excursion parameter',ARRAY['Maximum linear excursion','Motor-limited excursion','Mechanical overtravel','Mechanical compliance','Force factor']::text[],ARRAY['Confusing instantaneous displacement with peak or RMS displacement.','Ignoring the sign that shows direction of motion.','Assuming displacement follows the input voltage shape at every frequency.']::text[],ARRAY['Watching a cone''s motion on a laser displacement plot.','Checking peak excursion against Xmax.','Explaining how bass content drives large cone travel.']::text[],'Intermediate','x(t) = X_peak * sin(2 * pi * f * t)','For a pure tone, instantaneous displacement equals the peak excursion times the sine of two pi times frequency times time.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Instantaneous displacement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a02600d0-5eb6-4604-b19d-94a9d3111453','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a02600d0-5eb6-4604-b19d-94a9d3111453') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a02600d0-5eb6-4604-b19d-94a9d3111453');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b04041d5-8a25-4bc3-aaf0-cb3cfecc334b','Inverted dome','A dome-radiator geometry, most common in tweeters, where the dome is concave (curving inward toward the motor) instead of convex, with the voice coil attached at the dome''s outer rim. Focal''s beryllium and aluminium-magnesium tweeters are well-known examples; makers cite dispersion and rigidity benefits.','Most tweeter domes bulge outward. An inverted dome curves inward instead. The coil sits at the dome''s outer edge. Makers say this aids stiffness and the spread of sound.','It is an alternative dome shape aiming for wide dispersion and a rigid diaphragm well coupled to its coil.','A technician meets inverted-dome tweeters in Focal monitors and car audio; the concave dome usually pairs with a shaped faceplate or waveguide.','Diaphragm geometry',ARRAY['Modal diaphragm','Magnesium cone','Graphene diaphragm','Honeycomb core','Kevlar cone']::text[],ARRAY['Mistaking the concave shape for a dented or damaged dome.','Assuming inverted always means beryllium; several materials are used.','Believing dome direction alone sets the frequency response.']::text[],ARRAY['Identifying a concave tweeter on a monitor.','Explaining Focal''s tweeter design to a client.','Handling an inverted dome carefully during service.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inverted dome');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b04041d5-8a25-4bc3-aaf0-cb3cfecc334b','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b04041d5-8a25-4bc3-aaf0-cb3cfecc334b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b04041d5-8a25-4bc3-aaf0-cb3cfecc334b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5001e26a-a8ba-4fe5-946b-d671ce2abdf7','Kevlar cone','A loudspeaker cone woven from or reinforced with Kevlar, DuPont''s para-aramid fibre. The woven aramid combines high tensile strength with internal damping, so breakup resonances are spread out and damped rather than forming one sharp peak; Bowers & Wilkins'' yellow cones are a famous use.','Kevlar is a strong DuPont aramid fibre. A Kevlar cone is woven from this fibre. It is stiff and self-damping. Its breakup is spread out, not one sharp spike.','It provides a strong, well-damped cone whose breakup is gradual and controllable.','A technician meets woven-aramid cones in monitors and hi-fi (such as B&W) and expects a smooth, damped midrange rather than a sharp resonance.','Diaphragm material',ARRAY['Modal diaphragm','Honeycomb core','Magnesium cone','Graphene diaphragm','Mechanical fatigue']::text[],ARRAY['Assuming any yellow cone is Kevlar; colour is not proof.','Thinking Kevlar is perfectly pistonic; it still breaks up, only damped.','Using ''Kevlar'' generically; it is a DuPont trademark for para-aramid.']::text[],ARRAY['Identifying a woven-aramid cone in a studio monitor.','Explaining damped breakup to a student.','Comparing cone materials for midrange smoothness.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Kevlar cone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5001e26a-a8ba-4fe5-946b-d671ce2abdf7','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5001e26a-a8ba-4fe5-946b-d671ce2abdf7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5001e26a-a8ba-4fe5-946b-d671ce2abdf7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '034f6acf-0fab-4f80-acaf-9d87cb40b4a0','Kms','The mechanical stiffness of a driver''s suspension (spider plus surround), in newtons per metre (N/m), equal to the reciprocal of mechanical compliance Cms (Kms = 1/Cms). It sets the restoring force F = Kms*x that returns the moving system to rest.','Kms is how stiff the suspension springs are. It is the opposite of compliance. A stiffer suspension pulls the cone back harder. Engineers give it in newtons per metre.','It quantifies the suspension''s restoring force and, with the moving mass, sets the driver''s resonance.','If Cms = 0.5 mm/N (5e-4 m/N), then Kms = 1/Cms = 2000 N/m; at x = 3 mm the restoring force is F = Kms*x = 6 N.','Suspension parameter',ARRAY['Mechanical compliance','Kms(x)','Instantaneous displacement','Maximum linear excursion','Force factor']::text[],ARRAY['Confusing stiffness Kms with compliance Cms; they are inverses.','Mixing units (N/m for stiffness, m/N for compliance).','Assuming Kms is constant; it rises at large excursion.']::text[],ARRAY['Converting a compliance spec to stiffness.','Estimating restoring force at a given excursion.','Explaining why a stiff suspension raises resonance.']::text[],'Intermediate','Kms = 1 / Cms ;  F = Kms * x','Suspension stiffness equals one divided by mechanical compliance; the restoring force equals stiffness times displacement.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Kms');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '034f6acf-0fab-4f80-acaf-9d87cb40b4a0','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='034f6acf-0fab-4f80-acaf-9d87cb40b4a0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='034f6acf-0fab-4f80-acaf-9d87cb40b4a0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '155d7c19-9740-4994-8120-eb26034e69c5','Kms(x)','The suspension stiffness expressed as a function of displacement x, capturing how the spider and surround stiffen progressively at large excursions. The shape of the Kms(x) curve, and any asymmetry in it, governs large-signal distortion and any DC offset of the cone''s rest position.','Real suspensions get stiffer as the cone moves far. Kms(x) is stiffness plotted against position. A lopsided curve adds distortion. It can also push the cone off-centre.','It describes the nonlinear spring that limits how far a driver can move while staying clean.','A technician reads Kms(x) in Klippel plots; a symmetric, wide curve means more clean excursion, while asymmetry near resonance shows up as a DC offset.','Suspension nonlinearity',ARRAY['Kms','Mechanical compliance','Maximum linear excursion','Motor-limited excursion','Motor asymmetry']::text[],ARRAY['Treating the suspension as a linear spring at all excursions.','Confusing Kms(x) asymmetry with Bl(x) asymmetry; their DC-offset behaviour at resonance differs.','Ignoring that a steeply stiffening curve limits low-frequency output.']::text[],ARRAY['Interpreting a Kms(x) curve for excursion limits.','Diagnosing a cone that rests off-centre.','Comparing suspension linearity between drivers.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Kms(x)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '155d7c19-9740-4994-8120-eb26034e69c5','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='155d7c19-9740-4994-8120-eb26034e69c5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='155d7c19-9740-4994-8120-eb26034e69c5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9b58fc5c-9c8a-48dd-b736-e3da4c0a1e5d','Long-coil motor','A moving-coil motor whose voice coil is longer than the magnetic gap (an ''overhung'' coil), so a constant number of turns stays in the gap across a range of travel. This gives a flat-topped Bl(x) curve with a hard-limiting edge, at the cost of lower efficiency and added moving mass compared with an equal-length or underhung coil.','Here the coil is taller than the magnet gap. Extra coil hangs outside the gap. The same turns stay in the field as it moves. This keeps push steady, then drops off sharply.','It keeps the force factor roughly constant across excursion, giving linear large-signal output in high-travel drivers.','A technician recognises overhung motors in high-excursion woofers and subs; expect flat Bl over Xmax, a hard limit beyond, and lower efficiency than an equal-length coil.','Motor design',ARRAY['Force factor','Maximum linear excursion','Motor strength','Magnet gap','Motor-limited excursion']::text[],ARRAY['Confusing overhung (long-coil) with underhung (short-coil) motors.','Assuming a longer coil always means more output; it can lower efficiency.','Ignoring the extra moving mass a long coil adds.']::text[],ARRAY['Choosing a woofer for deep, high-excursion bass.','Explaining a flat-topped Bl(x) curve.','Comparing overhung and underhung motor trade-offs.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Long-coil motor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9b58fc5c-9c8a-48dd-b736-e3da4c0a1e5d','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9b58fc5c-9c8a-48dd-b736-e3da4c0a1e5d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9b58fc5c-9c8a-48dd-b736-e3da4c0a1e5d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bd2e0f65-bea3-47ac-a094-24f78e35f1ae','Lossy coating','A damping compound applied to a diaphragm or surround to add internal mechanical loss (resistance), converting vibration energy to heat so that cone breakup resonances are reduced in amplitude and broadened rather than left as sharp peaks.','A lossy coating is a soft damping layer on the cone. It turns some vibration into heat. This calms sharp breakup peaks. The response then gets smoother.','It damps resonances and tames breakup without changing the base diaphragm material.','A technician sees coated paper or plastic cones and expects lower, wider breakup peaks and smoother off-axis response.','Diaphragm treatment',ARRAY['Modal diaphragm','Mechanical fatigue','Kevlar cone','Honeycomb core','Mechanical compliance']::text[],ARRAY['Thinking coating adds output; it mainly reduces peaks by adding loss.','Assuming more coating is always better; it adds mass and can dull output.','Confusing surround damping with cone-material stiffness.']::text[],ARRAY['Identifying a damped cone in a monitor.','Explaining smoother breakup from a coating.','Choosing between a coated and uncoated driver.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lossy coating');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bd2e0f65-bea3-47ac-a094-24f78e35f1ae','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bd2e0f65-bea3-47ac-a094-24f78e35f1ae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bd2e0f65-bea3-47ac-a094-24f78e35f1ae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9877e7b5-69ec-4a33-b761-e538c7c472e0','Magnesium cone','A diaphragm made of magnesium, usually a magnesium or magnesium-aluminium alloy, a very light metal giving a high stiffness-to-mass ratio and better self-damping than aluminium. It is used in midrange and mid-woofer drivers to raise breakup frequency, but has a strong, sharp breakup peak that must be crossed over below.','Magnesium is a very light metal. A magnesium cone is stiff yet low in mass. That pushes breakup high and keeps the band clean. But it has one sharp peak to filter out.','It provides a stiff, light metal diaphragm with some damping, for an extended pistonic range.','A technician meets magnesium and mag-alloy cones in hi-fi and studio mid-woofers (such as SEAS Excel); the sharp breakup mode needs a crossover set well below it.','Diaphragm material',ARRAY['Modal diaphragm','Inverted dome','Kevlar cone','Graphene diaphragm','Honeycomb core']::text[],ARRAY['UNSAFE: magnesium powder, swarf, and chips are flammable; never grind, sand, or machine a magnesium cone.','Thinking magnesium removes breakup; it has a strong, narrow peak.','Confusing pure magnesium with aluminium-magnesium alloys.']::text[],ARRAY['Identifying a metal cone in a mid-woofer.','Setting a crossover below a magnesium breakup peak.','Safely disposing of a damaged magnesium driver.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magnesium cone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9877e7b5-69ec-4a33-b761-e538c7c472e0','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9877e7b5-69ec-4a33-b761-e538c7c472e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9877e7b5-69ec-4a33-b761-e538c7c472e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '774efe7c-eef8-4561-b673-92380e2fcb32','Magnet gap','The narrow annular air gap in a driver''s magnetic circuit, between the pole piece and the top plate, where the voice coil sits in a concentrated radial magnetic field. Its width sets the gap flux density (and hence Bl) and the mechanical clearance around the coil.','The magnet gap is a small ring-shaped slot in the motor. The voice coil hangs inside it. A strong field crosses the gap. A tighter gap gives a stronger field.','It concentrates flux where the coil sits so current in the coil produces force.','A technician keeps the gap free of steel debris; a narrower gap raises flux density and Bl but cuts clearance and risks coil rub.','Magnetic circuit',ARRAY['Magnetic circuit','Magnetic flux','Force factor','Magnetic saturation','Long-coil motor']::text[],ARRAY['UNSAFE: keep fingers and steel tools clear of an exposed magnet assembly; strong magnets can snap shut and pinch or launch objects.','Confusing the magnet gap with a pole vent hole.','Thinking a wider gap is better; it lowers flux density.']::text[],ARRAY['Cleaning grit from a driver''s gap.','Explaining why gap width sets flux density.','Inspecting a rubbing voice coil.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magnet gap');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '774efe7c-eef8-4561-b673-92380e2fcb32','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='774efe7c-eef8-4561-b673-92380e2fcb32') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='774efe7c-eef8-4561-b673-92380e2fcb32');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '053b8a8b-b071-442a-b39e-b045bc82ebc6','Magnet thermal resistance','The thermal resistance (in kelvin per watt, K/W) of the heat path from the magnet and pole structure to the surrounding air, describing how well heat generated in the voice coil is finally shed to ambient. It is one element (with coil-to-magnet resistance) that sets steady-state coil temperature and power compression.','The coil heats up when it works. Heat must escape through the magnet and frame to the air. Thermal resistance says how hard that is. High resistance means a hotter coil.','It helps predict coil heating, power compression, and thermal limits for a given input power.','With magnet-to-air resistance R_tm = 2 K/W and 30 W dissipated, the magnet-path temperature rise is delta_T = P*R_tm = 60 K.','Thermal parameter',ARRAY['Magnetic circuit','Magnet gap','Magnetic saturation','Force factor','Maximum linear excursion']::text[],ARRAY['UNSAFE: an overdriven voice coil can exceed 200 degrees C; let a driver cool before touching it to avoid burns.','Confusing thermal resistance with electrical resistance.','Ignoring power compression as the coil heats.']::text[],ARRAY['Estimating coil temperature at rated power.','Explaining power compression in a hot driver.','Comparing vented and solid pole thermal designs.']::text[],'Advanced','delta_T = P * R_tm','The magnet-path temperature rise equals the power dissipated times the magnet-to-air thermal resistance.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magnet thermal resistance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '053b8a8b-b071-442a-b39e-b045bc82ebc6','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='053b8a8b-b071-442a-b39e-b045bc82ebc6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='053b8a8b-b071-442a-b39e-b045bc82ebc6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b5a44b9c-e149-41f3-9230-9cff228bc0d1','Magnetic circuit','The assembly of permanent magnet, pole piece, top plate, and back plate that guides magnetic flux from the magnet through the gap and back, analogous to an electrical circuit where magnetomotive force drives flux against reluctance. Its design sets the gap flux density and therefore the force factor Bl.','The magnetic circuit is the metal path for the magnet''s field. It steers the field into the gap. Then it loops the field back to the magnet. Good design makes the gap field strong.','It routes and concentrates flux into the gap efficiently so the coil can make force.','A technician treats the whole motor as one magnetic loop; keeping it clean and undamaged preserves gap flux, but assembled magnets are hazardous to handle.','Magnetic circuit',ARRAY['Magnetic return path','Magnetic flux','Magnet gap','Magnetic saturation','Force factor']::text[],ARRAY['UNSAFE: assembled neodymium motors are strongly magnetic and can snap shut on fingers or fling steel tools; handle with care.','Confusing magnetic reluctance with electrical resistance.','Thinking only the magnet matters, ignoring the pole and plates.']::text[],ARRAY['Explaining how a driver''s motor makes force.','Handling a strong magnet assembly safely.','Diagnosing weak output from a damaged plate.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magnetic circuit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b5a44b9c-e149-41f3-9230-9cff228bc0d1','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b5a44b9c-e149-41f3-9230-9cff228bc0d1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b5a44b9c-e149-41f3-9230-9cff228bc0d1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a0ebcf81-b892-42ee-9c6f-60cdb31a2b49','Magnetic flux','The total magnetic field passing through a surface; for a uniform field perpendicular to area A it is Phi = B*A, measured in webers (Wb, where 1 Wb = 1 T*m^2). In a driver the useful quantity is the gap flux, and its density B, crossing the voice coil.','Magnetic flux is the amount of magnetic field through an area. More field or more area means more flux. In a speaker it is the field crossing the gap. That field drives the coil.','It quantifies the magnetic field available in the gap to produce force on the coil.','For a gap field B = 1.2 T through an annular area A = 1.5e-4 m^2, the flux is Phi = B*A = 1.8e-4 Wb.','Magnetic quantity',ARRAY['Magnetic circuit','Magnet gap','Magnetic saturation','Force factor','Magnetic return path']::text[],ARRAY['Confusing flux Phi (webers) with flux density B (tesla).','Forgetting flux depends on area and angle, not field strength alone.','Assuming flux is constant when saturation or modulation changes it.']::text[],ARRAY['Calculating gap flux from field and area.','Explaining the difference between flux and flux density.','Relating gap flux to force factor.']::text[],'Intermediate','Phi = B * A','Magnetic flux equals the flux density times the area it passes through, when the field is perpendicular to that area.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magnetic flux');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a0ebcf81-b892-42ee-9c6f-60cdb31a2b49','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a0ebcf81-b892-42ee-9c6f-60cdb31a2b49') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a0ebcf81-b892-42ee-9c6f-60cdb31a2b49');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '957220e1-87fc-4d5e-b9ae-02023093309e','Magnetic return path','The ferromagnetic part of the motor (back plate, pole piece, and top plate) that carries flux from one magnet pole back to the other, completing the magnetic circuit outside the gap with low reluctance. A poor or saturating return path wastes flux and lowers gap flux density.','The field must loop back to the magnet. The return path is the steel that carries it. It should give the field little resistance. A good path keeps the gap field strong.','It completes the flux loop with low loss so most of the magnet''s flux reaches the gap.','A technician recognises the steel yoke and back plate as the return path; rust, thin sections, or cracks raise reluctance and cut output.','Magnetic circuit',ARRAY['Magnetic circuit','Magnetic flux','Magnetic saturation','Magnet gap','Force factor']::text[],ARRAY['Thinking the return path is unimportant next to the magnet.','Confusing it with the voice-coil return lead wires.','Ignoring saturation in a thin return-path section.']::text[],ARRAY['Explaining how flux loops through the motor.','Diagnosing low output from a corroded yoke.','Comparing motor designs for return-path efficiency.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magnetic return path');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '957220e1-87fc-4d5e-b9ae-02023093309e','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='957220e1-87fc-4d5e-b9ae-02023093309e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='957220e1-87fc-4d5e-b9ae-02023093309e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e9c4a789-2904-45b4-be11-f9032c168e67','Magnetic saturation','The condition where a ferromagnetic material can carry almost no additional flux density as the magnetising force increases, because its magnetic domains are already fully aligned. In a driver, saturation of the pole or plates caps gap flux and contributes to inductance and flux-modulation nonlinearities.','Iron can only hold so much magnetic field. Past that point, more drive adds almost no field. This is saturation. In a motor it limits gap field and adds distortion.','It explains a hard limit on usable flux and a source of large-signal nonlinearity.','A technician links a saturating pole to added distortion at high current; designers use shaped poles or larger cross-sections to avoid it.','Magnetic behavior',ARRAY['Magnetic flux','Magnetic circuit','Inductance modulation','Magnetic return path','Magnet gap']::text[],ARRAY['Thinking a bigger magnet always gives more gap flux; the steel can saturate first.','Confusing saturation with demagnetisation.','Assuming saturation occurs only at DC, not with signal current.']::text[],ARRAY['Explaining distortion that rises with drive current.','Justifying a larger pole cross-section.','Reading a B-H curve near saturation.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magnetic saturation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e9c4a789-2904-45b4-be11-f9032c168e67','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e9c4a789-2904-45b4-be11-f9032c168e67') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e9c4a789-2904-45b4-be11-f9032c168e67');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a681b149-473c-48a8-8e82-2fd836923fa7','Magnetostrictive driver','A transducer that produces motion using magnetostriction, the change in length of a ferromagnetic material (commonly the giant-magnetostrictive alloy Terfenol-D) when magnetised. An audio-frequency magnetic field strains a biased rod, which drives a diaphragm or panel; it is rare in audio, seen in some flat-panel exciters and specialty actuators.','Some metals change length in a magnetic field. This is called magnetostriction. A magnetostrictive driver uses that to make motion. An alloy named Terfenol-D is common. It can shake a panel to make sound.','It offers an alternative motor principle for exciters and actuators, giving high force from a small rod.','A technician may meet giant-magnetostrictive exciters on flat-panel speakers; expect high force, small stroke, and both a bias magnet and a drive coil.','Transducer type',ARRAY['Modal diaphragm','Magnetic flux','Magnetic circuit','Force factor','Honeycomb core']::text[],ARRAY['Confusing magnetostrictive (magnetic field) with piezoelectric (electric field) drivers.','Assuming a large stroke; magnetostrictive strain is small and needs mechanical amplification.','Overlooking the required magnetic bias for linear operation.']::text[],ARRAY['Explaining a giant-magnetostrictive panel exciter.','Comparing exotic transducer principles.','Discussing Terfenol-D actuators in specialty audio.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Magnetostrictive driver');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a681b149-473c-48a8-8e82-2fd836923fa7','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a681b149-473c-48a8-8e82-2fd836923fa7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a681b149-473c-48a8-8e82-2fd836923fa7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f611933e-51af-4736-a58c-e2677e310477','Maximum linear excursion','The peak one-way voice-coil displacement (Xmax) over which a driver stays approximately linear, before Bl(x) and Kms(x) fall enough to raise distortion sharply. A common geometric estimate for an overhung coil is Xmax = (Hc - Hg)/2; manufacturers may instead define it at a fixed distortion or Bl-decline threshold.','Xmax is how far the cone can move each way and stay clean. Past it, distortion climbs fast. One simple estimate uses coil height minus gap height. Makers may use a distortion limit instead.','It sets the clean output and SPL limit of a driver at low frequencies.','With coil height Hc = 12 mm and gap height Hg = 6 mm, Xmax = (12 - 6)/2 = 3 mm of clean travel each way.','Excursion parameter',ARRAY['Motor-limited excursion','Instantaneous displacement','Mechanical overtravel','Long-coil motor','Force factor']::text[],ARRAY['Confusing Xmax (linear limit) with Xmech or Xdamage (physical limit).','Comparing Xmax figures defined by different methods.','Treating Xmax as a hard mechanical stop rather than a distortion limit.']::text[],ARRAY['Comparing clean bass headroom between woofers.','Estimating maximum SPL at a low frequency.','Reading Xmax on a driver datasheet.']::text[],'Intermediate','Xmax = (Hc - Hg) / 2','For an overhung coil, maximum linear excursion is the coil winding height minus the gap height, divided by two.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Maximum linear excursion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f611933e-51af-4736-a58c-e2677e310477','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f611933e-51af-4736-a58c-e2677e310477') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f611933e-51af-4736-a58c-e2677e310477');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8f04c3b2-d806-4ffd-8a05-98178ed30a08','Mechanical compliance','The mechanical compliance Cms of a driver''s moving system (spider plus surround), the inverse of stiffness, in metres per newton (m/N). It measures how easily the suspension yields to force and, with the moving mass Mms, sets the free-air resonance fs = 1/(2*pi*sqrt(Mms*Cms)).','Compliance is how easily the suspension springs give. It is the opposite of stiffness. A soft, high compliance yields more per newton. With the moving mass it sets the resonance.','It is a core Thiele-Small parameter that sets resonance and low-frequency behaviour.','With Cms = 1 mm/N (1e-3 m/N) and Mms = 20 g (0.02 kg), fs = 1/(2*pi*sqrt(0.02*0.001)) = about 35.6 Hz.','Suspension parameter',ARRAY['Kms','Kms(x)','Maximum linear excursion','Instantaneous displacement','Force factor']::text[],ARRAY['Confusing compliance (m/N) with stiffness (N/m).','Forgetting Cms drops with age, temperature, and large excursion.','Mixing mechanical Cms with acoustic compliance Cas or Vas.']::text[],ARRAY['Predicting resonance from Cms and moving mass.','Explaining why a broken-in driver has lower fs.','Reading Cms on a Thiele-Small spec sheet.']::text[],'Intermediate','Cms = 1 / Kms ;  fs = 1 / (2 * pi * sqrt(Mms * Cms))','Compliance is one divided by stiffness; free-air resonance is one over two pi times the square root of moving mass times compliance.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mechanical compliance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8f04c3b2-d806-4ffd-8a05-98178ed30a08','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8f04c3b2-d806-4ffd-8a05-98178ed30a08') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8f04c3b2-d806-4ffd-8a05-98178ed30a08');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '66139eb0-b38a-4890-b80b-796031f347a3','Mechanical fatigue','The progressive weakening and eventual cracking of a driver''s flexing parts (surround, spider, cone, and tinsel lead wires) from repeated cyclic stress over many vibration cycles, even at stress levels below the one-time breaking limit. It gradually changes compliance and can end in open circuits or mechanical failure.','Speaker parts flex millions of times. Repeated bending slowly weakens them. This is fatigue. Over time a surround or lead wire can crack.','It names a wear-out failure mode that limits a driver''s service life.','A technician inspects surrounds, spiders, and tinsel leads for fatigue cracks; a sagging, buzzing, or intermittent driver may have fatigued parts.','Failure mechanism',ARRAY['Mechanical compliance','Mechanical overtravel','Lossy coating','Kms','Motor-limited excursion']::text[],ARRAY['Assuming failure comes only from overpowering, not cyclic fatigue.','Ignoring tinsel lead-wire fatigue as a rattle or open-circuit cause.','Thinking a rested driver ''heals'' fatigue damage.']::text[],ARRAY['Diagnosing an intermittent driver with cracked leads.','Explaining why old surrounds sag or tear.','Assessing service life under heavy use.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mechanical fatigue');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '66139eb0-b38a-4890-b80b-796031f347a3','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='66139eb0-b38a-4890-b80b-796031f347a3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='66139eb0-b38a-4890-b80b-796031f347a3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '84e124da-478e-445a-b518-05b233c645c2','Mechanical overtravel','Voice-coil or cone motion beyond the intended linear range, up to the physical limits of the moving system, where the coil former can strike the back plate (''bottoming'') or the suspension fully stretches (''topping''). It produces hard distortion and can permanently damage the driver.','If pushed too hard, the cone moves past its safe range. The coil can slam the back plate. Or the suspension can stretch to its end. This makes loud distortion and can break the driver.','It describes the region past Xmax up to the point of mechanical damage.','A technician hears bottoming as a hard knock on bass peaks and uses a high-pass filter and limiter to prevent overtravel.','Excursion limit',ARRAY['Maximum linear excursion','Motor-limited excursion','Instantaneous displacement','Mechanical fatigue','Mechanical compliance']::text[],ARRAY['UNSAFE: the extreme levels that cause bottoming reach hearing-damaging SPL; use hearing protection and a limiter.','Driving a woofer into hard bottoming can wreck the coil former; add a high-pass filter.','Confusing mechanical overtravel with electrical clipping.']::text[],ARRAY['Preventing woofer damage with a high-pass filter.','Diagnosing a knocking sound on bass transients.','Setting a limiter to protect a subwoofer.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mechanical overtravel');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '84e124da-478e-445a-b518-05b233c645c2','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='84e124da-478e-445a-b518-05b233c645c2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='84e124da-478e-445a-b518-05b233c645c2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3a6be60f-3d2b-4374-a409-9bc39a39ee74','Modal diaphragm','A diaphragm operated in, or deliberately designed around, its modal (bending-resonance) region, where different areas vibrate in distinct patterns rather than moving as one piston. Controlled-breakup cones and bending-wave or distributed-mode panels use geometry, damping, and terminations so these modes spread output smoothly.','Above a point, a cone no longer moves as one piece. Parts flex in patterns called modes. A modal diaphragm is designed around these patterns. Good design spreads them smoothly, not as one harsh peak.','It manages or exploits breakup so a diaphragm can radiate smoothly over a wide band.','A technician sees this in soft-dome, woven-aramid, and bending-wave or flat-panel designs, expecting a gradual, damped transition into breakup.','Diaphragm behavior',ARRAY['Kevlar cone','Lossy coating','Honeycomb core','Magnesium cone','Mechanical fatigue']::text[],ARRAY['Assuming any diaphragm stays perfectly pistonic at all frequencies.','Confusing controlled modal breakup with pure distortion.','Thinking stiffer is always better; damping the modes can matter more.']::text[],ARRAY['Explaining a distributed-mode (flat-panel) loudspeaker.','Comparing pistonic and modal cone behaviour.','Choosing a well-damped midrange diaphragm.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal diaphragm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3a6be60f-3d2b-4374-a409-9bc39a39ee74','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3a6be60f-3d2b-4374-a409-9bc39a39ee74') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3a6be60f-3d2b-4374-a409-9bc39a39ee74');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd3cee60b-ed4f-46ab-a2e4-fe4bf9653ea9','Motor asymmetry','An imbalance in a driver''s motor so its force behaviour differs for inward versus outward coil travel, typically an asymmetric Bl(x) or Le(x) curve caused by coil-gap offset or magnetic geometry. It produces even-order distortion and a DC displacement of the cone from its rest position.','A perfect motor pushes equally both ways. Real motors often differ in and out. That imbalance is motor asymmetry. It adds even-order distortion and can shift the cone off-centre.','It names a motor nonlinearity that is diagnosed and reduced in large-signal testing.','A technician sees an asymmetric Bl(x) curve in Klippel plots; correctly centring the coil in the gap at rest reduces the asymmetry.','Motor nonlinearity',ARRAY['Inductance asymmetry','Motor instability','Force factor','Kms(x)','Motor strength']::text[],ARRAY['Confusing motor (Bl or Le) asymmetry with suspension (Kms) asymmetry.','Ignoring that asymmetry shows mainly as even-order harmonics.','Assuming a centred coil at rest guarantees symmetry across full travel.']::text[],ARRAY['Interpreting an asymmetric Bl(x) plot.','Diagnosing even-order distortion from the motor.','Adjusting coil rest position for symmetry.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Motor asymmetry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd3cee60b-ed4f-46ab-a2e4-fe4bf9653ea9','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d3cee60b-ed4f-46ab-a2e4-fe4bf9653ea9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d3cee60b-ed4f-46ab-a2e4-fe4bf9653ea9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eed59b31-1c11-43d5-9d0b-7fa7f718975a','Motor instability','A large-signal condition where the position-dependent reluctance force (arising from Le(x)) acts as a negative stiffness that, combined with a soft suspension and an overhung coil, can overcome the restoring force. The coil is driven toward a gap extreme, causing DC offset, jumping or bifurcation, and possible coil-out failure.','Current in the coil can pull it toward the iron. That pull acts like a negative spring. If it beats the suspension, the coil drifts to one end. It may jump out and fail.','It explains a dangerous large-signal behaviour that designers guard against.','A technician links a sudden DC offset or coil creep at high drive to instability; shorting rings and stiffer, symmetric suspensions reduce it.','Motor nonlinearity',ARRAY['Motor asymmetry','Inductance modulation','Kms(x)','Motor-limited excursion','Force factor']::text[],ARRAY['Confusing motor instability with amplifier oscillation.','Assuming a driver always self-centres; the reluctance force can push it off.','Ignoring that an overhung coil with a soft suspension raises the risk.']::text[],ARRAY['Diagnosing a woofer that pulls off-centre at high level.','Explaining reluctance-force negative stiffness.','Choosing a design resistant to coil jump-out.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Motor instability');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eed59b31-1c11-43d5-9d0b-7fa7f718975a','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eed59b31-1c11-43d5-9d0b-7fa7f718975a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eed59b31-1c11-43d5-9d0b-7fa7f718975a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0a3bb670-9480-4759-b1fe-82b6c870da34','Motor strength','An informal name for a driver''s force factor Bl (in T*m, equal to N/A): how much force the motor makes per ampere of coil current. Higher motor strength gives more force, greater efficiency, and stronger electrical damping (lower Qes).','Motor strength is how hard the motor pushes per amp. It is just another name for Bl. More strength means more force and tighter control. Weak motors give looser, less efficient bass.','It is an everyday term for Bl used to compare how forceful different drivers are.','With motor strength Bl = 10 T*m and a coil current of 1.5 A, the force produced is F = Bl*i = 15 N.','Motor parameter',ARRAY['Force factor','Magnetic flux','Magnet gap','Long-coil motor','Magnetic circuit']::text[],ARRAY['Thinking motor strength and force factor differ; they are the same Bl.','Assuming higher Bl is always better; it also lowers Qes and can over-damp bass.','Confusing Bl with magnet mass or size.']::text[],ARRAY['Comparing the motor strength of two subwoofers.','Explaining why high Bl raises sensitivity.','Relating Bl to electrical damping (Qes).']::text[],'Intermediate','Motor strength = Bl ;  F = Bl * i','Motor strength is the force factor Bl; the force produced equals Bl times the coil current.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Motor strength');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0a3bb670-9480-4759-b1fe-82b6c870da34','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0a3bb670-9480-4759-b1fe-82b6c870da34') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0a3bb670-9480-4759-b1fe-82b6c870da34');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9c4b3c88-799f-4ea5-a2d7-21f7e63029e0','Motor-limited excursion','The excursion range set by the motor''s linearity, mainly the decline of Bl(x), rather than by the suspension or physical stops. Beyond it the falling force factor, not the spring, is what caps clean output; this contrasts with suspension-limited or mechanically limited excursion.','Sometimes the motor, not the suspension, limits clean travel. As the coil leaves the gap, its push (Bl) drops. That falling force sets the clean limit. This is motor-limited excursion.','It distinguishes which subsystem caps a driver''s linear travel.','A technician compares the Bl(x) width with the Kms(x) width in Klippel data; whichever is narrower limits Xmax, and an underhung or long-gap motor widens the Bl-limited range.','Excursion limit',ARRAY['Maximum linear excursion','Force factor','Long-coil motor','Motor asymmetry','Kms(x)']::text[],ARRAY['Assuming the suspension always sets the excursion limit.','Confusing motor-limited with mechanically limited (bottoming) excursion.','Ignoring Bl(x) width when judging clean output.']::text[],ARRAY['Deciding whether the motor or suspension limits Xmax.','Reading Bl(x) and Kms(x) width together.','Choosing a motor topology for wide linear travel.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Motor-limited excursion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9c4b3c88-799f-4ea5-a2d7-21f7e63029e0','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9c4b3c88-799f-4ea5-a2d7-21f7e63029e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9c4b3c88-799f-4ea5-a2d7-21f7e63029e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f03ad689-5398-43bb-91e1-eea8d74d6ce4','Moving-coil motor','An electrodynamic motor that drives a loudspeaker diaphragm by passing the audio current through a voice coil suspended in a radial magnetic gap; the current interacting with the field produces an axial force (F = Bl*i) that moves the coil and attached cone. It is the dominant transducer motor used in cone and dome drivers.','A moving-coil motor uses a wire coil sitting in a magnet gap. Audio current flows through the coil. The magnet''s field pushes the coil back and forth. The coil moves the cone, and the cone makes sound.','It converts an electrical audio signal into mechanical motion of the diaphragm so the driver can radiate sound.','A technician checks force factor and impedance; for example, with Bl = 7 T*m and a coil current of 2 A, the motor force is Bl*i = 14 N.','Motor topology',ARRAY['Moving-magnet motor','Overhung voice coil','Short-coil motor','Position-dependent force factor','Push-pull motor']::text[],ARRAY['Confusing the moving-coil motor with the moving-magnet type, where the magnet moves instead.','Assuming the force factor Bl stays constant as the coil leaves the gap.','UNSAFE: Handling large driver magnets carelessly; they can pinch fingers or snap steel tools onto the pole piece.']::text[],ARRAY['Selecting a driver by its force factor and sensitivity.','Diagnosing weak output traced to a partly demagnetized magnet.','Explaining how coil current becomes cone motion during training.']::text[],'Beginner','F = Bl * i','The axial force on the coil equals the force factor (gap flux density times the length of wire in the gap) multiplied by the coil current.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Moving-coil motor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f03ad689-5398-43bb-91e1-eea8d74d6ce4','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f03ad689-5398-43bb-91e1-eea8d74d6ce4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f03ad689-5398-43bb-91e1-eea8d74d6ce4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ff285218-21df-4043-b304-e8553bea87f5','Moving-magnet motor','A transducer motor in which the permanent magnet is the moving member attached to the diaphragm while the coil is fixed, so current in the stationary coil creates a field that drives the magnet. It is the reverse of the common moving-coil layout and lets the coil stay still.','In this motor the magnet moves, not the coil. The coil stays fixed and carries the audio current. Its field pushes the magnet, which moves the diaphragm. It is the reverse layout of a normal moving-coil driver.','It keeps the coil stationary, which stops its lead wires from flexing and helps carry heat away, while the magnet does the moving.','A technician meets this layout in some shakers and specialty drivers, choosing it when a fixed, well-cooled coil matters more than keeping moving mass low.','Motor topology',ARRAY['Moving-coil motor','Reluctance force','Push-pull motor','Short-coil motor']::text[],ARRAY['Assuming it lowers moving mass; the magnet is heavy and often raises mass.','Confusing it with the moving-coil motor, which moves the wire instead.','UNSAFE: Letting a loose moving magnet slam onto steel parts, which can crush fingers.']::text[],ARRAY['Comparing motor layouts during driver selection.','Servicing a tactile transducer or bass shaker.','Explaining why the coil can stay fixed in some designs.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Moving-magnet motor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ff285218-21df-4043-b304-e8553bea87f5','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ff285218-21df-4043-b304-e8553bea87f5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ff285218-21df-4043-b304-e8553bea87f5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c14dbab8-82fa-4733-9ea6-5b799f5299da','Nodal circle','A concentric circular line of near-zero motion on a vibrating cone or dome, marking a boundary between annular regions that move in opposite phase during a diaphragm break-up mode. Nodal circles appear above the piston band, where the diaphragm no longer moves as one rigid unit.','At high frequencies a cone stops moving as one piece. Parts of it flex in and out against each other. A nodal circle is a ring on the cone that barely moves. It divides zones that push in opposite directions.','Naming this ring helps engineers describe cone break-up patterns and locate where the surface splits into out-of-phase zones.','A technician sees nodal circles in scanning-vibrometer plots and links them to the peaks and dips in a driver''s break-up region.','Modal behavior',ARRAY['Nodal diameter','Piston band','Oil-canning mode','Orthotropic diaphragm','Paper cone']::text[],ARRAY['Confusing a nodal circle (concentric) with a nodal diameter (radial line).','Thinking the whole cone still moves as a piston at these frequencies.','Assuming the nodal lines stay fixed; they shift with frequency.']::text[],ARRAY['Reading a laser vibrometer map of a cone.','Explaining a break-up peak in a driver''s response.','Comparing stiff and soft cone materials.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nodal circle');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c14dbab8-82fa-4733-9ea6-5b799f5299da','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c14dbab8-82fa-4733-9ea6-5b799f5299da') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c14dbab8-82fa-4733-9ea6-5b799f5299da');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '99dcf35a-32fc-450e-943b-c4092289beae','Nodal diameter','A straight, diametral line of near-zero motion crossing a vibrating diaphragm, separating angular sectors that move in opposite phase during a break-up mode. The count of nodal diameters and nodal circles labels each modal shape of a circular radiator.','A nodal diameter is a straight line of near-stillness across a cone. It runs through the center like a diameter. The sectors on each side move in opposite directions. It marks one kind of cone break-up mode.','It helps classify a diaphragm''s vibration modes so engineers can predict and control break-up.','A technician counts nodal diameters and circles in a modal plot to identify which mode causes a specific resonance.','Modal behavior',ARRAY['Nodal circle','Piston band','Oil-canning mode','Orthotropic diaphragm']::text[],ARRAY['Mixing up nodal diameters (radial) with nodal circles (concentric).','Assuming these modes appear inside the useful piston band.','Believing a symmetric mode always dominates; asymmetric ones can too.']::text[],ARRAY['Identifying an asymmetric break-up mode.','Interpreting finite-element or laser modal results.','Explaining odd off-axis response wrinkles.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nodal diameter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '99dcf35a-32fc-450e-943b-c4092289beae','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='99dcf35a-32fc-450e-943b-c4092289beae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='99dcf35a-32fc-450e-943b-c4092289beae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cba0cb66-7104-4c6c-86a4-d63f19ed8f55','Oil-canning mode','A low-order diaphragm break-up in which a shallow cone or dome flexes with a large, buckling, snap-through motion resembling the popping of an oil-can bottom. It produces strong, often asymmetric distortion because the surface deforms rather than moving as a rigid piston.','Oil-canning is when a cone or dome buckles like the bottom of an oil can. The surface flexes in and out on a big scale. It is a low, coarse kind of cone break-up. It adds unwanted distortion.','The term flags a specific, audible break-up that designers try to push above the working band or damp out.','A technician suspecting oil-canning stiffens the diaphragm, adds damping, or picks a driver whose break-up sits above its crossover.','Modal behavior',ARRAY['Nodal circle','Nodal diameter','Orthotropic diaphragm','Sandwich composite','Paper cone']::text[],ARRAY['Confusing broad oil-canning with fine high-order break-up.','Assuming a stiffer cone alone always cures it, ignoring damping.','Overlooking that it can appear only at high drive levels.']::text[],ARRAY['Diagnosing coarse distortion at loud levels.','Comparing shallow versus deep cone geometries.','Choosing well-damped diaphragm materials.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Oil-canning mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cba0cb66-7104-4c6c-86a4-d63f19ed8f55','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cba0cb66-7104-4c6c-86a4-d63f19ed8f55') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cba0cb66-7104-4c6c-86a4-d63f19ed8f55');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11a470dd-a348-4a90-879f-635a288016f1','Orthotropic diaphragm','A diaphragm whose stiffness differs along different in-plane directions (for example radial versus circumferential), by design or from fiber and weave orientation. Tuning this direction-dependent stiffness lets engineers shift and smooth cone break-up modes.','An orthotropic diaphragm is stiffer in some directions than others. Fibers or ribs set the direction of the stiffness. Engineers use this to control how the cone breaks up. It helps smooth the response.','Direction-dependent stiffness gives designers a lever to move break-up resonances and reduce their severity.','A technician meets orthotropic behavior in woven-fiber or ribbed cones and expects break-up patterns that differ from a simple isotropic cone.','Diaphragm material',ARRAY['Poisson''s ratio','Sandwich composite','Nodal circle','Nodal diameter','Paper cone']::text[],ARRAY['Assuming every cone is isotropic (equal stiffness in all directions).','Ignoring fiber orientation when predicting break-up.','Treating a single stiffness value as enough to model the cone.']::text[],ARRAY['Selecting a woven-composite cone driver.','Modeling break-up in finite-element software.','Explaining why two same-size cones sound different.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Orthotropic diaphragm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11a470dd-a348-4a90-879f-635a288016f1','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11a470dd-a348-4a90-879f-635a288016f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11a470dd-a348-4a90-879f-635a288016f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '638bf8fd-4135-4cd1-a9f6-e0254cef4d33','Overhung voice coil','A voice-coil geometry in which the winding is longer than the magnetic gap, so coil turns overhang the gap at both ends of travel. This keeps a roughly constant length of wire in the field over a range of excursion, giving a more linear Bl(x) at the cost of added mass and inefficient use of flux.','In an overhung coil the winding is taller than the magnet gap. Extra turns stick out past the gap on both ends. So a steady number of turns stays in the field as the cone moves. This keeps the force steady but adds weight.','The overhang keeps the force factor stable across excursion, lowering distortion in drivers that must move far.','A technician expects overhung woofers to handle large excursion linearly, at the cost of some efficiency and heavier moving mass.','Motor topology',ARRAY['Short-coil motor','Position-dependent force factor','Peak displacement','Moving-coil motor','Push-pull motor']::text[],ARRAY['Confusing overhung (coil taller than gap) with underhung (coil shorter than gap).','Assuming overhung always means higher efficiency; it often lowers it.','Ignoring the extra moving mass the overhang adds.']::text[],ARRAY['Choosing a long-throw subwoofer driver.','Explaining a flat Bl(x) curve in a datasheet.','Comparing overhung and underhung motors.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Overhung voice coil');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '638bf8fd-4135-4cd1-a9f6-e0254cef4d33','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='638bf8fd-4135-4cd1-a9f6-e0254cef4d33') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='638bf8fd-4135-4cd1-a9f6-e0254cef4d33');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ec04498c-6376-4788-b06a-845cc677650f','Paper cone','A loudspeaker diaphragm made from felted cellulose (paper) pulp, often doped or coated, valued for a favorable balance of low mass, internal damping, and stiffness. It remains one of the most widely used cone materials across the frequency range.','A paper cone is molded from wood-pulp fibers, like thick paper. It is light, fairly stiff, and damps its own vibration well. Makers may coat or treat it. It is one of the most common cone materials.','Paper gives a low-mass, self-damping diaphragm that radiates efficiently and tames break-up better than many stiffer materials.','A technician expects treated paper cones to sound smooth through break-up but to absorb moisture unless coated.','Cone material',ARRAY['Polypropylene cone','Orthotropic diaphragm','Sandwich composite','Piston band']::text[],ARRAY['Assuming paper is low quality next to metal or composite cones.','Ignoring that untreated paper absorbs humidity and shifts parameters.','Thinking all paper cones behave the same regardless of treatment.']::text[],ARRAY['Selecting a midrange driver for smooth break-up.','Explaining parameter drift in humid conditions.','Comparing cone materials in a design review.']::text[],'Beginner',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Paper cone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ec04498c-6376-4788-b06a-845cc677650f','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ec04498c-6376-4788-b06a-845cc677650f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ec04498c-6376-4788-b06a-845cc677650f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8eede55a-ecb3-41a0-917c-ebe8637d76c0','Peak displacement','The greatest instantaneous distance the voice coil and diaphragm move from their rest position in one direction during operation, usually stated in millimetres. It is a one-way (zero-to-peak) measure, distinct from the total peak-to-peak swing.','Peak displacement is how far the cone moves from rest at its furthest, one way. It is measured from the middle to the extreme. Engineers list it in millimeters. It is half of the full back-and-forth swing.','It shows how far a driver moves before its motor or suspension runs out of linear travel, guarding against distortion and damage.','For a signal reaching 5 mm one-way peak displacement in a driver rated Xmax 4 mm, the technician expects rising distortion and reduces level.','Excursion metric',ARRAY['Peak-to-peak excursion','Rectified displacement','Overhung voice coil','Position-dependent force factor','Short-coil motor']::text[],ARRAY['Confusing one-way peak displacement with the peak-to-peak total.','Assuming the driver stays linear right up to peak displacement.','UNSAFE: Driving well past rated excursion, which can tear the suspension or slam the coil into the backplate.']::text[],ARRAY['Reading an excursion limit on a datasheet.','Setting a subwoofer limiter threshold.','Explaining audible distortion at high levels.']::text[],'Beginner',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Peak displacement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8eede55a-ecb3-41a0-917c-ebe8637d76c0','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8eede55a-ecb3-41a0-917c-ebe8637d76c0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8eede55a-ecb3-41a0-917c-ebe8637d76c0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c544b960-e1a1-4550-989c-7e8f6b4a2ea1','Peak-to-peak excursion','The total distance the voice coil and diaphragm travel between their two motion extremes in a cycle, that is the full swing from the most-forward to the most-rearward position. For symmetric motion it equals twice the one-way peak displacement.','Peak-to-peak excursion is the whole distance the cone travels. It runs from the farthest forward point to the farthest back point. For even motion it equals twice the one-way peak. Makers may quote it to show total travel.','It states the full mechanical travel a driver uses, which helps size the gap, former, and suspension for safe operation.','A driver with 4 mm one-way peak displacement shows about 8 mm peak-to-peak; the technician checks the suspension allows that full swing.','Excursion metric',ARRAY['Peak displacement','Rectified displacement','Overhung voice coil','Progressive suspension']::text[],ARRAY['Reporting peak-to-peak but comparing it to a one-way Xmax figure.','Assuming motion is symmetric when a DC offset shifts it.','UNSAFE: Ignoring total swing so the coil bottoms hard against the backplate.']::text[],ARRAY['Comparing excursion specs between drivers.','Confirming a suspension allows the full swing.','Explaining why peak-to-peak is double the one-way figure.']::text[],'Beginner','Xpp = 2 * Xpeak','The peak-to-peak excursion equals twice the one-way peak displacement, assuming forward and rearward travel are equal.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Peak-to-peak excursion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c544b960-e1a1-4550-989c-7e8f6b4a2ea1','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c544b960-e1a1-4550-989c-7e8f6b4a2ea1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c544b960-e1a1-4550-989c-7e8f6b4a2ea1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b3e1e8b0-c33c-44a0-b8c7-6a416ff2ddd6','Piston band','The frequency range over which a diaphragm moves essentially as one rigid piston, with all points in phase, before break-up modes set in. Within this band the driver''s radiation follows simple piston theory.','The piston band is the range where the whole cone moves as one solid piece. Every part moves together, in step. Simple math predicts its output here. Above this band the cone starts to flex and break up.','It defines where a driver behaves predictably, guiding crossover choices so drivers work mostly within their piston range.','A technician crosses a woofer over below its break-up so it stays in the piston band, keeping response smooth.','Radiation behavior',ARRAY['Piston diameter','Piston directivity','Nodal circle','Nodal diameter','Oil-canning mode']::text[],ARRAY['Assuming a cone stays pistonic across its whole range.','Crossing a driver over inside its break-up region.','Confusing the piston band with the flat part of the impedance curve.']::text[],ARRAY['Setting a crossover point below break-up.','Explaining why response smooths when staying pistonic.','Comparing a driver''s usable band to its size.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Piston band');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b3e1e8b0-c33c-44a0-b8c7-6a416ff2ddd6','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b3e1e8b0-c33c-44a0-b8c7-6a416ff2ddd6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b3e1e8b0-c33c-44a0-b8c7-6a416ff2ddd6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dfdcac46-3dba-4122-a6b0-63d12575bf0e','Piston diameter','The effective diameter of the radiating surface used to model a driver as a rigid circular piston, usually taken to about the middle of the surround. It sets the effective radiating area (Sd) and the frequency at which the driver becomes directional.','Piston diameter is the working width of the moving surface. It is usually measured out to the middle of the surround. It fixes the effective radiating area. It also sets where the driver starts to beam.','It provides the single size figure that piston models use to predict radiating area and directivity.','For a piston diameter of 0.13 m, the radius a = 0.065 m; the technician uses this in the product ka to judge where the driver narrows its coverage.','Radiation behavior',ARRAY['Piston directivity','Piston band','Peak displacement','Paper cone']::text[],ARRAY['Measuring the full frame diameter instead of the effective radiating diameter.','Confusing piston diameter with the nominal advertised size.','Ignoring that half of the surround adds to effective area.']::text[],ARRAY['Computing effective radiating area Sd.','Estimating the beaming frequency of a driver.','Comparing effective size across drivers.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Piston diameter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dfdcac46-3dba-4122-a6b0-63d12575bf0e','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dfdcac46-3dba-4122-a6b0-63d12575bf0e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dfdcac46-3dba-4122-a6b0-63d12575bf0e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '49ee0f89-404b-4dbd-b0ec-4589da4ba407','Piston directivity','The angular radiation pattern of a flat circular piston, which stays broad when the wavelength is large compared with the piston but narrows (beams) as frequency rises. For a piston in an infinite baffle it follows the directivity function 2*J1(ka*sin(theta))/(ka*sin(theta)).','Piston directivity describes how a driver''s output spreads with angle. At low frequencies it radiates widely. As frequency rises, the beam narrows toward the front. The pattern depends on size compared to the wavelength.','It predicts how a driver''s coverage narrows with frequency, guiding crossover and driver-size choices for even coverage.','For a 0.065 m radius piston at 3 kHz, k = 2*pi*f/c is about 55 rad/m, so ka is about 3.6 and the beam is already narrowing; the technician crosses over before it beams badly.','Radiation behavior',ARRAY['Piston diameter','Piston band','Ring radiator','Nodal circle']::text[],ARRAY['Assuming a driver radiates evenly at all frequencies.','Forgetting directivity depends on size versus wavelength (ka), not size alone.','Ignoring that off-axis response falls fastest at high frequencies.']::text[],ARRAY['Choosing a crossover so a woofer hands off before it beams.','Explaining off-axis high-frequency roll-off.','Comparing coverage of large and small drivers.']::text[],'Advanced','D(theta) = 2 * J1(ka*sin(theta)) / (ka*sin(theta))','The far-field pressure pattern of a baffled circular piston equals twice the first-order Bessel function of (wavenumber times radius times the sine of the off-axis angle), divided by that same argument.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Piston directivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '49ee0f89-404b-4dbd-b0ec-4589da4ba407','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='49ee0f89-404b-4dbd-b0ec-4589da4ba407') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='49ee0f89-404b-4dbd-b0ec-4589da4ba407');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '98be1b32-8b7f-41f7-9164-861cc01df6f3','Poisson''s ratio','A material property equal to the negative ratio of transverse strain to axial strain when a material is stretched or compressed, describing how much it contracts sideways as it is pulled lengthwise. In diaphragm design it affects how a cone or dome deforms and where its break-up modes fall.','Poisson''s ratio tells how much a material squeezes sideways when you stretch it. Pull a bar and it gets thinner. The ratio compares the sideways change to the lengthwise change. It shapes how a cone flexes.','It is one of the elastic constants engineers feed into models that predict a diaphragm''s stiffness and break-up behavior.','With an axial strain of 0.001 and a measured lateral strain of -0.0003, Poisson''s ratio nu = 0.3, a typical value the technician uses in finite-element cone models.','Material property',ARRAY['Orthotropic diaphragm','Sandwich composite','Nodal circle','Oil-canning mode']::text[],ARRAY['Forgetting the minus sign, since most materials thin as they stretch.','Assuming one Poisson''s ratio for an orthotropic (direction-dependent) material.','Confusing Poisson''s ratio with Young''s modulus.']::text[],ARRAY['Setting up a finite-element cone model.','Comparing elastic constants of cone materials.','Explaining how a diaphragm deforms under load.']::text[],'Advanced','nu = - epsilon_lateral / epsilon_axial','Poisson''s ratio equals the negative of the lateral (transverse) strain divided by the axial (loading-direction) strain.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Poisson''s ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '98be1b32-8b7f-41f7-9164-861cc01df6f3','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='98be1b32-8b7f-41f7-9164-861cc01df6f3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='98be1b32-8b7f-41f7-9164-861cc01df6f3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '79f4c6e4-c274-4f18-8002-544228c837fa','Polypropylene cone','A loudspeaker diaphragm molded from polypropylene, a thermoplastic polymer, offering high internal damping, good moisture resistance, and consistent, repeatable parameters. It is common in woofers and midranges where smooth, well-damped break-up is wanted.','A polypropylene cone is molded from a tough plastic. The plastic damps vibration strongly. It resists moisture and stays consistent between units. Makers use it widely for woofers and midranges.','Polypropylene gives a well-damped, weather-resistant diaphragm with stable, repeatable parameters for volume production.','A technician expects polypropylene woofers to have gentle break-up and to tolerate damp environments better than untreated paper.','Cone material',ARRAY['Paper cone','Sandwich composite','Orthotropic diaphragm','Piston band']::text[],ARRAY['Assuming plastic cones cannot sound accurate.','Ignoring that filled polypropylene differs from plain polypropylene.','Expecting the same stiffness as a metal or composite cone.']::text[],ARRAY['Choosing a driver for outdoor or humid use.','Explaining smooth break-up in a budget woofer.','Comparing damping across cone materials.']::text[],'Beginner',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Polypropylene cone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '79f4c6e4-c274-4f18-8002-544228c837fa','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='79f4c6e4-c274-4f18-8002-544228c837fa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='79f4c6e4-c274-4f18-8002-544228c837fa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '365beabd-d94e-4e47-9d51-55ad6371d57d','Position-dependent force factor','The way a driver''s force factor Bl varies with voice-coil displacement x, because the length of wire immersed in the gap field changes as the coil moves. A Bl(x) that falls or is asymmetric with excursion is a leading cause of large-signal distortion and dynamic DC offset.','The force factor Bl sets how hard the motor pushes. As the coil moves, less wire may sit in the strong field. So Bl changes with cone position. If it drops or is lopsided, the driver distorts at high levels.','Modeling Bl(x) lets engineers predict and reduce distortion and coil drift when a driver moves far.','A technician reads a Bl(x) curve; if Bl at +5 mm is far below the rest value, they expect compression and distortion, and may pick an overhung or underhung motor.','Nonlinear parameter',ARRAY['Position-dependent inductance','Position-dependent stiffness','Rectified displacement','Overhung voice coil','Short-coil motor']::text[],ARRAY['Treating Bl as a single constant regardless of excursion.','Ignoring Bl asymmetry, which drives the coil off-center.','Assuming a bigger magnet always fixes a Bl(x) drop.']::text[],ARRAY['Reading a Klippel large-signal report.','Diagnosing distortion that rises with level.','Choosing a motor geometry for linear force.']::text[],'Advanced','F(x, i) = Bl(x) * i','The motor force equals the displacement-dependent force factor multiplied by the coil current, so force varies with cone position as well as with current.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Position-dependent force factor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '365beabd-d94e-4e47-9d51-55ad6371d57d','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='365beabd-d94e-4e47-9d51-55ad6371d57d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='365beabd-d94e-4e47-9d51-55ad6371d57d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '57236c86-6f19-4712-8629-6ce9345d213a','Position-dependent inductance','The variation of voice-coil inductance Le with coil displacement, caused by the changing amount of iron (pole and plate) linking the coil as it moves. This nonlinearity generates a reluctance force and intermodulation distortion, especially at higher frequencies.','The coil''s inductance depends on how much iron surrounds it. As the coil moves, that iron changes. So inductance changes with cone position. This shift adds distortion, mostly at higher frequencies.','Modeling Le(x) helps engineers predict inductance-driven distortion and design shorting rings or copper caps to reduce it.','A technician sees Le rise as the coil moves toward the pole; adding a copper cap or shorting ring flattens Le(x) and lowers distortion.','Nonlinear parameter',ARRAY['Position-dependent force factor','Position-dependent stiffness','Reluctance force','Semi-inductance','Short-coil motor']::text[],ARRAY['Treating voice-coil inductance as a fixed value.','Ignoring the reluctance force that inductance variation creates.','Assuming inductance nonlinearity only matters at low frequencies.']::text[],ARRAY['Explaining rising distortion at higher frequencies.','Understanding why drivers use copper shorting rings.','Reading an Le(x) curve in a test report.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Position-dependent inductance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '57236c86-6f19-4712-8629-6ce9345d213a','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='57236c86-6f19-4712-8629-6ce9345d213a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='57236c86-6f19-4712-8629-6ce9345d213a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd6d03138-2c74-44fd-8487-1b6a7b23ef2c','Position-dependent stiffness','The change in suspension mechanical stiffness Kms (or compliance Cms) with cone displacement, as the spider and surround stiffen toward the travel limits. An asymmetric Kms(x) shifts the coil''s rest point under drive and adds distortion.','The suspension acts like a spring. It gets stiffer as the cone nears its limits. So stiffness changes with position. If it is lopsided, the cone drifts to the softer side and distorts.','Modeling Kms(x) lets engineers predict soft-clipping of excursion, coil drift, and distortion from the suspension.','A technician reads a Kms(x) curve; a strongly rising, asymmetric curve warns of a suspension that limits travel unevenly and shifts the coil off-center.','Nonlinear parameter',ARRAY['Position-dependent force factor','Position-dependent inductance','Progressive suspension','Regressive suspension','Rectified displacement']::text[],ARRAY['Treating suspension stiffness as constant with excursion.','Ignoring asymmetry that biases the coil off-center.','Confusing stiffness Kms with compliance Cms; they are reciprocals.']::text[],ARRAY['Reading a large-signal suspension curve.','Diagnosing coil drift under heavy bass.','Comparing progressive and regressive suspensions.']::text[],'Advanced','F_s(x) = Kms(x) * x','The suspension restoring force equals the displacement-dependent stiffness multiplied by the displacement, so the spring stiffens as the cone moves outward.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Position-dependent stiffness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd6d03138-2c74-44fd-8487-1b6a7b23ef2c','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d6d03138-2c74-44fd-8487-1b6a7b23ef2c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d6d03138-2c74-44fd-8487-1b6a7b23ef2c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f92625ba-b78e-4b46-8779-cb202acf23e5','Progressive suspension','A suspension designed so its stiffness rises progressively as the cone moves further from rest, giving a gradually firmer restoring force near the travel limits. This soft, gradual limiting protects the driver and can reduce abrupt distortion at the extremes.','A progressive suspension gets stiffer the further the cone moves. Near the limits it pushes back harder. This slows the cone gently before it runs out of travel. It gives smooth, gradual limiting.','It protects a driver by easing the cone to a stop, avoiding a hard mechanical crash at maximum excursion.','A technician chooses a progressively suspended woofer for long-throw bass, expecting graceful limiting rather than sudden bottoming.','Suspension behavior',ARRAY['Regressive suspension','Position-dependent stiffness','Peak displacement','Peak-to-peak excursion']::text[],ARRAY['Confusing progressive (stiffening) with regressive (softening) suspension.','Assuming a progressive suspension can never bottom out.','Expecting perfectly linear travel from any real suspension.']::text[],ARRAY['Selecting a long-throw subwoofer.','Explaining gentle excursion limiting.','Comparing suspension designs in a review.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Progressive suspension');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f92625ba-b78e-4b46-8779-cb202acf23e5','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f92625ba-b78e-4b46-8779-cb202acf23e5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f92625ba-b78e-4b46-8779-cb202acf23e5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dc49fe86-c5b8-4401-b844-538b11efad4c','Push-pull motor','A motor or driver arrangement in which two symmetric halves (for example dual coils or two opposed drivers) operate in opposition, so that even-order nonlinearities such as Bl and inductance asymmetry tend to cancel. The result is lower even-harmonic distortion than a single-ended motor.','A push-pull motor uses two matched halves working in opposite phase. One pushes while the other pulls. Their even-order distortions cancel each other. This makes the driver cleaner at high levels.','It cancels even-order distortion and inductance nonlinearity by pairing symmetric motor halves in opposition.','A technician meets push-pull layouts in dual-coil subwoofers and opposed-driver cabinets, expecting reduced even-harmonic distortion and inductance modulation.','Motor topology',ARRAY['Moving-coil motor','Reluctance force','Position-dependent inductance','Position-dependent force factor']::text[],ARRAY['Assuming push-pull cancels all distortion; it mainly targets even-order terms.','Confusing an electrical push-pull amplifier stage with a push-pull driver motor.','Expecting cancellation without well-matched halves.']::text[],ARRAY['Explaining low even-harmonic distortion in a subwoofer.','Understanding opposed-driver cabinet designs.','Comparing single-ended and push-pull motors.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Push-pull motor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dc49fe86-c5b8-4401-b844-538b11efad4c','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dc49fe86-c5b8-4401-b844-538b11efad4c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dc49fe86-c5b8-4401-b844-538b11efad4c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dc57ad4c-b158-47ce-96c9-a78adedc60fd','Rectified displacement','A steady (DC) offset in the voice coil''s average position that appears under drive when a symmetric signal meets asymmetric nonlinearities (Bl(x), Kms(x), or Le(x)), effectively rectifying some AC motion into a one-way shift. The coil typically drifts toward the softer suspension side or the weaker-Bl region, worsening distortion.','Rectified displacement is a steady drift of the cone''s center under drive. A back-and-forth signal produces a one-way shift. It happens because the motor or spring is lopsided. The drift pushes the coil off-center and adds distortion.','The concept explains why real drivers can pull off-center at high levels, helping engineers target the asymmetry that causes it.','A technician noticing a woofer that sucks in or pushes out under heavy bass suspects rectified displacement from asymmetric Bl(x) or Kms(x).','Nonlinear behavior',ARRAY['Position-dependent force factor','Position-dependent stiffness','Position-dependent inductance','Peak displacement','Rocking-mode distortion']::text[],ARRAY['Mistaking the offset for a wiring or DC-fault problem.','Assuming symmetric drive always gives symmetric motion.','UNSAFE: Ignoring a coil that drifts and rubs, which can overheat and fail the coil.']::text[],ARRAY['Diagnosing a cone that shifts off-center under bass.','Interpreting a DC-displacement plot.','Explaining intermodulation distortion from coil drift.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rectified displacement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dc57ad4c-b158-47ce-96c9-a78adedc60fd','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dc57ad4c-b158-47ce-96c9-a78adedc60fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dc57ad4c-b158-47ce-96c9-a78adedc60fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f30ed6c7-5160-4987-b717-6537dc9986a7','Regressive suspension','A suspension whose incremental stiffness decreases as the cone moves further out over some range, so the restoring force grows more slowly, or the suspension softens, with excursion. It is generally undesirable because it can allow runaway excursion and dynamic instability.','A regressive suspension gets softer as the cone moves out over part of its travel. It pushes back less just when more control is needed. This can let the cone swing too far. It is usually a fault, not a feature.','The term names a stiffness trend engineers try to avoid because it can lead to excursion runaway and instability.','A technician seeing a Kms(x) curve that dips with displacement flags a regressive region that may cause instability at high levels.','Suspension behavior',ARRAY['Progressive suspension','Position-dependent stiffness','Rocking instability','Peak displacement']::text[],ARRAY['Confusing regressive (softening) with progressive (stiffening) suspension.','Assuming a softer suspension is always safer.','Overlooking a regressive dip as a stability risk.']::text[],ARRAY['Spotting an instability risk in a suspension curve.','Comparing suspension stiffness trends.','Explaining excursion runaway at high drive.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Regressive suspension');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f30ed6c7-5160-4987-b717-6537dc9986a7','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f30ed6c7-5160-4987-b717-6537dc9986a7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f30ed6c7-5160-4987-b717-6537dc9986a7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4bd3482c-08dd-4990-a0c3-a0de787f9921','Reluctance force','A magnetic force produced when the voice-coil inductance changes with position, given by F = (1/2)*i^2*dLe/dx, arising because the coil-and-iron system tends to move toward lower magnetic reluctance (higher inductance). It acts even without a permanent magnet and adds even-order and intermodulation distortion.','A coil near iron feels a pull toward the iron, because that raises its inductance. This reluctance force depends on the current squared. So it does not reverse when the signal polarity flips. It adds distortion to the driver''s output.','Recognizing this force explains a distortion source tied to inductance change, which shorting rings and copper caps are used to suppress.','With i = 3 A and dLe/dx = 0.5 mH/m, the reluctance force is about (1/2)*(3^2)*0.0005 = 0.00225 N; the technician notes it grows with the square of current and near the pole.','Motor physics',ARRAY['Position-dependent inductance','Moving-magnet motor','Push-pull motor','Semi-inductance']::text[],ARRAY['Thinking a driver with a permanent magnet has no reluctance force.','Forgetting the force scales with current squared, not current.','Ignoring that it does not reverse when signal polarity flips.']::text[],ARRAY['Explaining distortion tied to voice-coil inductance.','Understanding why copper caps reduce distortion.','Analyzing even-order harmonic content.']::text[],'Advanced','F_rel = (1/2) * i^2 * dLe/dx','The reluctance force equals one half of the coil current squared, multiplied by the rate at which the voice-coil inductance changes with displacement.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reluctance force');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4bd3482c-08dd-4990-a0c3-a0de787f9921','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4bd3482c-08dd-4990-a0c3-a0de787f9921') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4bd3482c-08dd-4990-a0c3-a0de787f9921');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '656421b5-91f4-4f59-af95-b5e500ed2aa0','Ring radiator','A tweeter or driver whose diaphragm is a ring (annulus), typically driven near its mid-radius and combined with a central phase plug, rather than a solid dome. The annular shape and phase plug push break-up modes higher and can smooth and extend the top octave. ''Ring radiator'' describes the generic geometry; specific designs such as the Vifa/Scan-Speak ''XT'' series are made by their respective owners (Tymphany).','A ring radiator tweeter uses a ring-shaped diaphragm, not a solid dome. It is driven near the middle of the ring. A cone-shaped plug sits in the center. This design pushes break-up higher and can smooth the treble.','The ring-and-phase-plug shape moves diaphragm break-up above the audio band, aiming for smoother, extended high-frequency output.','A technician meets ring radiators in high-frequency tweeters and expects wide, smooth top-octave response; the name describes the geometry, not one brand.','Driver type',ARRAY['Nodal circle','Piston directivity','Paper cone','Orthotropic diaphragm']::text[],ARRAY['Assuming ''ring radiator'' names one company''s product; the geometry is generic.','Confusing it with a compression driver''s annular diaphragm.','Expecting ordinary dome-tweeter break-up behavior from it.']::text[],ARRAY['Selecting a tweeter for smooth extended treble.','Explaining the role of the central phase plug.','Comparing ring radiators with dome tweeters.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ring radiator');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '656421b5-91f4-4f59-af95-b5e500ed2aa0','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='656421b5-91f4-4f59-af95-b5e500ed2aa0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='656421b5-91f4-4f59-af95-b5e500ed2aa0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b2ad5a9f-9bc4-43b0-a060-a67a776e03a1','Rocking instability','A tendency of the cone-and-coil assembly to tilt or rock about a transverse axis instead of moving purely axially, driven by asymmetries in the suspension, motor, or glue joints. Severe rocking lets the coil rub the pole or gap walls and can grow unstable at high excursion.','Rocking instability is when the cone tilts side to side instead of moving straight. Small unevenness in the suspension or motor starts it. At high levels the tilt can grow. The coil may then rub and wear.','The concept flags an unwanted non-axial motion that engineers control with spider design, centering, and symmetry to protect the coil.','A technician hearing a rubbing or buzzing woofer at high level checks for rocking, uneven spider tension, or an off-center coil.','Nonlinear behavior',ARRAY['Rocking-mode distortion','Regressive suspension','Position-dependent stiffness','Overhung voice coil']::text[],ARRAY['Blaming a rubbing coil only on damage, not on rocking geometry.','Assuming a well-centered coil cannot rock under drive.','UNSAFE: Continuing to drive a rocking, rubbing coil, which overheats and destroys it.']::text[],ARRAY['Diagnosing a rubbing or buzzing driver.','Explaining why spiders and centering matter.','Investigating failures at high excursion.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rocking instability');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b2ad5a9f-9bc4-43b0-a060-a67a776e03a1','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b2ad5a9f-9bc4-43b0-a060-a67a776e03a1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b2ad5a9f-9bc4-43b0-a060-a67a776e03a1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2ec6fbe-eb77-43af-bfee-43160f1abc70','Rocking-mode distortion','Distortion and irregular radiation caused when the diaphragm rocks (tilts) rather than moving purely as a piston, producing modulation, coil rub, and uneven off-axis output. It is the audible and measurable consequence of rocking instability.','When a cone rocks instead of moving straight, it distorts the sound. The tilt changes output at different angles. The coil may rub and add noise. This is rocking-mode distortion.','The term links the physical rocking motion to its audible penalty, helping engineers justify symmetric, well-centered designs.','A technician measuring rising distortion and odd off-axis behavior at high excursion traces it to rocking-mode distortion and improves centering or spider design.','Nonlinear behavior',ARRAY['Rocking instability','Rectified displacement','Position-dependent stiffness','Nodal diameter']::text[],ARRAY['Confusing rocking-mode distortion with normal cone break-up.','Assuming it appears at all levels rather than mainly at high excursion.','Ignoring off-axis clues that point to rocking.']::text[],ARRAY['Explaining distortion that rises with excursion.','Interpreting uneven off-axis measurements.','Justifying a redesign of the spider or centering.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rocking-mode distortion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2ec6fbe-eb77-43af-bfee-43160f1abc70','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2ec6fbe-eb77-43af-bfee-43160f1abc70') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2ec6fbe-eb77-43af-bfee-43160f1abc70');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '264e3312-3dae-4f93-8f3e-4139479838f0','Rohacell core','A rigid, low-density polymethacrylimide (PMI) foam used as the lightweight core of sandwich-construction diaphragms, giving a high stiffness-to-weight ratio for cones and domes. ROHACELL is a registered trademark of Evonik (Evonik Industries / Evonik Operations GmbH); the generic material is closed-cell PMI structural foam.','A Rohacell core is a stiff, very light foam. It sits between two skins to form a sandwich cone. The foam adds stiffness with little weight. Rohacell is a brand of PMI foam owned by Evonik.','The foam core raises a diaphragm''s stiffness-to-weight ratio, pushing break-up higher while keeping moving mass low.','A technician meets Rohacell-cored cones in high-end drivers and expects high stiffness, low mass, and break-up pushed above the working band.','Diaphragm material',ARRAY['Sandwich composite','Orthotropic diaphragm','Paper cone','Piston band']::text[],ARRAY['Using ''Rohacell'' as a generic word; it is Evonik''s trademark for PMI foam.','Assuming the foam radiates sound; the skins radiate, the core stiffens.','Expecting the same behavior from any lightweight foam.']::text[],ARRAY['Reviewing a high-end sandwich-cone driver.','Explaining a very stiff, light diaphragm.','Comparing core materials in composite cones.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rohacell core');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '264e3312-3dae-4f93-8f3e-4139479838f0','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='264e3312-3dae-4f93-8f3e-4139479838f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='264e3312-3dae-4f93-8f3e-4139479838f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f7b94f85-bae7-48af-97ff-af65e6d1a1e7','Sandwich composite','A diaphragm made of two thin, stiff face skins bonded to a lightweight core (foam, honeycomb, or similar), so the pair acts as a stiff, low-mass beam. This construction maximizes bending stiffness for a given weight, raising the break-up frequency.','A sandwich composite cone has two stiff outer layers and a light middle. The core spaces the skins apart. That makes the cone very stiff for its weight. It pushes break-up higher.','It delivers a high stiffness-to-weight diaphragm, extending the pistonic range and reducing break-up in the working band.','A technician expects sandwich cones (for example skinned Rohacell or honeycomb) to stay pistonic higher, at higher cost and with care in bonding.','Diaphragm material',ARRAY['Rohacell core','Orthotropic diaphragm','Paper cone','Piston band','Poisson''s ratio']::text[],ARRAY['Assuming a single-material cone can match a sandwich''s stiffness-to-weight.','Ignoring that a weak bond between skins and core ruins performance.','Thinking thicker always means better without weighing the mass cost.']::text[],ARRAY['Selecting a stiff, light diaphragm.','Explaining an extended pistonic range.','Comparing construction methods in a design review.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sandwich composite');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f7b94f85-bae7-48af-97ff-af65e6d1a1e7','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f7b94f85-bae7-48af-97ff-af65e6d1a1e7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f7b94f85-bae7-48af-97ff-af65e6d1a1e7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ab0ff9f6-0cc6-4d58-aa27-841179c2c9b6','Semi-inductance','A circuit model of the voice coil''s lossy, frequency-dependent inductance in which the impedance rises with roughly the square root of frequency (impedance proportional to (j*omega)^n, with n near 0.5) rather than the linear rise of an ideal inductor. It captures eddy-current losses in the pole and plate; Leach''s model represents it with a semi-inductance element.','A real voice coil is not a perfect inductor. Eddy currents in the iron cause losses. So its impedance rises with about the square root of frequency, not straight up. This half-way behavior is called semi-inductance. Models use it to fit real coils.','It gives an accurate impedance model of the coil at higher frequencies, improving crossover and response predictions.','A technician fitting an impedance curve uses a semi-inductance (lossy) element instead of a plain inductor to match the gently rising high-frequency impedance.','Electrical model',ARRAY['Position-dependent inductance','Reluctance force','Moving-coil motor','Short-coil motor']::text[],ARRAY['Modeling the coil as an ideal inductor rising 6 dB per octave.','Ignoring eddy-current losses in the pole and plate.','Confusing semi-inductance with the position-dependent Le(x) nonlinearity.']::text[],ARRAY['Fitting a driver''s impedance curve.','Designing a crossover that tracks true coil impedance.','Explaining the gentle high-frequency impedance rise.']::text[],'Advanced','Z_L(omega) = K * (j*omega)^n,  n approx 0.5','The lossy coil impedance equals a constant times (j times angular frequency) raised to a power near one half, giving a rise slower than that of an ideal inductor.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Semi-inductance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ab0ff9f6-0cc6-4d58-aa27-841179c2c9b6','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ab0ff9f6-0cc6-4d58-aa27-841179c2c9b6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ab0ff9f6-0cc6-4d58-aa27-841179c2c9b6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '584212ce-3164-4823-83ca-af8c8ce3eada','Short-coil motor','A motor geometry in which the voice coil is shorter than the magnetic gap (underhung), so the entire coil stays within the gap field over its linear travel. It uses flux efficiently and keeps moving mass low, but linear excursion is limited by the extra gap height needed.','In a short-coil (underhung) motor the coil is shorter than the magnet gap. The whole coil stays in the strong field as it moves. This uses the magnet well and keeps the coil light. But it limits how far it can travel linearly.','It keeps the force factor Bl constant and moving mass low by holding the short coil fully inside a taller gap.','A technician expects underhung short-coil drivers to be efficient and low-distortion for modest excursion, but not the choice for very long-throw bass.','Motor topology',ARRAY['Overhung voice coil','Position-dependent force factor','Moving-coil motor','Peak displacement']::text[],ARRAY['Confusing short-coil (underhung) with a physically small driver.','Assuming underhung motors allow long excursion; their linear throw is limited.','Overlooking the heavier magnet system a tall gap needs.']::text[],ARRAY['Choosing an efficient, low-distortion midbass driver.','Explaining a flat Bl(x) over a small range.','Comparing underhung and overhung motors.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Short-coil motor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '584212ce-3164-4823-83ca-af8c8ce3eada','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='584212ce-3164-4823-83ca-af8c8ce3eada') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='584212ce-3164-4823-83ca-af8c8ce3eada');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cb69be1f-2587-4c93-898f-4a693e185444','Silk dome','A dome-shaped soft diaphragm, most often used for tweeters, made from woven silk cloth that is impregnated with a damping resin or coating and heat-formed into a shallow dome. The fabric and coating give it internal self-damping, so resonances are spread out and gently absorbed rather than ringing sharply.','A silk dome is a small fabric dome used in a tweeter. Woven silk is coated with resin and pressed into shape. The soft cloth soaks up its own vibrations. This gives a smooth, gentle high-frequency sound.','It provides a lightweight, self-damped high-frequency radiator whose smooth breakup makes the treble sound less harsh than a hard-metal dome.','A technician choosing a soft-dome tweeter expects a forgiving, non-peaky top end and avoids poking the fragile dome, which is easily dented and cannot always be pushed back out.','Diaphragm material',ARRAY['Titanium diaphragm','Vapor-deposited diaphragm','Surround','Young''s modulus','Specific modulus']::text[],ARRAY['Assuming silk domes are pure silk when they rely heavily on the damping coating.','Believing a soft dome must always sound better than a metal dome.','Trying to reshape a dented fabric dome, which usually damages it further.']::text[],ARRAY['Selecting a tweeter for a smooth, laid-back high-frequency character.','Explaining why a soft dome shows gentle breakup instead of a sharp peak.','Diagnosing a dented dome and its effect on high-frequency response.']::text[],'Beginner',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Silk dome');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cb69be1f-2587-4c93-898f-4a693e185444','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cb69be1f-2587-4c93-898f-4a693e185444') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cb69be1f-2587-4c93-898f-4a693e185444');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '458ea5c5-853f-4d70-a010-f6ec287939e7','Specific modulus','The ratio of a material''s Young''s modulus to its density, giving stiffness per unit mass. In loudspeaker cones and domes it predicts how high in frequency a diaphragm can stay piston-like before breakup, because a high specific modulus pushes bending resonances upward.','Specific modulus is stiffness divided by weight for a material. A high value means stiff but light. Cone makers want this to be high. It keeps the cone rigid up to higher frequencies before it flexes.','It lets a designer compare cone and dome materials on stiffness-for-weight, which sets how far a diaphragm behaves as a rigid piston.','For aluminium, Young''s modulus about 69 GPa and density 2700 kg/m^3 give a specific modulus of about 2.56x10^7 m^2/s^2 (about 25.6 MJ/kg), higher than most plastics, so aluminium cones stay stiff to a higher frequency.','Material property',ARRAY['Young''s modulus','Titanium diaphragm','Silk dome','Vapor-deposited diaphragm','Stress relaxation']::text[],ARRAY['Confusing specific modulus with Young''s modulus alone and ignoring density.','Assuming the highest specific modulus always wins, ignoring internal damping.','Forgetting that a light stiff cone can still ring badly without damping.']::text[],ARRAY['Comparing aluminium, paper, and composite cones for stiffness-to-weight.','Explaining why beryllium domes push breakup very high.','Choosing a diaphragm material to raise the piston-band limit.']::text[],'Advanced','E_s = E / rho','Specific modulus equals the Young''s modulus divided by the material''s density.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Specific modulus');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '458ea5c5-853f-4d70-a010-f6ec287939e7','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='458ea5c5-853f-4d70-a010-f6ec287939e7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='458ea5c5-853f-4d70-a010-f6ec287939e7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f512ab41-64c6-4667-99ee-1eabc69e2321','Spider','The inner suspension of a dynamic driver, usually a corrugated ring of resin-impregnated woven fabric that connects the voice-coil former to the frame. It centres the coil in the magnetic gap, supplies most of the mechanical restoring force, and lets the cone move axially while blocking side-to-side rocking.','The spider is a flexible ring inside a speaker. It links the voice coil to the frame. It keeps the coil centred in the magnet gap. It also acts like a spring that pushes the cone back to rest.','It centres and guides the voice coil while providing the main restoring stiffness that returns the cone to its rest position.','A technician re-gluing a cone checks the spider is flat and concentric so the coil sits centred in the gap; an off-centre spider causes rubbing and buzzing.','Suspension',ARRAY['Surround','Suspension creep','Spider linearity','Suspension symmetry','Voice-coil rubbing']::text[],ARRAY['Thinking the surround, not the spider, provides most of the restoring force.','Ignoring that a distorted spider lets the coil rub in the gap.','Assuming the spider only centres the coil and stores no stiffness.']::text[],ARRAY['Reconing a woofer and aligning the spider concentrically.','Diagnosing a rubbing voice coil caused by a warped spider.','Explaining where a driver''s low-frequency stiffness comes from.']::text[],'Beginner',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spider');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f512ab41-64c6-4667-99ee-1eabc69e2321','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f512ab41-64c6-4667-99ee-1eabc69e2321') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f512ab41-64c6-4667-99ee-1eabc69e2321');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '48c4c7a4-06e6-43da-9a57-e105ce6f82a8','Spider linearity','How closely the spider''s restoring force stays proportional to displacement as the coil moves. Because the corrugations stiffen progressively at large excursion, real spiders are nonlinear; the stiffness Kms rises with displacement, and any front-to-back asymmetry adds even-order distortion and can push the coil off-centre.','Spider linearity means the spider acts like an even spring. A perfect spring pushes back in step with how far it moves. Real spiders get stiffer at large travel. Uneven stiffness bends the sound and adds distortion.','It describes how faithfully the inner suspension follows the signal, which controls low-frequency distortion at high excursion.','A designer measures stiffness Kms(x) versus displacement; a symmetric, gently rising curve keeps distortion low, while a lopsided curve makes the resting coil drift toward the softer side.','Suspension behavior',ARRAY['Spider','Suspension symmetry','Surround linearity','Suspension creep','Suspension-limited excursion']::text[],ARRAY['Assuming a spider is a perfectly linear spring at all excursions.','Overlooking that asymmetric spider stiffness creates even-order distortion.','Ignoring that a soft-side offset shifts the coil rest position.']::text[],ARRAY['Measuring Kms(x) to predict large-signal distortion.','Explaining even-harmonic rise as excursion increases.','Choosing a spider profile to keep stiffness symmetric.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spider linearity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '48c4c7a4-06e6-43da-9a57-e105ce6f82a8','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='48c4c7a4-06e6-43da-9a57-e105ce6f82a8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='48c4c7a4-06e6-43da-9a57-e105ce6f82a8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9c2a3b39-bcc9-4841-9f13-b457e94627e4','Stress relaxation','The gradual fall in internal stress within a viscoelastic material held at a fixed strain over time. In loudspeaker suspensions, holding the spider or surround at a constant deflection makes the resisting force decay, which lowers effective stiffness and shifts parameters such as resonance frequency.','Stress relaxation happens when a material is bent and held still. Over time it pushes back with less force. Speaker suspensions do this. The spring gets a little weaker while held in one position.','It explains why a suspension held or worked at constant deflection loses stiffness over time, a key part of driver break-in and long-term drift.','A technician who measures resonance frequency right after flexing a new driver, then again after rest, sees fs settle as the suspension stress relaxes, so break-in matters before final tuning.','Material behavior',ARRAY['Viscoelastic creep','Suspension creep','Suspension aging','Spider','Surround']::text[],ARRAY['Confusing stress relaxation (fixed strain) with creep (fixed load).','Assuming suspension stiffness never changes over time.','Measuring fs before break-in and treating it as final.']::text[],ARRAY['Explaining why a new driver''s resonance drops after break-in.','Interpreting parameter drift in a suspension held under strain.','Comparing fresh and exercised drivers during QC.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stress relaxation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9c2a3b39-bcc9-4841-9f13-b457e94627e4','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9c2a3b39-bcc9-4841-9f13-b457e94627e4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9c2a3b39-bcc9-4841-9f13-b457e94627e4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2eaf3310-c05e-42d2-a610-c2dda0f84637','Surround','The outer suspension of a dynamic driver, a flexible ring, often a half-roll, joining the cone edge to the frame. It seals the moving cone to the basket, allows long axial travel, adds a share of restoring stiffness, and helps damp and terminate cone-edge resonances.','The surround is the flexible ring around the edge of a cone. It joins the cone to the frame. It lets the cone move in and out. It also seals the front of the cone from the back.','It seals and guides the cone edge while allowing large excursion and contributing part of the suspension stiffness.','A technician replacing a rotted foam surround matches roll shape and compliance so excursion and resonance frequency stay close to the original design.','Suspension',ARRAY['Spider','Tangential surround','Surround linearity','Suspension aging','Suspension-limited excursion']::text[],ARRAY['Assuming the surround supplies most restoring force, when the spider usually does.','Fitting a stiffer or wrong-profile surround and shifting fs.','Ignoring that surround roll direction affects excursion symmetry.']::text[],ARRAY['Re-foaming a woofer whose surround has crumbled.','Explaining how the surround seals front and rear cone radiation.','Selecting surround compliance to hit a target resonance.']::text[],'Beginner',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surround');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2eaf3310-c05e-42d2-a610-c2dda0f84637','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2eaf3310-c05e-42d2-a610-c2dda0f84637') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2eaf3310-c05e-42d2-a610-c2dda0f84637');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4ab5c05b-bcbf-4fb6-aaa8-73df9240aa34','Surround linearity','How proportional the surround''s restoring force stays as the cone moves. A half-roll surround stiffens and can pull unevenly at large excursion; asymmetry between in and out travel adds even-order distortion and, combined with the spider, sets where mechanical excursion is limited.','Surround linearity means the outer ring pushes back evenly with travel. Real surrounds get stiffer at large movement. In and out travel may not match. This unevenness adds distortion at high volume.','It describes the surround''s contribution to large-signal stiffness symmetry, which affects distortion and the excursion limit.','A designer pairs surround and spider so their combined stiffness Kms(x) is symmetric; a surround that stiffens hard on outward travel can clip the positive half of excursion.','Suspension behavior',ARRAY['Surround','Spider linearity','Suspension symmetry','Suspension-limited excursion','Tangential surround']::text[],ARRAY['Treating the surround as a linear spring at all excursions.','Ignoring that surround and spider must be balanced together.','Overlooking asymmetric roll geometry as a distortion source.']::text[],ARRAY['Balancing surround and spider stiffness for symmetric travel.','Diagnosing even-order distortion from an asymmetric surround.','Predicting where outward excursion becomes limited.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surround linearity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4ab5c05b-bcbf-4fb6-aaa8-73df9240aa34','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4ab5c05b-bcbf-4fb6-aaa8-73df9240aa34') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4ab5c05b-bcbf-4fb6-aaa8-73df9240aa34');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5fe9dd8f-19fb-4444-b087-eb25dc484498','Suspension aging','The long-term change in a driver''s suspension properties from repeated flexing, heat, humidity, ultraviolet light, and oxidation. Foam surrounds may crumble, rubber can harden or soften, and adhesives can weaken, all shifting compliance, resonance frequency, and eventually reliability.','Suspension aging is how the spider and surround change over years. Heat, light, air, and use all wear them out. Foam can rot and crumble. Rubber can harden. The speaker''s tuning drifts as a result.','It captures how a suspension degrades with time and environment, which affects long-term performance and service life.','A technician servicing older studio monitors inspects foam surrounds for rot and re-tests fs, since an aged suspension changes tuning and may fail.','Suspension behavior',ARRAY['Suspension creep','Stress relaxation','Surround','Viscoelastic creep','Spider']::text[],ARRAY['Assuming a driver''s parameters stay fixed for its whole life.','Blaming electronics when an aged surround has shifted the tuning.','Ignoring environmental factors like ultraviolet light and humidity.']::text[],ARRAY['Refurbishing vintage speakers with rotted foam surrounds.','Explaining why old drivers measure differently from new ones.','Planning preventive maintenance for a fleet of loudspeakers.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Suspension aging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5fe9dd8f-19fb-4444-b087-eb25dc484498','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5fe9dd8f-19fb-4444-b087-eb25dc484498') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5fe9dd8f-19fb-4444-b087-eb25dc484498');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dc4d618d-afe9-4b3a-b64e-5884481058b1','Suspension creep','The slow, time-dependent increase in a suspension''s deflection when held under a constant force, a viscoelastic effect. It makes stiffness frequency-dependent: many suspensions are noticeably softer at very low frequencies and DC than at the resonance frequency, which the LR-2 creep model in Klippel measurements accounts for.','Suspension creep is slow give under a steady push. Hold a load on the spider and it keeps stretching a little. This makes the suspension softer at very low frequencies. It behaves like a spring that relaxes over time.','It explains why suspension stiffness is not constant but depends on frequency and time, affecting low-frequency behavior and modeling accuracy.','A technician modeling a woofer includes a creep factor so the simulated compliance at DC is higher than at fs, matching measured low-frequency impedance and displacement.','Suspension behavior',ARRAY['Viscoelastic creep','Stress relaxation','Suspension aging','Spider','Surround']::text[],ARRAY['Assuming suspension stiffness is a single fixed number.','Confusing creep (constant load) with stress relaxation (constant strain).','Ignoring creep when modeling low-frequency response.']::text[],ARRAY['Fitting a creep model to match low-frequency impedance.','Explaining softer DC stiffness than resonance stiffness.','Interpreting drift in measured compliance over time.']::text[],'Advanced','Kms(f) with creep: Kms lower at DC than at fs','Effective suspension stiffness varies with frequency because of viscoelastic creep, being lower toward DC than at the resonance frequency.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Suspension creep');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dc4d618d-afe9-4b3a-b64e-5884481058b1','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dc4d618d-afe9-4b3a-b64e-5884481058b1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dc4d618d-afe9-4b3a-b64e-5884481058b1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fed858ed-cc31-4f6f-b20f-15f5cd58e507','Suspension noise','Unwanted mechanical sounds produced by the suspension itself, such as ticking, rustling, creaking, or friction noise from the spider, surround, or lead wires. It is a defect distinct from the intended acoustic output and often signals damage, contamination, or a manufacturing fault.','Suspension noise is extra sound from the spider or surround. It can be a tick, creak, or rustle. It is not part of the music. It usually means something is worn, loose, or dirty.','As a quality and fault indicator, it flags suspensions that are damaged, contaminated, or badly assembled and need attention.','During end-of-line testing a technician drives a low-frequency tone and listens for ticking or rustling that reveals a cracked spider, loose lead wire, or debris in the gap.','Suspension defect',ARRAY['Voice-coil rubbing','Spider','Surround','Suspension aging','Suspension creep']::text[],ARRAY['Confusing suspension noise with normal driver output.','Overlooking loose lead wires slapping the cone as a source.','Assuming all buzzing is the voice coil rubbing.']::text[],ARRAY['End-of-line rub-and-buzz testing of drivers.','Diagnosing a ticking noise from a cracked spider.','Tracing a rustle to debris trapped in the suspension.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Suspension noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fed858ed-cc31-4f6f-b20f-15f5cd58e507','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fed858ed-cc31-4f6f-b20f-15f5cd58e507') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fed858ed-cc31-4f6f-b20f-15f5cd58e507');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '21ec438e-6ffc-486b-a593-21a386e923c5','Suspension symmetry','How equally a suspension resists inward and outward cone travel. When stiffness Kms(x) is symmetric about rest, distortion stays low; asymmetry produces mainly even-order harmonics and a DC offset that pushes the resting coil toward the softer side, worsening at high excursion.','Suspension symmetry means the spring feels the same pushing in and out. If it is even, distortion stays low. If one side is softer, the coil drifts that way. Uneven suspensions add even-order distortion.','It sets how balanced the restoring force is, which controls even-order distortion and whether the coil stays centred at high drive.','A designer inspects the measured Kms(x) curve for symmetry; a lopsided curve is corrected by adjusting spider or surround geometry so the coil does not creep off-centre under bass drive.','Suspension behavior',ARRAY['Symmetric magnetic circuit','Spider linearity','Surround linearity','Suspension-limited excursion','Suspension creep']::text[],ARRAY['Assuming a suspension resists in and out travel equally by default.','Blaming only the motor when asymmetric suspension adds even harmonics.','Ignoring the DC offset that asymmetry causes at high excursion.']::text[],ARRAY['Reading a Kms(x) curve for front-to-back balance.','Diagnosing even-order distortion and coil drift under bass.','Tuning spider and surround for symmetric compliance.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Suspension symmetry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '21ec438e-6ffc-486b-a593-21a386e923c5','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='21ec438e-6ffc-486b-a593-21a386e923c5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='21ec438e-6ffc-486b-a593-21a386e923c5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e870de51-0356-49fb-a785-2537dd680dc1','Suspension-limited excursion','The condition where a driver''s usable travel is capped by the suspension stiffening steeply, rather than by the voice coil leaving the magnetic gap. Beyond this point the rapidly rising Kms adds heavy distortion and can tear the spider or surround, so it marks a mechanical excursion limit.','This is when the spider and surround, not the magnet, set the travel limit. The suspension stiffens hard near the end of its range. Pushing past it adds heavy distortion. It can also tear the suspension.','It identifies the mechanical ceiling on cone movement set by suspension stiffness, protecting against overdrive damage and defining maximum output at low frequencies.','A technician setting a high-pass or limiter keeps a subwoofer below the excursion where the suspension slams stiff, preventing distortion and physical damage to the spider or surround.','Excursion limit',ARRAY['Suspension symmetry','Spider linearity','Surround linearity','Spider','Surround']::text[],ARRAY['Confusing suspension-limited excursion with Bl-limited (motor) excursion.','Assuming the coil leaving the gap is always the first limit.','Driving past the mechanical limit and tearing the surround.']::text[],ARRAY['Setting subwoofer limiters below the mechanical travel limit.','Explaining sudden distortion rise at very high excursion.','Diagnosing a torn surround from over-excursion.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Suspension-limited excursion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e870de51-0356-49fb-a785-2537dd680dc1','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e870de51-0356-49fb-a785-2537dd680dc1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e870de51-0356-49fb-a785-2537dd680dc1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1e248861-e4f5-47ab-ae16-f5287710827c','Symmetric magnetic circuit','A motor design whose magnetic field in the gap is balanced about the coil rest position, so the force factor Bl(x) falls off equally for inward and outward travel. Features such as a T-shaped pole with a matching plate, faraday rings, or extended pole tips are used to symmetrize Bl(x) and reduce even-order distortion.','This is a motor built so the magnet field is even around the coil. The push on the coil then drops off equally in and out. That keeps the force balanced during large travel. Balanced force means lower even-order distortion.','It keeps the motor force factor Bl(x) symmetric about rest so large-signal distortion and coil offset stay low.','A designer shapes pole pieces and adds shorting rings so the measured Bl(x) curve is symmetric; this cuts second-harmonic distortion compared with a lopsided motor.','Motor design',ARRAY['Underhung voice coil','Suspension symmetry','Voice-coil inductance','Voice-coil current','Spider linearity']::text[],ARRAY['Assuming any motor gives symmetric Bl(x) without special design.','Ignoring that inductance Le(x) asymmetry also adds distortion.','UNSAFE: handling powerful neodymium magnet assemblies loosely, which can snap together and crush fingers or launch steel tools; keep hands, ferrous objects, and pacemakers clear.']::text[],ARRAY['Designing a woofer motor for low even-harmonic distortion.','Comparing Bl(x) curves of symmetric and asymmetric motors.','Adding shorting rings to linearize the magnetic gap.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Symmetric magnetic circuit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1e248861-e4f5-47ab-ae16-f5287710827c','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1e248861-e4f5-47ab-ae16-f5287710827c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1e248861-e4f5-47ab-ae16-f5287710827c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b945e9d7-f6c5-43d0-87eb-1ce4f52fcfe8','Tangential surround','A surround whose roll is broken into angled, tangentially oriented segments or corrugations rather than a single smooth ring. The geometry equalizes stiffness around the circumference, resists uneven pull, and helps suppress asymmetric rocking modes while allowing controlled axial excursion.','A tangential surround has angled sections instead of one smooth ring. The angled shape spreads the springiness evenly around the edge. This helps stop the cone from rocking side to side. It keeps motion straight and even.','It evens out edge stiffness and controls rocking modes, keeping cone motion axial and reducing asymmetry-driven distortion.','A technician selecting a replacement surround matches a tangential pattern where the original used one, since the segmented geometry sets both compliance and rock-mode control.','Suspension',ARRAY['Surround','Surround linearity','Suspension symmetry','Spider','Suspension-limited excursion']::text[],ARRAY['Treating a tangential surround as merely decorative.','Swapping it for a plain half-roll and changing rock-mode behavior.','Assuming all surrounds have identical stiffness distribution.']::text[],ARRAY['Matching a segmented surround pattern during a re-foam.','Explaining how surround geometry curbs rocking modes.','Comparing tangential and plain-roll surround compliance.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tangential surround');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b945e9d7-f6c5-43d0-87eb-1ce4f52fcfe8','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b945e9d7-f6c5-43d0-87eb-1ce4f52fcfe8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b945e9d7-f6c5-43d0-87eb-1ce4f52fcfe8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '51709271-6ad6-490f-a019-51556b4e9eac','Titanium diaphragm','A thin titanium dome or membrane used mainly in compression drivers and some tweeters. Titanium''s high stiffness-to-weight ratio pushes its breakup resonances into the high treble, giving extended response and durability, though the metal ring at breakup usually needs damping or equalization.','A titanium diaphragm is a thin metal dome. It is used in horn compression drivers and some tweeters. Titanium is light but very stiff. That lets it play high notes and take rough handling. The metal can ring, so it is damped or equalized.','It provides a rugged, high-frequency-capable diaphragm for compression drivers, extending usable response while surviving high drive levels.','A technician rebuilding a horn driver fits the exact titanium diaphragm and phasing plug spacing specified, because clearances are tiny and mismatched parts cause rubbing or failure.','Diaphragm material',ARRAY['Silk dome','Vapor-deposited diaphragm','Specific modulus','Young''s modulus','Voice-coil temperature']::text[],ARRAY['Assuming a metal diaphragm has no resonance to control.','Fitting a diaphragm not matched to the exact driver model.','UNSAFE: standing close to a horn-loaded compression driver at high SPL without hearing protection; levels near the mouth can exceed 120 dB and cause immediate hearing damage.']::text[],ARRAY['Replacing a blown compression-driver diaphragm.','Explaining why a metal dome needs a breakup notch or EQ.','Choosing a high-output driver for a horn-loaded PA.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Titanium diaphragm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '51709271-6ad6-490f-a019-51556b4e9eac','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='51709271-6ad6-490f-a019-51556b4e9eac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='51709271-6ad6-490f-a019-51556b4e9eac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1c552325-4a0f-48f4-99b7-246406a407c4','Underhung voice coil','A coil-and-gap arrangement where the voice-coil winding is shorter than the magnetic gap height, so the whole coil stays immersed in the field throughout its travel. This keeps the force factor Bl nearly constant over the excursion range, lowering distortion, at the cost of a heavier magnet and lower efficiency than an overhung design.','An underhung coil is shorter than the magnet gap. The whole coil stays inside the strong field as it moves. So the push on the coil barely changes with travel. This lowers distortion, but needs a bigger, heavier magnet.','It holds the force factor Bl steady across excursion to reduce large-signal distortion, trading efficiency and magnet size for linearity.','A designer choosing an underhung motor for a high-fidelity woofer accepts a bigger magnet and lower sensitivity to gain flatter Bl(x) and lower distortion.','Voice coil',ARRAY['Symmetric magnetic circuit','Voice-coil inductance','Voice-coil current','Suspension-limited excursion','Voice-coil temperature']::text[],ARRAY['Mixing up underhung (coil shorter than gap) with overhung (coil taller than gap).','Expecting high efficiency from an underhung motor.','Assuming underhung alone guarantees symmetric Bl without good gap design.']::text[],ARRAY['Selecting a low-distortion woofer motor topology.','Explaining the efficiency cost of underhung designs.','Comparing Bl(x) flatness of underhung and overhung coils.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Underhung voice coil');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1c552325-4a0f-48f4-99b7-246406a407c4','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1c552325-4a0f-48f4-99b7-246406a407c4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1c552325-4a0f-48f4-99b7-246406a407c4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3c2862fc-2200-4692-865e-8497fd809935','Vapor-deposited diaphragm','A diaphragm formed or coated by depositing material from a vapor phase, such as physical or chemical vapor deposition, onto a substrate or mandrel. The process builds very thin, uniform, and often exotic layers (for example diamond-like carbon or beryllium coatings) that raise stiffness and push breakup resonances higher.','This diaphragm is built by laying down material as a vapor. The vapor coats a form in a very thin, even layer. It can use special hard materials. The result is a light, stiff dome that plays very high before it flexes.','It creates ultra-thin, high-stiffness diaphragms with controlled thickness, extending high-frequency piston behavior beyond what molded parts allow.','A technician handling a vapor-deposited dome, such as a diamond or beryllium-coated tweeter, avoids touching or flexing it, since the thin coating is brittle and cannot be repaired.','Diaphragm material',ARRAY['Titanium diaphragm','Silk dome','Specific modulus','Young''s modulus','Stress relaxation']::text[],ARRAY['Assuming a deposited coating is as tough as it is stiff.','Confusing vapor deposition with simple painting or plating.','UNSAFE: grinding or breaking beryllium diaphragms, whose dust is toxic if inhaled; damaged units must be handled and disposed of per the manufacturer''s safety guidance.']::text[],ARRAY['Servicing a high-end tweeter with a coated dome.','Explaining why deposited diaphragms extend treble response.','Handling brittle diamond or beryllium domes safely.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vapor-deposited diaphragm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3c2862fc-2200-4692-865e-8497fd809935','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3c2862fc-2200-4692-865e-8497fd809935') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3c2862fc-2200-4692-865e-8497fd809935');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '336a1271-833f-46c4-844b-a5fb68e76c61','Viscoelastic creep','The combined elastic-and-viscous response of a polymer or rubber that makes it deform slowly and continue to give under a sustained load. In loudspeaker suspensions it is the physical cause of suspension creep and time- and frequency-dependent stiffness, and it also contributes internal damping.','Viscoelastic creep is slow give in rubber and plastic. These materials act part spring, part thick liquid. Under a steady load they keep stretching a bit. This is why speaker suspensions soften at very low frequencies.','It is the material-science basis for why suspensions and some diaphragm coatings show time-dependent stiffness and built-in damping.','A technician who understands viscoelastic creep expects a rubber-surround woofer to measure a lower resonance after prolonged use, and models it with a frequency-dependent compliance.','Material behavior',ARRAY['Suspension creep','Stress relaxation','Suspension aging','Surround','Spider']::text[],ARRAY['Treating rubber and foam as ideal, time-independent springs.','Confusing creep (constant load) with stress relaxation (constant strain).','Ignoring the damping that viscoelasticity also provides.']::text[],ARRAY['Explaining time-dependent stiffness in rubber surrounds.','Modeling frequency-dependent compliance in a woofer.','Relating material choice to suspension damping.']::text[],'Advanced',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Viscoelastic creep');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '336a1271-833f-46c4-844b-a5fb68e76c61','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='336a1271-833f-46c4-844b-a5fb68e76c61') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='336a1271-833f-46c4-844b-a5fb68e76c61');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd1707559-b230-406b-83e3-c41372805660','Voice-coil current','The electrical current flowing through the voice-coil winding, set by the drive voltage and the coil''s frequency-dependent impedance. This current in the magnetic field produces the motor force through F = Bl*i, so it is the direct link between amplifier output and cone motion; it also heats the coil.','Voice-coil current is the current the amplifier pushes through the coil. The drive voltage and the coil impedance set how much flows. That current in the magnet makes the force that moves the cone. It also heats the coil up.','It is the quantity that both drives cone motion, through the force factor, and dissipates heat in the coil.','With 20 V rms across an 8 ohm nominal driver the current is about 2.5 A; if Bl is 10 T*m the motor force is about 25 N (F = Bl*i).','Motor parameter',ARRAY['Voice-coil inductance','Voice-coil temperature','Symmetric magnetic circuit','Underhung voice coil','Voice-coil thermal resistance']::text[],ARRAY['Using only the nominal impedance and ignoring its rise with frequency.','Forgetting that inductance makes current lag and fall at high frequency.','UNSAFE: probing live voice-coil or amplifier output terminals at high power; contact can shock, arc, or damage hearing, especially if the driver is bridged or fed from a high-voltage 70/100 V distributed line.']::text[],ARRAY['Estimating driver current draw from amplifier voltage.','Relating current to motor force in a design calculation.','Explaining why current falls off as inductance rises.']::text[],'Intermediate','i = v / |Z| ,  F = Bl * i','Voice-coil current equals the drive voltage divided by the coil impedance magnitude; that current times the force factor Bl gives the motor force.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voice-coil current');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd1707559-b230-406b-83e3-c41372805660','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d1707559-b230-406b-83e3-c41372805660') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d1707559-b230-406b-83e3-c41372805660');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '07569d60-fd8a-49c9-ab0e-7e88e7d9012a','Voice-coil inductance','The self-inductance of the voice coil, symbol Le, arising because the coil is a wound solenoid, often around iron. Its reactance rises with frequency (X_L = 2*pi*f*Le), which raises impedance and rolls off high-frequency output; Le also varies with cone position, adding distortion.','Voice-coil inductance is the coil acting like an inductor. Its opposition to current grows with frequency. This lifts the driver''s impedance at high frequencies. It also reduces high-frequency output. The value shifts as the coil moves.','It explains the rising high-frequency impedance and treble roll-off of a driver, and, through Le(x), a source of large-signal distortion.','For Le = 0.5 mH at 10 kHz the inductive reactance is X_L = 2*pi*10000*0.0005 which is about 31 ohms, well above the DC resistance, so impedance climbs steeply in the treble.','Electrical parameter',ARRAY['Voice-coil current','Voice-coil temperature','Symmetric magnetic circuit','Underhung voice coil','Voice-coil thermal resistance']::text[],ARRAY['Assuming impedance stays at the nominal value across all frequencies.','Ignoring that Le changes with coil position and adds distortion.','Confusing rising impedance from inductance with a crossover effect.']::text[],ARRAY['Explaining the high-frequency impedance rise on an impedance plot.','Designing a crossover that accounts for driver inductance.','Interpreting Le(x) curves for distortion analysis.']::text[],'Intermediate','X_L = 2 * pi * f * Le','The coil''s inductive reactance equals two pi times the frequency times the voice-coil inductance.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voice-coil inductance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '07569d60-fd8a-49c9-ab0e-7e88e7d9012a','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='07569d60-fd8a-49c9-ab0e-7e88e7d9012a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='07569d60-fd8a-49c9-ab0e-7e88e7d9012a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7ad5fcf-011b-4077-9709-f44ac1d199fa','Voice-coil rubbing','A fault where the voice-coil former or winding scrapes the pole piece or top plate inside the magnetic gap during motion. Causes include an off-centre spider, a deformed former, debris in the gap, or a partly collapsed coil from overheating; it produces scratching or buzzing noise and accelerates failure.','Voice-coil rubbing is the coil scraping the metal in the magnet gap. It makes a scratchy or buzzing sound. Causes include an off-centre spider, a bent coil, or dirt in the gap. It quickly wears the coil out.','As a fault symptom, it signals a misaligned, damaged, or contaminated motor that needs recentering, cleaning, or reconing.','Hearing a scratchy buzz on bass notes, a technician gently presses the cone evenly; if rubbing is felt, the driver needs recentering, gap cleaning, or a recone.','Voice coil defect',ARRAY['Suspension noise','Spider','Voice-coil temperature','Suspension symmetry','Symmetric magnetic circuit']::text[],ARRAY['Mistaking voice-coil rubbing for normal suspension noise.','Blowing debris deeper into the gap instead of removing it carefully.','Ignoring heat-collapsed coils as a cause of rubbing.']::text[],ARRAY['Diagnosing a scratchy buzz on a bass-heavy track.','Checking gap alignment after a driver is dropped.','Cleaning ferrofluid or metal debris from a rubbing coil.']::text[],'Intermediate',NULL,NULL,'5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voice-coil rubbing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7ad5fcf-011b-4077-9709-f44ac1d199fa','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7ad5fcf-011b-4077-9709-f44ac1d199fa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7ad5fcf-011b-4077-9709-f44ac1d199fa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5bdc60bf-e1c2-4c96-8566-672219d8b532','Voice-coil temperature','The operating temperature of the voice-coil winding, which rises with input power because most electrical power is dissipated as heat in the coil. Because copper resistance climbs with temperature, a hot coil raises Re, causing power compression, and sustained high temperature can char the former, adhesive, or wire and destroy the driver.','Voice-coil temperature is how hot the coil gets in use. Most amplifier power turns into heat in the coil. As it heats, its resistance rises and output drops. Too much heat burns the coil and kills the speaker.','It governs power handling, thermal power compression, and the thermal failure limit of a driver.','Using copper''s temperature coefficient (about 0.0039 per deg C), a 6 ohm coil at 25 C that rises 125 C reads Re = 6*(1 + 0.0039*125) which is about 8.9 ohms, so output sags as the coil heats.','Thermal parameter',ARRAY['Voice-coil thermal resistance','Voice-coil current','Voice-coil inductance','Titanium diaphragm','Voice-coil rubbing']::text[],ARRAY['Assuming voice-coil resistance is constant regardless of power.','Blaming the amplifier for output loss that is really thermal compression.','UNSAFE: touching a driver''s voice coil, pole piece, or basket right after high-power use; coil temperatures can exceed 150-200 C and cause burns, and a hot magnet assembly stays hot for minutes.']::text[],ARRAY['Explaining power compression during a loud, sustained show.','Sizing amplifier power to stay within thermal limits.','Diagnosing a burnt-open coil after overpowering.']::text[],'Intermediate','Re(T) = Re0 * [1 + alpha * (T - T0)]','The coil resistance at temperature T equals its reference resistance times one plus copper''s temperature coefficient times the temperature rise.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voice-coil temperature');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5bdc60bf-e1c2-4c96-8566-672219d8b532','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5bdc60bf-e1c2-4c96-8566-672219d8b532') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5bdc60bf-e1c2-4c96-8566-672219d8b532');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4c700bae-4048-4bae-92c9-cdab7a28bf55','Voice-coil thermal resistance','The thermal resistance between the voice coil and a reference point such as the magnet structure or ambient air, expressed in kelvin (or degrees Celsius) per watt. It sets how much the coil temperature rises per watt of dissipated power, so a lower value means better cooling and higher power handling.','Voice-coil thermal resistance shows how hard it is for coil heat to escape. It is measured in degrees per watt. A low value means the coil cools well. That lets the driver take more power before it overheats.','It quantifies a driver''s cooling ability, linking dissipated power to coil temperature rise and thus to power handling.','If the coil-to-air thermal resistance is 2 K/W and the coil dissipates 50 W, the steady temperature rise is about 2*50 = 100 K above ambient (Rth = deltaT / P).','Thermal parameter',ARRAY['Voice-coil temperature','Voice-coil current','Voice-coil inductance','Underhung voice coil','Symmetric magnetic circuit']::text[],ARRAY['Confusing thermal resistance with electrical resistance.','Assuming thermal resistance is constant, ignoring airflow and heat sinking.','Overlooking a single thermal resistance versus separate coil-to-magnet and magnet-to-air paths.']::text[],ARRAY['Estimating coil temperature rise from continuous power.','Comparing vented and sealed motor cooling designs.','Setting a safe long-term power limit from thermal data.']::text[],'Advanced','Rth = (T_vc - T_amb) / P','Thermal resistance equals the temperature difference between voice coil and surroundings divided by the power dissipated as heat.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voice-coil thermal resistance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4c700bae-4048-4bae-92c9-cdab7a28bf55','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4c700bae-4048-4bae-92c9-cdab7a28bf55') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4c700bae-4048-4bae-92c9-cdab7a28bf55');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b4a273f8-a580-4a73-b7a3-317e95da3fef','Young''s modulus','A material''s elastic (tensile) modulus, the ratio of tensile stress to tensile strain in the linear elastic region, measured in pascals. In loudspeakers it governs diaphragm and former stiffness and, with density, sets the speed of bending waves and the frequency at which a cone or dome breaks up.','Young''s modulus measures how stiff a material is. It is stress divided by strain when you stretch it. A high value means the material resists bending. Stiffer cone material breaks up at a higher frequency.','It is the basic stiffness measure used to predict how rigid a diaphragm or former is and where its resonances fall.','For a rod under stress 1x10^8 Pa (100 N on 1 mm^2) with strain 0.001, Young''s modulus is E = stress/strain = 1x10^11 Pa, that is 100 GPa, typical of a stiff metal.','Material property',ARRAY['Specific modulus','Titanium diaphragm','Silk dome','Vapor-deposited diaphragm','Stress relaxation']::text[],ARRAY['Confusing Young''s modulus (stiffness) with strength or hardness.','Using Young''s modulus alone and ignoring density for cone breakup.','Applying it beyond the linear elastic region where it no longer holds.']::text[],ARRAY['Comparing candidate cone materials by stiffness.','Predicting the breakup frequency of a diaphragm.','Explaining why stiff formers resist bell-mode ringing.']::text[],'Intermediate','E = sigma / epsilon = (F/A) / (dL/L)','Young''s modulus equals tensile stress divided by tensile strain, where stress is force per unit area and strain is the fractional change in length.','5133f8bd-e4cc-4be3-8133-ccccd41e05e2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Young''s modulus');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b4a273f8-a580-4a73-b7a3-317e95da3fef','5133f8bd-e4cc-4be3-8133-ccccd41e05e2',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b4a273f8-a580-4a73-b7a3-317e95da3fef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b4a273f8-a580-4a73-b7a3-317e95da3fef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8015d659-8444-426b-881b-27a185537bcb','1/f noise','A low-frequency noise whose power spectral density rises inversely with frequency, so it dominates a microphone or preamplifier''s noise well below a few hundred hertz. It is also called flicker noise and arises in semiconductors, resistors, and active devices from carrier trapping and related mechanisms.','This is a background hiss that grows louder toward the lowest frequencies. It is also called flicker noise. It comes from the electronics inside a microphone or preamp, not the sound. Engineers fight it with better parts and circuit design.','It names the noise that sets the low-frequency limit of a microphone channel''s dynamic range and cannot be removed by simple filtering without losing wanted low bass.','An engineer choosing a low-noise preamp compares 1/f corner frequencies; below the corner, halving frequency roughly adds 3 dB of noise power.','Noise',ARRAY['A-weighted self-noise','Acoustic noise floor','Brownian noise','Charge amplifier','Complex sensitivity']::text[],ARRAY['Assuming 1/f noise is white; its level actually climbs as frequency falls.','Blaming room rumble for a rising low-frequency hiss that is really circuit flicker noise.','Thinking a high-pass filter removes it without also cutting desired low bass.']::text[],ARRAY['Comparing datasheet noise curves when picking a preamp for quiet, low-frequency measurement.','Troubleshooting excess low-end hiss in a condenser microphone front end.','Explaining why microphone self-noise specs are weighted rather than flat.']::text[],'Advanced','S(f) = K / f^a,  a approximately 1','The noise power spectral density equals a device constant divided by frequency raised to an exponent near one.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='1/f noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8015d659-8444-426b-881b-27a185537bcb','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8015d659-8444-426b-881b-27a185537bcb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8015d659-8444-426b-881b-27a185537bcb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5ee9b2c3-3887-4060-a1de-2df0f79a4651','A-weighted self-noise','The equivalent noise level of a microphone expressed as the A-weighted sound pressure level that would produce the same output as the device''s own inherent noise. It is stated in dB(A) referenced to 20 micropascals and is the standard figure for comparing microphone self-noise.','Every microphone makes a little noise of its own with no sound present. This number says how loud a real sound would need to be to match that noise. It uses A-weighting, which follows human hearing. Lower dB(A) means a quieter, better microphone.','It gives one hearing-weighted number for a microphone''s inherent noise so technicians can rank models and predict usable quiet-signal range.','A studio condenser rated 7 dB(A) is far quieter than a measurement microphone at about 15 dB(A); the difference is roughly 8 dB of noise.','Noise',ARRAY['1/f noise','Acoustic noise floor','Brownian noise','Complex sensitivity','Calibration uncertainty']::text[],ARRAY['Confusing self-noise, which is inherent, with the acoustic noise floor of the room.','Comparing an A-weighted figure directly against an unweighted (CCIR or flat) noise figure.','Forgetting the 20 micropascal reference, which fixes 0 dB SPL at the hearing threshold.']::text[],ARRAY['Choosing a microphone quiet enough to record a soft solo instrument.','Reading a condenser datasheet''s equivalent noise level line.','Explaining why two microphones with equal sensitivity can sound differently noisy.']::text[],'Beginner','L_A = 20*log10( p_eq / p_0 ) [A-weighted],  p_0 = 20 uPa','The A-weighted self-noise equals twenty times the base-ten log of the equivalent noise pressure divided by the 20 micropascal reference.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='A-weighted self-noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5ee9b2c3-3887-4060-a1de-2df0f79a4651','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5ee9b2c3-3887-4060-a1de-2df0f79a4651') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5ee9b2c3-3887-4060-a1de-2df0f79a4651');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '097080b1-1cb3-4ff1-bdc7-0d7f40ccd297','Acoustic mesh','The fine metal or fabric screen placed over a microphone capsule or a MEMS sound port that lets sound pass while blocking dust, moisture, and light wind. In small devices it also provides electromagnetic shielding and can add controlled acoustic resistance.','This is the small screen over a microphone''s opening. It lets sound in but keeps out dust, water, and wind. On phones and earbuds it also blocks electrical interference. It must not choke the sound it protects.','It protects the delicate diaphragm and port from contamination and interference while keeping the acoustic path open.','A technician replacing a clogged phone microphone mesh restores lost high-frequency output and level caused by blocked airflow.','Construction',ARRAY['Acoustic noise floor','Backplate perforation','Capacitive MEMS microphone','Bulk micromachining','Back-volume compliance']::text[],ARRAY['Assuming the mesh is purely cosmetic when it also shields and damps.','Blocking or painting over the mesh, which muffles and dulls the sound.','Ignoring a clogged mesh as a cause of weak or dull microphone output.']::text[],ARRAY['Diagnosing a muffled smartphone microphone caused by pocket lint in the mesh.','Selecting a rugged microphone with a protective mesh for field work.','Explaining why a MEMS port needs a screen against dust ingress.']::text[],'Beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic mesh');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '097080b1-1cb3-4ff1-bdc7-0d7f40ccd297','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='097080b1-1cb3-4ff1-bdc7-0d7f40ccd297') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='097080b1-1cb3-4ff1-bdc7-0d7f40ccd297');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ff6b10f8-a396-4eb0-b438-ea0de562be0d','Acoustic noise floor','The background acoustic sound pressure level present in a space, which sets the lowest sound a microphone can usefully capture regardless of how quiet the microphone itself is. It is a property of the environment, not of the microphone''s electronics.','Every room has some quiet background sound. It comes from air systems, traffic, and other sources. This background sets the softest sound you can record clearly. Even a perfect microphone cannot hear below it.','It defines the environmental limit on quiet-signal capture and measurement, separate from the microphone''s own self-noise.','If a room''s acoustic noise floor is 30 dB SPL, a microphone with 10 dB(A) self-noise still cannot resolve sounds beneath that 30 dB level.','Noise',ARRAY['A-weighted self-noise','1/f noise','Brownian noise','Acoustic mesh','Calibration uncertainty']::text[],ARRAY['Confusing the room''s acoustic noise floor with the microphone''s electronic self-noise.','Expecting a quieter microphone to lower the actual background noise in a room.','Ignoring heating and cooling systems as a major contributor to the floor.']::text[],ARRAY['Measuring background level before rating a studio''s suitability for quiet recording.','Explaining why a whisper cannot be captured cleanly in a noisy room.','Setting realistic dynamic-range expectations for a field recording site.']::text[],'Beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic noise floor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ff6b10f8-a396-4eb0-b438-ea0de562be0d','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ff6b10f8-a396-4eb0-b438-ea0de562be0d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ff6b10f8-a396-4eb0-b438-ea0de562be0d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8ead692-03b3-437b-9119-789d9bd16e42','Adaptive beamformer','A microphone-array processor whose combining weights adapt in real time to the measured statistics of the incoming signals, steering the beam toward a wanted source while placing nulls on interference and noise. Minimum-variance and generalized-sidelobe-canceller designs are common examples.','This is smart array processing that changes as sounds change. It listens to several microphones at once. It keeps the wanted talker loud and cancels noise from other directions. It updates itself many times per second.','It improves the wanted signal against interference by continuously reshaping the array''s spatial response as conditions change.','In a conference speakerphone, an adaptive beamformer tracks the active talker and nulls a noisy projector fan behind the array.','Array Processing',ARRAY['Beamformer weight','Capon beamformer','Broadband beamformer','Blind beamforming','Amplitude shading']::text[],ARRAY['Assuming a fixed beam pattern when the weights actually change with the scene.','Ignoring array calibration errors, which degrade adaptive null depth badly.','Expecting perfect cancellation when reverberation spreads interference across directions.']::text[],ARRAY['Cleaning up a talker''s voice in a noisy conference room.','Suppressing steady machinery noise while keeping a moving speaker clear.','Comparing fixed and adaptive beamformers for a voice interface.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Adaptive beamformer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8ead692-03b3-437b-9119-789d9bd16e42','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8ead692-03b3-437b-9119-789d9bd16e42') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8ead692-03b3-437b-9119-789d9bd16e42');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11618700-ff3c-4d68-9018-02cc92676ae4','Always-on microphone','A low-power microphone, usually a MEMS type, that listens continuously so a device can detect a wake word or voice activity without a button press. It runs at very low current and typically buffers only a short window of audio until a trigger wakes the main system.','This microphone never fully sleeps. It listens quietly all the time for a wake word. It uses very little power to do this. When it hears the trigger, it wakes the rest of the device.','It enables hands-free voice activation by keeping a low-power listening path alive while the main processor stays off.','A technician integrating a smart speaker sets the always-on MEMS microphone to a low-power mode that only wakes the CPU on a detected keyword.','Microphone Type',ARRAY['Capacitive MEMS microphone','Acoustic mesh','Adaptive beamformer','Bulk micromachining','Amplitude shading']::text[],ARRAY['Assuming always-on means always recording and uploading; it usually only buffers locally until a trigger.','Overlooking the low-power current budget that limits its front-end design.','Confusing wake-word listening with full continuous transcription.']::text[],ARRAY['Designing voice wake-up for a battery-powered smart speaker.','Explaining privacy behavior of a voice assistant''s listening microphone.','Selecting a MEMS part rated for low-power always-listening operation.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Always-on microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11618700-ff3c-4d68-9018-02cc92676ae4','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11618700-ff3c-4d68-9018-02cc92676ae4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11618700-ff3c-4d68-9018-02cc92676ae4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '83a4a4f4-3083-4392-95bb-d2059ae5e2e6','Amplitude shading','The deliberate tapering of the amplitude weights applied across a microphone array''s elements, giving central elements more weight than edge elements to lower the spatial sidelobes of the beam. It trades a wider main lobe for reduced pickup from off-axis directions.','In an array, each microphone gets a weight before the signals add. Amplitude shading makes the middle microphones count more than the edges. This lowers unwanted pickup from the sides. The cost is a slightly wider main beam.','It suppresses the spatial sidelobes that otherwise let sound leak in from unwanted directions, at the cost of some angular resolution.','Applying a Taylor or Chebyshev taper to a line array of microphones can drop first sidelobes well below the main beam while widening it modestly.','Array Processing',ARRAY['Beamformer weight','Array aperture','Broadband beamformer','Adaptive beamformer']::text[],ARRAY['Expecting lower sidelobes with no penalty; the main beam always widens.','Confusing amplitude shading with steering, which sets phase, not amplitude.','Applying a taper without accounting for the loss in array gain.']::text[],ARRAY['Reducing off-axis leakage in a fixed conferencing microphone array.','Choosing a window function to balance beamwidth against sidelobe level.','Explaining why a shaded array rejects room reflections better.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Amplitude shading');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '83a4a4f4-3083-4392-95bb-d2059ae5e2e6','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='83a4a4f4-3083-4392-95bb-d2059ae5e2e6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='83a4a4f4-3083-4392-95bb-d2059ae5e2e6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee77cefc-9119-46f5-8ac4-4ed304d0d440','Array aperture','The overall physical size, or span, of a microphone array, which together with wavelength sets its angular resolution and directivity. A larger aperture relative to wavelength gives a narrower main beam and finer ability to separate sources by direction.','Aperture is how big the array is overall. A bigger array can focus more tightly on a direction. It works best when its size is large compared with the sound''s wavelength. Small arrays cannot separate low bass well.','It quantifies the array''s spatial extent, the main lever controlling beamwidth and the ability to resolve sources by angle.','For a uniform line array of N elements spaced d apart, the aperture is (N-1)d; a 0.5 m aperture at 1 kHz spans over one wavelength.','Array Processing',ARRAY['Array matching','Amplitude shading','Circular microphone array','Beamformer weight','Broadband beamformer']::text[],ARRAY['Confusing aperture (total array size) with the spacing between neighboring elements.','Expecting sharp directivity at low frequencies where aperture is small versus wavelength.','Ignoring spatial aliasing that appears when element spacing exceeds half a wavelength.']::text[],ARRAY['Sizing a microphone array to resolve two talkers a set angle apart.','Explaining why a small array cannot beamform useful bass directionality.','Trading array length against portability in a conferencing product.']::text[],'Intermediate','L = (N - 1) * d ;  delta_theta approximately lambda / L','Array length equals the element count minus one times the spacing; beamwidth is roughly wavelength divided by aperture.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Array aperture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee77cefc-9119-46f5-8ac4-4ed304d0d440','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee77cefc-9119-46f5-8ac4-4ed304d0d440') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee77cefc-9119-46f5-8ac4-4ed304d0d440');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e001db0c-4e38-42ac-98c2-d3084e545e29','Array matching','The process and requirement of making the individual microphones in an array agree closely in sensitivity, frequency response, and phase so that beamforming behaves as designed. Mismatch between elements raises sidelobes, shallows nulls, and degrades directivity.','Every microphone in an array must behave nearly the same. Their loudness, tone, and timing should match. If they differ, the array cannot focus or cancel noise well. Makers sort and correct microphones to keep them matched.','It ensures the array''s elements are close enough in response that combining them yields the intended, sharp spatial pattern.','A technician applies stored per-microphone correction filters so a production array''s null on interference stays deep despite part-to-part variation.','Array Processing',ARRAY['Array aperture','Complex sensitivity','Adaptive beamformer','Beamformer weight','Calibration drift']::text[],ARRAY['Assuming nominally identical microphones are matched without measuring them.','Ignoring phase mismatch, which harms null depth more than small gain errors.','Forgetting that aging and temperature can drift elements out of match over time.']::text[],ARRAY['Calibrating a conferencing array during manufacturing test.','Diagnosing poor noise cancellation traced to a drifted array element.','Specifying tolerance limits for microphones used in a beamforming product.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Array matching');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e001db0c-4e38-42ac-98c2-d3084e545e29','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e001db0c-4e38-42ac-98c2-d3084e545e29') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e001db0c-4e38-42ac-98c2-d3084e545e29');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c79af294-339e-49db-967f-49c056761741','Back-volume compliance','The acoustic compliance of the sealed air volume behind a microphone diaphragm, which acts as a spring that stores energy under pressure. Its value depends on the enclosed volume and the air''s density and sound speed, and it strongly shapes the capsule''s low-frequency stiffness and resonance.','Behind the diaphragm is a small sealed pocket of air. That trapped air acts like a spring. A bigger pocket is a softer spring and lets the diaphragm move more easily. This shaping controls how the capsule handles low and mid frequencies.','It models the trapped air''s springiness, a key element setting a capsule''s resonant frequency and low-frequency behavior.','For a back cavity of volume V, the acoustic compliance is V divided by (air density times sound speed squared); a 100 cubic millimetre cavity gives a stiff, small compliance.','Construction',ARRAY['Backplate perforation','Capacitance variation','Capacitive MEMS microphone','Acoustic mesh','Complex sensitivity']::text[],ARRAY['Treating the back cavity as inert when its springiness sets capsule resonance.','Assuming a fully sealed cavity; a static vent is needed for barometric equalisation.','Confusing acoustic compliance (springiness) with acoustic mass or resistance.']::text[],ARRAY['Modelling a MEMS capsule''s low-frequency roll-off from its back volume.','Explaining why a smaller back cavity stiffens a capsule''s response.','Designing a capsule resonance by tuning the enclosed air volume.']::text[],'Advanced','C_a = V / (rho_0 * c^2)','Acoustic compliance equals the back-cavity volume divided by air density times the square of the speed of sound.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Back-volume compliance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c79af294-339e-49db-967f-49c056761741','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c79af294-339e-49db-967f-49c056761741') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c79af294-339e-49db-967f-49c056761741');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4c1fb46b-523f-4825-a5d6-b35646b51b35','Backplate perforation','The pattern of small holes bored through the fixed backplate of a condenser or MEMS capsule, sitting close behind the diaphragm. The holes and the thin air film between plate and diaphragm set the squeeze-film damping and acoustic resistance that shape the capsule''s response and resonance.','The back plate behind the diaphragm has tiny holes. Air must squeeze through the gap and holes as the diaphragm moves. This squeezing acts like a shock absorber. Designers tune the holes to control the microphone''s response.','It provides the controlled air damping that tames the capsule''s mechanical resonance and flattens its frequency response.','A capsule designer adjusts hole size and count to set squeeze-film damping so the diaphragm resonance is critically damped, not peaky.','Construction',ARRAY['Back-volume compliance','Capacitance variation','Capacitive MEMS microphone','Acoustic mesh','Bulk micromachining']::text[],ARRAY['Thinking the holes only relieve pressure, ignoring their damping role.','Assuming more or bigger holes always improve response; they change damping either way.','Overlooking how the thin air film, not just the holes, sets the resistance.']::text[],ARRAY['Tuning a MEMS backplate perforation to flatten a resonance peak.','Explaining why a condenser capsule''s response depends on backplate geometry.','Comparing capsule designs with different backplate hole patterns.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Backplate perforation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4c1fb46b-523f-4825-a5d6-b35646b51b35','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4c1fb46b-523f-4825-a5d6-b35646b51b35') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4c1fb46b-523f-4825-a5d6-b35646b51b35');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f562f5c-cb5e-4654-b0fc-842f5fce755f','Barometric pressure coefficient','The change in a microphone''s sensitivity per unit change in the static atmospheric (barometric) pressure surrounding it, usually stated in decibels per kilopascal. For laboratory standard condenser microphones it is a small negative value, so sensitivity falls slightly as static pressure rises.','Weather and altitude change the air pressure around a microphone. That slowly shifts how sensitive the microphone is. The change is small but real. Calibration labs correct for it to keep measurements accurate.','It lets metrology technicians correct a microphone''s calibrated sensitivity for the actual barometric pressure at the time and place of use.','With a coefficient near -0.012 dB/kPa, a 5 kPa drop in barometric pressure changes sensitivity by about +0.06 dB, which precise work must correct.','Calibration',ARRAY['Calibration drift','Calibration uncertainty','Comparison calibration','Complex sensitivity','Back-volume compliance']::text[],ARRAY['Ignoring barometric correction in precise sound-level measurements at altitude.','Assuming the coefficient is positive; for standard capsules it is slightly negative.','Confusing the static pressure coefficient with the temperature coefficient.']::text[],ARRAY['Correcting a reference microphone''s sensitivity for weather during a field survey.','Applying altitude corrections during precision acoustic metrology.','Reading the influence-coefficient table on a measurement microphone datasheet.']::text[],'Advanced','delta_L = k_p * (P - P_ref)','The sensitivity change in decibels equals the static pressure coefficient times the difference between actual and reference barometric pressure.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Barometric pressure coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f562f5c-cb5e-4654-b0fc-842f5fce755f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f562f5c-cb5e-4654-b0fc-842f5fce755f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f562f5c-cb5e-4654-b0fc-842f5fce755f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '80cebce3-5574-4cc1-8183-53faedce87f1','Beamformer weight','The complex coefficient, carrying both a gain and a phase, that is applied to one microphone channel of an array before all channels are summed. The full set of weights defines the array''s spatial response, steering the main beam and shaping its nulls.','Before an array adds its microphone signals, each one is scaled and delayed. That scale-and-delay is the weight for that microphone. The whole set of weights decides where the array listens. Changing them steers and shapes the beam.','It is the basic control variable of beamforming, setting how each channel contributes to the combined array output.','An engineer computes weights as the conjugate of each channel''s steering value so signals from the look direction add in phase.','Array Processing',ARRAY['Amplitude shading','Adaptive beamformer','Capon beamformer','Broadband beamformer','Array aperture']::text[],ARRAY['Treating weights as real gains only, ignoring their essential phase part.','Forgetting that the output uses the conjugate (Hermitian) of the weight vector.','Assuming one weight set works across all frequencies in a wideband signal.']::text[],ARRAY['Setting delay-and-sum weights to steer a fixed array toward a talker.','Updating weights adaptively to null a moving interferer.','Explaining how a taper is applied through the array''s weights.']::text[],'Intermediate','y = w^H * x = sum_n conj(w_n) * x_n','The array output is the Hermitian (conjugate-transpose) weight vector times the vector of channel signals, summed over channels.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beamformer weight');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '80cebce3-5574-4cc1-8183-53faedce87f1','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='80cebce3-5574-4cc1-8183-53faedce87f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='80cebce3-5574-4cc1-8183-53faedce87f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b37f156-1b81-45b7-b5b6-7ca4bc948b40','Blind beamforming','Microphone-array processing that separates or enhances sources without prior knowledge of the array geometry or the source directions, relying instead on statistical properties of the signals themselves. Independent component analysis and related blind source separation methods are typical approaches.','Normal beamforming needs to know where the microphones and sound are. Blind methods do not. They learn from the sound statistics alone. This helps when the setup is unknown or changing.','It enables source separation and enhancement when array calibration or source-location information is unavailable or unreliable.','A technician applies blind source separation to split two overlapping talkers recorded by an uncalibrated pair of microphones.','Array Processing',ARRAY['Adaptive beamformer','Beamformer weight','Capon beamformer','Broadband beamformer','Array matching']::text[],ARRAY['Expecting blind methods to beat calibrated beamforming when geometry is known.','Ignoring permutation and scaling ambiguities inherent in blind separation.','Assuming convergence is guaranteed in strong reverberation.']::text[],ARRAY['Separating mixed voices from an unknown microphone setup.','Enhancing speech when array geometry cannot be measured.','Comparing blind separation against a known-geometry beamformer.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Blind beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b37f156-1b81-45b7-b5b6-7ca4bc948b40','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b37f156-1b81-45b7-b5b6-7ca4bc948b40') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b37f156-1b81-45b7-b5b6-7ca4bc948b40');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96044de1-3afe-42f2-8f8d-7e5ab52896fd','Bootstrapped input','A circuit technique that raises effective input impedance by driving one end of a component with a buffered copy of the input voltage, so almost no signal current flows through it. In condenser microphone front ends it preserves very high input impedance and protects low-frequency response.','A condenser microphone needs an extremely high input resistance. Bootstrapping fakes an even higher one. It feeds a copy of the signal back so little current is lost. This keeps the low bass from leaking away.','It boosts the effective input impedance of a preamplifier stage so a high-impedance capsule keeps its full low-frequency output.','A designer bootstraps the gate-bias resistor of a condenser microphone JFET stage to hold input impedance high and extend bass response.','Circuit',ARRAY['Charge amplifier','Capacitance variation','Constant-current line drive','Back-volume compliance','Complex sensitivity']::text[],ARRAY['Thinking the bootstrap adds signal gain; it only raises the effective input impedance while the stage stays near unity gain.','Assuming a bootstrap gives infinite impedance; parasitics still set a limit.','Overlooking stability, since positive feedback can cause oscillation if overdone.']::text[],ARRAY['Designing the input stage of a condenser microphone preamplifier.','Extending low-frequency response of a high-impedance capsule buffer.','Explaining why a JFET gate resistor is bootstrapped rather than grounded directly.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bootstrapped input');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96044de1-3afe-42f2-8f8d-7e5ab52896fd','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96044de1-3afe-42f2-8f8d-7e5ab52896fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96044de1-3afe-42f2-8f8d-7e5ab52896fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ef710b4f-162c-4127-a933-a741cab807fd','Broadband beamformer','A beamformer engineered to keep a consistent beam pattern across a wide frequency band, compensating for the fact that a fixed array''s beamwidth naturally narrows as frequency rises. It is typically built as a filter-and-sum structure or a frequency-invariant design.','A plain array listens more tightly at high frequencies than low ones. That makes speech sound uneven across its range. A broadband beamformer fixes this. It keeps the beam shape steady over the whole band.','It provides a frequency-independent spatial response so wideband signals such as speech are captured with even directionality.','A conferencing array uses per-band filters so its beam covers the same angle at 300 Hz and 3 kHz, keeping a talker''s voice natural.','Array Processing',ARRAY['Adaptive beamformer','Beamformer weight','Amplitude shading','Array aperture','Capon beamformer']::text[],ARRAY['Assuming a single delay-and-sum weight set gives even coverage across a band.','Ignoring that beamwidth scales with wavelength for a fixed array.','Overlooking the extra filtering cost of frequency-invariant designs.']::text[],ARRAY['Designing even speech pickup for a wideband conferencing microphone.','Explaining why a fixed array sounds tonally uneven off axis.','Choosing a filter-and-sum structure for broadband voice capture.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Broadband beamformer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ef710b4f-162c-4127-a933-a741cab807fd','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ef710b4f-162c-4127-a933-a741cab807fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ef710b4f-162c-4127-a933-a741cab807fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1af44aae-c117-403c-b1ea-dcd5ca9ed86b','Brownian noise','In transducer engineering, the fundamental noise from the random thermal (Brownian) motion of air molecules and lossy mechanical elements, which sets a microphone''s ultimate acoustic self-noise floor. By the fluctuation-dissipation theorem, any acoustic resistance produces a force-noise power spectral density of four times Boltzmann''s constant, temperature, and that resistance.','Air molecules jiggle randomly because they are warm. That jiggle pushes on the diaphragm and makes a tiny hiss. This sets the lowest noise a microphone can ever reach. Smaller, lossier capsules hit this limit sooner.','It defines the physics-based lower bound on microphone self-noise that no electronics can beat, guiding capsule design toward low acoustic loss.','A MEMS designer lowers acoustic resistance in the vent and backplate to cut Brownian force noise, since it scales with four times k, T, and resistance.','Noise',ARRAY['A-weighted self-noise','1/f noise','Acoustic noise floor','Backplate perforation','Capacitive MEMS microphone']::text[],ARRAY['Confusing thermal Brownian noise with the spectral color called brown or red noise.','Believing better electronics can push self-noise below the Brownian floor.','Ignoring that higher acoustic loss (resistance) raises this noise.']::text[],ARRAY['Explaining why tiny MEMS capsules have higher self-noise than large diaphragms.','Setting the theoretical noise limit when designing a low-noise microphone.','Distinguishing physical thermal noise from a synthesized brown-noise test signal.']::text[],'Advanced','S_F = 4 * k_B * T * R_a','The thermal force-noise power spectral density equals four times Boltzmann''s constant times absolute temperature times the acoustic resistance.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Brownian noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1af44aae-c117-403c-b1ea-dcd5ca9ed86b','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1af44aae-c117-403c-b1ea-dcd5ca9ed86b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1af44aae-c117-403c-b1ea-dcd5ca9ed86b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c0ff4c48-7bef-48f9-ae07-09533392f13c','Bulk micromachining','A microelectromechanical fabrication method that etches deep into or entirely through the bulk of a silicon wafer to form structures such as a microphone''s diaphragm and its back cavity. It contrasts with surface micromachining, which builds thin structural layers on top of the wafer.','MEMS microphones are carved from silicon chips. Bulk micromachining cuts deep into the silicon itself. It shapes the thin diaphragm and the air cavity behind it. This is different from building layers on the surface.','It forms the three-dimensional diaphragm and back-cavity structures a silicon microphone needs directly out of the wafer body.','A MEMS microphone maker uses a deep silicon etch to open the back cavity that sets the capsule''s compliance and low-frequency response.','Fabrication',ARRAY['Capacitive MEMS microphone','Back-volume compliance','Backplate perforation','Always-on microphone','Acoustic mesh']::text[],ARRAY['Confusing bulk micromachining with surface micromachining of thin films.','Assuming all MEMS microphones use identical fabrication flows.','Overlooking how the etched back cavity governs low-frequency behavior.']::text[],ARRAY['Explaining how a silicon microphone''s back cavity is formed.','Comparing MEMS process choices for microphone performance.','Understanding a MEMS microphone datasheet''s construction notes.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bulk micromachining');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c0ff4c48-7bef-48f9-ae07-09533392f13c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c0ff4c48-7bef-48f9-ae07-09533392f13c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c0ff4c48-7bef-48f9-ae07-09533392f13c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1532b3fe-f4e7-4744-ae84-0c4dc44d650d','Calibration drift','The slow change in a microphone''s sensitivity or frequency response over time and use, which gradually moves its output away from the value set at its last calibration. It is why measurement microphones carry a recommended recalibration interval.','A microphone slowly changes how it responds as it ages. This drift makes its old calibration data wrong. So labs recheck each microphone on a set schedule. That keeps your measurements trustworthy.','It captures the aging-related shift that makes periodic recalibration necessary for accurate measurement microphones.','A lab tracks a reference microphone''s sensitivity across yearly calibrations and retires it if drift exceeds its stated tolerance.','Calibration',ARRAY['Calibration uncertainty','Comparison calibration','Barometric pressure coefficient','Complex sensitivity','Array matching']::text[],ARRAY['Assuming a calibrated microphone stays accurate indefinitely without rechecks.','Confusing gradual drift with a sudden fault from damage or contamination.','Skipping recalibration intervals for precision measurement work.']::text[],ARRAY['Setting a recalibration schedule for a measurement microphone.','Deciding whether an aged reference microphone still meets tolerance.','Explaining why field microphones need a daily calibrator check.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Calibration drift');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1532b3fe-f4e7-4744-ae84-0c4dc44d650d','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1532b3fe-f4e7-4744-ae84-0c4dc44d650d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1532b3fe-f4e7-4744-ae84-0c4dc44d650d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9a3fc4b2-6c0b-42b2-968c-15cb0a8105b8','Calibration uncertainty','The quantified doubt associated with a microphone calibration result, expressed as an uncertainty interval with a stated coverage factor, following the internationally agreed GUM framework. It combines contributions such as reference standard error, environmental corrections, and measurement repeatability.','No calibration is perfectly exact. Calibration uncertainty states how much the result might be off. It is given as a range with a confidence level. Smaller uncertainty means a more trustworthy number.','It tells the user how much confidence to place in a calibrated sensitivity value and lets results be compared meaningfully.','A certificate might state a pressure sensitivity with an expanded uncertainty of a few hundredths of a decibel at a coverage factor of two, near ninety-five percent confidence.','Calibration',ARRAY['Calibration drift','Comparison calibration','Barometric pressure coefficient','Complex sensitivity','A-weighted self-noise']::text[],ARRAY['Treating a calibrated value as exact and ignoring its stated uncertainty.','Reporting uncertainty without stating the coverage factor or confidence level.','Confusing uncertainty (a range of doubt) with a single measurement error.']::text[],ARRAY['Reading the uncertainty line on a microphone calibration certificate.','Deciding whether two microphones agree within their combined uncertainties.','Building an uncertainty budget for an acoustic measurement.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Calibration uncertainty');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9a3fc4b2-6c0b-42b2-968c-15cb0a8105b8','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9a3fc4b2-6c0b-42b2-968c-15cb0a8105b8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9a3fc4b2-6c0b-42b2-968c-15cb0a8105b8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '41ccb36e-2a9d-4485-9839-0f74cfa17a0f','Capacitance variation','The change in a condenser microphone capsule''s capacitance as sound pressure moves the diaphragm and alters the gap between it and the fixed backplate. With a nearly constant charge on the capsule, this small capacitance change produces the microphone''s output voltage.','A condenser capsule is two plates with air between them. Sound moves one plate, changing the gap. That changes the capacitance. With a fixed charge, this makes the output voltage.','It is the core transduction step of a condenser microphone, turning diaphragm motion into an electrical signal.','For a parallel-plate capsule, capacitance equals permittivity times area over gap; as the gap shrinks under pressure, capacitance rises and voltage responds.','Transduction',ARRAY['Capacitive MEMS microphone','Charge amplifier','Backplate perforation','Back-volume compliance','Complex sensitivity']::text[],ARRAY['Thinking the diaphragm generates power itself; the polarising charge does.','Assuming large plate motion; the gap changes only slightly under normal sound.','Confusing the capacitance change with a resistance change.']::text[],ARRAY['Explaining how a condenser microphone converts sound to voltage.','Understanding why a condenser needs polarising voltage or a charged electret.','Modelling capsule output from plate spacing and area.']::text[],'Intermediate','C = eps_0 * A / d','Capacitance equals the permittivity of air times the plate area divided by the gap between diaphragm and backplate.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Capacitance variation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '41ccb36e-2a9d-4485-9839-0f74cfa17a0f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='41ccb36e-2a9d-4485-9839-0f74cfa17a0f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='41ccb36e-2a9d-4485-9839-0f74cfa17a0f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ec60ff36-e724-47b1-baa3-772274d36d5f','Capacitive MEMS microphone','A silicon microphone in which a micromachined thin diaphragm and a perforated fixed backplate form a variable capacitor, read out by an integrated circuit that supplies the bias and buffers the signal. It is the dominant microphone type in phones, laptops, and hearables.','This is a tiny condenser microphone built on a silicon chip. A thin silicon diaphragm faces a fixed plate with holes. Sound changes the gap and the capacitance. A small chip inside powers and buffers it.','It provides a small, stable, mass-producible condenser microphone suited to consumer and voice-interface devices.','A phone designer reflow-solders a MEMS microphone whose internal charge pump biases the capsule and whose ASIC drives the analog or digital output.','Microphone Type',ARRAY['Capacitance variation','Backplate perforation','Bulk micromachining','Always-on microphone','Charge amplifier']::text[],ARRAY['Assuming a MEMS microphone needs external phantom power; it uses a low supply and internal bias.','Overheating the part beyond its reflow profile during soldering.','Ignoring the sealed acoustic path between the port and the capsule.']::text[],ARRAY['Integrating a microphone into a smartphone or laptop.','Selecting a digital MEMS microphone for a voice-interface board.','Explaining why modern devices dropped electret capsules for MEMS.']::text[],'Intermediate','C = eps_0 * A / d','The capsule capacitance equals air permittivity times diaphragm area divided by the gap to the backplate.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Capacitive MEMS microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ec60ff36-e724-47b1-baa3-772274d36d5f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ec60ff36-e724-47b1-baa3-772274d36d5f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ec60ff36-e724-47b1-baa3-772274d36d5f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '77f0539c-fb38-421c-8b33-4f037684a6fb','Capon beamformer','A minimum-variance distortionless-response beamformer that minimizes the array''s total output power while holding unit gain toward the look direction, so it places nulls on interference automatically. Its weight vector uses the inverse of the signal covariance matrix and the look-direction steering vector, and it is named after Jack Capon''s 1969 method.','This adaptive beamformer keeps the wanted direction at full gain. Then it makes everything else as quiet as possible. It automatically nulls out strong interferers. It is named after Jack Capon.','It maximises interference and noise rejection without distorting the wanted look-direction signal, giving high-resolution spatial filtering.','Given a covariance matrix R and steering vector a, the Capon weights are R-inverse times a, divided by a-Hermitian times R-inverse times a.','Array Processing',ARRAY['Adaptive beamformer','Beamformer weight','Broadband beamformer','Blind beamforming','Amplitude shading']::text[],ARRAY['Confusing Capon (MVDR) with simple delay-and-sum beamforming.','Ignoring that steering-vector or calibration errors can cancel the wanted signal.','Using a poorly estimated or singular covariance matrix without diagonal loading.']::text[],ARRAY['Rejecting a strong interferer while keeping a talker undistorted.','Estimating source direction with high-resolution spatial spectra.','Comparing MVDR against fixed beamformers for noise rejection.']::text[],'Advanced','w = (R^-1 * a) / (a^H * R^-1 * a)','The weight vector equals the inverse covariance matrix times the steering vector, divided by the steering vector''s Hermitian times the inverse covariance times the steering vector.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Capon beamformer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '77f0539c-fb38-421c-8b33-4f037684a6fb','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='77f0539c-fb38-421c-8b33-4f037684a6fb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='77f0539c-fb38-421c-8b33-4f037684a6fb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ed88b61c-81e2-4d3d-b649-ba653601023a','Charge amplifier','An operational-amplifier integrator that converts the electrical charge from a high-impedance source, such as a piezoelectric or condenser element, into an output voltage set by a feedback capacitor. Because the input is held at a virtual ground, the output is nearly independent of cable capacitance.','Some sensors put out charge, not voltage. A charge amplifier turns that charge into a clean voltage. It uses an op-amp with a feedback capacitor. It also cancels the effect of long cables.','It reads out charge-producing transducers accurately and makes their output insensitive to cable length and capacitance.','With feedback capacitor Cf, the output voltage equals minus the input charge divided by Cf; a 100 pC input into a 1 nF capacitor gives -0.1 V.','Circuit',ARRAY['Capacitance variation','Bootstrapped input','Constant-current line drive','Capacitive MEMS microphone','Complex sensitivity']::text[],ARRAY['Assuming output depends on cable capacitance; the virtual ground removes that.','Forgetting the feedback resistor needed to set the low-frequency time constant.','Confusing a charge amplifier with a plain voltage amplifier.']::text[],ARRAY['Conditioning a piezoelectric sensor or microphone signal.','Reading a charge-output transducer over a long cable run.','Explaining why gain is set by the feedback capacitor, not a resistor ratio.']::text[],'Advanced','V_out = - Q / C_f','The output voltage equals minus the input charge divided by the feedback capacitance.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Charge amplifier');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ed88b61c-81e2-4d3d-b649-ba653601023a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ed88b61c-81e2-4d3d-b649-ba653601023a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ed88b61c-81e2-4d3d-b649-ba653601023a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4c45cfa9-e499-4430-bd4c-671798fddfe2','Circular microphone array','A microphone array whose elements are arranged around a circle or ring, giving uniform sensitivity to sound arriving from any azimuth. This geometry suits full 360-degree beamforming and sound-field capture, as in conferencing devices and Ambisonic-style recording.','This array puts its microphones in a ring. That gives even coverage all the way around. It can steer a beam to any horizontal direction. It suits round conference tables and 360-degree capture.','It provides symmetric azimuthal coverage so the array can steer or capture equally well in every horizontal direction.','A conferencing puck uses a ring of microphones to steer a beam toward whichever talker around the table is active.','Array Geometry',ARRAY['Conformal microphone array','Coincident microphone array','Array aperture','Adaptive beamformer','Array matching']::text[],ARRAY['Assuming a circular array resolves elevation as well as azimuth.','Ignoring spatial aliasing set by the spacing around the ring.','Confusing a ring array with a coincident stereo pair.']::text[],ARRAY['Designing a 360-degree conferencing microphone.','Capturing a sound field for immersive playback.','Steering a beam around a table to the active talker.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Circular microphone array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4c45cfa9-e499-4430-bd4c-671798fddfe2','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4c45cfa9-e499-4430-bd4c-671798fddfe2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4c45cfa9-e499-4430-bd4c-671798fddfe2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '53f49d48-ca2a-4dd0-b67c-30b1eb7f3869','Coincident microphone array','A stereo or surround microphone technique in which two or more directional capsules are mounted as close together as possible, ideally at the same point, so that direction is encoded almost entirely by level differences rather than time differences. X-Y, Blumlein, and mid-side setups are common coincident arrangements.','Here two directional microphones sit almost on top of each other. Sound reaches both at nearly the same instant. So direction shows up as loudness differences, not timing. This keeps the stereo signal mono-compatible.','It captures stereo or surround images using only level differences, which keeps the result well behaved when summed to mono.','An engineer sets two cardioids at a coincident 90-degree X-Y angle to record an ensemble with a stable, mono-compatible stereo image.','Array Geometry',ARRAY['Circular microphone array','Conformal microphone array','Array aperture','Complex sensitivity','Amplitude shading']::text[],ARRAY['Spacing the capsules apart, which adds time differences and breaks true coincidence.','Assuming coincident pairs give a wide image; they trade width for mono compatibility.','Confusing coincident X-Y with spaced (A-B) omnidirectional pairs.']::text[],ARRAY['Recording an acoustic ensemble with a mono-compatible stereo image.','Setting up a Blumlein pair of figure-eight microphones.','Explaining why coincident techniques resist phase cancellation in mono.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coincident microphone array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '53f49d48-ca2a-4dd0-b67c-30b1eb7f3869','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='53f49d48-ca2a-4dd0-b67c-30b1eb7f3869') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='53f49d48-ca2a-4dd0-b67c-30b1eb7f3869');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f37ecf40-b8a7-4ed1-ade1-b3905fad1b8d','Comparison calibration','A secondary calibration method in which an uncalibrated microphone is compared against a reference microphone of known sensitivity exposed to the same sound field, and its sensitivity is derived by substitution. It is faster and cheaper than primary reciprocity calibration but inherits the reference''s uncertainty.','Here you calibrate one microphone against a trusted reference. Both hear the same sound. You compare their outputs to find the unknown one. It is quicker than the primary method but slightly less exact.','It transfers a known sensitivity from a reference microphone to a working microphone quickly for routine calibration.','A lab places a working microphone and a reference microphone in the same coupler, then computes the unknown sensitivity from their output ratio.','Calibration',ARRAY['Calibration drift','Calibration uncertainty','Barometric pressure coefficient','Complex sensitivity','Array matching']::text[],ARRAY['Forgetting that comparison results inherit the reference microphone''s uncertainty.','Assuming the two microphones see identical fields when placement differs.','Confusing comparison calibration with primary reciprocity calibration.']::text[],ARRAY['Routine calibration of working measurement microphones against a reference.','Transferring a standard''s sensitivity to production microphones.','Choosing comparison over reciprocity for speed in a busy lab.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Comparison calibration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f37ecf40-b8a7-4ed1-ade1-b3905fad1b8d','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f37ecf40-b8a7-4ed1-ade1-b3905fad1b8d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f37ecf40-b8a7-4ed1-ade1-b3905fad1b8d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ea107b4d-1c49-4619-810e-5a8af6efd2d7','Complex sensitivity','A microphone''s sensitivity expressed as a complex quantity, carrying both magnitude and phase as functions of frequency, rather than magnitude alone. The phase information is essential for phase-matched work such as array beamforming and sound-intensity measurement.','Sensitivity is usually given as loudness per unit sound pressure. Complex sensitivity adds the timing, or phase, too. Both parts change with frequency. Arrays and intensity probes need this phase to work.','It fully describes how a microphone responds in both amplitude and timing, which phase-critical applications require.','Sound-intensity probes require two microphones with matched complex sensitivity, since a small phase mismatch produces a large low-frequency intensity error.','Calibration',ARRAY['Array matching','Calibration uncertainty','Comparison calibration','Barometric pressure coefficient','Capacitance variation']::text[],ARRAY['Reporting only magnitude sensitivity and ignoring the phase response.','Assuming phase mismatch is negligible for intensity or array work; it is critical.','Confusing electrical phase with the acoustic time-of-arrival difference.']::text[],ARRAY['Matching a microphone pair for a sound-intensity probe.','Characterising array elements for phase-accurate beamforming.','Explaining why phase, not just level, must be calibrated.']::text[],'Advanced','M(f) = |M(f)| * exp(j*phi(f))','Complex sensitivity at each frequency equals its magnitude times the exponential of j times its phase angle.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complex sensitivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ea107b4d-1c49-4619-810e-5a8af6efd2d7','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ea107b4d-1c49-4619-810e-5a8af6efd2d7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ea107b4d-1c49-4619-810e-5a8af6efd2d7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dca7c395-56ad-45e2-9d27-22004e78cb35','Conformal microphone array','A microphone array whose elements follow a non-planar surface, such as a curved device shell, a vehicle body, or worn equipment, rather than lying on a flat line or plane. The known three-dimensional element positions are built into the beamformer so it can steer despite the irregular shape.','A conformal array wraps its microphones over a curved surface. It fits the shape of a device or vehicle. The processor knows exactly where each microphone sits. That lets it still steer a beam.','It lets designers place array elements on the available curved surfaces of a product while still performing accurate beamforming.','Engineers mount microphones along a laptop''s curved lid, then feed their measured positions into the beamformer to steer toward the user.','Array Geometry',ARRAY['Circular microphone array','Coincident microphone array','Array aperture','Adaptive beamformer','Array matching']::text[],ARRAY['Assuming a flat-array beamformer works unchanged on a curved surface.','Neglecting accurate element positions, which the beamformer strictly needs.','Ignoring shadowing and scattering from the mounting surface.']::text[],ARRAY['Placing microphones on a curved consumer-device shell.','Beamforming from sensors mounted on a vehicle body.','Fitting an array to an irregular wearable form factor.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Conformal microphone array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dca7c395-56ad-45e2-9d27-22004e78cb35','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dca7c395-56ad-45e2-9d27-22004e78cb35') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dca7c395-56ad-45e2-9d27-22004e78cb35');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '950448bd-031e-4622-ac8b-8694852619f7','Constant-current line drive','A powering and readout scheme in which a constant direct current is sent up the same coaxial signal line that carries the audio, powering the microphone''s internal preamplifier, whose output rides on a fixed DC bias voltage as an alternating signal. Bruel & Kjaer market this as CCLD; the generic industry equivalent is IEPE.','One thin cable both powers the microphone and carries its sound. A steady current flows up the line. The built-in preamp uses it and sits on a fixed DC voltage. The audio rides on top as small changes.','It simplifies cabling by combining power and signal on one coaxial line for microphones and sensors with internal electronics.','A conditioner feeds a nominal 4 mA constant current (range 2 to 20 mA); the preamp output sits near a 12 V DC bias with audio as its AC variation.','Powering',ARRAY['Charge amplifier','Bootstrapped input','Capacitive MEMS microphone','Complex sensitivity']::text[],ARRAY['UNSAFE: Connecting a CCLD/IEPE microphone to 48 V phantom power, whose voltage can damage the internal electronics.','Confusing single-wire constant-current CCLD/IEPE powering with balanced 48 V phantom power.','Ignoring the compliance-voltage and current limits the source must supply.']::text[],ARRAY['Powering a measurement microphone through a CCLD/IEPE conditioner.','Choosing between IEPE and phantom-powered microphones for a test setup.','Diagnosing a dead sensor traced to wrong constant-current supply settings.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Constant-current line drive');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '950448bd-031e-4622-ac8b-8694852619f7','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='950448bd-031e-4622-ac8b-8694852619f7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='950448bd-031e-4622-ac8b-8694852619f7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd48af351-4903-4e75-a7ab-27bba2ef27a9','Constant-current powering','A powering scheme in which the microphone''s built-in preamplifier is fed from a constant-current source (typically 2 mA to 20 mA) delivered on the signal conductor, with the audio riding as a voltage on a DC bias of roughly 8 V to 14 V and a supply compliance near 24 V to 30 V. It is the powering standard for prepolarized (electret) measurement microphones and is the same interface known generically as IEPE.','This powers a microphone using a steady, fixed electric current, not a fixed voltage. The audio signal rides on top of a small direct-current voltage on the same wire. It is used for measuring microphones that have their own built-in amplifier. The industry short name for it is IEPE.','To power a measurement microphone''s internal preamplifier and carry its output on one coaxial line, giving low noise and long, robust cable runs without a separate polarizing supply.','A technician plugs a CCP measurement microphone into an IEPE-capable analyzer input, confirms the constant-current source (for example 4 mA) is enabled, and checks the DC bias voltage sits in the normal 8-14 V window before measuring.','Microphone powering',ARRAY['Externally polarized condenser microphone','Electret polarization','Phantom power','Prepolarized microphone','Preamplifier']::text[],ARRAY['UNSAFE: Feeding 48 V phantom power into a CCP/IEPE microphone input, or a CCP mic into a phantom input, which can damage the preamplifier.','Assuming the constant current sets the signal level; the current only biases the electronics, while acoustic pressure sets the output.','Reading a stuck bias voltage (near 0 V or near the compliance rail) as a level problem instead of a broken cable or dead preamp.']::text[],ARRAY['Connecting a 1/2-inch prepolarized measurement microphone to an IEPE data-acquisition front end.','Diagnosing a bias-voltage fault to tell a cable break from a preamp failure.','Choosing CCP over externally polarized cartridges for portable field acoustic measurements.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Constant-current powering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd48af351-4903-4e75-a7ab-27bba2ef27a9','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d48af351-4903-4e75-a7ab-27bba2ef27a9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d48af351-4903-4e75-a7ab-27bba2ef27a9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ace69db7-ffa8-4d0f-bd3f-ce0e1a361c1a','Coupler reciprocity','The reciprocity relationship exploited when two microphones are coupled through a small closed cavity (coupler) so that the product of their pressure sensitivities can be found absolutely from an electrical transfer measurement and the coupler''s known acoustic transfer impedance. It underlies the primary pressure-calibration method of laboratory standard microphones defined in IEC 61094-2.','Two mics face each other across a small sealed air gap. One acts as a tiny speaker. The other one listens. A mic works the same way in both roles. So we can find their combined output exactly. No known reference mic is needed.','To calibrate laboratory standard microphones from first principles, so their pressure sensitivity is traceable without relying on a previously calibrated reference microphone.','In a standards lab, three microphones are measured in pairs across a defined coupler; solving the three sensitivity products yields each microphone''s absolute pressure sensitivity in mV/Pa.','Calibration method',ARRAY['Free-field reciprocity','Pressure calibration','Laboratory standard microphone','Coupler','Transfer impedance']::text[],ARRAY['Believing a reference microphone of known sensitivity is required; reciprocity is a primary, self-referencing method.','Ignoring heat conduction, capillary tubes, and coupler volume corrections that shape the low-frequency acoustic impedance.','Confusing coupler (pressure) reciprocity with free-field reciprocity, which uses an anechoic path instead of a cavity.']::text[],ARRAY['Establishing primary pressure sensitivity for a national or accredited calibration laboratory.','Cross-checking a set of three standard microphones by pairwise reciprocity.','Explaining why coupler geometry must be tightly specified for traceable results.']::text[],'Advanced','M1 * M2 = Z_e,12 / Z_a,12','The product of the two microphones'' pressure sensitivities equals the measured electrical transfer impedance between them divided by the acoustic transfer impedance of the coupler that joins them.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coupler reciprocity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ace69db7-ffa8-4d0f-bd3f-ce0e1a361c1a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ace69db7-ffa8-4d0f-bd3f-ce0e1a361c1a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ace69db7-ffa8-4d0f-bd3f-ce0e1a361c1a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4966ddd8-3cc4-4e11-be2d-20f6231e9d77','Current-noise density','The spectral density of the noise current at a microphone preamplifier''s input, expressed in amperes per root hertz (A/vHz), which flows through the source impedance to create a voltage noise that dominates at high source impedance and, for a capacitive condenser source, rises toward low frequency as the capsule reactance climbs. For a high-impedance condenser front end it is set largely by the input device''s gate or base leakage (shot noise).','This measures how much random noise current an amplifier input makes. It is given per unit of bandwidth, in amps for each square root of a hertz. This current flows through the microphone''s high impedance and turns into noise voltage. It matters most at high frequencies with high-impedance condenser capsules.','To quantify one of the two fundamental preamplifier noise contributions (voltage noise and current noise) so designers can match the input device to a microphone''s source impedance for lowest self-noise.','For a JFET input with 1 pA gate leakage, shot-noise current density is i_n = sqrt(2*q*I) = sqrt(2*1.602e-19*1e-12) ~ 0.57 fA/vHz; across a 100 MOhm capsule reactance this adds meaningful high-frequency noise.','Noise parameter',ARRAY['Voltage-noise density','Equivalent acoustic noise','Shot noise','Preamplifier','Diaphragm-backplate capacitance']::text[],ARRAY['Treating current noise as negligible for all sources; it dominates when the source impedance is high, as with condensers.','Confusing current-noise density (A/vHz) with voltage-noise density (V/vHz); they combine through the source impedance.','Forgetting that current noise rises with the input device''s leakage current, which itself climbs with temperature.']::text[],ARRAY['Selecting a low-leakage JFET or op-amp for a condenser capsule preamp.','Explaining why self-noise worsens at high frequency with a small capsule.','Predicting temperature drift of a measurement microphone''s noise floor.']::text[],'Advanced','i_n = sqrt(2 * q * I)','The shot-noise current spectral density equals the square root of twice the electron charge times the direct leakage current flowing in the input device.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Current-noise density');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4966ddd8-3cc4-4e11-be2d-20f6231e9d77','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4966ddd8-3cc4-4e11-be2d-20f6231e9d77') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4966ddd8-3cc4-4e11-be2d-20f6231e9d77');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '190fdb01-4438-4cf5-ae7f-c1a18ddd33da','Deep reactive-ion etching','A dry plasma etching process that alternates a reactive etch step with a passivation step to cut deep, nearly vertical trenches in silicon, most commonly by the Bosch (time-multiplexed) method. It is a core micro-electro-mechanical-systems (MEMS) fabrication step used to form the backplate holes, back cavity, and released diaphragm of a MEMS microphone.','This is a way to carve very deep, steep-sided holes into silicon using plasma. It switches between etching and coating steps to keep the walls straight. Micro-electro-mechanical-systems, or MEMS, makers use it to shape tiny microphone parts. It forms the back holes and frees the moving diaphragm.','To create the high-aspect-ratio silicon structures (back cavity, vent holes, released membrane) that a MEMS microphone needs, with steep sidewalls a wet etch cannot achieve.','A MEMS foundry uses a Bosch-process DRIE recipe to open the back volume behind the diaphragm, then a release etch frees the membrane so it can move in response to sound.','MEMS fabrication',ARRAY['MEMS microphone','Diaphragm','Backplate','Silicon micromachining','Back cavity']::text[],ARRAY['Confusing dry plasma DRIE with wet chemical etching, which follows crystal planes and cannot make vertical deep trenches.','Assuming the scalloped sidewalls from the Bosch cycle are defects rather than a normal signature of the alternating steps.','Thinking DRIE shapes the audible diaphragm tuning directly; it defines geometry, while film stress and thickness set the acoustics.']::text[],ARRAY['Understanding how a smartphone MEMS microphone capsule is built.','Comparing MEMS capsule manufacturing to traditional foil condenser assembly.','Explaining why MEMS microphones are so uniform part-to-part.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Deep reactive-ion etching');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '190fdb01-4438-4cf5-ae7f-c1a18ddd33da','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='190fdb01-4438-4cf5-ae7f-c1a18ddd33da') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='190fdb01-4438-4cf5-ae7f-c1a18ddd33da');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8fc2a8d9-d8ef-427c-a4e3-db47bac4ea89','Diagonal loading','A robustness technique in adaptive array processing that adds a small positive constant to the diagonal of the estimated spatial covariance matrix before inverting it, so the beamformer tolerates steering errors, calibration mismatch, and short data records. It trades a little noise-rejection performance for large gains in stability of the microphone-array beamformer.','This makes an adaptive microphone array behave more reliably. It adds a small fixed value along the main diagonal of a math matrix before the array inverts it. That small addition stops the array from over-reacting to errors. The result is steadier performance when aiming or calibration is not perfect.','To stabilize adaptive (for example, MVDR) beamformers so small errors in the steering direction or microphone gains do not cause the array to cancel the wanted signal.','An engineer tuning a conference-array MVDR beamformer sets the loading factor to a few times the noise-floor power; too little gives fragile nulls, too much broadens the beam and reduces interference rejection.','Array processing',ARRAY['Adaptive beamformer','Covariance matrix','MVDR beamformer','Robust beamforming','Fixed beamformer']::text[],ARRAY['Setting the loading factor far too high, which turns the adaptive beamformer into a plain delay-and-sum one.','Assuming diagonal loading fixes any array error; it helps with small mismatches, not gross miscalibration.','Confusing the loading constant with signal power; it is a regularization term, not part of the acoustic model.']::text[],ARRAY['Hardening a smart-speaker or conference microphone array against steering error.','Preventing signal self-cancellation in an adaptive beamformer with short data.','Explaining the stability-versus-selectivity trade-off in robust beamforming.']::text[],'Advanced','R_dl = R + delta * I','The diagonally loaded covariance matrix equals the estimated covariance matrix plus a small loading constant times the identity matrix.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diagonal loading');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8fc2a8d9-d8ef-427c-a4e3-db47bac4ea89','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8fc2a8d9-d8ef-427c-a4e3-db47bac4ea89') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8fc2a8d9-d8ef-427c-a4e3-db47bac4ea89');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '53320406-cabe-4465-905c-8476884cc20e','Diaphragm collapse','The failure mode of a condenser or MEMS microphone in which the electrostatic attraction between the charged diaphragm and backplate exceeds the diaphragm''s mechanical restoring force, so the diaphragm snaps against the backplate (electrostatic pull-in). It can be triggered by an excessive polarization or bias voltage or by physical shorting, and can also occur transiently under very high sound pressure.','This is when a condenser microphone''s thin diaphragm slaps against the fixed plate behind it. It happens when the electric pull between them beats the diaphragm''s springiness. Too high a bias voltage or a fault can cause it. Once it collapses, the microphone stops working normally until reset.','Naming this failure lets technicians recognize and avoid the pull-in limit that caps how high a polarizing voltage or sound pressure a condenser capsule can safely take.','Designers keep the polarizing voltage well below the pull-in value; the collapse (pull-in) voltage scales as V_pi = sqrt(8*k*d0^3 / (27*e0*A)), and pull-in occurs once the gap closes to about one third of its rest value.','Failure mode',ARRAY['Electrostatic attraction','Diaphragm-backplate capacitance','Externally polarized condenser microphone','Polarization voltage','Pull-in']::text[],ARRAY['UNSAFE: Raising a capsule''s polarizing/bias voltage above spec to boost sensitivity, which can force pull-in and destroy the capsule.','UNSAFE: Applying power to a wet or condensation-affected capsule, where leakage can trigger collapse or arcing.','Believing a collapsed diaphragm is always permanently ruined; some recover once voltage is removed, but many are damaged.','Confusing electrostatic pull-in with mechanical over-excursion tearing at extreme sound pressure levels.']::text[],ARRAY['Setting a safe polarization voltage margin in condenser capsule design.','Diagnosing a dead condenser microphone after a power or moisture fault.','Explaining the pull-in limit in MEMS microphone reliability testing.']::text[],'Advanced','V_pi = sqrt( 8 * k * d0^3 / (27 * e0 * A) )','The pull-in (collapse) voltage equals the square root of eight times the diaphragm stiffness times the cube of the rest gap, divided by twenty-seven times the permittivity of free space times the electrode area.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diaphragm collapse');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '53320406-cabe-4465-905c-8476884cc20e','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='53320406-cabe-4465-905c-8476884cc20e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='53320406-cabe-4465-905c-8476884cc20e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '82144906-61e2-4c85-803d-76de31f88d6a','Diaphragm–backplate capacitance','The electrical capacitance formed between a condenser microphone''s conductive diaphragm and its fixed backplate, which changes as sound moves the diaphragm and varies the air gap. With a fixed charge on the capsule this capacitance change is what converts acoustic motion into the microphone''s output voltage.','A condenser microphone has a thin moving plate and a fixed plate. Together they store electric charge like a small capacitor. When sound moves the diaphragm, the gap changes and so does the capacitance. That changing capacitance is what creates the output signal.','This varying capacitance is the transduction element of a condenser microphone: it turns diaphragm displacement into a voltage change when the charge is held constant.','For a backplate area A = 50 mm^2 and gap d = 20 um in air, C = e0*A/d = 8.854e-12 * 50e-6 / 20e-6 ~ 22 pF, a typical small-capsule value that sets the preamp impedance needs.','Transducer parameter',ARRAY['Externally polarized condenser microphone','Electrostatic attraction','Diaphragm collapse','Preamplifier','Electret polarization']::text[],ARRAY['Forgetting that the capsule capacitance is only tens of picofarads, so it needs a very high-impedance preamp input.','Assuming capacitance scales with the gap rather than inversely; a smaller gap gives more capacitance.','Ignoring cable and stray capacitance, which shunt the tiny capsule capacitance and cut sensitivity.']::text[],ARRAY['Sizing the input impedance of a condenser microphone preamplifier.','Explaining why long unbuffered capsule leads lose signal.','Estimating a capsule''s baseline capacitance from its geometry.']::text[],'Intermediate','C = e0 * A / d','The capacitance equals the permittivity of free space times the overlapping electrode area, divided by the air-gap spacing between diaphragm and backplate.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diaphragm–backplate capacitance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '82144906-61e2-4c85-803d-76de31f88d6a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='82144906-61e2-4c85-803d-76de31f88d6a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='82144906-61e2-4c85-803d-76de31f88d6a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ac9e6240-9439-47f6-b81b-a09e006f5f43','Dielectric noise','Thermal noise arising from the dielectric losses of a capacitor, modeled by an equivalent series resistance set by the material''s dissipation factor (loss tangent). In a condenser microphone the capsule insulation and dielectric losses add a small noise component that can matter at low frequencies and with lossy insulators.','A capacitor''s insulation is never perfect. Its small loss acts like a tiny resistor. Any resistor makes a faint thermal noise. So a condenser mic gains a slight hiss. Damp or lossy insulators make it worse.','To account for the noise contributed by imperfect dielectrics so designers pick low-loss capsule insulation and keep the microphone''s self-noise low.','The equivalent series resistance from loss is R_s = D/(2*pi*f*C); its thermal noise density is sqrt(4*k*T*R_s), so a technician keeps capsule insulators clean and dry to hold the dissipation factor D low.','Noise mechanism',ARRAY['Current-noise density','Equivalent acoustic noise','Diaphragm-backplate capacitance','Dissipation factor','Thermal noise']::text[],ARRAY['Ignoring dielectric loss because a capacitor is assumed ideal; real insulators dissipate and add noise.','Confusing dielectric noise with the resistor thermal noise of the load; both are thermal but come from different elements.','Overlooking that humidity and contamination raise the loss tangent and therefore the noise.']::text[],ARRAY['Choosing low-loss insulators for a low-noise measurement microphone.','Explaining why a damp capsule gets noisier at low frequencies.','Budgeting the noise contributions of a condenser front end.']::text[],'Advanced','e_n = sqrt( 4 * k * T * D / (2 * pi * f * C) )','The dielectric noise voltage density equals the square root of four times Boltzmann''s constant times temperature times the dissipation factor, divided by two pi times frequency times capacitance.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dielectric noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ac9e6240-9439-47f6-b81b-a09e006f5f43','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ac9e6240-9439-47f6-b81b-a09e006f5f43') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ac9e6240-9439-47f6-b81b-a09e006f5f43');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '980a6eef-ab5a-40c6-b2b7-1822922747c2','Differential array','A microphone array whose output is formed by differencing closely spaced sensors so that its directivity depends on the pressure gradient rather than absolute pressure. A first-order differential array gives directional patterns such as cardioid, hypercardioid, and figure-eight from two or more elements spaced much less than a wavelength.','This array subtracts the signals from microphones placed very close together. The difference responds to how pressure changes across space, not just its level. That gives a directional pickup from tiny spacing. Patterns like cardioid and figure-eight come from this method.','To achieve directional pickup and interference rejection from a compact array much smaller than a wavelength, as used in headsets, hearing aids, and mobile devices.','A two-microphone endfire differential array with a few millimeters spacing plus an internal delay yields a cardioid; the technician checks that low-frequency roll-off and self-noise stay acceptable.','Array type',ARRAY['Differential beamforming','Pressure-gradient microphone','Element spacing','Cardioid','Endfire array']::text[],ARRAY['Expecting wide spacing; differential arrays need spacing far below a wavelength or the pattern degrades.','Ignoring the strong low-frequency roll-off and noise penalty that come with differencing.','Confusing a differential (gradient) array with a delay-and-sum additive array.']::text[],ARRAY['Designing a directional two-mic pickup for a headset or phone.','Explaining how hearing aids get directionality from tiny spacing.','Comparing gradient arrays with larger additive arrays.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Differential array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '980a6eef-ab5a-40c6-b2b7-1822922747c2','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='980a6eef-ab5a-40c6-b2b7-1822922747c2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='980a6eef-ab5a-40c6-b2b7-1822922747c2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2f5b912a-c29f-4c65-a4a3-2a730c6e10ab','Differential beamforming','The signal-processing method of combining closely spaced microphone signals through differencing (spatial derivatives) to synthesize frequency-independent directional patterns from a compact array. Differential beamforming realizes patterns such as cardioid or hypercardioid whose order equals the number of nulls placed in the response.','This combines nearby microphone signals by subtracting them in a controlled way. It builds a directional pattern that stays similar across frequency. Higher order means sharper focus and more nulls. It works even when the microphones sit very close together.','To form steerable, frequency-consistent directivity from a small array, trading array size for a rise in low-frequency noise and sensitivity to element mismatch.','For a third-order differential beamformer, a technician verifies four elements and three nulls give the target pattern, then confirms the white-noise gain penalty at low frequency is tolerable.','Array processing',ARRAY['Differential array','Fixed beamformer','Filter-and-sum beamformer','Element spacing','Hypercardioid']::text[],ARRAY['Assuming higher order is always better; each added order sharply increases low-frequency noise gain.','Neglecting how small gain and phase mismatches between elements distort the synthesized pattern.','Confusing differential beamforming with additive delay-and-sum, which needs large arrays for the same directivity.']::text[],ARRAY['Building a compact steerable directional microphone for voice pickup.','Weighing pattern order against added self-noise.','Explaining why element matching is critical in small directional arrays.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Differential beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2f5b912a-c29f-4c65-a4a3-2a730c6e10ab','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2f5b912a-c29f-4c65-a4a3-2a730c6e10ab') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2f5b912a-c29f-4c65-a4a3-2a730c6e10ab');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '01250ce4-c2b9-4b08-918c-61a6e769e99e','Diffuse-field correction','The adjustment applied to a microphone''s frequency response so it reads correctly for sound arriving randomly from all directions (a diffuse or reverberant field) rather than head-on. Because a microphone''s directivity and body diffraction differ between the two conditions, a diffuse-field microphone or a correction network flattens the random-incidence response.','A microphone reacts differently to sound coming from one direction versus from everywhere at once. In a reverberant room, sound arrives from all sides. A diffuse-field correction adjusts the response for that spread-out sound. It keeps the measurement flat when there is no single source direction.','To make a microphone measure accurately in reverberant or random-incidence conditions, matching standardized diffuse-field targets used in acoustics and hearing work.','For room reverberation or hearing-related measurements, a technician selects a diffuse-field measurement microphone (or applies its correction curve) instead of a free-field type aimed at the source.','Response correction',ARRAY['Free-field reciprocity','Random-incidence response','Pressure microphone','Free-field microphone','Directivity']::text[],ARRAY['Using a free-field microphone in a reverberant field without correction, biasing the high-frequency reading.','Assuming pressure, free-field, and diffuse-field responses are interchangeable; each targets a different sound field.','Forgetting that microphone body and grid diffraction, not just the diaphragm, shape the diffuse-field response.']::text[],ARRAY['Choosing a microphone type for reverberation-room measurements.','Applying a diffuse-field correction curve for hearing-aid or audiology work.','Explaining why the same microphone reads differently free-field versus diffuse-field.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffuse-field correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '01250ce4-c2b9-4b08-918c-61a6e769e99e','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='01250ce4-c2b9-4b08-918c-61a6e769e99e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='01250ce4-c2b9-4b08-918c-61a6e769e99e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '687d87c1-b6e7-44ac-bf3b-af676d8ce999','Digital decimation','The digital-signal-processing step of reducing a sample rate by an integer factor, combining low-pass anti-alias filtering with downsampling. In a digital MEMS microphone it converts the high-rate one-bit pulse-density-modulated (PDM) bitstream into a lower-rate multi-bit pulse-code-modulated (PCM) audio signal.','Decimation lowers a digital signal''s sample rate by a whole-number factor. It first filters out high frequencies, then keeps only every Nth sample. A digital MEMS microphone uses it to turn a very fast one-bit stream into normal audio. This gives standard audio samples that a device can use.','To bring an oversampled or one-bit modulator output down to a standard audio rate and word length while removing the noise and aliases pushed to high frequency.','A PDM MEMS microphone clocked at 3.072 MHz decimated by M = 64 yields f_out = f_s/M = 3.072 MHz / 64 = 48 kHz PCM; the technician must set the clock and decimation factor to match.','Digital processing',ARRAY['MEMS microphone','Pulse-density modulation','Anti-aliasing filter','Oversampling','Sigma-delta modulator']::text[],ARRAY['Downsampling without the anti-alias low-pass first, which folds high-frequency content into the audio band.','Confusing decimation (rate reduction) with plain sample dropping; the required filter is essential.','Mismatching the PDM clock and decimation factor, giving the wrong output sample rate.']::text[],ARRAY['Configuring a digital MEMS microphone''s clock and output rate.','Explaining how a one-bit modulator becomes standard PCM audio.','Troubleshooting aliasing after an improper rate change.']::text[],'Intermediate','f_out = f_s / M','The output sample rate equals the input sample rate divided by the integer decimation factor.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Digital decimation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '687d87c1-b6e7-44ac-bf3b-af676d8ce999','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='687d87c1-b6e7-44ac-bf3b-af676d8ce999') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='687d87c1-b6e7-44ac-bf3b-af676d8ce999');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7db92e69-9763-47c2-8cf0-6dc32410a392','Direction of arrival','The estimated bearing (angle) from which a sound reaches a microphone array, inferred from the time or phase differences of arrival across the elements. Direction-of-arrival (DOA) estimation ranges from simple time-difference methods to subspace algorithms such as MUSIC and ESPRIT.','Direction of arrival is the angle a sound comes from. An array of microphones finds it from tiny timing differences between them. Sound reaches the nearer microphone slightly earlier. From those delays, the array computes the source direction.','To locate or track a talker or sound source so a system can steer a beam toward it, log its position, or separate it from other sources.','For two microphones 0.10 m apart with a source at 30 deg, the time difference is tau = d*sin(theta)/c = 0.10*sin(30)/343 ~ 146 us, which the array converts back to the angle.','Array processing',ARRAY['ESPRIT algorithm','Element spacing','Beamforming','Time difference of arrival','Effective aperture']::text[],ARRAY['Ignoring spatial aliasing when elements are spaced wider than half a wavelength, which gives ambiguous angles.','Assuming one measurement fixes range; a small array mainly gives direction, not distance.','Confusing the physical arrival angle with the steered beam direction of the beamformer.']::text[],ARRAY['Steering a conference microphone array toward the active talker.','Tracking a moving source across a room.','Explaining why widely spaced elements cause direction ambiguity.']::text[],'Intermediate','tau = d * sin(theta) / c','The inter-element time difference of arrival equals the element spacing times the sine of the arrival angle, divided by the speed of sound.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Direction of arrival');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7db92e69-9763-47c2-8cf0-6dc32410a392','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7db92e69-9763-47c2-8cf0-6dc32410a392') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7db92e69-9763-47c2-8cf0-6dc32410a392');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11754d06-ade6-4383-959a-606b338df4c6','Distributed microphone array','A microphone array whose elements are spread across separate devices or positions in a space, often without a fixed common geometry or clock, and whose signals are combined over a network. Distributed (ad hoc) arrays exploit wide spatial coverage but must handle unknown positions and clock and sample-rate offsets between nodes.','This spreads microphones around a room instead of packing them together. They may sit in different devices, like phones or laptops. Their signals are combined over a network. The hard part is that their positions and clocks are not aligned.','To gain wide spatial coverage and closer average source distance than a single compact array, useful for large rooms and ad hoc smart-device setups.','When combining laptop and phone microphones for a meeting, an engineer must estimate node positions and correct sample-rate/clock offsets before the distributed array can beamform coherently.','Array type',ARRAY['Microphone array','Element spacing','Distributed sensing','Clock synchronization','Beamforming']::text[],ARRAY['Assuming node clocks are synchronized; unsynchronized sample rates ruin coherent combining.','Treating unknown microphone positions as negligible; geometry must be estimated for beamforming.','Expecting compact-array directivity from a sparse, irregular distributed layout.']::text[],ARRAY['Combining several smart devices'' microphones for one meeting pickup.','Covering a large room where no single array reaches every talker.','Explaining synchronization challenges in ad hoc microphone networks.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distributed microphone array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11754d06-ade6-4383-959a-606b338df4c6','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11754d06-ade6-4383-959a-606b338df4c6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11754d06-ade6-4383-959a-606b338df4c6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b887c84-7930-479c-a090-1913b925a065','Dolph–Chebyshev weighting','An array shading (amplitude weighting) scheme that sets element gains from Chebyshev polynomials so that all sidelobes of the array response sit at one chosen equal level. Dolph-Chebyshev weighting gives the narrowest main beam for a specified sidelobe level, or the lowest sidelobes for a given beamwidth.','This sets how strongly each microphone in an array is weighted. It makes all the unwanted side responses equal in height. You pick how low those sidelobes should be. In return you get the narrowest possible main beam for that choice.','To design a fixed beamformer with an optimal trade between main-beam width and a uniform, controllable sidelobe level for consistent off-axis rejection.','To hold sidelobes 30 dB down, the design sets the Chebyshev ratio R = 10^(30/20) ~ 31.6 and solves for element weights; a technician then loads those tapered gains into the beamformer.','Array shading',ARRAY['Fixed beamformer','Array shading','Element spacing','Effective aperture','Sidelobe level']::text[],ARRAY['Expecting decaying sidelobes; Dolph-Chebyshev makes them all equal in height by design.','Pushing sidelobes very low without accepting the wider main beam and larger edge weights that result.','Confusing amplitude shading with time delays; Chebyshev weighting sets gains, not steering.']::text[],ARRAY['Designing a fixed line array with a set worst-case sidelobe level.','Trading beamwidth against off-axis rejection in a microphone array.','Explaining why equal-ripple sidelobes minimize the main-beam width.']::text[],'Advanced','R = 10^(SLL_dB / 20);  AF(psi) proportional to T_{N-1}( x0 * cos(psi/2) )','The sidelobe ratio is ten raised to the sidelobe level in decibels over twenty; the array factor follows the Chebyshev polynomial of order one less than the element count, scaled so its peak equals that ratio.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dolph–Chebyshev weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b887c84-7930-479c-a090-1913b925a065','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b887c84-7930-479c-a090-1913b925a065') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b887c84-7930-479c-a090-1913b925a065');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fb7eb917-d7ca-484d-ba5e-560a385a5999','Dust ingress','The entry of dust or fine particles into a microphone capsule or its acoustic path, which can add mass to the diaphragm, block vents or sound inlets, and raise noise or shift response. Ingress resistance is often described by the enclosure''s IP (Ingress Protection) rating under IEC 60529.','Dust ingress means fine dirt getting inside the microphone. It can weigh down the diaphragm or clog the sound holes. This can change the sound or add noise. Sealing and protective mesh help keep dust out.','Understanding dust ingress lets technicians protect capsules and read IP ratings so a microphone survives dusty stages, field use, or industrial environments.','For a dusty environment a technician checks the device''s IP code (the first digit rates solid-particle protection, up to 6 for dust-tight) and fits protective mesh or covers over the sound inlet.','Environmental reliability',ARRAY['IP rating','Windscreen','MEMS microphone','Sound inlet','Diaphragm']::text[],ARRAY['Reading the second IP digit (water) as the dust rating; the first digit rates solid-particle protection.','Assuming any mesh is dust-tight; only proper sealing meets a high IP first digit.','Cleaning a fouled capsule with compressed air aggressively, which can drive dust deeper or damage the diaphragm.']::text[],ARRAY['Selecting a microphone for a dusty industrial or outdoor setting.','Interpreting an IP rating on a MEMS microphone module.','Diagnosing lost sensitivity from a clogged sound inlet.']::text[],'Beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dust ingress');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fb7eb917-d7ca-484d-ba5e-560a385a5999','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fb7eb917-d7ca-484d-ba5e-560a385a5999') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fb7eb917-d7ca-484d-ba5e-560a385a5999');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4619c940-78c5-4119-b737-fbd3d94f3ace','ESPRIT algorithm','A subspace direction-of-arrival estimation algorithm (Estimation of Signal Parameters via Rotational Invariance Techniques) that exploits a shift-invariance structure between two identical sub-arrays to solve for source angles without a spectral search. Introduced by Roy and Kailath, it estimates arrival angles from the eigenstructure of the array covariance matrix.','ESPRIT is a math tool. It finds where sounds come from. It uses a set of mics called an array. The name is short for Estimation of Signal Parameters via Rotational Invariance Techniques. It uses two matched groups of mics, set a fixed step apart. From how they line up, it finds the source angles.','To estimate source directions accurately and efficiently, avoiding the exhaustive angle search that spectral methods like MUSIC require.','An array-processing engineer splits a uniform line array into two overlapping sub-arrays, computes the signal-subspace rotation, and reads off multiple source bearings from its eigenvalues.','Array processing',ARRAY['Direction of arrival','MUSIC algorithm','Subspace method','Covariance matrix','Element spacing']::text[],ARRAY['Forgetting that ESPRIT needs a shift-invariant (uniformly structured) array geometry.','Assuming it needs more sources than sensors; resolvable sources must stay below the array''s degrees of freedom.','Confusing ESPRIT (closed-form, no search) with MUSIC, which scans a spatial spectrum.']::text[],ARRAY['Locating several simultaneous talkers with a uniform microphone array.','Choosing an efficient DOA method to avoid a costly angular search.','Explaining subspace-based source localization in teaching array processing.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ESPRIT algorithm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4619c940-78c5-4119-b737-fbd3d94f3ace','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4619c940-78c5-4119-b737-fbd3d94f3ace') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4619c940-78c5-4119-b737-fbd3d94f3ace');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '99005b8b-61e8-4c9d-a113-c518d9079c83','Effective aperture','The overall spatial extent of a microphone array, essentially the distance from its first to its last element, which sets the array''s angular resolving power. A larger effective aperture gives a narrower beam and finer direction resolution, roughly proportional to the wavelength divided by the aperture.','Effective aperture is how wide a microphone array reaches from end to end. A wider array can tell apart directions more finely. It gives a narrower, sharper beam. A short array can only resolve broad directions.','To predict an array''s angular resolution and beamwidth from its physical size, guiding how many elements and how much spacing a design needs.','For a uniform line array of N = 8 elements at d = 21 mm spacing, the aperture is L = (N-1)*d = 147 mm; angular resolution scales as about lambda/L, so higher frequencies resolve finer.','Array geometry',ARRAY['Element spacing','Beamforming','Direction of arrival','Dolph-Chebyshev weighting','Array geometry']::text[],ARRAY['Thinking more elements alone sharpen the beam; the physical aperture, not just the count, sets resolution.','Ignoring that resolution is frequency dependent; the same array resolves low frequencies more coarsely.','Confusing aperture (total size) with element spacing (gap between neighbors).']::text[],ARRAY['Sizing a microphone array to resolve two nearby talkers.','Explaining why a small array cannot separate low-frequency sources well.','Trading array length against physical mounting constraints.']::text[],'Intermediate','L = (N - 1) * d;  resolution ~ lambda / L','The aperture equals one less than the element count times the element spacing; angular resolution is approximately the wavelength divided by that aperture.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Effective aperture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '99005b8b-61e8-4c9d-a113-c518d9079c83','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='99005b8b-61e8-4c9d-a113-c518d9079c83') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='99005b8b-61e8-4c9d-a113-c518d9079c83');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '21dfbf72-687b-414e-af61-44cc32077df7','Electret polarization','The quasi-permanent electric charge stored in a dielectric (an electret) that supplies the fixed bias of an electret condenser microphone without an external polarizing supply. A charged film (commonly a fluoropolymer such as FEP, or an oxide layer) holds trapped charge that acts like a built-in polarization voltage across the capsule gap.','An electret is a material that holds a fixed electric charge for years. It gives a condenser microphone its bias without any external voltage. The trapped charge acts like a built-in battery for the capsule. Sessler and West invented the foil-electret microphone in 1962.','To let a condenser microphone work from a simple low-voltage supply, since the electret provides the bias that an externally polarized capsule would need a high-voltage source to supply.','An electret with stored surface charge density sigma ~ 5e-5 C/m^2 across a d = 25 um gap gives an effective bias V = sigma*d/e0 = 5e-5*25e-6/8.854e-12 ~ 140 V, comparable to an externally polarized capsule.','Transducer principle',ARRAY['Externally polarized condenser microphone','Prepolarized microphone','Constant-current powering','Diaphragm-backplate capacitance','Electret condenser microphone']::text[],ARRAY['Thinking an electret capsule needs no power at all; it still needs a supply for its built-in preamp.','Assuming electret charge is truly permanent; it decays slowly, faster under heat and humidity.','Confusing a prepolarized (electret) capsule with an externally polarized one that needs a high-voltage bias.']::text[],ARRAY['Explaining how a lavalier or consumer electret microphone gets its bias.','Understanding why electret capsules tolerate simple low-voltage powering.','Discussing long-term stability and heat sensitivity of electret charge.']::text[],'Intermediate','V_eff = sigma * d / e0','The effective bias voltage equals the electret''s stored surface charge density times the air-gap spacing, divided by the permittivity of free space.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electret polarization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '21dfbf72-687b-414e-af61-44cc32077df7','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='21dfbf72-687b-414e-af61-44cc32077df7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='21dfbf72-687b-414e-af61-44cc32077df7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '04ed855b-c066-4a9a-84b6-580d7f73cbd0','Electrostatic actuator calibration','A frequency-response calibration method in which a rigid, perforated electrode (the actuator) is placed just in front of a measurement microphone''s diaphragm and driven with a high AC voltage on a DC bias, so the electrostatic force simulates a known, uniform sound pressure on the diaphragm. It is standardized in IEC 61094-6 for determining the pressure frequency response of standard microphones.','This tests a measurement microphone''s frequency response using an electric force, not real sound. A metal grid sits just in front of the diaphragm. A high voltage on the grid pulls on the diaphragm like a known pressure would. Sweeping the frequency maps the microphone''s response.','To obtain a repeatable pressure frequency response of a measurement microphone without an acoustic source, since the applied electrostatic force is calculable and uniform across the diaphragm.','A metrology technician mounts the actuator grid over the cartridge, applies a large DC bias with a small AC signal, and the simulated pressure p = e0*(V_dc + v)^2 / (2*d^2) drives the diaphragm for a response sweep.','Calibration method',ARRAY['Electrostatic attraction','Pressure calibration','Frequency response','Laboratory standard microphone','Coupler reciprocity']::text[],ARRAY['UNSAFE: Handling the actuator grid while its high DC bias is applied, risking shock; power down before touching.','Forgetting the DC bias, so the squared voltage doubles the frequency and distorts the response.','Assuming the actuator gives an absolute sensitivity; it mainly yields the pressure response shape, not primary sensitivity.']::text[],ARRAY['Measuring the pressure frequency response of a standard microphone cartridge.','Routine response checks in an acoustics calibration laboratory.','Explaining why the actuator needs a DC bias much larger than the AC signal.']::text[],'Advanced','p = e0 * (V_dc + v)^2 / (2 * d^2)','The equivalent pressure on the diaphragm equals the permittivity of free space times the square of the total actuator voltage, divided by twice the square of the actuator-to-diaphragm gap.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electrostatic actuator calibration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '04ed855b-c066-4a9a-84b6-580d7f73cbd0','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='04ed855b-c066-4a9a-84b6-580d7f73cbd0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='04ed855b-c066-4a9a-84b6-580d7f73cbd0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fe7da27b-0fd7-4e41-bf78-35fc1a6f3fc0','Electrostatic attraction','The inward electrostatic force between the oppositely charged diaphragm and backplate of a condenser microphone, which grows with the square of the voltage and inversely with the square of the gap. This force sets the capsule''s static diaphragm tension load and, if excessive, drives the pull-in collapse of the diaphragm.','In a condenser microphone the charged diaphragm and back plate pull toward each other. This pull gets much stronger as the voltage rises. It also gets stronger as the gap shrinks. Too much pull can snap the diaphragm onto the back plate.','Quantifying this force explains the static load on a biased diaphragm and defines the safe upper limit on polarization voltage before pull-in collapse.','For area A = 50 mm^2, gap d = 20 um, and V = 200 V, F = e0*A*V^2/(2*d^2) = 8.854e-12*50e-6*200^2/(2*(20e-6)^2) ~ 0.022 N, about a 443 Pa static pull on the diaphragm.','Transducer physics',ARRAY['Diaphragm collapse','Diaphragm-backplate capacitance','Externally polarized condenser microphone','Polarization voltage','Electret polarization']::text[],ARRAY['UNSAFE: Increasing polarization voltage to raise output; force rises with voltage squared and can pull the diaphragm in.','Assuming the force scales linearly with voltage; it scales with the square of the voltage.','Ignoring that a smaller gap sharply increases the force for the same voltage.']::text[],ARRAY['Setting a safe polarization voltage in condenser capsule design.','Explaining the static diaphragm load in a biased capsule.','Understanding the origin of pull-in collapse.']::text[],'Advanced','F = e0 * A * V^2 / (2 * d^2)','The attractive force equals the permittivity of free space times the electrode area times the square of the voltage, divided by twice the square of the gap.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electrostatic attraction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fe7da27b-0fd7-4e41-bf78-35fc1a6f3fc0','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fe7da27b-0fd7-4e41-bf78-35fc1a6f3fc0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fe7da27b-0fd7-4e41-bf78-35fc1a6f3fc0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4a4b42dd-00dc-4d10-8b15-d51844d34cbe','Element spacing','The physical distance between adjacent elements of a microphone array, which must generally be no more than half the wavelength of the highest frequency of interest to avoid spatial aliasing (grating lobes). Element spacing together with the number of elements sets the array''s aperture, beamwidth, and usable frequency range.','Element spacing is the gap between neighboring microphones in an array. If the gap is too big, the array confuses directions, like a visual illusion. To avoid this, the spacing stays under half a wavelength at the top frequency. Smaller spacing works to higher frequencies.','To set array element positions so the beamformer avoids ambiguous grating lobes while giving the wanted aperture and directivity.','For an upper frequency of 8 kHz, half-wavelength spacing is d <= c/(2*f) = 343/(2*8000) ~ 21.4 mm; a technician keeps element spacing at or below this to prevent spatial aliasing.','Array geometry',ARRAY['Effective aperture','Spatial aliasing','Direction of arrival','Beamforming','Differential array']::text[],ARRAY['Spacing elements wider than half a wavelength, which creates grating lobes and false directions.','Believing tighter spacing is always better; very close elements add noise and give little aperture.','Forgetting that the half-wavelength rule is set by the highest frequency handled, not the lowest.']::text[],ARRAY['Laying out a uniform linear microphone array for a target bandwidth.','Diagnosing false beam directions from too-wide spacing.','Balancing spacing against aperture in array design.']::text[],'Intermediate','d <= lambda_min / 2 = c / (2 * f_max)','The element spacing must be at most half the wavelength at the highest frequency, which equals the speed of sound divided by twice that frequency.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Element spacing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4a4b42dd-00dc-4d10-8b15-d51844d34cbe','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4a4b42dd-00dc-4d10-8b15-d51844d34cbe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4a4b42dd-00dc-4d10-8b15-d51844d34cbe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '37cc767d-c044-4c8b-bac2-c485c4fd183b','Equivalent acoustic noise','The self-noise of a microphone expressed as the sound pressure level that would produce the same output as the microphone''s own internal noise, usually stated as an A-weighted level in dB SPL relative to 20 uPa. Equivalent (input-referred) acoustic noise sets the quietest sound a microphone can usefully capture and is defined in IEC 60268-4.','Every microphone makes a little noise of its own. Equivalent acoustic noise states that noise as a sound level. It is the loudness of a sound that would match the microphone''s own hiss. A lower number means a quieter, more sensitive microphone.','To give a single input-referred figure for how quiet a microphone is, letting technicians compare capsules and predict the noise floor of a recording.','For sensitivity S = 50 mV/Pa and A-weighted output noise 5 uV, input-referred pressure = 5e-6/0.05 = 100 uPa, so L_n = 20*log10(100e-6/20e-6) ~ 14 dB(A) self-noise.','Noise specification',ARRAY['Current-noise density','Dielectric noise','Signal-to-noise ratio','Sensitivity','Self-noise']::text[],ARRAY['Comparing self-noise figures without noting whether they are A-weighted or unweighted; the two differ by several dB.','Confusing equivalent noise level with signal-to-noise ratio, which is referenced to 94 dB SPL.','Assuming lower sensitivity always means more noise; the input-referred figure already accounts for sensitivity.']::text[],ARRAY['Choosing a low-noise microphone for quiet acoustic or classical recording.','Comparing capsules on their self-noise specification.','Predicting the noise floor of a distant, quiet source pickup.']::text[],'Intermediate','L_n = 20 * log10( (e_n / S) / p0 )','The equivalent noise level equals twenty times the logarithm of the input-referred noise pressure, which is the output noise voltage divided by sensitivity, referenced to twenty micropascals.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equivalent acoustic noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '37cc767d-c044-4c8b-bac2-c485c4fd183b','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='37cc767d-c044-4c8b-bac2-c485c4fd183b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='37cc767d-c044-4c8b-bac2-c485c4fd183b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aa1d9dcf-87be-4db4-9612-9f4dc8900c60','Externally polarized condenser microphone','A condenser microphone whose fixed bias is supplied by an external DC polarizing voltage applied across the capsule, rather than by a stored electret charge. Laboratory and studio externally polarized capsules typically use a polarizing voltage on the order of 60 V to 200 V (200 V for standard measurement microphones per IEC 61094-1).','This condenser microphone gets its charge from an outside voltage supply. It does not use a stored charge like an electret does. Measurement models often use about 200 volts across the capsule. That external bias is what makes the capsule work.','To bias a condenser capsule from a stable external voltage, which gives measurement microphones a defined, adjustable polarization and high, consistent sensitivity.','A technician powers an externally polarized measurement cartridge from a preamp/power supply set to 200 V, and confirms the polarization is present, since a wrong or missing voltage changes the sensitivity.','Microphone type',ARRAY['Electret polarization','Prepolarized microphone','Polarization voltage','Diaphragm-backplate capacitance','Laboratory standard microphone']::text[],ARRAY['UNSAFE: Touching capsule terminals or the backplate while the 200 V polarization is applied, which can give a shock; discharge first.','UNSAFE: Powering a capsule with condensation present, where leakage across the high-voltage bias can arc or force collapse.','Confusing a 200 V polarizing supply with 48 V phantom power; they are different voltages for different jobs.','Assuming a measurement mic set to the wrong polarization voltage still reads correct sensitivity.']::text[],ARRAY['Setting the 200 V polarization for a laboratory standard measurement microphone.','Explaining why studio tube and FET condensers need an internal high-voltage bias.','Diagnosing a sensitivity error caused by a wrong polarization setting.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Externally polarized condenser microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aa1d9dcf-87be-4db4-9612-9f4dc8900c60','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aa1d9dcf-87be-4db4-9612-9f4dc8900c60') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aa1d9dcf-87be-4db4-9612-9f4dc8900c60');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '37cf8081-b202-4f98-be62-4c45f77226c8','Fabry–Pérot microphone','An optical microphone that senses sound from the change in a Fabry-Perot interferometer cavity, where a thin diaphragm forms one reflective surface and its motion modulates the cavity length and thus the reflected or transmitted light intensity. Because sensing is optical, the capsule carries no electrical bias and is immune to electromagnetic interference.','This microphone measures sound with light instead of electricity. A thin diaphragm forms a tiny reflective gap called a Fabry-Perot cavity. When sound moves the diaphragm, the gap changes and the reflected light changes. Reading that light change recovers the sound.','To detect diaphragm motion optically, giving a microphone that is immune to electromagnetic and radio interference and usable in strong fields such as MRI rooms.','In an MRI-safe or high-EMI setting, a technician uses a fiber-fed Fabry-Perot optical microphone whose reflected optical phase, phi = 4*pi*L/lambda, tracks the diaphragm gap L to recover audio.','Optical microphone',ARRAY['Fiber Bragg grating microphone','Optical microphone','Diaphragm','Interferometer','Electromagnetic interference']::text[],ARRAY['Assuming an optical microphone needs no power; the light source and photodetector electronics still need power.','Thinking optical sensing removes the diaphragm; a moving diaphragm still transduces the sound.','Confusing a Fabry-Perot cavity sensor with a fiber Bragg grating sensor; they read different optical effects.']::text[],ARRAY['Capturing audio inside an MRI scanner where metal and fields rule out normal microphones.','Measuring sound in strong electromagnetic environments.','Explaining interference-immune optical transduction.']::text[],'Advanced','phi = 4 * pi * L / lambda','The round-trip optical phase of the cavity equals four pi times the cavity length divided by the light wavelength.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fabry–Pérot microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '37cf8081-b202-4f98-be62-4c45f77226c8','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='37cf8081-b202-4f98-be62-4c45f77226c8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='37cf8081-b202-4f98-be62-4c45f77226c8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'be2a2c57-43b6-46d2-aa96-e1bdd381e871','Fiber Bragg grating microphone','An optical microphone that transduces sound through the strain-induced shift of the reflected wavelength of a fiber Bragg grating, a periodic index modulation written into an optical fiber. Sound-driven strain changes the grating period and effective index, shifting the Bragg wavelength that is detected optically.','This microphone uses a special optical fiber to hear sound. The fiber has a built-in pattern called a Bragg grating. Sound stretches the fiber slightly and shifts the color of light it reflects. Measuring that shift recovers the sound.','To sense acoustic strain optically with immunity to electromagnetic interference and the ability to place many sensors along one fiber.','A grating with effective index n = 1.45 and period Lambda = 535 nm reflects at Bragg wavelength lambda_B = 2*n*Lambda ~ 1551 nm; acoustic strain shifts lambda_B, which the interrogator reads as the audio signal.','Optical microphone',ARRAY['Fabry-Perot microphone','Optical microphone','Interferometer','Electromagnetic interference','Strain sensing']::text[],ARRAY['Assuming the fiber senses light color changes from the sound directly; sound acts through strain on the grating.','Ignoring temperature sensitivity, which also shifts the Bragg wavelength and must be compensated.','Confusing a Bragg grating sensor with a Fabry-Perot cavity sensor; they use different optical mechanisms.']::text[],ARRAY['Distributed acoustic sensing along a single optical fiber.','Measuring sound or vibration in high-EMI or explosive environments.','Comparing fiber Bragg grating and Fabry-Perot optical microphones.']::text[],'Advanced','lambda_B = 2 * n_eff * Lambda','The Bragg reflection wavelength equals twice the effective refractive index times the grating period.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fiber Bragg grating microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'be2a2c57-43b6-46d2-aa96-e1bdd381e871','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='be2a2c57-43b6-46d2-aa96-e1bdd381e871') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='be2a2c57-43b6-46d2-aa96-e1bdd381e871');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24d06876-aebd-4f05-9564-f08843601b64','Filter-and-sum beamformer','A beamformer that applies a separate finite-impulse-response filter to each microphone channel before summing, so its directivity and response can be shaped as a function of frequency. Filter-and-sum generalizes delay-and-sum by replacing each pure delay with a full filter, enabling frequency-independent beam patterns and superdirective designs.','This array method filters each microphone''s signal, then adds them together. Using a full filter per channel, not just a delay, gives finer control. It can hold the beam shape steady across frequency. It is a more flexible version of simple delay-and-sum.','To design a beamformer whose beam shape stays consistent over frequency and can be made superdirective, by choosing per-channel filters rather than single delays.','An engineer designs per-microphone FIR filters so a small array keeps a constant beamwidth from low to high frequency, then checks the white-noise-gain penalty of the superdirective solution.','Array processing',ARRAY['Fixed beamformer','Delay-and-sum beamformer','Differential beamforming','Superdirectivity','Diagonal loading']::text[],ARRAY['Confusing filter-and-sum with delay-and-sum; the former uses full filters, giving frequency-dependent control.','Ignoring the noise-gain penalty of aggressive superdirective filter designs.','Assuming the filters steer direction only; they also shape the frequency-dependent beam pattern.']::text[],ARRAY['Designing a constant-beamwidth microphone array.','Building a superdirective compact array with per-channel filters.','Explaining the step from delay-and-sum to filter-and-sum.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Filter-and-sum beamformer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24d06876-aebd-4f05-9564-f08843601b64','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24d06876-aebd-4f05-9564-f08843601b64') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24d06876-aebd-4f05-9564-f08843601b64');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a2c65110-8f72-4a2a-94fb-1908bac11bd8','Fixed beamformer','A beamformer whose weights are fixed by design and do not change with the incoming signal statistics, in contrast to an adaptive beamformer. Delay-and-sum, filter-and-sum, and differential beamformers are common fixed (data-independent) designs, chosen for predictable behavior and low computation.','A fixed beamformer uses set, unchanging weights. It does not adjust itself to the sounds it hears. This makes it predictable and simple to run. Delay-and-sum arrays are a common example.','To give a stable, low-cost, predictable spatial response, useful where the source geometry is known or where adaptive behavior would be too fragile.','For a fixed conference array, a technician loads precomputed delay-and-sum or shaded weights aimed at the meeting table, knowing the pattern will not drift with changing noise.','Array processing',ARRAY['Adaptive beamformer','Delay-and-sum beamformer','Filter-and-sum beamformer','Diagonal loading','Dolph-Chebyshev weighting']::text[],ARRAY['Assuming a fixed beamformer adapts to moving interference; it does not change with the signal.','Expecting adaptive-level interference nulling from fixed weights.','Confusing fixed weighting with fixed steering; a fixed beamformer can still be steered by design choice.']::text[],ARRAY['Deploying a predictable, low-compute array for a known meeting layout.','Choosing fixed over adaptive processing for robustness.','Teaching the contrast between data-independent and adaptive beamformers.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fixed beamformer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a2c65110-8f72-4a2a-94fb-1908bac11bd8','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a2c65110-8f72-4a2a-94fb-1908bac11bd8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a2c65110-8f72-4a2a-94fb-1908bac11bd8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '16ba6837-5937-437d-8c3b-28cde81b6c3c','Flicker noise','A low-frequency noise whose power spectral density rises as frequency falls, roughly in proportion to one over frequency (1/f), arising in semiconductors and resistive materials. In a microphone preamplifier flicker noise raises the noise floor at low audio frequencies, adding to the thermal and shot-noise floors.','Flicker noise is a random noise that grows as frequency drops. Its power rises roughly as one divided by frequency. That is why it is also called one-over-f noise. In a microphone preamp it lifts the noise floor at low frequencies.','To describe the low-frequency noise rise in active devices so designers pick low-flicker input parts and understand why self-noise climbs toward the bottom of the audio band.','Because power scales as S(f) = K/f, halving the frequency roughly doubles the noise power; a technician chooses JFETs known for low 1/f noise for a quiet condenser preamp.','Noise mechanism',ARRAY['Current-noise density','Dielectric noise','Equivalent acoustic noise','Thermal noise','Shot noise']::text[],ARRAY['Assuming the noise floor is flat with frequency; flicker noise makes it rise at low frequencies.','Confusing 1/f flicker noise with white thermal noise, which is frequency independent.','Expecting the same flicker level from every device; it varies strongly with device type and process.']::text[],ARRAY['Explaining a rising low-frequency noise floor in a condenser preamp.','Selecting low-1/f-noise input devices for microphone electronics.','Interpreting a measured noise spectrum that climbs toward low frequency.']::text[],'Advanced','S(f) = K / f^alpha,  alpha ~ 1','The noise power spectral density equals a device constant divided by frequency raised to an exponent near one.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flicker noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '16ba6837-5937-437d-8c3b-28cde81b6c3c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='16ba6837-5937-437d-8c3b-28cde81b6c3c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='16ba6837-5937-437d-8c3b-28cde81b6c3c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd2db6fa1-026e-4cbc-b61b-ce49c9ddd0ca','Free-field reciprocity','The reciprocity relationship used to calibrate microphones in a free (anechoic) sound field, where sound travels an unobstructed path between a reciprocal transducer acting as source and the microphone acting as receiver. It is the basis of the primary free-field calibration of laboratory standard microphones defined in IEC 61094-3.','This calibrates a microphone using sound over open air, not in a small cavity. One transducer acts as a speaker and another as the microphone. Because a microphone works the same in both roles, their combined free-field sensitivity can be found exactly. It needs an anechoic (echo-free) space.','To obtain the primary free-field sensitivity of laboratory standard microphones from first principles, giving traceable calibration for measurements of sound coming from a defined direction.','In an anechoic chamber a technician measures reciprocal microphone pairs over a known separation, and the free-field reciprocity relation yields each microphone''s free-field sensitivity in mV/Pa.','Calibration method',ARRAY['Coupler reciprocity','Diffuse-field correction','Free-field microphone','Laboratory standard microphone','Anechoic chamber']::text[],ARRAY['Confusing free-field reciprocity (open anechoic path) with pressure/coupler reciprocity (small closed cavity).','Ignoring propagation, distance, and diffraction corrections that the free-field method requires.','Assuming any quiet room suffices; reflections corrupt the free-field condition.']::text[],ARRAY['Establishing primary free-field sensitivity in an anechoic calibration lab.','Explaining why free-field and pressure sensitivities of a microphone differ.','Setting up an anechoic measurement of standard microphones.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Free-field reciprocity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd2db6fa1-026e-4cbc-b61b-ce49c9ddd0ca','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d2db6fa1-026e-4cbc-b61b-ce49c9ddd0ca') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d2db6fa1-026e-4cbc-b61b-ce49c9ddd0ca');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dd615433-f143-4fb3-a70e-c9f6a9896e85','Frequency-domain beamforming','An array-processing method that transforms each microphone signal into the frequency domain, then applies a complex weight to every frequency bin before summing the channels to steer or shape the array response. Working per frequency lets the weights match the wavelength-dependent geometry of the sound field.','A microphone array uses many mics at once. This method first splits each mic signal into separate frequencies. It then adjusts and adds the mics for each frequency on its own. This steers the array toward a chosen direction.','It lets an array apply the correct phase and gain at each frequency, so beam steering and noise rejection stay accurate across a wide band.','An engineer runs a short-time Fourier transform on each mic channel, multiplies each bin by steering weights, sums, then inverse-transforms to hear the steered output.','Array Beamforming',ARRAY['Frequency-invariant beamforming','MVDR beamformer','Frost beamformer','MUSIC algorithm','GCC-PHAT']::text[],ARRAY['Assuming one set of real gains works for all frequencies; weights must be complex and per-bin.','Ignoring spatial aliasing when mic spacing is larger than half a wavelength.','Forgetting that block length sets frequency resolution and latency.']::text[],ARRAY['Steering a conference-room mic array toward the active talker.','Suppressing steady fan noise while keeping speech in a smart speaker.','Designing sub-band weights for a broadband sound-capture array.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-domain beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dd615433-f143-4fb3-a70e-c9f6a9896e85','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dd615433-f143-4fb3-a70e-c9f6a9896e85') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dd615433-f143-4fb3-a70e-c9f6a9896e85');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4cf6bfc8-abbb-49c8-97ca-e8c92b315b3a','Frequency-invariant beamforming','A beamformer design in which the array''s directivity pattern stays nearly constant over a wide frequency range, achieved by shaping the per-frequency weights and often the effective aperture so the beam width does not change with frequency. It counters the natural tendency of a fixed array to form narrower beams at high frequencies.','A plain microphone array aims a narrow beam at high notes and a wide beam at low notes. That makes the sound colour change with direction. Frequency-invariant design keeps the beam the same shape at every frequency. So the captured tone stays even.','It gives a uniform beam shape across the audio band, which keeps timbre consistent for off-axis sources and simplifies broadband capture.','A designer scales the active aperture with frequency, using more mics at low frequencies and fewer at high, to hold a constant beam width from 200 Hz to 8 kHz.','Array Beamforming',ARRAY['Frequency-domain beamforming','MVDR beamformer','Linearly constrained minimum-variance beamformer','Frost beamformer']::text[],ARRAY['Believing any beamformer is automatically frequency-invariant; it requires deliberate design.','Overlooking that a fixed geometry gives frequency-dependent beam width by default.','Confusing constant beam width with constant on-axis gain.']::text[],ARRAY['Building a broadband hearing-aid or telephony array with even tone.','Designing a lecture-capture array that sounds natural off-axis.','Comparing nested sub-array structures for constant directivity.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-invariant beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4cf6bfc8-abbb-49c8-97ca-e8c92b315b3a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4cf6bfc8-abbb-49c8-97ca-e8c92b315b3a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4cf6bfc8-abbb-49c8-97ca-e8c92b315b3a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9efde159-b7f0-4966-a0e0-202bbf0c321d','Frost beamformer','A time-domain adaptive array algorithm that minimizes output power while holding the response toward the desired direction fixed by a set of linear constraints, using a constrained least-mean-square update on a tapped-delay-line filter behind each sensor. It is the classic adaptive realization of the linearly constrained minimum-variance criterion.','This is a smart microphone array that learns as it runs. It keeps full sensitivity toward the wanted direction. At the same time it lowers everything else to cut noise. It updates its filters step by step using an adaptive rule.','It adaptively suppresses interference and noise from other directions while guaranteeing a distortionless response toward the target, without needing to know the noise statistics in advance.','With a steering constraint fixed to unity gain at broadside, the filters adapt so a side interferer is nulled; the constraint vector f keeps the look direction protected.','Array Beamforming',ARRAY['Linearly constrained minimum-variance beamformer','MVDR beamformer','Frequency-domain beamforming','MUSIC algorithm']::text[],ARRAY['Setting the adaptation step too large, which makes the constrained update diverge.','Assuming it needs prior noise statistics; it learns them online.','Forgetting that steering-vector error leaks the target into the null and cancels signal.']::text[],ARRAY['Adaptive speech enhancement in a noisy vehicle cabin.','Nulling a fixed interfering loudspeaker during a live capture.','Teaching constrained adaptive filtering in an array course.']::text[],'Advanced','w = R^{-1} C (C^H R^{-1} C)^{-1} f','The optimum weight vector equals the inverse noise-plus-signal covariance times the constraint matrix, times the inverse of the constraint matrix Hermitian-transposed and multiplied by the inverse covariance and the constraint matrix again, all multiplied by the constraint response vector.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frost beamformer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9efde159-b7f0-4966-a0e0-202bbf0c321d','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9efde159-b7f0-4966-a0e0-202bbf0c321d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9efde159-b7f0-4966-a0e0-202bbf0c321d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5244f722-ef52-4f22-9cb7-fc8cdd6693ae','GCC-PHAT','The generalized cross-correlation with phase transform, a time-delay estimation method that cross-correlates two microphone signals after whitening each frequency bin by its magnitude, so only phase information sets the correlation peak. The lag of the peak gives the time difference of arrival between the two microphones.','Two microphones hear the same sound at slightly different times. This method finds that tiny time gap. It compares the two signals but keeps only their phase, not loudness. The strongest match points to the delay, which reveals the source direction.','It gives a sharp, robust estimate of the time difference of arrival for source localization, staying reliable in reverberant rooms where plain cross-correlation smears.','For a peak lag of 0.29 ms between two mics, the path-length difference is c times tau, about 343 m/s times 0.00029 s, roughly 0.10 m, which sets the source angle.','Localization',ARRAY['MUSIC algorithm','Frequency-domain beamforming','MVDR beamformer','Frost beamformer']::text[],ARRAY['Dividing by a magnitude near zero at quiet bins, which injects noise; a regularizer is needed.','Confusing the correlation lag axis sign, which flips the estimated direction.','Assuming one peak; strong reflections can create competing peaks.']::text[],ARRAY['Locating a talker for a camera-tracking video system.','Steering a smart-speaker beam toward a voice command.','Estimating time difference of arrival in a two-mic array.']::text[],'Advanced','R(tau) = integral psi(f) * X1(f) * conj(X2(f)) * e^{j 2 pi f tau} df,   psi_PHAT(f) = 1 / |X1(f) conj(X2(f))|','The generalized cross-correlation is the inverse Fourier transform of the cross-spectrum multiplied by a weighting function; the phase-transform weighting equals one divided by the magnitude of that cross-spectrum, keeping only phase.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='GCC-PHAT');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5244f722-ef52-4f22-9cb7-fc8cdd6693ae','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5244f722-ef52-4f22-9cb7-fc8cdd6693ae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5244f722-ef52-4f22-9cb7-fc8cdd6693ae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aeb3efe9-79b3-4f1b-abec-78299f1d674d','Grid diffraction','The change in a measurement microphone''s high-frequency response caused by the protective grid (protection grille) over the diaphragm, which scatters and reflects short-wavelength sound and alters the pressure that reaches the diaphragm. Manufacturers supply grid-on and grid-off correction curves so results can be adjusted.','A measurement microphone has a metal cap protecting its thin diaphragm. At high frequencies this cap bends and reflects the sound. That slightly changes what the microphone reads. Makers give correction curves for grid on and grid off.','It explains and corrects a real high-frequency error, so precision acoustic measurements stay accurate whether the grid is fitted or removed.','For flat free-field readings above about 10 kHz, a technician applies the datasheet grid-correction curve, or removes the grid in a clean lab and uses the grid-off curve.','Measurement Microphones',ARRAY['Incidence correction','Laboratory standard microphone','Insert-voltage technique','Free-field correction']::text[],ARRAY['UNSAFE: removing the protection grid exposes the fragile diaphragm; a touch or dust particle can permanently ruin the microphone.','Assuming the grid has no effect; it clearly shapes the top octave.','Mixing grid-on measurements with grid-off correction curves.']::text[],ARRAY['Calibrating a half-inch measurement microphone above 10 kHz.','Comparing free-field response with and without the protection grid.','Explaining a high-frequency bump in a precision sound measurement.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Grid diffraction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aeb3efe9-79b3-4f1b-abec-78299f1d674d','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aeb3efe9-79b3-4f1b-abec-78299f1d674d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aeb3efe9-79b3-4f1b-abec-78299f1d674d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fe2a0fdc-7973-41c1-8672-27b75ee0bb32','Heterodyne interferometry','An optical interferometry scheme in which the reference and measurement beams differ by a fixed carrier frequency, usually set by an acousto-optic (Bragg) cell, so the detector produces a beat signal at that carrier whose phase or frequency is modulated by the target''s motion. Demodulating the carrier recovers displacement or velocity with a known sense of direction.','This optical method splits a laser into two beams. One beam is shifted to a slightly different frequency. When the beams recombine they make a steady beat tone. Motion of the target changes that tone, and the change reveals speed and direction.','The carrier lets the system sense the direction of motion and stay stable at low signal levels, which is why laser vibrometers use it.','A Bragg cell offsets one beam by 40 MHz; the photodetector beat at 40 MHz is frequency-demodulated, and its Doppler shift gives the diaphragm velocity.','Optical Sensing',ARRAY['Homodyne interferometry','Laser Doppler vibrometry','Mach-Zehnder interferometer','Michelson interferometer','Interferometric displacement sensitivity']::text[],ARRAY['Confusing heterodyne with homodyne; heterodyne uses a nonzero carrier offset.','Assuming direction is ambiguous; the carrier resolves the sign of motion.','Ignoring that carrier bandwidth limits the maximum measurable velocity.']::text[],ARRAY['Non-contact measurement of a loudspeaker cone''s velocity.','Reading a microphone diaphragm''s motion without loading it.','Calibrating vibration references in a metrology lab.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Heterodyne interferometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fe2a0fdc-7973-41c1-8672-27b75ee0bb32','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fe2a0fdc-7973-41c1-8672-27b75ee0bb32') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fe2a0fdc-7973-41c1-8672-27b75ee0bb32');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '374d2e8e-f10c-4d4d-abb5-ab3a560ba712','Homodyne interferometry','An optical interferometry scheme in which the reference and measurement beams are at the same optical frequency, so the detector output varies directly with the interference phase set by the optical path difference. Without a carrier it is simple but needs quadrature detection to resolve the direction of motion and to avoid dead spots at phase extremes.','This optical method also splits a laser into two beams. Here both beams keep the same frequency. The detector signal rises and falls as the target moves. It is simple, but extra optics are needed to tell which way the target moves.','It offers a low-cost, low-noise displacement readout for small vibrations, common where a full carrier scheme is not needed.','A technician adds a quadrature (two-signal) detector so a diaphragm moving toward or away is distinguished, avoiding fringe-counting errors near peaks and troughs.','Optical Sensing',ARRAY['Heterodyne interferometry','Michelson interferometer','Mach-Zehnder interferometer','Interferometric displacement sensitivity','Laser Doppler vibrometry']::text[],ARRAY['Assuming a single detector gives motion direction; quadrature is required.','Operating at a phase peak or trough where sensitivity drops to zero.','Confusing homodyne (zero offset) with heterodyne (carrier offset).']::text[],ARRAY['A compact optical microphone reading membrane displacement.','Laboratory measurement of nanometre vibration amplitudes.','Teaching interferometer fringe behaviour and quadrature detection.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Homodyne interferometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '374d2e8e-f10c-4d4d-abb5-ab3a560ba712','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='374d2e8e-f10c-4d4d-abb5-ab3a560ba712') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='374d2e8e-f10c-4d4d-abb5-ab3a560ba712');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f5a2bb09-8745-4bd2-9a25-5183e91ff853','Humidity coefficient','The rate at which a microphone''s sensitivity changes with ambient relative humidity, expressed in decibels per percent relative humidity. For well-designed condenser measurement microphones it is very small, but it is characterized because moisture can affect the air gap, insulation, and any hygroscopic parts.','Air can be dry or damp. This number tells how much damp air changes a microphone''s output. For good measurement microphones the change is tiny. Makers still list it so lab results can be corrected.','It bounds one environmental influence on calibration, letting metrology labs judge or correct sensitivity errors from changing humidity.','A technician notes the humidity coefficient from the datasheet and, for precision work, records relative humidity so any small correction can be applied to the stated sensitivity.','Measurement Microphones',ARRAY['Laboratory standard microphone','Incidence correction','Insert-voltage technique','Integrated noise']::text[],ARRAY['Assuming humidity has no effect at all; it is small but specified.','UNSAFE: cleaning or drying a condenser capsule with heat or solvents can damage the diaphragm and coating.','Ignoring condensation, which can short the high-impedance capsule and cause noise.']::text[],ARRAY['Correcting a reference microphone''s sensitivity in a humid test bay.','Documenting environmental conditions during a primary calibration.','Investigating drifting readings after a change in room humidity.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Humidity coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f5a2bb09-8745-4bd2-9a25-5183e91ff853','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f5a2bb09-8745-4bd2-9a25-5183e91ff853') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f5a2bb09-8745-4bd2-9a25-5183e91ff853');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '92ce4b78-2db1-4dc2-9532-44d234648973','Hydrophobic acoustic membrane','A thin, water-repellent porous membrane, commonly expanded PTFE, placed over a microphone or speaker port to block liquid water and dust while letting sound pressure pass with minimal loss. Its high surface tension keeps water out up to a rated pressure, giving ingress protection without sealing the acoustic path.','This is a tiny water-proof mesh over a microphone hole. It stops water and dirt from getting in. Sound still passes through it almost freely. Phones and outdoor gear use it to survive rain and dust.','It protects a transducer from water and contaminants while preserving acoustic performance, enabling water-resistant phones, wearables, and outdoor microphones.','A designer specifies an expanded-PTFE vent membrane with a stated water-entry pressure and a small, known insertion loss, then tunes the port to keep response flat.','Microphone Construction',ARRAY['Acoustic mesh','Dust ingress','Windscreen','Ingress protection rating']::text[],ARRAY['Assuming the membrane is fully airtight; it passes sound and slow air, only blocking liquid water and dust.','Ignoring its insertion loss and added acoustic resistance when tuning the port.','UNSAFE: puncturing or peeling the membrane to ''improve'' sound removes the water seal and can ruin the device.']::text[],ARRAY['Waterproofing a smartphone or smartwatch microphone port.','Protecting an outdoor measurement microphone from rain.','Selecting a vent membrane with acceptable acoustic loss.']::text[],'Beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hydrophobic acoustic membrane');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '92ce4b78-2db1-4dc2-9532-44d234648973','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='92ce4b78-2db1-4dc2-9532-44d234648973') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='92ce4b78-2db1-4dc2-9532-44d234648973');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd031cd12-ca69-4205-a59b-6619a15adc27','IEPE sensor','An Integrated Electronics Piezo-Electric sensor, a transducer with a built-in field-effect amplifier that converts the piezoelectric element''s high-impedance charge into a low-impedance voltage, powered by a constant-current supply on the same two-wire coaxial line. The signal rides on a DC bias voltage that the readout removes with a coupling capacitor.','This is a sensor with a tiny amplifier built inside. It runs on a small steady current sent down one cable. That same cable carries the signal back. The design gives clean signals over long cables from vibration and sound sensors.','The internal amplifier and constant-current powering let piezoelectric microphones and accelerometers drive long cables with low noise and simple wiring.','A technician feeds about 4 mA constant current at a 24 to 30 V compliance; the sensor sits at roughly a 10 to 12 V bias, and the AC signal is read through a blocking capacitor.','Sensor Powering',ARRAY['Junction field-effect transistor','Microphone preamplifier','MEMS ASIC','Laboratory standard microphone']::text[],ARRAY['UNSAFE: applying phantom power or a voltage source instead of a constant-current supply can overheat and destroy the internal electronics.','Forgetting the settling time as the bias charges before valid readings.','Assuming the bias voltage is the signal; the audio is the AC riding on it.']::text[],ARRAY['Wiring a piezoelectric accelerometer to a data-acquisition input.','Powering a prepolarized measurement microphone with a CCLD supply.','Troubleshooting a missing bias voltage on an IEPE channel.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='IEPE sensor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd031cd12-ca69-4205-a59b-6619a15adc27','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d031cd12-ca69-4205-a59b-6619a15adc27') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d031cd12-ca69-4205-a59b-6619a15adc27');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e610ed4f-cb7c-4a04-82eb-d1cefe479196','Incidence correction','A frequency-dependent correction that converts a measurement microphone''s calibrated pressure or reference response to the response for a specific angle of sound incidence, most often 0 degrees (perpendicular) free field or random incidence. It accounts for how the microphone body and diaphragm diffract sound differently with direction at high frequencies.','A measurement microphone reacts a little differently to sound from the front than from the side. This correction adjusts the reading for the sound''s arrival angle. It matters most at high frequencies. Labs pick a front or random-incidence correction to match the test.','It lets one calibrated microphone give correct results in free-field, pressure, or diffuse-field conditions by adding the right angle-dependent curve.','For a source in front, a technician adds the datasheet 0-degree free-field correction to the pressure response, flattening the reading above a few kHz.','Measurement Microphones',ARRAY['Grid diffraction','Laboratory standard microphone','Free-field correction','Insert-voltage technique']::text[],ARRAY['Applying a free-field correction when the microphone is used in a diffuse field.','Ignoring incidence angle and assuming the response is flat in all directions.','Mixing pressure-response and free-field-response numbers without correction.']::text[],ARRAY['Setting up a free-field microphone facing a loudspeaker under test.','Choosing random-incidence correction for reverberation-room measurements.','Comparing pressure and free-field calibrations of one microphone.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Incidence correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e610ed4f-cb7c-4a04-82eb-d1cefe479196','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e610ed4f-cb7c-4a04-82eb-d1cefe479196') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e610ed4f-cb7c-4a04-82eb-d1cefe479196');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '988de411-91f3-4d33-9c87-a41a15135203','Insert-voltage technique','A microphone calibration method that determines the open-circuit sensitivity by inserting a known reference voltage in series with the capsule at the preamplifier input and adjusting it to match the response produced by a known sound pressure. It corrects for the loading effect of the preamplifier''s finite input impedance and gain.','A microphone''s true output is hard to measure directly. This method injects a known tiny voltage in series with the capsule. The technician sets that voltage to match the sound signal. The match reveals the microphone''s real open-circuit sensitivity.','It yields accurate open-circuit sensitivity that is not distorted by preamplifier loading, which is essential for traceable microphone calibration.','During calibration a technician applies a reference sound at 250 Hz, then injects a series voltage and trims it until the readout matches, reading sensitivity from the balanced voltage.','Measurement Microphones',ARRAY['Laboratory standard microphone','Incidence correction','Grid diffraction','Microphone preamplifier']::text[],ARRAY['Confusing the inserted voltage with the microphone''s own output; they are matched, not the same.','Neglecting the preamplifier loading that the method is designed to remove.','Using the wrong insertion point, which corrupts the series balance.']::text[],ARRAY['Traceable calibration of a working standard microphone.','Checking a preamplifier''s loading effect on a capsule.','Verifying open-circuit sensitivity in a metrology laboratory.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Insert-voltage technique');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '988de411-91f3-4d33-9c87-a41a15135203','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='988de411-91f3-4d33-9c87-a41a15135203') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='988de411-91f3-4d33-9c87-a41a15135203');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '47ae8503-5c7f-4ff5-97eb-ff4bea1c569c','Integrated noise','The total noise of a microphone or channel obtained by integrating its noise power spectral density over a specified bandwidth, giving a single root-mean-square value, often expressed as an equivalent input noise or A-weighted self-noise level. It summarizes broadband noise in one figure rather than a spectrum.','A microphone makes a faint hiss across many frequencies. Integrated noise adds all that hiss over a chosen band. It gives one single noise number. Engineers use it to compare how quiet different microphones are.','It reduces a full noise spectrum to a single comparable value, letting engineers rate self-noise and signal-to-noise for capture chains.','For a flat spectral density of 10 nV per root hertz over a 20 kHz band, the integrated noise is 10 nV/rtHz times the square root of 20000, about 1.4 microvolts rms.','Noise Measurement',ARRAY['Johnson-Nyquist noise','Laboratory standard microphone','Microphone preamplifier','MEMS ASIC']::text[],ARRAY['Adding noise voltages directly instead of adding powers (root-sum-square).','Forgetting the bandwidth and weighting, which set the number.','Comparing an A-weighted figure with an unweighted one as if equal.']::text[],ARRAY['Rating a condenser microphone''s A-weighted self-noise.','Comparing preamplifier equivalent input noise across a band.','Specifying the signal-to-noise ratio of a recording chain.']::text[],'Intermediate','V_n = sqrt( integral_{f1}^{f2} S_v(f) df )','The integrated noise voltage equals the square root of the noise power spectral density integrated over the lower to upper band edges.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Integrated noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '47ae8503-5c7f-4ff5-97eb-ff4bea1c569c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='47ae8503-5c7f-4ff5-97eb-ff4bea1c569c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='47ae8503-5c7f-4ff5-97eb-ff4bea1c569c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e08137f6-a373-4d98-a624-6bab2335e41a','Interferometric displacement sensitivity','The change in interference phase produced per unit change in the target''s displacement in an optical interferometer, set by the wavelength and the number of passes of light over the moving path. For a double-pass Michelson arrangement it is four pi over the wavelength radians per metre.','An optical sensor turns tiny motion into a change of light phase. This number says how much phase change each nanometre of motion gives. Shorter light wavelength means more sensitivity. It shows why lasers can read very small vibrations.','It quantifies how finely an interferometer can resolve motion, guiding the design of optical microphones and vibrometers.','With a 633 nm laser in a double-pass Michelson, sensitivity is four pi over 633 nm; a 1 nm move gives about 4 pi times 1.58e-3, roughly 0.020 radians of phase.','Optical Sensing',ARRAY['Michelson interferometer','Mach-Zehnder interferometer','Homodyne interferometry','Heterodyne interferometry','Laser Doppler vibrometry']::text[],ARRAY['Forgetting the factor of two extra sensitivity from double-pass (round-trip) geometry.','Assuming sensitivity is constant across the fringe; it is highest at quadrature and zero at peaks.','Ignoring that longer wavelength lowers displacement sensitivity.']::text[],ARRAY['Estimating the smallest diaphragm motion an optical microphone can read.','Designing a laser vibrometer for nanometre vibration.','Explaining why phase noise limits interferometric resolution.']::text[],'Advanced','dphi/dx = 4*pi / lambda   (double-pass Michelson);  2*pi/lambda (single pass)','The interferometric displacement sensitivity, in radians of phase per metre, equals four pi divided by the optical wavelength for a double-pass geometry, or two pi over the wavelength for a single pass.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interferometric displacement sensitivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e08137f6-a373-4d98-a624-6bab2335e41a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e08137f6-a373-4d98-a624-6bab2335e41a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e08137f6-a373-4d98-a624-6bab2335e41a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c70aa388-7373-494a-9c51-a7d803ea2585','Ionophone microphone','A near-massless acoustic sensor in which sound pressure modulates an electrical discharge in ionized air, so the changing ion current or discharge voltage tracks the sound. The name recalls the ionophone plasma loudspeaker developed by Siegfried Klein; as a microphone the approach remains largely experimental.','This microphone senses sound with glowing, ionized air instead of a moving part. Sound pressure changes the tiny electric discharge. That change becomes the audio signal. Having almost no moving mass, it can react very fast, but it stays rare and experimental.','By replacing a heavy diaphragm with ionized gas, it aims for extremely low moving mass and wide bandwidth, useful in research on plasma acoustic transducers.','A researcher biases a small corona or glow discharge, then reads the sound-induced modulation of its current, calibrating the microphone against a reference in a controlled rig.','Specialty Microphones',ARRAY['Microflown sensor','Laboratory standard microphone','Hydrophobic acoustic membrane','Microphone preamplifier']::text[],ARRAY['UNSAFE: the discharge uses high voltage and produces ozone; it needs proper insulation and ventilation.','Assuming it is a common studio microphone; it is a research device, not a product.','Confusing the ionophone loudspeaker with a microphone; the name comes from the speaker.']::text[],ARRAY['Research into massless, wide-band acoustic transducers.','Demonstrating a plasma-based sound sensor in a lab.','Studying microplasma microphones in an acoustics paper.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ionophone microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c70aa388-7373-494a-9c51-a7d803ea2585','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c70aa388-7373-494a-9c51-a7d803ea2585') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c70aa388-7373-494a-9c51-a7d803ea2585');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '341c1857-184d-4360-ab2b-fb3295927cac','Johnson–Nyquist noise','The thermal noise voltage generated across any resistance by the random motion of charge carriers, with a mean-square value equal to four times Boltzmann''s constant times absolute temperature times resistance times bandwidth. It sets a fundamental noise floor for microphones, preamplifiers, and any resistive source.','Every resistor makes a faint hiss just from heat. Warmer and larger resistances hiss more. This noise sets the lowest possible noise floor. It limits how quiet a microphone and its preamp can be.','It defines the unavoidable thermal noise floor, so designers know the best self-noise a resistive source and its amplifier can reach.','For a 1 kohm resistor at 300 K over 20 kHz, the noise is the square root of 4 times 1.38e-23 times 300 times 1000 times 20000, about 0.58 microvolts rms.','Noise Measurement',ARRAY['Integrated noise','Junction field-effect transistor','Microphone preamplifier','MEMS ASIC']::text[],ARRAY['Thinking a quieter design can go below the thermal floor of its source resistance.','Forgetting the bandwidth factor; wider bandwidth means more noise.','Confusing thermal (Johnson) noise with shot noise, which needs a current flow.']::text[],ARRAY['Estimating the noise floor set by a microphone''s source impedance.','Choosing preamplifier input resistors for low self-noise.','Explaining why cooling a resistor lowers its thermal noise.']::text[],'Intermediate','<v_n^2> = 4 * k_B * T * R * df','The mean-square thermal noise voltage equals four times Boltzmann''s constant times the absolute temperature times the resistance times the bandwidth.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Johnson–Nyquist noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '341c1857-184d-4360-ab2b-fb3295927cac','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='341c1857-184d-4360-ab2b-fb3295927cac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='341c1857-184d-4360-ab2b-fb3295927cac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e28b3573-7a6d-4e5f-bc43-e027f267b9ef','Junction field-effect transistor','A three-terminal semiconductor amplifying device whose gate-channel PN junction, reverse-biased, controls current between source and drain through the width of a conducting channel. Its very high input impedance makes it the classic impedance converter inside condenser microphone capsules.','A JFET is a small transistor that amplifies signals. Its input barely draws any current. That very high input resistance suits a condenser microphone capsule. It turns the capsule''s tiny high-impedance signal into a usable low-impedance one.','Its high input impedance and low noise let it buffer a condenser capsule''s fragile, high-impedance signal without loading it down.','In an electret microphone, a single JFET in a source-follower converts the capsule''s high impedance to a low one, biased through a resistor from the phantom or bias supply.','Microphone Electronics',ARRAY['Microphone preamplifier','MEMS ASIC','IEPE sensor','Johnson–Nyquist noise']::text[],ARRAY['Confusing a JFET with a MOSFET; the JFET gate is a reverse-biased PN junction.','Loading the capsule with too low a gate resistance, which cuts low-frequency response.','Assuming the gate draws no current; a tiny leakage current still flows.']::text[],ARRAY['Impedance conversion inside an electret condenser microphone.','Designing a low-noise front end for a capacitor capsule.','Troubleshooting a dead electret capsule''s JFET buffer.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Junction field-effect transistor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e28b3573-7a6d-4e5f-bc43-e027f267b9ef','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e28b3573-7a6d-4e5f-bc43-e027f267b9ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e28b3573-7a6d-4e5f-bc43-e027f267b9ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '110ab459-6649-4e70-a503-1e52363efb90','Laboratory standard microphone','A precision condenser microphone built and specified for the highest calibration accuracy and stability, used as a primary reference and calibrated by the reciprocity method. International standards define one-inch (LS1) and half-inch (LS2) types with tightly controlled dimensions and characteristics.','This is the most accurate kind of measurement microphone. Labs use it as a master reference. It is very stable and made to strict rules. Other microphones are calibrated by comparing them to it.','It provides a traceable, highly stable acoustic reference so other microphones and sound levels can be calibrated with known accuracy.','A national lab calibrates an LS2 half-inch standard by reciprocity, then uses it to transfer calibration to working microphones by comparison.','Measurement Microphones',ARRAY['Insert-voltage technique','Incidence correction','Grid diffraction','Integrated noise']::text[],ARRAY['Treating an ordinary measurement microphone as a laboratory standard; the grade and traceability differ.','UNSAFE: handling the bare capsule or touching the diaphragm, which can permanently damage this costly reference.','Ignoring environmental corrections that the reference''s accuracy depends on.']::text[],ARRAY['Primary calibration by reciprocity in a metrology lab.','Transferring calibration to working standard microphones.','Serving as the reference in an interlaboratory comparison.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Laboratory standard microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '110ab459-6649-4e70-a503-1e52363efb90','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='110ab459-6649-4e70-a503-1e52363efb90') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='110ab459-6649-4e70-a503-1e52363efb90');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c98ca43c-8dfe-4ee1-88af-a5b5e6cc984c','Laser Doppler vibrometry','A non-contact technique that measures the velocity of a vibrating surface from the Doppler frequency shift of laser light reflected from it, recovered by optical interferometry. Because it adds no mass, it is ideal for reading the motion of light diaphragms and small structures.','A laser beam is aimed at a vibrating surface. The moving surface shifts the light''s frequency a little. The instrument measures that shift to find the surface speed. It touches nothing, so it does not weigh down a thin diaphragm.','It gives accurate, load-free velocity measurement of vibrating surfaces, widely used to characterize transducers and structures.','For a surface moving at 0.01 m/s toward a 633 nm laser, the Doppler shift is two times 0.01 divided by 633e-9, about 31.6 kHz, which the interferometer demodulates.','Optical Sensing',ARRAY['Heterodyne interferometry','Homodyne interferometry','Michelson interferometer','Laser ultrasonics','Interferometric displacement sensitivity']::text[],ARRAY['Assuming it reads displacement directly; it senses velocity, then integrates for displacement.','Ignoring speckle dropout from a poorly reflecting rough surface.','Forgetting that only the motion component along the beam is measured.']::text[],ARRAY['Mapping a loudspeaker cone''s velocity without contact.','Measuring a microphone diaphragm''s vibration pattern.','Non-contact modal testing of a small structure.']::text[],'Advanced','f_D = 2 * v / lambda','The Doppler frequency shift equals two times the surface velocity along the beam divided by the optical wavelength.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Laser Doppler vibrometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c98ca43c-8dfe-4ee1-88af-a5b5e6cc984c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c98ca43c-8dfe-4ee1-88af-a5b5e6cc984c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c98ca43c-8dfe-4ee1-88af-a5b5e6cc984c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b63220f7-af29-4ab1-b194-cd7f6b1c33e6','Laser ultrasonics','A fully non-contact method that uses a pulsed laser to generate ultrasonic waves in a material by rapid thermoelastic expansion or slight surface ablation, and a second laser interferometer to detect the resulting surface motion. It enables ultrasonic inspection where contact transducers cannot be used.','A short laser pulse hits a surface and makes it expand fast. That expansion launches ultrasound into the material. A second laser reads the surface motion to detect flaws. Nothing touches the part, so it works on hot or moving pieces.','It provides remote generation and detection of ultrasound for non-destructive testing on surfaces that contact transducers cannot reach.','A technician fires generation pulses to launch ultrasound, then uses an interferometric receiver to time echoes and reveal a subsurface defect in a hot metal part.','Optical Sensing',ARRAY['Laser Doppler vibrometry','Michelson interferometer','Heterodyne interferometry','Interferometric displacement sensitivity']::text[],ARRAY['Confusing it with laser vibrometry; here the laser also generates the ultrasound.','UNSAFE: high-power pulsed lasers require eye protection and interlocks to prevent injury.','Assuming ablation is always used; low-power work stays in the thermoelastic regime.']::text[],ARRAY['Inspecting hot metal in a rolling mill without contact.','Testing composite parts where couplant is not allowed.','Research on non-contact ultrasonic evaluation.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Laser ultrasonics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b63220f7-af29-4ab1-b194-cd7f6b1c33e6','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b63220f7-af29-4ab1-b194-cd7f6b1c33e6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b63220f7-af29-4ab1-b194-cd7f6b1c33e6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '067a0f1e-4280-4970-a4b9-86d562c9690c','Linearly constrained minimum-variance beamformer','An array beamformer that minimizes the output power (variance) subject to one or more linear constraints on the response, most commonly a distortionless gain toward the desired direction. Its closed-form weight solution uses the array covariance matrix and the constraint matrix.','This microphone array lowers total output as much as possible. But it is forced to keep set responses toward chosen directions. Usually it keeps full, undistorted gain on the target. Doing both cuts noise while protecting the wanted sound.','It gives flexible, optimal noise and interference suppression while enforcing exact gains toward chosen look directions.','With a single unity-gain constraint on the target direction, the LCMV weights reduce to the MVDR solution; extra constraints can also null a known interferer.','Array Beamforming',ARRAY['Frost beamformer','MVDR beamformer','Frequency-domain beamforming','MUSIC algorithm','Frequency-invariant beamforming']::text[],ARRAY['Adding more constraints than sensors, which leaves no freedom to suppress noise.','Assuming steering errors are harmless; they leak signal into the minimized output.','Confusing LCMV (batch, covariance-based) with the Frost time-domain adaptive form.']::text[],ARRAY['Speech capture with a protected look direction and nulled interferer.','Designing an array with multiple response constraints.','Deriving MVDR as the single-constraint special case.']::text[],'Advanced','w = R^{-1} C (C^H R^{-1} C)^{-1} g','The weight vector equals the inverse array covariance times the constraint matrix, times the inverse of the constraint matrix Hermitian-transposed times the inverse covariance times the constraint matrix, times the desired response vector.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Linearly constrained minimum-variance beamformer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '067a0f1e-4280-4970-a4b9-86d562c9690c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='067a0f1e-4280-4970-a4b9-86d562c9690c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='067a0f1e-4280-4970-a4b9-86d562c9690c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ea55c204-e8d6-409b-be80-16b4f616921f','MEMS ASIC','The application-specific integrated circuit paired with a micro-electro-mechanical microphone element inside a MEMS microphone package, which buffers the capsule''s high-impedance signal, provides bias, and outputs analog or digital audio. In digital MEMS microphones it includes the analog-to-digital converter that produces a PDM or I2S bitstream.','A MEMS microphone has two chips in one small package. One is the tiny sensing element. The other is this control chip. It boosts the weak signal and, in digital versions, turns it into a data stream.','It conditions and, when digital, converts the MEMS sensor''s signal, making the tiny capsule usable directly by phones and devices.','A designer picks a digital MEMS microphone whose ASIC outputs a pulse-density-modulation stream, then clocks it and decimates to standard PCM audio.','MEMS Microphones',ARRAY['MEMS backplate','MEMS diaphragm','Junction field-effect transistor','Microphone preamplifier','IEPE sensor']::text[],ARRAY['Assuming the ASIC is the sensor; it is the electronics beside the MEMS element.','Ignoring the PDM clock rate, which sets bandwidth and noise shaping.','Treating analog and digital MEMS microphones as interchangeable in a design.']::text[],ARRAY['Interfacing a digital MEMS microphone''s bitstream to a processor.','Comparing analog versus digital MEMS microphone front ends.','Diagnosing noise from an unstable MEMS microphone clock.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='MEMS ASIC');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ea55c204-e8d6-409b-be80-16b4f616921f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ea55c204-e8d6-409b-be80-16b4f616921f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ea55c204-e8d6-409b-be80-16b4f616921f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5ecb86a7-b132-4fe8-9585-840006a38c24','MEMS backplate','The rigid, perforated fixed electrode in a MEMS condenser microphone, etched in silicon and separated from the moving diaphragm by a narrow air gap to form a variable capacitor. Its perforations let air pass so the diaphragm can move freely while the plate stays still.','Inside a MEMS microphone sits a stiff, hole-filled plate. It does not move. A thin diaphragm vibrates just above it. Together they act like a capacitor whose value changes with sound.','It forms the fixed half of the microphone''s capacitor, so diaphragm motion changes capacitance and produces the electrical signal.','A device engineer relies on the backplate''s holes to reduce air damping; their size and count set the microphone''s noise and high-frequency behaviour.','MEMS Microphones',ARRAY['MEMS diaphragm','MEMS ASIC','Microphone preamplifier','Grid diffraction']::text[],ARRAY['Confusing the fixed backplate with the moving diaphragm.','Assuming the holes are cosmetic; they control air damping and noise.','Ignoring the air-gap spacing, which sets sensitivity and pull-in risk.']::text[],ARRAY['Explaining how a MEMS condenser converts sound to capacitance change.','Analyzing acoustic noise from backplate air damping.','Comparing MEMS capsule construction to traditional condenser capsules.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='MEMS backplate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5ecb86a7-b132-4fe8-9585-840006a38c24','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5ecb86a7-b132-4fe8-9585-840006a38c24') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5ecb86a7-b132-4fe8-9585-840006a38c24');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a666b8eb-bafe-4b9f-9573-3d849a004fa9','MEMS diaphragm','The thin, flexible silicon membrane in a MEMS microphone that moves with sound pressure, forming the movable electrode of the microphone''s variable capacitor opposite the fixed backplate. Its very small mass and size give wide bandwidth and good unit-to-unit consistency.','This is the tiny moving film inside a MEMS microphone. Sound pressure makes it flex. Its motion changes the capacitor''s value. Because it is so small and light, it reacts fast and matches well between units.','It is the moving sensing element that turns sound pressure into a capacitance change, defining the microphone''s sensitivity and bandwidth.','A designer uses the diaphragm''s tight tolerances so many MEMS microphones in an array match closely, which beamforming needs for accurate steering.','MEMS Microphones',ARRAY['MEMS backplate','MEMS ASIC','Hydrophobic acoustic membrane','Microphone preamplifier']::text[],ARRAY['Confusing the moving diaphragm with the fixed backplate.','Assuming larger always means better; the tiny diaphragm favours bandwidth and matching.','Ignoring the vent that equalizes static pressure and sets the low-frequency roll-off.']::text[],ARRAY['Building a matched MEMS microphone array for beamforming.','Explaining MEMS microphone sensitivity and bandwidth.','Comparing MEMS and electret capsule diaphragms.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='MEMS diaphragm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a666b8eb-bafe-4b9f-9573-3d849a004fa9','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a666b8eb-bafe-4b9f-9573-3d849a004fa9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a666b8eb-bafe-4b9f-9573-3d849a004fa9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5522ab7d-d2c6-4fe5-b80c-e337ccf5bc8b','MUSIC algorithm','Multiple Signal Classification, a subspace method that estimates the directions of arrival of sources by splitting the array covariance matrix into signal and noise subspaces, then finding angles whose steering vectors are orthogonal to the noise subspace. Those angles appear as sharp peaks in the MUSIC pseudospectrum.','MUSIC finds the directions of several sound sources at once. It studies the array''s data to separate signal from noise parts. Directions that match real sources stand out as sharp peaks. It can resolve sources closer than simple beam scanning can.','It gives high-resolution direction-of-arrival estimates for multiple sources, beyond the resolution of a plain scanned beam.','With 4 microphones and 1 source, the noise subspace has 3 dimensions; the pseudospectrum peaks at the one angle whose steering vector is orthogonal to that subspace.','Localization',ARRAY['GCC-PHAT','MVDR beamformer','Frequency-domain beamforming','Frost beamformer','Linearly constrained minimum-variance beamformer']::text[],ARRAY['Overestimating the number of sources, which corrupts the subspace split.','Assuming it works with fully correlated (coherent) sources without extra smoothing.','Ignoring calibration errors, which blur the sharp peaks.']::text[],ARRAY['Resolving two closely spaced talkers with a microphone array.','Estimating source directions in a research localization system.','Comparing subspace methods to beam-scanning localization.']::text[],'Advanced','P_MUSIC(theta) = 1 / ( a^H(theta) * E_n * E_n^H * a(theta) )','The MUSIC pseudospectrum equals one divided by the squared projection of the steering vector for a candidate angle onto the noise subspace; it peaks where the steering vector is orthogonal to that subspace.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='MUSIC algorithm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5522ab7d-d2c6-4fe5-b80c-e337ccf5bc8b','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5522ab7d-d2c6-4fe5-b80c-e337ccf5bc8b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5522ab7d-d2c6-4fe5-b80c-e337ccf5bc8b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a8fd70bf-ec5c-4f2d-9c19-b37026abdfe3','MVDR beamformer','The minimum-variance distortionless-response beamformer, which minimizes total array output power while constraining unity gain toward the desired direction, so the target passes undistorted and everything else is suppressed. It is the single-constraint case of the linearly constrained minimum-variance beamformer.','This microphone array keeps the target sound at full, unchanged level. At the same time it makes total output as small as it can. That forces noise and interference from other directions down. The wanted signal stays clean.','It gives optimal interference and noise suppression while guaranteeing the desired direction is passed without distortion.','The weight vector is R-inverse times the steering vector, divided by the steering vector times R-inverse times itself; this holds unity gain on target while minimizing power.','Array Beamforming',ARRAY['Linearly constrained minimum-variance beamformer','Frost beamformer','MUSIC algorithm','Frequency-domain beamforming','GCC-PHAT']::text[],ARRAY['Assuming perfect steering; look-direction error causes self-nulling of the target.','Using a rank-deficient covariance estimate, which makes the inverse unstable.','Confusing MVDR (also called Capon) with a fixed delay-and-sum beamformer.']::text[],ARRAY['Enhancing a target talker while suppressing room noise.','Adaptive nulling of interference in a communication array.','Estimating a spatial power spectrum by the Capon method.']::text[],'Advanced','w = ( R^{-1} d ) / ( d^H R^{-1} d )','The MVDR weight vector equals the inverse covariance matrix times the steering vector, divided by the steering vector Hermitian-transposed times the inverse covariance matrix times the steering vector.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='MVDR beamformer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a8fd70bf-ec5c-4f2d-9c19-b37026abdfe3','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a8fd70bf-ec5c-4f2d-9c19-b37026abdfe3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a8fd70bf-ec5c-4f2d-9c19-b37026abdfe3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f4c02d00-1b48-4830-86bb-41646dbae4c9','Mach–Zehnder interferometer','A two-beam interferometer that splits light at one beam splitter into two separate paths and recombines it at a second, so a change in the optical path of one arm shifts the interference at the outputs. Its separated arms suit sensing a phase change along one path, as in some optical microphones.','This device splits a light beam into two separate paths. The two paths later join again. If sound changes one path a little, the combined light brightness changes. That change becomes the sound signal.','Its two independent arms let one path sense an acoustic or index change while the other stays a fixed reference, giving a phase-sensitive readout.','In an optical microphone, sound modulates the refractive index or path in one arm; the recombined intensity, read at quadrature, tracks the pressure.','Optical Sensing',ARRAY['Michelson interferometer','Homodyne interferometry','Heterodyne interferometry','Interferometric displacement sensitivity']::text[],ARRAY['Confusing it with a Michelson; the Mach-Zehnder uses two splitters and separated paths, not one splitter with retroreflection.','Operating away from quadrature, where sensitivity falls.','Ignoring drift between the two arms, which needs stabilization.']::text[],ARRAY['Building a fibre-optic or free-space optical microphone.','Sensing acoustic pressure via refractive-index change in one arm.','Teaching two-path interference and phase sensing.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mach–Zehnder interferometer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f4c02d00-1b48-4830-86bb-41646dbae4c9','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f4c02d00-1b48-4830-86bb-41646dbae4c9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f4c02d00-1b48-4830-86bb-41646dbae4c9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4b630f30-608c-4675-9775-7b043024b493','Michelson interferometer','A two-beam interferometer that splits light at one beam splitter, sends the beams to two mirrors, and recombines them after they return along the same paths, so moving one mirror changes the interference by twice the displacement. Its double-pass geometry gives high displacement sensitivity, used in vibrometers and optical microphones.','This device splits a light beam toward two mirrors. The beams bounce back and rejoin. Moving one mirror shifts the light pattern. Because the light travels the path twice, small motions show up strongly.','Its retro-reflecting arms give sensitive displacement measurement, making it a common core for laser vibrometry and optical acoustic sensors.','A vibrometer bounces the measurement beam off a diaphragm-mounted mirror; each half-wavelength of motion sweeps one full fringe, giving fine displacement readout.','Optical Sensing',ARRAY['Mach–Zehnder interferometer','Laser Doppler vibrometry','Homodyne interferometry','Heterodyne interferometry','Interferometric displacement sensitivity']::text[],ARRAY['Forgetting the double-pass factor of two between mirror motion and path change.','Confusing it with the Mach-Zehnder''s two-splitter, separated-path layout.','Reading amplitude at a fringe peak, where sensitivity drops to zero.']::text[],ARRAY['The optical core of a laser Doppler vibrometer.','Measuring nanometre diaphragm displacement in a lab.','Demonstrating fringe counting and half-wavelength resolution.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Michelson interferometer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4b630f30-608c-4675-9775-7b043024b493','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4b630f30-608c-4675-9775-7b043024b493') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4b630f30-608c-4675-9775-7b043024b493');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8b886bb0-d648-4688-b516-d6a4e5042d22','Microflown sensor','An acoustic particle-velocity sensor that uses two closely spaced heated platinum wires; sound-driven airflow cools them asymmetrically, and the resulting temperature and resistance difference measures particle velocity directly, not pressure. It is a MEMS device made by Microflown Technologies and has a figure-of-eight directivity along the wire axis.','Most microphones measure sound pressure. This sensor measures how fast air particles move instead. It uses two tiny hot wires side by side. Moving air cools one wire more than the other, and that difference gives the signal.','It measures acoustic particle velocity directly, enabling sound-intensity and vector measurements that a pressure microphone alone cannot make.','Paired with a pressure microphone in a p-u probe, it lets a technician measure sound intensity and locate sources by combining pressure and velocity.','Specialty Microphones',ARRAY['Ionophone microphone','Laboratory standard microphone','MEMS diaphragm','Hydrophobic acoustic membrane']::text[],ARRAY['Assuming it senses pressure; it senses particle velocity and is a vector (figure-of-eight) sensor.','Forgetting that Microflown is a trademark of Microflown Technologies for this specific device.','Ignoring its limited high-frequency range compared with a pressure microphone.']::text[],ARRAY['Measuring sound intensity with a combined pressure-velocity probe.','Locating noise sources by sensing the velocity vector.','Near-field acoustic holography with velocity data.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microflown sensor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8b886bb0-d648-4688-b516-d6a4e5042d22','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8b886bb0-d648-4688-b516-d6a4e5042d22') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8b886bb0-d648-4688-b516-d6a4e5042d22');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '745325b1-fe20-441f-bf23-c7086b3eebe2','Microphone preamplifier','An amplifier that raises the very low output of a microphone to line level while providing a suitable input impedance, low noise, and, for condenser microphones, phantom power. It sets the gain, noise floor, and headroom at the front of a recording or sound-reinforcement chain.','A microphone''s signal is very weak. A preamplifier boosts it up to a usable level. It adds as little noise as possible while doing so. For condenser microphones it also sends power up the cable.','It provides clean gain and the correct input conditions so the weak microphone signal can drive later equipment without added noise or distortion.','A technician sets preamp gain so peaks sit safely below clipping, and switches 48 V phantom power on only for condenser microphones that need it.','Microphone Electronics',ARRAY['Junction field-effect transistor','MEMS ASIC','IEPE sensor','Integrated noise','Johnson–Nyquist noise']::text[],ARRAY['UNSAFE: applying 48 V phantom power to many ribbon microphones, or hot-patching with phantom on, can burn out the ribbon or capsule.','Turning phantom power on or off with faders up, which sends a loud thump downstream.','Confusing input gain with output level, or setting gain so high it clips.']::text[],ARRAY['Setting gain and phantom power for a condenser vocal microphone.','Choosing a low-noise preamp for a quiet room recording.','Protecting a ribbon microphone from phantom power on a shared console.']::text[],'Beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microphone preamplifier');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '745325b1-fe20-441f-bf23-c7086b3eebe2','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='745325b1-fe20-441f-bf23-c7086b3eebe2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='745325b1-fe20-441f-bf23-c7086b3eebe2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9293a0fc-4300-4749-a50e-c75ee22f183a','Microphone reciprocity','The principle that a microphone built as a reciprocal transducer works equally well in reverse as a sound source, with a fixed relationship between its receiving sensitivity and its transmitting response. This reversibility underlies the primary reciprocity calibration of laboratory standard microphones, in which three reversible cartridges are measured pairwise in an acoustic coupler and their absolute pressure sensitivities are solved without any prior reference microphone.','A reciprocal microphone can also act as a tiny loudspeaker. Its listening sensitivity and its output as a source are linked by a fixed rule. This lets labs find a microphone''s true sensitivity from scratch. They measure three microphones in pairs and solve the math.','It provides an absolute, first-principles way to determine microphone sensitivity, so a national lab can establish the primary standard for sound pressure without relying on an already-calibrated reference.','Three reversible cartridges are coupled in pairs and their electrical transfer impedances measured; solving the equations yields each absolute pressure sensitivity, for example about 50 mV/Pa (-26 dB re 1 V/Pa) for a 1-inch laboratory standard microphone.','Calibration principle',ARRAY['Pistonphone calibration','Permanently polarized microphone','Pressure sensitivity','Acoustic coupler','Laboratory standard microphone']::text[],ARRAY['Assuming reciprocity calibration needs a reference microphone; the three-microphone method is absolute.','Thinking any microphone is reciprocal; ribbon and true condenser cartridges are, but not all types qualify.','Confusing the microphone''s electrical transfer impedance with its acoustic impedance in the coupler.']::text[],ARRAY['A metrology lab establishing the primary sound-pressure standard.','Calibrating 1-inch LS1 cartridges before field use.','Explaining why measurement mics can also emit a test tone.']::text[],'Advanced','M_a = sqrt( (Z_ab^e * Z_ac^e) / (Z_bc^e * Z_c^a) )','A microphone''s pressure sensitivity equals the square root of the product of its two pairwise electrical transfer impedances, divided by the third pair''s electrical transfer impedance times the coupler''s acoustic transfer impedance.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microphone reciprocity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9293a0fc-4300-4749-a50e-c75ee22f183a','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9293a0fc-4300-4749-a50e-c75ee22f183a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9293a0fc-4300-4749-a50e-c75ee22f183a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '917b6d11-69a3-4002-84bf-aedc09347e19','Minimum detectable pressure','The smallest sound pressure a microphone can resolve, set by its own self-noise: the equivalent sound pressure that produces an output equal to the microphone''s intrinsic noise in the stated bandwidth. It is usually expressed as an equivalent (often A-weighted) sound pressure level referred to 20 micropascals.','This is the quietest sound a microphone can pick out. Below it, the sound is buried in the microphone''s own hiss. The best studio condensers get down to a self-noise floor near 6 to 10 dB(A) SPL. That level equals only tens of millionths of a pascal.','It tells an engineer the noise floor of a microphone, so they can judge whether it can capture very quiet sources without its own hiss dominating.','For a microphone with a 6.5 dB(A) equivalent self-noise level, the minimum detectable pressure is 20 uPa x 10^(6.5/20) = about 42 uPa.','Noise metric',ARRAY['Noise-equivalent pressure','Minimum detectable signal','Noise spectral density','Self-noise','Equivalent noise level']::text[],ARRAY['Confusing minimum detectable pressure (self-noise floor) with maximum SPL (the loud limit).','Comparing self-noise numbers without checking the weighting and bandwidth used.','Assuming a higher sensitivity always means a lower detectable pressure; noise matters too.']::text[],ARRAY['Selecting a microphone for very quiet ambience or foley.','Comparing datasheet self-noise between two condenser mics.','Explaining why distant, quiet sources sound hissy.']::text[],'Intermediate','p_min = p_ref * 10^(L_n / 20)','The minimum detectable pressure equals the reference pressure of 20 micropascals multiplied by ten raised to the equivalent noise level in decibels divided by twenty.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Minimum detectable pressure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '917b6d11-69a3-4002-84bf-aedc09347e19','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='917b6d11-69a3-4002-84bf-aedc09347e19') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='917b6d11-69a3-4002-84bf-aedc09347e19');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c41af3fd-c7a3-4db4-837d-d57f7bd84d06','Minimum detectable signal','The smallest input a sensor can register with a signal-to-noise ratio of one, meaning the output just equals the root-mean-square noise. For a microphone it reduces to the input pressure whose output equals the self-noise; the value equals the noise divided by the responsivity.','This is the faintest input a sensor can still detect. At this point the signal is exactly as strong as the noise. You find it by dividing the noise by the sensitivity. Anything smaller disappears into the noise.','It sets the detection limit of any transducer, letting a technician know the lowest input worth trusting above the noise.','For 1.4 uV of output noise and a 50 mV/Pa microphone, the minimum detectable pressure is 1.4e-6 / 0.05 = about 28 uPa (an illustrative value).','Noise metric',ARRAY['Minimum detectable pressure','Noise-equivalent pressure','Noise spectral density','Signal-to-noise ratio','Responsivity']::text[],ARRAY['Assuming SNR of one is usable; real detection usually needs several dB more.','Ignoring bandwidth, which changes the noise and thus the detection limit.','Confusing the minimum detectable signal with the resolution or step size of a converter.']::text[],ARRAY['Setting the detection floor of a photoacoustic gas sensor.','Comparing quietest resolvable input across sensor designs.','Explaining why averaging over time lowers the detection limit.']::text[],'Intermediate','MDS = N / R','The minimum detectable signal equals the root-mean-square output noise divided by the responsivity, that is the input level giving a signal-to-noise ratio of one.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Minimum detectable signal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c41af3fd-c7a3-4db4-837d-d57f7bd84d06','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c41af3fd-c7a3-4db4-837d-d57f7bd84d06') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c41af3fd-c7a3-4db4-837d-d57f7bd84d06');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '194bb959-a251-4cd7-a40b-f228b78c8408','Narrowband beamformer','A microphone-array beamformer that assumes the signal occupies a narrow band around a single center frequency, so steering to a direction is done by applying complex weights (pure phase shifts) rather than true time delays. Its output is the weighted sum of the array''s per-element signals, y = w^H x, using the steering vector for the look direction.','This combines many microphones to listen in one direction. It works on a single narrow band of frequencies. For that band it just shifts each channel''s phase. Then it adds the channels together to boost the wanted direction.','It focuses an array toward a chosen direction within a narrow frequency band, boosting a target source and suppressing sound from other angles.','With half-wavelength spacing and a 30-degree steer angle, the phase shift between neighboring microphones is 2*pi*(d/lambda)*sin(theta) = 2*pi*0.5*0.5 = pi/2 (90 degrees).','Array beamforming',ARRAY['Phase shading','Planar microphone array','Neural beamforming','Steering vector','Spatial aliasing']::text[],ARRAY['Applying one narrowband weight set to wideband speech, which smears the beam across frequency.','Forgetting that phase-only steering assumes small fractional bandwidth.','Ignoring spatial aliasing when element spacing exceeds half a wavelength.']::text[],ARRAY['Processing one FFT bin of a microphone-array recording.','Steering a sonar or radar-style array at a fixed tone.','Teaching delay-and-sum before moving to wideband arrays.']::text[],'Advanced','y = w^H x,   with steering phase  Dphi = 2*pi*(d/lambda)*sin(theta)','The output is the conjugate-transpose weight vector times the array snapshot; the inter-element steering phase equals two pi times the spacing-to-wavelength ratio times the sine of the steer angle.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Narrowband beamformer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '194bb959-a251-4cd7-a40b-f228b78c8408','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='194bb959-a251-4cd7-a40b-f228b78c8408') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='194bb959-a251-4cd7-a40b-f228b78c8408');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee1057f3-13dd-49f5-8be6-d830fb9f6459','Neural beamforming','An array-processing approach in which a deep neural network estimates the quantities that drive a beamformer, typically time-frequency masks that separate target speech from noise so the spatial covariance matrices can be computed, after which a statistically optimum filter such as MVDR is applied. Some variants let the network output the multichannel filter directly.','This uses a trained neural network to help aim a microphone array. The network labels which time-frequency parts are speech or noise. Those labels build the math for an optimal filter. The filter then keeps the target voice and cuts the rest.','It improves robustness of spatial filtering in noisy, reverberant conditions by learning to identify the target, which classic hand-tuned beamformers struggle to do.','A network predicts speech and noise masks per time-frequency bin; the noise covariance R_n and steering vector then set the MVDR weights w = R_n^-1 a / (a^H R_n^-1 a).','Array beamforming',ARRAY['Narrowband beamformer','Phase shading','Planar microphone array','MVDR beamformer','Time-frequency mask']::text[],ARRAY['Assuming the network replaces the beamformer; usually it only estimates masks or covariances.','Expecting good results outside the acoustic conditions the network was trained on.','Confusing single-channel denoising with true multichannel spatial filtering.']::text[],ARRAY['Front-end enhancement for far-field voice assistants.','Cleaning conference-room speech before recognition.','Comparing learned masks against oracle masks in research.']::text[],'Advanced','w = (R_n^-1 * a) / (a^H * R_n^-1 * a)','The minimum-variance distortionless-response weights equal the inverse noise covariance times the steering vector, normalized by the steering vector times the inverse noise covariance times the steering vector.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Neural beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee1057f3-13dd-49f5-8be6-d830fb9f6459','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee1057f3-13dd-49f5-8be6-d830fb9f6459') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee1057f3-13dd-49f5-8be6-d830fb9f6459');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a91d171d-7c70-4b9e-9123-34b314ff1c5d','Noise spectral density','How a signal''s noise is distributed across frequency, given as power spectral density in volts squared per hertz, or as amplitude spectral density in volts per root-hertz (or pascals per root-hertz for microphones). The total root-mean-square noise is the square root of the spectral density integrated over the measurement bandwidth.','This shows how much noise sits at each frequency. It is quoted per hertz of bandwidth. For flat white noise the value stays constant. To get total noise you add it up across the band.','It lets an engineer predict how much noise a device adds in any chosen bandwidth, and reveals whether the noise is flat, rising, or dominated by low-frequency components.','A flat amplitude spectral density of 10 nV/rtHz across a 20 kHz bandwidth gives total noise of 10e-9 * sqrt(20000) = about 1.41 uV rms.','Noise metric',ARRAY['Noise-equivalent pressure','Minimum detectable pressure','Self-noise','Power spectral density','A-weighting']::text[],ARRAY['Adding noise voltages linearly instead of in quadrature (root-sum-square).','Confusing amplitude spectral density (per root-hertz) with power spectral density (per hertz).','Forgetting that wider bandwidth raises total noise even at constant spectral density.']::text[],ARRAY['Reading a microphone preamp''s input noise from a datasheet.','Predicting recorder noise over the audio band.','Diagnosing low-frequency hum rising above a white noise floor.']::text[],'Intermediate','e_n = sqrt( integral of S(f) df )','The total root-mean-square noise equals the square root of the noise power spectral density integrated over the measurement bandwidth.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise spectral density');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a91d171d-7c70-4b9e-9123-34b314ff1c5d','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a91d171d-7c70-4b9e-9123-34b314ff1c5d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a91d171d-7c70-4b9e-9123-34b314ff1c5d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f500055e-918f-453d-ab65-5fc2b3118510','Noise-equivalent pressure','The sound pressure that would produce a microphone output equal to its own noise in a given bandwidth, so the signal-to-noise ratio is one. It is often given as a pressure spectral density in pascals per root-hertz, or as an A-weighted equivalent sound pressure level, and equals the noise voltage density divided by the sensitivity.','This is the sound level that matches a microphone''s own noise. At that level the wanted sound and the hiss are equal. You get it by dividing the noise by the sensitivity. Lower numbers mean a quieter, more sensitive microphone.','It expresses a microphone or hydrophone''s noise floor in acoustic units, letting designers compare how faint a pressure each device can sense.','For a noise voltage density of 30 nV/rtHz and a sensitivity of 50 mV/Pa, the noise-equivalent pressure is 30e-9 / 0.05 = 600 nPa/rtHz (0.6 uPa/rtHz).','Noise metric',ARRAY['Minimum detectable pressure','Noise spectral density','Minimum detectable signal','Self-noise','Sensitivity']::text[],ARRAY['Quoting noise-equivalent pressure without stating the bandwidth or weighting.','Assuming it is a fixed dB SPL; it depends on frequency and bandwidth.','Mixing per-root-hertz density with a broadband A-weighted level.']::text[],ARRAY['Comparing hydrophone noise floors for underwater work.','Rating a MEMS microphone''s faintest resolvable pressure.','Specifying a measurement mic for low-level acoustics.']::text[],'Advanced','NEP = e_n / M','The noise-equivalent pressure equals the noise voltage spectral density divided by the microphone''s sensitivity.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise-equivalent pressure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f500055e-918f-453d-ab65-5fc2b3118510','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f500055e-918f-453d-ab65-5fc2b3118510') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f500055e-918f-453d-ab65-5fc2b3118510');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3aba0fc0-3ee8-4d81-91a8-dbd98dcb7913','Nonresonant photoacoustic cell','A photoacoustic sample chamber operated below any acoustic resonance, where the microphone senses the pressure rise produced as the sample absorbs modulated light and periodically heats the trapped gas in a fixed volume. Because no acoustic standing wave amplifies the signal, response depends mainly on cell volume and modulation frequency rather than a resonance gain.','This is a photoacoustic gas cell run below its resonant note. The gas heats and cools as the light pulses. That makes the pressure rise and fall in a sealed space. A microphone reads that pressure without help from an echo mode.','It gives a simple, broadband photoacoustic response for gas analysis when a resonant cell''s frequency lock or higher complexity is not wanted.','A technician keeps the light modulation frequency well below the cell''s lowest acoustic resonance, so signal scales with absorbed power and cell geometry, not resonance amplification.','Photoacoustic sensing',ARRAY['Photoacoustic cell','Photoacoustic spectroscopy','Photoacoustic microphone','Photothermal excitation','Optoacoustic microphone']::text[],ARRAY['Assuming a nonresonant cell is as sensitive as a resonant one; it lacks the resonance gain.','Modulating too fast so the cell drifts toward a resonance.','Neglecting window and wall absorption that add background signal.']::text[],ARRAY['Building a simple trace-gas photoacoustic detector.','Teaching photoacoustics before introducing resonant cells.','Comparing signal levels of resonant versus nonresonant cells.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nonresonant photoacoustic cell');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3aba0fc0-3ee8-4d81-91a8-dbd98dcb7913','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3aba0fc0-3ee8-4d81-91a8-dbd98dcb7913') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3aba0fc0-3ee8-4d81-91a8-dbd98dcb7913');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '777b8327-bd81-4321-a3e9-b92aeebd373c','Optical MEMS microphone','A micro-electro-mechanical microphone that senses diaphragm motion optically, using light reflected from or transmitted past the moving diaphragm rather than a capacitive backplate. Optical readout (interferometric or intensity-based) can resolve sub-nanometer displacement, giving very low self-noise and immunity to electromagnetic interference.','This tiny chip microphone reads its diaphragm with light, not electric charge. A beam bounces off the moving diaphragm. A detector turns the light change into a signal. This can give very low noise and no electrical pickup.','It offers a path to high signal-to-noise MEMS microphones with strong noise immunity, useful where capacitive MEMS parts hit noise or interference limits.','A packaged optical MEMS microphone shines light on the diaphragm and detects displacement; research devices reach A-weighted self-noise near or below 15 dB(A) SPL.','Optical transduction',ARRAY['Optical interferometric sensing','Optical intensity modulation','Optical phase modulation','Piezoelectric MEMS microphone','Diaphragm displacement']::text[],ARRAY['Assuming optical MEMS microphones need no electronics; the light source and detector consume power.','Confusing an optically read microphone with a photoacoustic (light-generated sound) device.','Expecting all optical MEMS mics to use interferometry; some use simpler intensity modulation.']::text[],ARRAY['Evaluating next-generation low-noise mobile microphones.','Recording in strong electromagnetic environments.','Comparing optical readout against capacitive MEMS noise floors.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Optical MEMS microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '777b8327-bd81-4321-a3e9-b92aeebd373c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='777b8327-bd81-4321-a3e9-b92aeebd373c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='777b8327-bd81-4321-a3e9-b92aeebd373c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'caa574fc-376a-4e3a-acd4-6fa7dca35c63','Optical intensity modulation','An optical readout method in which diaphragm displacement changes the intensity of light reaching a photodetector, for example by varying how much a reflected or coupled beam is captured. Over a linear operating region the detected optical power tracks the displacement, giving a simple electrical output proportional to sound.','Here the moving diaphragm changes how much light hits a detector. As it moves, the light gets brighter or dimmer. The detector turns that brightness into a voltage. It is the simplest way to read motion with light.','It provides a low-complexity optical transduction scheme, trading some sensitivity for a design that avoids the alignment demands of interferometry.','A diaphragm partly blocks or reflects a beam; a 1 percent change in captured light gives a 1 percent change in photocurrent that a transimpedance amplifier converts to signal.','Optical transduction',ARRAY['Optical MEMS microphone','Optical phase modulation','Optical interferometric sensing','Photodetector','Diaphragm displacement']::text[],ARRAY['Confusing intensity modulation with phase or interferometric readout, which measure path length.','Assuming linearity over the full stroke; only a limited region stays proportional.','Ignoring light-source intensity drift, which adds low-frequency noise.']::text[],ARRAY['Designing a simple low-cost optical microphone.','Explaining the most basic optical readout to students.','Reading fiber-coupled displacement in a sensor.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Optical intensity modulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'caa574fc-376a-4e3a-acd4-6fa7dca35c63','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='caa574fc-376a-4e3a-acd4-6fa7dca35c63') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='caa574fc-376a-4e3a-acd4-6fa7dca35c63');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '606bf3d2-135b-4bf6-b512-403a4b770bd4','Optical interferometric sensing','A displacement-sensing method that interferes light reflected from a moving diaphragm with a reference beam; the changing optical path length shifts the interference fringes, and the detected intensity varies as the cosine of the round-trip phase. It resolves sub-nanometer motion, making it well suited to low-noise optical microphones.','This method measures motion by overlapping two light beams. One beam bounces off the moving diaphragm. When the diaphragm shifts, the combined light brightens and dims. Reading those fringes reveals motion smaller than a nanometer.','It gives extremely fine displacement resolution, letting optical microphones and sensors detect tiny diaphragm movements that capacitive sensing would lose in noise.','In a two-beam setup with round-trip phase 4*pi*d/lambda and lambda = 850 nm, a diaphragm move of lambda/4 = about 213 nm shifts the output by half a fringe (pi radians).','Optical transduction',ARRAY['Optical phase modulation','Optical intensity modulation','Optical MEMS microphone','Fabry-Perot cavity','Diaphragm displacement']::text[],ARRAY['Forgetting the round-trip factor of two in reflection, which doubles the phase per displacement.','Operating at a fringe peak where sensitivity to small motion is near zero.','Underestimating the mechanical and thermal stability an interferometer needs.']::text[],ARRAY['Building a sub-nanometer optical microphone.','Reading MEMS diaphragm motion in a lab.','Explaining why interferometry beats intensity readout on noise.']::text[],'Advanced','I = I_0 * [ 1 + cos(4*pi*d/lambda) ]','The detected intensity equals the baseline intensity times one plus the cosine of four pi times the diaphragm displacement divided by the wavelength (the round-trip phase).','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Optical interferometric sensing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '606bf3d2-135b-4bf6-b512-403a4b770bd4','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='606bf3d2-135b-4bf6-b512-403a4b770bd4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='606bf3d2-135b-4bf6-b512-403a4b770bd4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2c45a049-fedf-4a54-ad1b-9b7de7584c58','Optical phase modulation','An optical transduction principle in which diaphragm motion changes the optical phase of a light beam, because a reflected beam''s path length changes by twice the displacement. The phase shift is recovered interferometrically, giving an output proportional to displacement for small motions.','Here the moving diaphragm changes the light''s phase, not its brightness. Moving the diaphragm lengthens or shortens the light''s path. In reflection the path changes by twice the motion. An interferometer turns that phase change into a signal.','It underlies high-resolution optical microphones, encoding tiny diaphragm displacements as measurable optical phase shifts.','For a 1 nm displacement at lambda = 1550 nm, the reflected phase shift is 4*pi*d/lambda = 4*pi*(1e-9)/(1.55e-6) = about 8.1 milliradians.','Optical transduction',ARRAY['Optical interferometric sensing','Optical intensity modulation','Optical MEMS microphone','Optical phase','Diaphragm displacement']::text[],ARRAY['Using the one-way phase 2*pi*d/lambda when reflection needs the round-trip 4*pi*d/lambda.','Assuming phase is read directly; it requires an interferometer to convert to intensity.','Confusing optical phase modulation of a readout beam with photoacoustic sound generation.']::text[],ARRAY['Designing an interferometric optical microphone.','Analyzing phase sensitivity per nanometer of motion.','Teaching how path length maps to optical phase.']::text[],'Advanced','Dphi = 4*pi*d/lambda','The reflected optical phase shift equals four pi times the diaphragm displacement divided by the optical wavelength.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Optical phase modulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2c45a049-fedf-4a54-ad1b-9b7de7584c58','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2c45a049-fedf-4a54-ad1b-9b7de7584c58') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2c45a049-fedf-4a54-ad1b-9b7de7584c58');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2a347338-50ce-48b6-84a1-e3c2d2fb7962','Optoacoustic effect','The generation of acoustic (pressure) waves when a material absorbs modulated or pulsed light: the absorbed optical energy becomes heat, which drives thermoelastic expansion and a pressure disturbance. It is the same phenomenon commonly called the photoacoustic effect, first reported by Alexander Graham Bell in 1880.','Shine pulsing light on a material that absorbs it. The material heats up and cools in step with the light. That heating makes it expand and contract, creating sound. Bell first showed this back in 1880.','It is the physical basis of photoacoustic sensing and imaging, converting light absorption into a measurable sound signal.','A technician chops or pulses a light source onto an absorbing sample and detects the resulting pressure wave with a microphone or ultrasound sensor.','Photoacoustic physics',ARRAY['Photoacoustic effect','Photothermal excitation','Optoacoustic microphone','Photoacoustic spectroscopy','Thermoelastic expansion']::text[],ARRAY['Thinking the light directly pushes the air; the sound comes from heating and expansion.','Assuming only gases respond; solids and liquids show the effect too.','Treating optoacoustic and photoacoustic as different phenomena; they are the same effect.']::text[],ARRAY['Explaining how a photoacoustic gas sensor makes sound.','Introducing the physics behind photoacoustic imaging.','Crediting Bell''s 1880 discovery in a lecture.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Optoacoustic effect');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2a347338-50ce-48b6-84a1-e3c2d2fb7962','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2a347338-50ce-48b6-84a1-e3c2d2fb7962') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2a347338-50ce-48b6-84a1-e3c2d2fb7962');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a8fc92b7-6e6a-4537-9348-29d432354331','Optoacoustic microphone','A detector that uses the optoacoustic (photoacoustic) effect: modulated light absorbed in a gas, coating, or sample generates a pressure signal that an acoustic transducer senses. The term is also used loosely for microphones whose diaphragm motion is read optically, so context matters.','This microphone works with light-made sound. Pulsing light heats an absorbing material and makes tiny pressure waves. A sensor then hears those waves. Some people also use the name for microphones read out by light.','It enables sensitive detection in photoacoustic instruments, turning a sample''s light absorption into an acoustic signal a transducer can measure.','In a gas analyzer, chopped infrared light tuned to a target gas produces a periodic pressure that a sensitive microphone or cantilever sensor detects.','Photoacoustic sensing',ARRAY['Photoacoustic microphone','Optoacoustic effect','Photoacoustic cell','Optoacoustic tomography','Photothermal excitation']::text[],ARRAY['Assuming it always means an optically read microphone; often it means a photoacoustic detector.','Expecting it to hear ordinary airborne speech; it detects light-induced pressure.','Ignoring that background light absorption at windows adds unwanted signal.']::text[],ARRAY['Detecting trace gases with modulated laser light.','Reading the pressure signal in a photoacoustic cell.','Clarifying two meanings of the term in a datasheet review.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Optoacoustic microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a8fc92b7-6e6a-4537-9348-29d432354331','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a8fc92b7-6e6a-4537-9348-29d432354331') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a8fc92b7-6e6a-4537-9348-29d432354331');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '73155ce7-76eb-46c0-b4de-4d28f5ffd53f','Optoacoustic tomography','A biomedical imaging method that reconstructs three-dimensional maps of optical absorption by detecting the ultrasound generated through the photoacoustic effect when tissue is illuminated with short laser pulses. It combines the rich contrast of optical absorption with the fine spatial resolution and depth reach of ultrasound.','This imaging shines laser pulses into tissue. Absorbing spots, like blood, heat up and emit tiny ultrasound waves. Sensors around the body record those waves. A computer turns the timing into a 3D picture.','It lets clinicians and researchers image blood, oxygenation, and other absorbers deeper than pure optical methods, at better resolution than optics alone allows.','Ultrasound arrays record the light-induced pressure waves, and time-of-flight reconstruction builds the image; the term optoacoustic tomography is used interchangeably with photoacoustic tomography.','Photoacoustic imaging',ARRAY['Photoacoustic imaging','Optoacoustic microphone','Optoacoustic effect','Photoacoustic effect','Ultrasound transducer']::text[],ARRAY['Confusing it with pure optical imaging; the signal detected is ultrasound.','Assuming unlimited depth; light delivery still limits how deep it reaches.','Treating optoacoustic and photoacoustic tomography as different techniques.']::text[],ARRAY['Imaging blood vessels and oxygenation in tissue.','Comparing optical, ultrasound, and photoacoustic imaging.','Explaining depth-versus-resolution trade-offs to students.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Optoacoustic tomography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '73155ce7-76eb-46c0-b4de-4d28f5ffd53f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='73155ce7-76eb-46c0-b4de-4d28f5ffd53f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='73155ce7-76eb-46c0-b4de-4d28f5ffd53f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd0825deb-cd1d-45ff-8142-24b148cc1a6f','Part-to-part matching','The degree to which nominally identical microphones agree in sensitivity and phase from unit to unit. Tight matching (for example sensitivity held within about plus or minus 1 dB) is critical for microphone arrays and noise-cancelling pairs, because beamforming and cancellation rely on units behaving alike.','This is how closely two of the same microphone match. Their loudness and timing should line up. MEMS parts are often held within about one decibel. Arrays and noise cancelling need this tight match to work.','It ensures arrays and multi-microphone systems form accurate beams and deep nulls, since mismatched units blur the beam and leak noise.','A designer checks a MEMS datasheet for a sensitivity tolerance of about plus or minus 1 dB and a stated phase match, then budgets array performance around it.','Array tolerance',ARRAY['Planar microphone array','Narrowband beamformer','Neural beamforming','Sensitivity tolerance','MEMS microphone']::text[],ARRAY['Assuming same model number guarantees identical sensitivity; tolerance still applies.','Matching only sensitivity and ignoring phase, which also matters for arrays.','Overlooking temperature and aging drift that widen matching over time.']::text[],ARRAY['Choosing microphones for a beamforming array.','Pairing mics for active noise cancellation.','Reading a MEMS datasheet''s sensitivity tolerance spec.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Part-to-part matching');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd0825deb-cd1d-45ff-8142-24b148cc1a6f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d0825deb-cd1d-45ff-8142-24b148cc1a6f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d0825deb-cd1d-45ff-8142-24b148cc1a6f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ae54d565-993e-4b4a-9c6e-b0141d1d4253','Particle ingress protection','Protection of a microphone''s acoustic port and interior against solid particles and dust, described by the first digit of the IP (Ingress Protection) code in IEC 60529, where a digit of 5 means dust-protected and 6 means dust-tight. MEMS and rugged microphones use meshes, gaskets, or membranes to block particles while passing sound.','This is how well a microphone keeps dust out. The IP code rates it with a first number. A 5 means mostly dust-proof, a 6 means fully dust-tight. Tiny meshes let sound in but block particles.','It keeps grit and dust from clogging or damaging a microphone port, which is vital for phones, wearables, and outdoor or industrial use.','A technician reads a rating like IP67, where the first digit 6 means dust-tight; the acoustic mesh blocks particles while still passing sound to the diaphragm.','Mic protection',ARRAY['Permanently polarized microphone','Piezoelectric MEMS microphone','Water ingress protection','Acoustic mesh','MEMS microphone']::text[],ARRAY['Reading only the second IP digit (water) and ignoring the first (dust).','Assuming a mesh has no acoustic effect; it can add slight loss or resonance.','Thinking a higher IP number always means better sound; it describes sealing, not audio.']::text[],ARRAY['Specifying a microphone for a phone or smartwatch.','Choosing a rugged mic for a dusty factory.','Reading an IP rating on a MEMS microphone datasheet.']::text[],'Beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Particle ingress protection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ae54d565-993e-4b4a-9c6e-b0141d1d4253','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ae54d565-993e-4b4a-9c6e-b0141d1d4253') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ae54d565-993e-4b4a-9c6e-b0141d1d4253');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f1a6c499-5268-4bb3-9c82-4cbf7ed5a304','Permanently polarized microphone','A condenser microphone whose fixed charge is supplied by an electret, a dielectric that holds a quasi-permanent electric charge, instead of an external polarization voltage. Also called a prepolarized microphone, it needs essentially no external polarizing voltage, whereas an externally polarized measurement cartridge typically requires 200 V.','This is a condenser microphone with a built-in charge. A specially charged material replaces the usual high voltage supply. So it needs almost no polarizing voltage of its own. A classic externally polarized measurement mic instead needs about 200 volts.','It gives condenser-quality response without a high-voltage polarization supply, making microphones simpler, cheaper, and more tolerant of humidity in the field.','A technician grabs a prepolarized 1/2-inch measurement microphone for humid field work, avoiding the 200 V supply that an externally polarized cartridge would need.','Condenser microphone',ARRAY['Phantom powering','Microphone reciprocity','Pistonphone calibration','Electret','Externally polarized cartridge']::text[],ARRAY['Thinking an electret needs no power at all; its impedance converter still needs supply (often phantom).','Assuming prepolarized always means lower quality; modern electrets rival externally polarized types.','Confusing the electret''s built-in charge with the phantom voltage that feeds the internal buffer.']::text[],ARRAY['Selecting a field measurement microphone for humid sites.','Explaining why an electret lavalier needs only bias, not 200 V.','Comparing prepolarized and externally polarized cartridges.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Permanently polarized microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f1a6c499-5268-4bb3-9c82-4cbf7ed5a304','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f1a6c499-5268-4bb3-9c82-4cbf7ed5a304') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f1a6c499-5268-4bb3-9c82-4cbf7ed5a304');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c62d7359-c685-44a4-b430-645c7b5fb41e','Phantom powering','A method of supplying direct-current power to a condenser microphone over the same balanced audio pair that carries the signal, applying an equal positive voltage to both signal conductors through matched feed resistors with the return on the shield. The common P48 form is 48 V (tolerance about plus or minus 4 V) fed through two 6.8 kilohm resistors, delivering up to roughly 10 mA per microphone; 12 V and 24 V variants exist. It is described in IEC 61938 (successor to DIN 45596).','Phantom power sends DC voltage to a condenser mic down the mic cable. The same equal voltage goes on both signal wires. Because it is equal, a balanced input ignores it as audio. The common form is 48 volts through two matched resistors.','It powers condenser and electret microphones from the mixer or interface, so they need no batteries or separate supply on stage or in the studio.','The voltage at the mic drops as it draws current: V = 48 - I*(6800/2). At 2 mA the effective 3.4 kilohm source drops 6.8 V, leaving about 41.2 V.','Microphone powering',ARRAY['Permanently polarized microphone','Balanced audio','Condenser microphone','P48','Feed resistor']::text[],ARRAY['UNSAFE: Applying phantom power to a ribbon microphone with a wiring fault or on a hot patch can force damaging current through the delicate ribbon; keep phantom off for ribbons unless the model explicitly allows it.','UNSAFE: Plugging or unplugging a microphone with phantom power on can send transient current surges and loud pops; always mute and power down first.','Assuming phantom power harms every dynamic microphone; a correctly balanced dynamic is unaffected, but faulty or unbalanced wiring can cause problems.','Confusing phantom power (equal on both legs) with T-power/A-B powering (voltage across the legs), which is not compatible.']::text[],ARRAY['Powering a studio condenser from an audio interface.','Deciding whether to enable 48 V for a ribbon mic on a shared strip.','Troubleshooting a loud pop after hot-patching a live channel.']::text[],'Beginner','V_mic = V_p - I * (R_f / 2)','The voltage available at the microphone equals the phantom supply voltage minus the current drawn times half the feed-resistor value (the two matched resistors act as a source impedance of half their value).','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phantom powering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c62d7359-c685-44a4-b430-645c7b5fb41e','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c62d7359-c685-44a4-b430-645c7b5fb41e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c62d7359-c685-44a4-b430-645c7b5fb41e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd62f3cfc-99cb-4dfe-b4c3-3250acfbf82b','Phase shading','Applying a chosen progression of phase weights across the elements of an array to steer or shape the beam, as distinct from amplitude shading, which sets element gains to control sidelobes. A linear phase gradient across the aperture steers the main lobe to a target direction.','Shading means setting weights across an array''s microphones. Phase shading adjusts the timing (phase) of each element. A steady phase step across the array tilts the beam. This aims the array without moving it.','It electronically points or reshapes an array''s beam by adjusting element phases, enabling steering and beam control without physical movement.','To steer a half-wavelength array to 20 degrees, each element gets phase -n*2*pi*(d/lambda)*sin(20 deg); the first element''s step is about -61.6 degrees.','Array beamforming',ARRAY['Narrowband beamformer','Planar microphone array','Neural beamforming','Amplitude shading','Steering vector']::text[],ARRAY['Confusing phase shading (steering) with amplitude shading (sidelobe control).','Applying a fixed phase gradient to wideband signals, which steers each frequency differently.','Ignoring spatial aliasing when spacing exceeds half a wavelength.']::text[],ARRAY['Steering a fixed microphone array toward a talker.','Designing beam patterns for an acoustic camera.','Explaining electronic steering versus mechanical aiming.']::text[],'Advanced','phi_n = -n * 2*pi*(d/lambda) * sin(theta_0)','The phase applied to element n equals negative n times two pi times the spacing-to-wavelength ratio times the sine of the desired steer angle.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase shading');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd62f3cfc-99cb-4dfe-b4c3-3250acfbf82b','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d62f3cfc-99cb-4dfe-b4c3-3250acfbf82b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d62f3cfc-99cb-4dfe-b4c3-3250acfbf82b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ebc9882d-361b-4c17-a604-588356ad05e1','Photoacoustic cell','The enclosed chamber in photoacoustic spectroscopy that holds the sample (often a gas) together with a microphone; modulated light absorbed by the sample causes periodic heating and a pressure signal the microphone detects. Cells are designed as resonant, using an acoustic mode to amplify the signal, or nonresonant.','This is the sealed chamber of a photoacoustic instrument. The sample and a microphone sit inside. Pulsing light heats the sample and makes pressure waves. The microphone in the cell picks up that signal.','It houses the sample and detector so light absorption can be turned into a measurable acoustic signal for gas and material analysis.','A technician fills the cell with a gas sample, shines modulated light through a window, and reads the microphone signal, which rises with target-gas concentration.','Photoacoustic sensing',ARRAY['Nonresonant photoacoustic cell','Photoacoustic spectroscopy','Photoacoustic microphone','Optoacoustic microphone','Resonant cell']::text[],ARRAY['Ignoring window and wall absorption, which create a background signal.','Assuming any cell is resonant; many are deliberately nonresonant.','Forgetting that flowing or refreshing the sample affects the reading.']::text[],ARRAY['Setting up a photoacoustic gas analyzer.','Choosing a resonant versus nonresonant cell design.','Explaining where the microphone sits in a photoacoustic sensor.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Photoacoustic cell');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ebc9882d-361b-4c17-a604-588356ad05e1','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ebc9882d-361b-4c17-a604-588356ad05e1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ebc9882d-361b-4c17-a604-588356ad05e1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f47fa9ac-cb51-4811-a512-20287b26de3f','Photoacoustic effect','The production of acoustic waves when a material absorbs modulated or pulsed light, converting the absorbed energy into heat and then, through thermoelastic expansion, into pressure. First reported by Alexander Graham Bell in 1880, it is identical to the optoacoustic effect. For pulsed excitation the initial pressure follows p0 = Gamma * mu_a * F.','Light that a material absorbs can make sound. The absorbed light becomes heat. The heat makes the material expand and contract. That expansion sends out pressure waves we can detect.','It is the core physics behind photoacoustic spectroscopy and imaging, linking optical absorption to a measurable pressure signal.','For tissue with Grueneisen parameter 0.2, absorption 100 per meter, and fluence 100 J/m^2 (10 mJ/cm^2), the initial pressure is p0 = 0.2*100*100 = about 2000 Pa (2 kPa).','Photoacoustic physics',ARRAY['Optoacoustic effect','Photothermal excitation','Photoacoustic imaging','Photoacoustic spectroscopy','Thermoelastic expansion']::text[],ARRAY['Believing light pressure (radiation pressure) makes the sound; it is heating and expansion.','Assuming only strong absorbers respond; any absorbing medium produces some signal.','Treating photoacoustic and optoacoustic as separate effects.']::text[],ARRAY['Explaining the basis of photoacoustic imaging.','Estimating initial pressure from a laser pulse in tissue.','Introducing Bell''s 1880 experiment in a course.']::text[],'Intermediate','p0 = Gamma * mu_a * F','For short-pulse excitation, the initial photoacoustic pressure equals the Grueneisen parameter times the optical absorption coefficient times the local light fluence.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Photoacoustic effect');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f47fa9ac-cb51-4811-a512-20287b26de3f','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f47fa9ac-cb51-4811-a512-20287b26de3f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f47fa9ac-cb51-4811-a512-20287b26de3f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '462df468-76fe-417b-be02-f098acb0cb26','Photoacoustic imaging','An imaging modality that maps optical absorption inside a sample by detecting the ultrasound generated through the photoacoustic effect when short light pulses are absorbed and cause thermoelastic expansion. It spans photoacoustic microscopy and tomography, offering optical contrast with the deeper reach and finer resolution of ultrasound.','This imaging turns light absorption into an ultrasound picture. Short light pulses heat absorbing spots inside tissue. Those spots emit tiny ultrasound waves. Detectors and a computer build an image from them.','It reveals absorbers such as blood and pigments deeper than optical imaging can, combining optical contrast with ultrasonic resolution.','A pulsed laser illuminates tissue and an ultrasound sensor records the emitted waves; the initial pressure scales as p0 = Gamma * mu_a * F, so stronger absorbers appear brighter.','Photoacoustic imaging',ARRAY['Optoacoustic tomography','Photoacoustic effect','Photoacoustic microphone','Ultrasound transducer','Thermoelastic expansion']::text[],ARRAY['Confusing it with ultrasound imaging; here light generates the sound, not an emitter.','Assuming unlimited depth; optical delivery still limits penetration.','Ignoring that motion during pulses blurs the reconstruction.']::text[],ARRAY['Imaging blood vessels or oxygenation in tissue.','Comparing photoacoustic microscopy and tomography.','Explaining optical contrast with acoustic resolution.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Photoacoustic imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '462df468-76fe-417b-be02-f098acb0cb26','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='462df468-76fe-417b-be02-f098acb0cb26') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='462df468-76fe-417b-be02-f098acb0cb26');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8a3c846-83a2-4bd4-9a5e-64a4c33381c9','Photoacoustic microphone','The sensitive acoustic detector that reads the pressure signal inside a photoacoustic cell. Besides conventional condenser or MEMS microphones, specialized detectors are used, including cantilever-enhanced pressure sensors and quartz tuning forks (quartz-enhanced photoacoustic spectroscopy, QEPAS).','This is the microphone inside a photoacoustic sensor. It listens for the tiny pressure made by absorbed light. Some designs use a normal condenser or MEMS mic. Others use a thin cantilever or a quartz tuning fork.','It converts the small light-induced pressure into an electrical signal, setting much of a photoacoustic instrument''s sensitivity.','In quartz-enhanced photoacoustic spectroscopy, a quartz tuning fork resonating near 32.7 kHz replaces a conventional microphone as the pressure detector.','Photoacoustic sensing',ARRAY['Photoacoustic cell','Optoacoustic microphone','Photoacoustic spectroscopy','Nonresonant photoacoustic cell','Cantilever sensor']::text[],ARRAY['Assuming it detects normal speech; it senses light-induced pressure in a cell.','Overlooking cantilever and tuning-fork detectors as alternatives to a microphone.','Ignoring that detector noise sets the instrument''s detection limit.']::text[],ARRAY['Choosing a detector for a trace-gas photoacoustic sensor.','Comparing microphone, cantilever, and QEPAS detection.','Explaining the sensor at the heart of a photoacoustic cell.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Photoacoustic microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8a3c846-83a2-4bd4-9a5e-64a4c33381c9','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8a3c846-83a2-4bd4-9a5e-64a4c33381c9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8a3c846-83a2-4bd4-9a5e-64a4c33381c9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '440e7678-7fe4-42a0-94c0-aa483aa9ac41','Photoacoustic spectroscopy','A measurement technique that determines a sample''s composition from the acoustic signal produced when it absorbs light modulated at chosen wavelengths; the signal grows with absorption and concentration. Because no light means no signal, it is a near zero-background method well suited to sensitive trace-gas detection.','This method identifies substances by the sound they make under light. Light tuned to a target is switched on and off. The sample absorbs it and makes a pressure signal. Stronger absorption means more of the target is present.','It enables very sensitive trace-gas and material analysis, since the signal appears only when the target absorbs, giving a low background.','A technician tunes a laser to a gas''s absorption line and modulates it; the microphone signal in the cell rises in proportion to the gas concentration.','Photoacoustic sensing',ARRAY['Photoacoustic cell','Photoacoustic microphone','Photothermal excitation','Nonresonant photoacoustic cell','Optoacoustic effect']::text[],ARRAY['Assuming a strong laser alone guarantees sensitivity; cell and detector noise also matter.','Neglecting window absorption and wall effects that add background.','Forgetting that pressure, temperature, and humidity shift the calibration.']::text[],ARRAY['Measuring trace pollutants in air.','Detecting a single gas species at low concentration.','Calibrating a photoacoustic gas monitor.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Photoacoustic spectroscopy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '440e7678-7fe4-42a0-94c0-aa483aa9ac41','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='440e7678-7fe4-42a0-94c0-aa483aa9ac41') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='440e7678-7fe4-42a0-94c0-aa483aa9ac41');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5c2373f8-3615-4f27-94f9-c18412b190a3','Photothermal excitation','The use of modulated or pulsed light absorption to deposit heat that drives thermal expansion, motion, or a pressure change in a material or structure. It is the driving step behind photoacoustics and is also used to actuate micro-cantilevers and MEMS devices without physical contact.','This means using absorbed light as a heater. Pulsing light warms a spot again and again. The warming makes the material expand and move. That heat-driven motion drives sensors and tiny mechanical parts.','It provides a contactless way to drive motion, pressure, or vibration, underlying both photoacoustic signal generation and optical actuation of micro-devices.','A technician focuses a modulated laser on a micro-cantilever; the periodic heating flexes it at the modulation frequency, with no mechanical drive needed.','Photoacoustic physics',ARRAY['Photoacoustic effect','Optoacoustic effect','Photoacoustic spectroscopy','Thermoelastic expansion','Optical actuation']::text[],ARRAY['Confusing photothermal excitation (the heating drive) with the resulting photoacoustic sound.','Assuming instant response; thermal diffusion sets a finite time constant.','Overlooking that too much power can overheat or damage the sample.']::text[],ARRAY['Driving a MEMS cantilever with a laser.','Explaining the heating step in photoacoustics.','Actuating a structure without physical contact.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Photothermal excitation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5c2373f8-3615-4f27-94f9-c18412b190a3','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5c2373f8-3615-4f27-94f9-c18412b190a3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5c2373f8-3615-4f27-94f9-c18412b190a3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'be56aa41-fdd1-46b0-9f02-9b8362862f6b','Piezoelectric MEMS microphone','A micro-electro-mechanical microphone that senses sound with a piezoelectric thin film, commonly aluminum nitride, on a cantilever or diaphragm; sound bends the film and the resulting stress generates a charge. Unlike capacitive MEMS microphones it needs no bias voltage or backplate, and it tolerates dust and water well. Vesper (a trademark of Vesper Technologies, acquired by Qorvo) is a commercial example of this generic piezoelectric approach.','This tiny microphone turns bending into voltage. Sound flexes a film that makes charge when stressed. It needs no bias voltage and has no fragile backplate. That makes it rugged against dust and water.','It offers a robust, backplate-free MEMS microphone with good survivability, useful in harsh or dusty environments where capacitive MEMS parts are vulnerable.','A designer picks a piezoelectric MEMS microphone for a waterproof earbud, gaining dust and water tolerance without needing a polarization bias.','MEMS microphone',ARRAY['Optical MEMS microphone','Part-to-part matching','Particle ingress protection','Aluminum nitride','Capacitive MEMS microphone']::text[],ARRAY['Assuming all MEMS microphones are capacitive; piezoelectric types work differently.','Thinking it needs a bias voltage; the piezoelectric film needs none.','Expecting a backplate; piezoelectric designs have none, aiding robustness.']::text[],ARRAY['Choosing a rugged mic for a waterproof wearable.','Comparing piezoelectric and capacitive MEMS noise and robustness.','Explaining why some MEMS mics survive dust and water.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Piezoelectric MEMS microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'be56aa41-fdd1-46b0-9f02-9b8362862f6b','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='be56aa41-fdd1-46b0-9f02-9b8362862f6b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='be56aa41-fdd1-46b0-9f02-9b8362862f6b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd811f0de-3b94-4552-b396-59ad4639a65c','Pistonphone calibration','Calibrating a microphone''s sensitivity with a pistonphone: a precision closed coupler in which cam-driven pistons displace a known volume, producing a stable, calculable sound pressure level. The Bruel & Kjaer Type 4228 generates 124 dB re 20 uPa at nominally 250 Hz and requires a barometric-pressure correction because the level depends on ambient static pressure. Pistonphones are sound calibrators under IEC 60942.','A pistonphone makes a known, steady tone for calibration. Small pistons push a set volume of air inside a sealed coupler. That creates a precise sound level, such as 124 decibels near 250 hertz. You adjust for air pressure because it changes the level.','It provides a traceable reference level to check and set a measurement microphone''s sensitivity before taking readings.','A technician slips the mic into the pistonphone, applies the barometric correction, and adjusts gain so the meter reads 124 dB (about 31.7 Pa rms) at 250 Hz.','Calibration method',ARRAY['Microphone reciprocity','Permanently polarized microphone','Sound calibrator','Sensitivity','Barometric correction']::text[],ARRAY['Skipping the barometric-pressure correction, which shifts the true level at altitude or in weather changes.','Using the wrong adapter so the coupler does not seal, giving a false level.','Confusing a pistonphone''s fixed calibration level with the microphone''s usable maximum SPL.']::text[],ARRAY['Checking a sound-level meter before field measurements.','Setting a measurement microphone''s sensitivity in the lab.','Correcting the reference level for local barometric pressure.']::text[],'Intermediate','L_p = 20 * log10(p / p_ref)','The sound pressure level in decibels equals twenty times the base-ten logarithm of the pressure divided by the 20 micropascal reference; a 124 dB level corresponds to about 31.7 pascals rms.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pistonphone calibration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd811f0de-3b94-4552-b396-59ad4639a65c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d811f0de-3b94-4552-b396-59ad4639a65c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d811f0de-3b94-4552-b396-59ad4639a65c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bac1b937-8627-48c2-a404-ab780c84217b','Planar microphone array','A two-dimensional arrangement of microphones lying in a plane, such as a grid or spiral, that enables beamforming and source localization over both azimuth and elevation and supports acoustic imaging (acoustic cameras). The aperture size sets angular resolution, while element spacing must stay small enough to avoid spatial aliasing.','This is a flat layout of many microphones. Being 2D, it can locate sound in two directions at once. Bigger arrays see finer detail. Spacing must stay small to avoid errors at high frequency.','It lets a system map where sounds come from across a surface, powering acoustic cameras and 2D beam steering.','To avoid spatial aliasing up to 8 kHz, spacing must satisfy d <= c/(2f) = 343/(2*8000) = about 21.4 mm.','Microphone array',ARRAY['Narrowband beamformer','Phase shading','Neural beamforming','Part-to-part matching','Spatial aliasing']::text[],ARRAY['Spacing elements too far apart, which causes spatial aliasing at high frequencies.','Assuming more microphones always help; geometry and calibration matter as much.','Ignoring part-to-part mismatch, which degrades beam quality.']::text[],ARRAY['Building an acoustic camera to find noise sources.','Localizing sound in azimuth and elevation.','Designing a conference-room ceiling array.']::text[],'Advanced','d <= c / (2 * f_max)','To avoid spatial aliasing, the element spacing must be less than or equal to the speed of sound divided by twice the highest frequency of interest.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Planar microphone array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bac1b937-8627-48c2-a404-ab780c84217b','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bac1b937-8627-48c2-a404-ab780c84217b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bac1b937-8627-48c2-a404-ab780c84217b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '99a814bd-4eed-4ac9-9d1f-2a9601f14d01','Plasma microphone','A microphone with no moving diaphragm that senses sound through its effect on an electrically ionized gas (a plasma or corona). Sound pressure changes the gas density and thus the plasma''s conductivity or impedance, modulating an electrical current to produce the signal. The near-massless plasma gives very wide bandwidth, but the approach is niche and requires high voltage.','This microphone has no moving part. It uses a small patch of ionized, glowing gas. Sound squeezes that gas and changes how it conducts. That change becomes the electrical signal.','It offers extremely wide, low-mass response for specialized measurement or research, trading practicality for the absence of a mechanical diaphragm.','A researcher sustains a small corona or plasma and measures how sound-driven density changes modulate its current, using it where a massless sensor is worth the complexity.','Microphone type',ARRAY['Optical MEMS microphone','Permanently polarized microphone','Piezoelectric MEMS microphone','Corona discharge','Ionized gas transducer']::text[],ARRAY['UNSAFE: Plasma and corona microphones use high voltage that can shock or burn; treat the supply as a serious electrical hazard and follow high-voltage safety practice.','UNSAFE: Corona discharges generate ozone and can ignite flammable atmospheres; ventilate the area and keep them away from combustible gases.','Assuming it senses sound mechanically; there is no diaphragm, only ionized-gas conductivity changes.','Expecting a rugged everyday microphone; it is fragile, drifty, and mainly a research device.']::text[],ARRAY['Explaining a diaphragm-free, very wide-band microphone concept.','Discussing exotic transducers in a course.','Relating a plasma microphone to a plasma (ionic) tweeter''s physics.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Plasma microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '99a814bd-4eed-4ac9-9d1f-2a9601f14d01','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='99a814bd-4eed-4ac9-9d1f-2a9601f14d01') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='99a814bd-4eed-4ac9-9d1f-2a9601f14d01');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '492be0a6-708e-48ca-9ac4-15d776efa920','Polarization voltage','The steady DC voltage placed across a condenser microphone capsule, between the diaphragm and the fixed backplate, to hold a nearly constant electric charge on the capacitor. When sound moves the diaphragm and changes the gap, the near-constant charge forces the voltage to change, producing the output signal roughly in proportion to the polarization voltage. Laboratory measurement capsules commonly use 200 V, while studio condensers use lower internal values derived from phantom power.','A condenser mic uses two closely spaced plates as a capacitor. A DC voltage charges these plates and keeps them charged. Sound vibrates one plate, so the voltage across it wiggles. That wiggle is the audio signal. A higher charging voltage gives a bigger signal.','It converts the capsule''s tiny capacitance changes into a usable audio voltage, and it sets how much output the capsule gives for a given sound pressure.','With polarization voltage V_p = 200 V, diaphragm-to-backplate gap d0 = 20 um, and a diaphragm motion x = 1 nm, the signal is e = V_p*(x/d0) = 200*(1e-9/2e-5) = 0.01 V = 10 mV.','Condenser Mic Principle',ARRAY['Prepolarized condenser microphone','Pull-in voltage','Pressure sensitivity','Source impedance','Sensitivity level']::text[],ARRAY['Thinking a higher polarization voltage always improves a mic; too high a value risks arcing or pull-in collapse.','Confusing the internal polarization voltage of a studio condenser with the 48 V phantom supply that feeds it.','UNSAFE: Hot-patching or connecting a condenser mic while phantom power is live can send a large charging thump downstream that may damage loudspeakers or hearing; mute the channel first.']::text[],ARRAY['Setting up a 200 V supply for a laboratory measurement microphone before a calibration.','Explaining why an externally polarized measurement capsule needs a special power module.','Troubleshooting weak output traced to a missing or sagging polarization voltage.']::text[],'Intermediate','e = V_p * (x / d0)','The signal voltage equals the polarization voltage multiplied by the diaphragm displacement divided by the resting diaphragm-to-backplate gap.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Polarization voltage');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '492be0a6-708e-48ca-9ac4-15d776efa920','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='492be0a6-708e-48ca-9ac4-15d776efa920') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='492be0a6-708e-48ca-9ac4-15d776efa920');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ec10f50b-ae33-40dd-8472-eb50121bebe5','Pop-noise suppression','The set of techniques used to stop plosive consonants, such as p and b, from creating a loud low-frequency thump or momentary overload at a microphone. It works by breaking up or slowing the fast jet of air from the mouth before it strikes the diaphragm, using foam windscreens, mesh pop filters, or capsule grille design, sometimes aided by a low-cut filter.','Saying words like ''pop'' pushes a burst of air at the mic. That burst hits the diaphragm and makes a loud thump. Pop-noise suppression slows or scatters that air burst. Foam covers, mesh screens, and low-cut filters all help. The voice still gets through clearly.','It protects recordings and live sound from plosive blasts, keeping speech and vocals clean without the distracting low-frequency pops.','A technician clips a nylon-mesh pop filter a few centimeters in front of a vocal condenser and, if needed, engages the console high-pass filter around 80 Hz to remove any residual plosive energy.','Microphone Accessory',ARRAY['Windscreen','High-pass filter','Pressure sensitivity','Handling noise','Proximity effect']::text[],ARRAY['Believing a foam windscreen and a pop filter are identical; foam mainly cuts wind outdoors while mesh filters target vocal plosives.','Placing the pop filter touching the grille, which reduces its effect; a small gap works better.','Relying only on a steep low-cut, which can thin the voice instead of stopping the air blast at the source.']::text[],ARRAY['Recording a lead vocal where hard p and b sounds keep overloading the input.','Setting up a podcast microphone to reduce plosive thumps in speech.','Choosing between foam and mesh screens for an outdoor versus a studio session.']::text[],'Beginner',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pop-noise suppression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ec10f50b-ae33-40dd-8472-eb50121bebe5','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ec10f50b-ae33-40dd-8472-eb50121bebe5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ec10f50b-ae33-40dd-8472-eb50121bebe5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '594f00b4-5dc7-47e7-ad99-f810bce5424c','Preamplifier current noise','The equivalent input noise current of a microphone preamplifier, representing random fluctuations that flow out of the amplifier input and develop a noise voltage across the source impedance connected to it. Its effect grows with source impedance, so it dominates when the source is a high-impedance condenser capsule and is small for low-impedance dynamic sources.','Every preamp adds some hiss of its own. Part of that hiss acts like a tiny noisy current at the input. This current pushes through whatever the mic looks like electrically. A high-impedance source turns that current into a bigger noise voltage. So current noise matters most with condenser capsules.','It quantifies one of the two main preamp noise sources, letting designers and technicians predict hiss when a given microphone is connected.','With input noise current i_n = 5 fA/rtHz and a capsule source impedance Z_s = 80 MOhm at 100 Hz, the noise voltage density is e_n = i_n*Z_s = 5e-15 * 8e7 = 4e-7 V/rtHz = 0.4 uV/rtHz.','Preamp Noise',ARRAY['Preamplifier voltage noise','Source impedance','Shot noise','Sensitivity level','Prepolarized condenser microphone']::text[],ARRAY['Assuming current noise is always negligible; with gigaohm capsule impedance at low frequency it can dominate.','Mixing up current noise and voltage noise, which trade importance depending on source impedance.','Forgetting that current noise is worst at low frequencies where a capacitive capsule impedance is highest.']::text[],ARRAY['Comparing preamps for a high-impedance condenser capsule.','Explaining excess low-frequency hiss when a long high-impedance source drives a preamp.','Selecting a low current-noise FET input stage for a measurement microphone.']::text[],'Advanced','e_n = i_n * Z_s','The noise voltage from current noise equals the input noise current multiplied by the source impedance it flows through.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Preamplifier current noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '594f00b4-5dc7-47e7-ad99-f810bce5424c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='594f00b4-5dc7-47e7-ad99-f810bce5424c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='594f00b4-5dc7-47e7-ad99-f810bce5424c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c58ec2de-4708-47c0-88e2-8808d3bb179e','Preamplifier voltage noise','The equivalent input noise voltage of a microphone preamplifier, modeled as a small noise source in series with the input that appears at the output regardless of source impedance. It dominates the total preamp noise when the microphone source impedance is low, and it combines with current noise and the source''s own thermal noise to set the overall noise floor.','A preamp also adds hiss that behaves like a small noisy voltage at its input. This voltage appears no matter what the mic''s impedance is. It matters most when the mic has a low impedance. Then current noise barely shows up. Designers pick low-voltage-noise parts for such mics.','It captures the impedance-independent part of preamp noise, helping predict the noise floor when a low-impedance microphone is used.','With an input voltage noise density e_n = 4 nV/rtHz over a 20 kHz bandwidth, the total input noise is e_n*sqrt(BW) = 4e-9 * sqrt(20000) = 4e-9 * 141 = 0.57 uV RMS.','Preamp Noise',ARRAY['Preamplifier current noise','Source impedance','Shot noise','Sensitivity level','Sigma-delta modulator']::text[],ARRAY['Treating a single noise figure as valid for all mics; the best preamp depends on source impedance.','Adding voltage and current noise linearly instead of as a root-sum-of-squares.','Ignoring the source''s own thermal noise, which sets a floor no preamp can beat.']::text[],ARRAY['Choosing a low-noise preamp for a low-impedance ribbon or dynamic microphone.','Interpreting a datasheet equivalent input noise specification.','Diagnosing whether hiss comes from the mic, the source impedance, or the preamp.']::text[],'Advanced','E_n(total) = sqrt( e_n^2 + (i_n*Z_s)^2 + 4*k*T*Re(Z_s) ) ;  V_rms = e_n*sqrt(BW)','The total input noise density combines the preamp voltage noise, the current noise across the source impedance, and the source''s thermal noise, added as a root-sum-of-squares; over a bandwidth the RMS noise scales with the square root of the bandwidth.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Preamplifier voltage noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c58ec2de-4708-47c0-88e2-8808d3bb179e','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c58ec2de-4708-47c0-88e2-8808d3bb179e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c58ec2de-4708-47c0-88e2-8808d3bb179e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8009289c-e0a7-4781-aa57-1c95584ea88c','Prepolarized condenser microphone','A condenser (electrostatic) microphone whose bias charge is stored permanently in an electret material, usually a thin fluoropolymer such as PTFE or FEP on the backplate, so no external polarization voltage is needed. Widely called an electret microphone, it still requires a small powered impedance converter, and it trades slightly lower long-term and high-temperature stability for simpler, lower-cost powering.','This is a condenser mic that carries its own built-in charge. A special plastic layer holds that charge for years. So the mic needs no separate charging voltage. It still needs a little power for its internal buffer. These mics are cheap, common, and easy to power.','It removes the need for a high external polarization supply, enabling compact, low-cost microphones for consumer, measurement, and portable use.','A technician powers a prepolarized measurement capsule from a standard constant-current source and, unlike a 200 V externally polarized capsule, connects it with an ordinary coaxial lead instead of a special high-voltage connector.','Condenser Mic Type',ARRAY['Polarization voltage','Pressure sensitivity','Source impedance','Sensitivity level','Pulse-density modulation microphone']::text[],ARRAY['Thinking an electret needs no power at all; the capsule is self-biased but the internal buffer still needs supply.','Assuming electret quality is always inferior; modern back-electret capsules rival externally polarized types except in extreme heat.','Leaving a prepolarized capsule in high heat for long periods, which can slowly bleed off the stored charge.']::text[],ARRAY['Selecting a prepolarized measurement mic for field work without a high-voltage supply.','Explaining why a lavalier or laptop microphone is an electret type.','Comparing long-term stability of prepolarized and externally polarized capsules.']::text[],'Intermediate',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Prepolarized condenser microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8009289c-e0a7-4781-aa57-1c95584ea88c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8009289c-e0a7-4781-aa57-1c95584ea88c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8009289c-e0a7-4781-aa57-1c95584ea88c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '599d851d-92cc-4a7d-bb6d-f0a5e72fcdad','Pressure reciprocity','The application of the acoustic reciprocity principle within a small closed coupler, where the sound pressure is treated as uniform, to calibrate laboratory standard microphones without any prior reference. Two microphones share the coupler cavity; the ratio of one microphone''s open-circuit output voltage to the current driving the other, combined with the coupler''s known acoustic transfer impedance, yields the product of their pressure sensitivities.','Reciprocity means a good condenser mic works equally well whether it acts as a sender or a receiver. In a tiny sealed chamber the sound pressure is the same everywhere. One mic drives sound while another listens. From the measured electrical values and the chamber''s known behavior, you get their sensitivities. This needs no pre-calibrated mic.','It provides the physical basis for primary pressure calibration, giving traceable absolute sensitivity from electrical and geometric measurements alone.','In a coupler, the pressure-sensitivity product of two capsules is M1*M2 = Z_e / Z_a, where Z_e is the electrical transfer impedance measured between the pair and Z_a is the coupler''s computed acoustic transfer impedance.','Microphone Calibration',ARRAY['Reciprocity calibration','Reciprocity parameter','Reciprocity transducer','Pressure sensitivity','Primary calibration']::text[],ARRAY['Assuming the pressure is uniform at all frequencies; the coupler must be small compared with the wavelength.','Forgetting that the microphone must be reversible (reciprocal) for the method to hold.','Overlooking heat-conduction and capillary corrections that affect the coupler''s acoustic impedance.']::text[],ARRAY['Setting up a three-microphone coupler calibration in a national metrology laboratory.','Explaining how a primary pressure sensitivity is obtained without a reference microphone.','Analyzing why a coupler calibration is limited to lower frequencies.']::text[],'Advanced','M1 * M2 = Z_e / Z_a','The product of two microphones'' pressure sensitivities equals the electrical transfer impedance between them divided by the acoustic transfer impedance of the coupler that joins them.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure reciprocity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '599d851d-92cc-4a7d-bb6d-f0a5e72fcdad','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='599d851d-92cc-4a7d-bb6d-f0a5e72fcdad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='599d851d-92cc-4a7d-bb6d-f0a5e72fcdad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9ea86065-17e6-4b0e-bdf1-dec1c6e559bf','Pressure sensitivity','A microphone''s open-circuit output voltage per unit sound pressure acting uniformly on its diaphragm, as it would in a small closed coupler or pressure field. It is usually stated in millivolts per pascal or as a level in decibels relative to 1 V/Pa, and it differs from free-field and random-incidence sensitivity because it excludes the diffraction gain around the microphone body.','Pressure sensitivity says how much voltage a mic gives for a given pressure on its diaphragm. Here the pressure pushes evenly, as inside a tiny sealed cavity. It leaves out the boost from sound bending around the mic. It is a basic number found by calibration. It is often written in millivolts per pascal.','It defines the fundamental transfer factor of a microphone in a pressure field and is the quantity delivered by primary pressure calibration.','If a capsule gives 12.5 mV open-circuit output when exposed to 1 Pa of uniform pressure, its pressure sensitivity is M = 0.0125 V / 1 Pa = 12.5 mV/Pa.','Microphone Specification',ARRAY['Sensitivity level','Pressure-field correction','Pressure reciprocity','Random-incidence correction','Primary calibration']::text[],ARRAY['Confusing pressure sensitivity with free-field sensitivity, which adds the microphone''s diffraction gain.','Ignoring that pressure sensitivity is frequency dependent, not a single number.','Reading a decibel sensitivity level as if it were the raw millivolt-per-pascal figure.']::text[],ARRAY['Reading a measurement microphone''s calibration chart in a pressure field.','Choosing a pressure-field capsule for a coupler or ear-simulator measurement.','Converting a pressure sensitivity to a free-field figure using published corrections.']::text[],'Intermediate','M_p = e_oc / p','Pressure sensitivity equals the open-circuit output voltage divided by the uniform sound pressure on the diaphragm.','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure sensitivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9ea86065-17e6-4b0e-bdf1-dec1c6e559bf','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9ea86065-17e6-4b0e-bdf1-dec1c6e559bf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9ea86065-17e6-4b0e-bdf1-dec1c6e559bf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd9c7f9ee-6809-4f18-a1e7-8322ffea7e00','Pressure-field correction','A frequency-dependent adjustment, in decibels, that relates a microphone''s pressure-field response to the response it would have in another sound field, most often the free field. It accounts for the diffraction and pressure build-up that occur around the microphone body in a free field but are absent in a uniform pressure field, and standardized values are tabulated for laboratory standard capsules.','A mic behaves differently in a sealed cavity than out in open air. In open air, sound bends around the mic and adds a boost at high frequencies. A pressure-field correction is a set of decibel numbers. It converts the sealed-cavity response into the open-air response, or the reverse.','It lets a technician use one calibrated response to predict behavior in a different acoustic field, ensuring accurate measurements across field types.','After a coupler calibration gives the pressure response, the technician adds the tabulated free-field minus pressure difference (for example a few decibels of high-frequency gain near 10 kHz) to obtain the free-field response.','Microphone Calibration',ARRAY['Pressure sensitivity','Random-incidence correction','Protection-grid correction','Primary calibration','Sensitivity level']::text[],ARRAY['Applying a free-field correction to a mic used in a true pressure field, doubling the adjustment.','Treating the correction as constant; it rises with frequency as the body becomes large versus the wavelength.','Using corrections for the wrong capsule diameter or grid configuration.']::text[],ARRAY['Converting a coupler-calibrated pressure response into a free-field response.','Selecting the right correction table for a half-inch versus quarter-inch capsule.','Reconciling readings between a pressure-field and a free-field microphone.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure-field correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd9c7f9ee-6809-4f18-a1e7-8322ffea7e00','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d9c7f9ee-6809-4f18-a1e7-8322ffea7e00') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d9c7f9ee-6809-4f18-a1e7-8322ffea7e00');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e2b74049-2932-47fa-b8e8-4603229e1c3c','Primary calibration','An absolute calibration that determines a microphone''s sensitivity directly from measured electrical, mechanical, and geometric quantities and fundamental physical constants, without comparison to a previously calibrated microphone. For laboratory standard microphones it is realized chiefly by the reciprocity technique, providing the top of the traceability chain to SI units.','Primary calibration finds a mic''s sensitivity from scratch. It uses measured voltage, current, size, and known constants. It never leans on an already-calibrated mic. This makes it the most trusted method. National labs use it to anchor all other calibrations.','It establishes traceable, first-principles reference sensitivities that all secondary and field calibrations ultimately depend on.','A national metrology institute uses the reciprocity method in a coupler or anechoic room to assign an absolute sensitivity to a laboratory standard microphone, which then serves as a transfer standard.','Microphone Calibration',ARRAY['Secondary calibration','Reciprocity calibration','Pressure reciprocity','Reciprocity transducer','Sensitivity level']::text[],ARRAY['Calling a comparison against a reference microphone primary; that is a secondary method.','Assuming primary calibration is routine; it is complex and reserved for standard capsules.','Overlooking that primary results still carry an uncertainty budget from many measured terms.']::text[],ARRAY['Establishing a laboratory reference microphone at a metrology institute.','Explaining the traceability chain from a field mic back to SI units.','Deciding whether a device qualifies for primary versus comparison calibration.']::text[],'Advanced',NULL,NULL,'79ec1aac-5b74-44bb-9dc8-deab2d1fdd04' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Primary calibration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e2b74049-2932-47fa-b8e8-4603229e1c3c','79ec1aac-5b74-44bb-9dc8-deab2d1fdd04',true,'Advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e2b74049-2932-47fa-b8e8-4603229e1c3c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e2b74049-2932-47fa-b8e8-4603229e1c3c');
